rom 'src/manage-request/app/models/permission-manage.model';\r\nimport { GetLogInfoQuery } from '../../add-request/app/add-request/models/add-request.query';\r\nimport { GetLogInfoViewModel } from '../../add-request/app/add-request/models/get-log-info.model';\r\nimport { Selection } from '../../utility/models/selection.model';\r\nimport { GetOddsInfoQuery, OddsInfo } from '../components/advanced-mode/advanced-mode/advanced-mode.model';\r\nimport { GetBetTypesQuery, GroupBetTypesModel } from '../components/advanced-mode/group-bettypes/group-bettypes.model';\r\nimport { GroupBetTypeVirtualSport } from '../components/bettypes-virtualsports/bettypes-virtualsports.model';\r\nimport { BetTypesModel } from '../components/bettypes/bettypes.model';\r\nimport { NapUserInfoModel } from '../components/menu-bar/menu-bar.model';\r\nimport { Tooltip } from '../components/tooltip/tooltip.model';\r\nimport { DateTimeFormat } from '../constants/config';\r\nimport { BalanceUp } from '../models/balance-up.model';\r\nimport { CheckingPermissionModel } from '../models/checking-permission.model';\r\nimport { SportInfo } from '../models/event.model';\r\nimport { IssueInfo, IssueType, IssueTypesModel } from '../models/issue-type.model';\r\nimport { CheckMatchWithRefNoQuery, FirstTicketTime, MatchModel } from '../models/match.model';\r\nimport { Result, SqlResult } from '../models/result';\r\nimport { RequestDetailViewModel } from './../../edit-request/app/request.model';\r\nimport { HttpService } from './http.service';\r\n@Injectable({\r\n  providedIn: 'root'\r\n})\r\nexport class CommonService {\r\n  constructor(\r\n    private readonly httpService: HttpService\r\n  ) { }\r\n\r\n  async getNapUserInfo(): Promise<NapUserInfoModel> {\r\n    return this.httpService.getJson('api/SharedApi/GetNapUserInfo');\r\n  }\r\n\r\n  async getBalanceUp(): Promise<BalanceUp> {\r\n    return this.httpService.getJson(`api/SharedApi/GetBalanceUp`);\r\n  }\r\n  \r\n  async getBalanceUpZoneManila(): Promise<BalanceUp> {\r\n    return this.httpService.getJson(`api/SharedApi/GetBalanceUpZoneManila`);\r\n  }\r\n\r\n  async getGroupBetTypes(query: GetBetTypesQuery): Promise<GroupBetTypesModel> {\r\n    return this.httpService.postJson(query, `api/BetTypes/GetGroupBetTypesNg`);\r\n  }\r\n\r\n  async getBetTypesVirtualSports(): Promise<Array<GroupBetTypeVirtualSport>> {\r\n    return this.httpService.getJson(`api/BetTypes/GetVirtualSport`);\r\n  }\r\n\r\n  async getBetTypes(query: GetBetTypesQuery): Promise<BetTypesModel> {\r\n    return this.httpService.postJson(query, `api/BetTypes/GetBetTypes`);\r\n  }\r\n\r\n  async getSportsType(): Promise<SportInfo[]> {\r\n    return this.httpService.getJson('api/SharedApi/GetSportsType');\r\n  }\r\n\r\n\r\n  async getMatch(matchId: number, isExcludeChildMatchCricket?: boolean): Promise<MatchModel> {\r\n    return this.httpService.postJson({ matchId, isMatch3rd: false, isExcludeChildMatchCricket: isExcludeChildMatchCricket }, 'api/MatchInfo/GetInfo');\r\n  }\r\n\r\n  async getVoidActions(): Promise<Selection[]> {\r\n    return this.httpService.getJson('api/ManageRequest/GetVoidActions');\r\n  }\r\n\r\n  async getRequestById(id: number): Promise<RequestDetailViewModel> {\r\n    return this.httpService.getJson(`api/ManageRequest/GetRequest/${id}`);\r\n  }\r\n\r\n  async getIssueInfo(subId: number): Promise<IssueInfo> {\r\n    return this.httpService.getJson(`api/ManageRequest/GetIssueTypeName/${subId}`);\r\n  }\r\n\r\n  async getPermissionManageRequest(): Promise<PermissionManage> {\r\n    return this.httpService.getJson('api/ManageRequest/GetPermissionManage');\r\n  }\r\n\r\n  async getFirstTimeAndKickOffTime(id: number): Promise<FirstTicketTime> {\r\n    return this.httpService.getJson(`api/MatchInfo/GetFirstTimeAndKickOffTime/${id}`);\r\n  }\r\n\r\n  async checkMatchIdWithRefNo(query: CheckMatchWithRefNoQuery, tooltip: Tooltip): Promise<boolean> {\r\n    const NUMBER_ONE = 1;\r\n    const NUMBER_TWO = 2;\r\n    const NUMBER_THREE = 3;\r\n    const NUMBER_FOUR = 4;\r\n    const NUMBER_FIVE = 5;\r\n    const NUMBER_SIX = 6;\r\n    const url = 'Match/CheckMatchIdWithRefNo';\r\n    const data = await this.httpService.postJson<CheckMatchWithRefNoQuery, Result<string>>(query, url);\r\n\r\n    switch (data.errorCode) {\r\n      case NUMBER_ONE:\r\n      case NUMBER_TWO:\r\n      case NUMBER_THREE:\r\n      case NUMBER_FOUR:\r\n        tooltip.display('match-id', data.errorMsg);\r\n        break;\r\n      case NUMBER_FIVE:\r\n        tooltip.display('from-bet-id', data.errorMsg);\r\n        break;\r\n      case NUMBER_SIX:\r\n        tooltip.display('to-bet-id', data.errorMsg);\r\n        break;\r\n      default:\r\n        break;\r\n    }\r\n\r\n    return data.isSuccessful;\r\n  }\r\n\r\n  async checkVoidBetPermission(query: CheckingPermissionModel): Promise<SqlResult> {\r\n    return this.httpService.postJson(query, `state-api/simple-data/update`);\r\n  }\r\n\r\n  async getIssueTypePermissionList(): Promise<IssueType[]> {\r\n    return this.httpService.getJson('api/SharedApi/GetIssueTypePermissionList');\r\n  }\r\n\r\n  async getIssueTypes(): Promise<IssueTypesModel> {\r\n    return this.httpService.getJson('api/SharedApi/GetIssueTypes');\r\n  }\r\n\r\n  async getLogInfo(query: GetLogInfoQuery): Promise<GetLogInfoViewModel> {\r\n    return this.httpService.postJson<GetLogInfoQuery, GetLogInfoViewModel>(query, 'api/AddRequest/GetLogInfo');\r\n  }\r\n\r\n  async getMarkedTicketsCount(): Promise<number> {\r\n    return this.httpService.getJson('api/ManageRequest/GetMarkedTicketsCount');\r\n  }\r\n\r\n  async getResultCache<T>(guid: string): Promise<Result<T>> {\r\n    return this.httpService.postJson<{ guid: string }, Result<T>>({ guid: guid }, `Utility/GetResultCache`);\r\n  }\r\n\r\n  async GetOddsInfoSpecialBetTypes(query: GetOddsInfoQuery): Promise<OddsInfo[]> {\r\n    const url = 'api/BetTypes/GetOddsInfoSpecialBetTypes';\r\n    return this.httpService.postJson(query, url);\r\n  }\r\n}\r\n\r\nexport class CommonStaticService {\r\n  static convertToStrictTimeFormat(sourceTime: string): string {\r\n    return moment(sourceTime.trim(), DateTimeFormat.TIME_FORMAT, true).format(DateTimeFormat.TIME_FORMAT);\r\n  }\r\n}","import { Injectable } from '@angular/core';\r\nimport { NgbModal, NgbModalConfig, NgbModalRef } from '@ng-bootstrap/ng-bootstrap';\r\nimport * as _ from 'lodash';\r\nimport { CheckingPermissionModel } from '../../models/checking-permission.model';\r\nimport { CommonService } from '../../services/common.service';\r\nimport { ModalContentComponent } from './modal-content/modal-content.component';\r\nimport { IModal, ModalType } from './modal.model';\r\n\r\n\r\n@Injectable({\r\n  providedIn: 'root'\r\n})\r\nexport class ModalService {\r\n  private modalReference: NgbModalRef;\r\n\r\n  constructor(\r\n    config: NgbModalConfig,\r\n    private readonly ngbModal: NgbModal,\r\n    private readonly commonService: CommonService) {\r\n    config.backdrop = 'static';\r\n    config.keyboard = false;\r\n  }\r\n\r\n  open(data: IModal, closeEvent?: () => void) {\r\n    const modalContent = this.openModalContent();\r\n    modalContent.data = data;\r\n    modalContent.close.subscribe(() => {\r\n      this.executeMethodUndefinedable(closeEvent);\r\n    });\r\n  }\r\n\r\n  confirm(data: IModal, onYes?: () => void, onNo?: () => void) {\r\n    data.title =\r\n      _.isNull(data.title) || _.isUndefined(data.title)\r\n        ? 'Confirm'\r\n        : data.title;\r\n    data.type = ModalType.Confirm;\r\n    const modalContent = this.openModalContent();\r\n    modalContent.data = data;\r\n    modalContent.confirm.subscribe(() => {\r\n      this.executeMethodUndefinedable(onYes);\r\n    });\r\n\r\n    modalContent.close.subscribe(() => {\r\n      this.executeMethodUndefinedable(onNo);\r\n    });\r\n  }\r\n\r\n  confirmWithThreeButton(data: IModal, onYes?: () => void, onNo?: () => void,  onCancel?: () => void) {\r\n    data.title =\r\n      _.isNull(data.title) || _.isUndefined(data.title)\r\n        ? 'Confirm'\r\n        : data.title;\r\n    data.type = ModalType.ConfirmThreeButton;\r\n    const modalContent = this.openModalContent();\r\n    modalContent.data = data;\r\n    modalContent.confirmYes.subscribe(() => {\r\n      this.executeMethodUndefinedable(onYes);\r\n    });\r\n\r\n    modalContent.confirmNo.subscribe(() => {\r\n      this.executeMethodUndefinedable(onNo);\r\n    });\r\n\r\n    modalContent.close.subscribe(() => {\r\n      this.executeMethodUndefinedable(onCancel);\r\n    });\r\n  }\r\n\r\n  warning(message: string) {\r\n    this.open({\r\n      title: 'Warning',\r\n      message,\r\n      type: ModalType.Alert\r\n    });\r\n  }\r\n\r\n  async confirmPermission(query: CheckingPermissionModel, data: IModal, onYes?: () => void, onNo?: () => void) {\r\n    const result = await this.commonService.checkVoidBetPermission(query);\r\n    if (result.errCode !== 0 && query.action) {\r\n      const modalContent = this.openModalContent();\r\n      data.message = result.errMsg;\r\n      modalContent.data = data;\r\n      modalContent.confirm.subscribe(() => {\r\n        this.executeMethodUndefinedable(onNo);\r\n      });\r\n    } else {\r\n      this.executeMethodUndefinedable(onYes);\r\n    }\r\n  }\r\n\r\n  openModalContent() {\r\n    this.modalReference = this.ngbModal.open(ModalContentComponent, { centered: true });\r\n    return this.modalReference.componentInstance;\r\n  }\r\n\r\n  close() {\r\n    if (this.modalReference) {\r\n      this.modalReference.close();\r\n    }\r\n  }\r\n\r\n  private executeMethodUndefinedable(method?: () => void): void {\r\n    if (!_.isUndefined(method)) {\r\n      method();\r\n    }\r\n  }\r\n}","import { CommonModule } from '@angular/common';\r\nimport { NgModule } from '@angular/core';\r\nimport { NgbModalConfig, NgbModalModule } from '@ng-bootstrap/ng-bootstrap';\r\nimport { ClipboardModule } from 'ngx-clipboard';\r\nimport { PipeModule } from '../../pipes/pipe.module';\r\nimport { ModalContentComponent } from './modal-content/modal-content.component';\r\nimport { ModalService } from './modal.service';\r\n\r\n@NgModule({\r\n    imports: [ClipboardModule, CommonModule, NgbModalModule, PipeModule],\r\n    declarations: [ModalContentComponent],\r\n    exports: [ModalContentComponent],\r\n    providers: [ModalService, NgbModalConfig]\r\n})\r\nexport class ModalModule {}\r\n","import { CommonModule } from '@angular/common';\r\nimport { HttpClientModule } from '@angular/common/http';\r\nimport { NgModule } from '@angular/core';\r\nimport { FormsModule } from '@angular/forms';\r\nimport { NgbModule } from '@ng-bootstrap/ng-bootstrap';\r\nimport { NgSelectModule } from '@ng-select/ng-select';\r\n// import { AutoRefreshComponent } from './components/auto-refresh/auto-refresh.component';\r\n// import { BaseTicketsListComponent } from './components/base-tickets-list/base-tickets-list.component';\r\n// import { BetIdsComponent } from './components/bet-ids/bet-ids.component';\r\n// import { BetTypesVirtualSportComponent } from './components/bettypes-virtualsports/bettypes-virtualsports.component';\r\n// import { BetTypesComponent } from './components/bettypes/bettypes.component';\r\n import { ConfirmationComponent } from './components/confirmation/confirmation.component';\r\n// import { MatchDetailComponent } from './components/match-detail/match-detail.component';\r\n// import { MessagesResultComponent } from './components/messages-result/messages-result.component';\r\n// import { NotificationComponent } from './components/notification/notification.component';\r\nimport { UsernamesComponent } from './components/user-names/user-names.component';\r\n// import { OnlyNumberDirective } from './directives/number.directive';\r\n// import { NumbersOnlyDirective } from './directives/numbers-only.directive';\r\n// import { AdvancedModeModule } from './components/advanced-mode/advanced-mode.module';\r\n// import { DateTimeModule } from './components/date-time/date-time.module';\r\nimport { AdvancedModeModule } from './components/advanced-mode/advanced-mode.module';\r\nimport { AutoRefreshComponent } from './components/auto-refresh/auto-refresh.component';\r\nimport { BaseTicketsListComponent } from './components/base-tickets-list/base-tickets-list.component';\r\nimport { BetIdsComponent } from './components/bet-ids/bet-ids.component';\r\nimport { BetTypesVirtualSportComponent } from './components/bettypes-virtualsports/bettypes-virtualsports.component';\r\nimport { BetTypesComponent } from './components/bettypes/bettypes.component';\r\nimport { BlockFullUiModule } from './components/block-full-ui/block-full-ui.module';\r\nimport { BlockUiModule } from './components/block-ui/block-ui.module';\r\nimport { DateTimeModule } from './components/date-time/date-time.module';\r\nimport { MatchDetailComponent } from './components/match-detail/match-detail.component';\r\nimport { MenuBarComponent } from './components/menu-bar/menu-bar.component';\r\nimport { MessagesResultComponent } from './components/messages-result/messages-result.component';\r\nimport { ModalModule } from './components/modal/modal.module';\r\nimport { NotificationComponent } from './components/notification/notification.component';\r\nimport { PagingModule } from './components/paging/paging.module';\r\nimport { RequestInfoModule } from './components/request-info/request-info.module';\r\nimport { ToolTipModule } from './components/tooltip/tooltip.module';\r\nimport { OnlyNumberDirective } from './directives/number.directive';\r\nimport { NumbersOnlyDirective } from './directives/numbers-only.directive';\r\nimport { PipeModule } from './pipes/pipe.module';\r\nimport { CommonService } from './services/common.service';\r\nimport { HttpService } from './services/http.service';\r\n\r\n@NgModule({\r\n  imports: [\r\n    CommonModule,\r\n    FormsModule,\r\n    HttpClientModule,\r\n    ModalModule,\r\n    NgbModule,\r\n    PagingModule,\r\n    ToolTipModule,\r\n    NgSelectModule,\r\n    PipeModule,\r\n    // TemplateMessageModule,\r\n    AdvancedModeModule,\r\n    DateTimeModule,\r\n    BlockUiModule,\r\n    BlockFullUiModule,\r\n    RequestInfoModule\r\n  ],\r\n  declarations: [\r\n    UsernamesComponent,\r\n    MenuBarComponent,\r\n    AutoRefreshComponent,\r\n    BaseTicketsListComponent,\r\n    BetTypesComponent,\r\n    BetTypesVirtualSportComponent,\r\n    ConfirmationComponent,\r\n    MatchDetailComponent,\r\n    MessagesResultComponent,\r\n    NotificationComponent,\r\n    NumbersOnlyDirective,\r\n    OnlyNumberDirective,\r\n    BetIdsComponent,\r\n    AutoRefreshComponent\r\n  ],\r\n  exports: [\r\n    BaseTicketsListComponent,\r\n    BetTypesComponent,\r\n    BetTypesVirtualSportComponent,\r\n    ConfirmationComponent,\r\n    MatchDetailComponent,\r\n    MessagesResultComponent,\r\n    NotificationComponent,\r\n    NumbersOnlyDirective,\r\n    OnlyNumberDirective,\r\n    BetIdsComponent,\r\n    AutoRefreshComponent,\r\n    UsernamesComponent,\r\n    MenuBarComponent,\r\n    BlockFullUiModule\r\n  ],\r\n  providers: [HttpService, CommonService]\r\n})\r\nexport class UtilityModule {}\r\n","import { RedCardModel } from '../../add-request/app/add-request/models/event-red-card.model';\r\nimport { ReducedOverModel } from '../../add-request/app/add-request/models/event-reduced-over.model';\r\nimport { WrongHdpModel } from '../../add-request/app/add-request/models/event-wrong-hdp.model';\r\nimport { WrongOddsModel } from '../../add-request/app/add-request/models/event-wrong-odds.model';\r\nimport { WrongOuModel } from '../../add-request/app/add-request/models/event-wrong-ou.model';\r\nimport { WrongScoreModel } from '../../add-request/app/add-request/models/event-wrong-score.model';\r\nimport { OperatorInfo } from '../../add-request/app/add-request/others/others.model';\r\nimport { Message } from '../../utility/components/template-message/messages/message';\r\n\r\nexport class RequestDetailModel {\r\n  sportType: number;\r\n  issueTypeId: number;\r\n  actionId: number;\r\n  mistakenBy: string;\r\n  decidedBy: string;\r\n  operators: OperatorInfo[];\r\n  provider: string;\r\n  source: string;\r\n  remark: string;\r\n  isTest: boolean;\r\n  isVoided: boolean;\r\n  requestedBy: string;\r\n  userId: number;\r\n  voidedBy: string;\r\n}\r\n\r\nexport class RequestEventModel {\r\n  matchId: number;\r\n  subIssueTypeId: number;\r\n  eventDate: Date;\r\n  parentId: number;\r\n  leagueId: number;\r\n  homeId: number;\r\n  awayId: number;\r\n  kickOffTime: Date;\r\n  transIds: string;\r\n  htHomeScore?: number;\r\n  htAwayScore?: number;\r\n  finalHomeScore?: number;\r\n  finalAwayScore?: number;\r\n  liveScores?: string;\r\n  globalShowTime: Date;\r\n  filterFromTransTime?: Date;\r\n  filterToTransTime?: Date;\r\n  aaTime?: number;\r\n  paTime? : number;\r\n  saTime? : number;\r\n  filterBy?: number;\r\n  singleCount?: number;\r\n  mainParlayCount?: number;\r\n  minSingleTransId?: number;\r\n  maxSingleTransId?: number;\r\n  minMainParlayTransId?: number;\r\n  maxMainParlayTransId?: number;\r\n  voidFromTime: Date;\r\n  voidToTime: Date;\r\n  usernames?: string;\r\n  productIds?: string;\r\n  statusIds?: string;\r\n  fromDate?: string;\r\n  toDate?: string;\r\n}\r\n\r\nexport class RequestDetailViewModel {\r\n  requestId: number;\r\n  lastModifiedDate: Date;\r\n  request: RequestDetailModel;\r\n  event: RequestEventModel;\r\n  wrongScoreModels: WrongScoreModel[];\r\n  dangerAcceptedModels: RedCardModel[];\r\n  redCardModels: RedCardModel[];\r\n  wrongHdpModels: WrongHdpModel[];\r\n  wrongOuModels: WrongOuModel[];\r\n  wrongOddsModels: WrongOddsModel[];\r\n  reducedOverModels: ReducedOverModel[];\r\n  messages: Message[];\r\n}\r\n","export class IssueTypeConstant {\r\n  static readonly ABNORMAL_BET = '11';\r\n  static readonly ABNORMAL_BET_REAL_MEMBER = '15';\r\n  static readonly ABNORMAL_ACCOUNT = '13';\r\n  static readonly EARLY_KICK_OFF = '8';\r\n  static readonly WRONG_KICK_OFF = '9';\r\n  static readonly DANGER_ACCEPTED = '1';\r\n  static readonly RED_CARD = '10';\r\n  static readonly WRONG_ODDS = '2';\r\n  static readonly WRONG_SCORE = '3';\r\n  static readonly WRONG_OU = '6';\r\n  static readonly WRONG_1ST_OU = '7';\r\n  static readonly WRONG_HDP = '4';\r\n  static readonly WRONG_1ST_HDP = '5';\r\n  static readonly WRONG_QUARTER_HDP = '16';\r\n  static readonly ARCHIVED_TICKET = '17';\r\n  static readonly OTHER_ISSUES = '18';\r\n  static readonly REDUCED_OVER = '19';\r\n}","export class CONFIG {\r\n  static readonly EXPORT_EXCEL_LIMITED = 100000;\r\n  static readonly TICKET_LISTING_LIMITED = 200000;\r\n}\r\n\r\nexport class LABELS {\r\n  static readonly INVALID_MATCHID = 'Invalid MatchId.';\r\n  static readonly INVALID_REQUESTID = 'Invalid RequestId.';\r\n  static readonly USERNAME_TITLE = 'Username';\r\n  static readonly EVENT_TITLE = 'Event';\r\n  static readonly INVALID_BETID = 'All BetID(s) must be valid.';\r\n  static readonly INVALID_FROMBETID = 'Invalid From BetID.';\r\n  static readonly INVALID_TOBETID = 'Invalid To BetID.';\r\n  static readonly INVALID_DATETIME = 'Invalid Transdate';\r\n  static readonly INVALID_BETIDS = 'Invalid BetID(s) are highlighted in RED.';\r\n  static readonly REQUIRED_MATCHID = 'MatchId is required.';\r\n  static readonly REQUIRED_BETIDS = 'Bet ID is required.';\r\n  static readonly REQUIRED_FROMBETID = 'From BetID is required.';\r\n  static readonly REQUIRED_TOBETID = 'To BetID is required.';\r\n  static readonly REQUIRED_SUB_TYPE = 'Sub issue type is required.';\r\n  static readonly REQUIRED_HDP_VALUE = 'Hdp value is required.';\r\n  static readonly REQUIRED_HOME_FAVORITE = 'Home Favorite is required.';\r\n  static readonly REQUIRED_AWAY_FAVORITE = 'Away Favorite is required.';\r\n  static readonly REQUIRED_ACTUAL_MARKET = 'Actual Market is required.';\r\n  static readonly REQUIRED_WRONG_MARKET = 'Wrong Market is required.';\r\n\r\n  static readonly REQUIRED_CUSTOMER_NAME = 'Customer Name is required.';\r\n  static readonly REQUIRED_MEMBER = 'Member is required.';\r\n  static readonly REQUIRED_ACTUAL_SCORE = 'Actual Score is required.';\r\n\r\n  static readonly REQUIRED_USERNAME = 'Username is required.';\r\n  static readonly REQUIRED_PRODUCT = 'Products is required.';\r\n  static readonly REQUIRED_TICKET_STATUS = 'Ticket status is required.';\r\n\r\n  static readonly INVALID_USERNAMES = 'All Username(s) must be valid.';\r\n  static readonly MAX_USERNAME_EXCEEDED = 'Max Username Exceeded.';\r\n  static readonly INVALID_USERNAME = 'Invalid username';\r\n\r\n  static readonly EMPTY_LICENSEE = 'At least one Licensee  must be selected.';\r\n  static readonly EMPTY_CURRENCY = 'At least one Currency  must be selected.';\r\n  static readonly EMPTY_TICKET = 'At least one ticket must be selected.';\r\n  static readonly EMPTY_MATCH = 'At least one match must be selected.';\r\n  static readonly EMPTY_USER = 'At least one user must be selected.';\r\n  static readonly EMPTY_BETTYPE = 'At least one bettype must be selected.';\r\n  static readonly INVALID_TRANSDATE = 'Invalid Trans Date';\r\n  static readonly EMPTY_REQUEST = 'Please input Request No.';\r\n\r\n  static readonly INPUT_REASON = 'Please input reason.';\r\n  static readonly INPUT_PASSWORD = 'Please input password.';\r\n\r\n  static readonly EMPTY_ENGLISH = 'You must enter English message.';\r\n  static readonly INVALID_ENGLISH = 'You must include @@ in English message for replacing ticket number.';\r\n  static readonly EMPTY_CHINESE_TRADITIONAL = 'You must enter Chinese Traditional message.';\r\n  static readonly INVALID_CHINESE_TRADITIONAL = 'You must include @@ in Chinese Traditional message for replacing ticket number.';\r\n  static readonly EMPTY_CHINESE_SIMPLIFIED = 'You must enter Chinese Simplified message.';\r\n  static readonly INVALID_CHINESE_SIMPLIFIED = 'You must include @@ in Chinese Simplified message for replacing ticket number.';\r\n  static readonly EMPTY_NEW_CHINESE_SIMPLIFIED = 'You must enter New Chinese Simplified message.';\r\n  static readonly INVALID_NEW_CHINESE_SIMPLIFIED = 'You must include @@ in New Chinese Simplified message for replacing ticket number.';\r\n  static readonly INVALID_THAI = 'You must include @@ in Thai message for replacing ticket number.';\r\n  static readonly INVALID_KOREAN = 'You must include @@ in Korean message for replacing ticket number.';\r\n  static readonly INVALID_JAPANESE = 'You must include @@ in Japanese message for replacing ticket number.';\r\n  static readonly INVALID_ITALIAN = 'You must include @@ in Italian message for replacing ticket number.';\r\n  static readonly INVALID_SPANISH = 'You must include @@ in Spanish message for replacing ticket number.';\r\n  static readonly INVALID_MATCH = 'Invalid match';\r\n  static readonly INVALID_BET_ID = 'Invalid BetID.';\r\n\r\n  static readonly CONFIRM_CHECK_BY = 'Are you sure you want to verify request ';\r\n  static readonly CONFIRM_UNCHECK_BY = 'Are you sure you want to unverify request ';\r\n\r\n  static readonly CONFIRM_NEGATIVE_CUSTORMER = 'This action could lead to a negative amount of Bet Credit of the following customers: ';\r\n  static readonly CONFIRM_VOID_ALL_TICKETS = 'Are you sure you want to proceed? Please confirm and wait for the notification.';\r\n  static readonly CONFIRM_MARK_TICKET = 'Are you sure you want to mark tickets?';\r\n  static readonly CONFIRM_UNMARK_TICKET = 'Are you sure you want to unmark tickets?';\r\n  static readonly CONFIRM_TVS_UNMARK_TICKET = 'Ticket(s) on request should be unmarked. Are you sure you want to process?';\r\n  static readonly CONFIRM_TVS_UNMARK_TICKET_AND_AUTO_CAL = 'Ticket(s) on request should be unmarked. ' +\r\n    'Do you want system auto calculate ticket if possible?';\r\n\r\n  static readonly CONFIRM_RECOVER_TICKET = 'Are you sure you want to recover selected tickets?';\r\n  static readonly CONFIRM_RECOVER_TICKET_IN_PAGE =\r\n    'Only selected tickets on present page will be recovered. Are you sure you want to proceed?';\r\n  static readonly WARNING_FILTER_OPTION_CHANGED =\r\n    'WARNING! The filter option was changed! \\nYou are about to back the page and try a new search.';\r\n\r\n  static readonly NO_CHECKED_BETTYPE = 'At least one bettype must be selected.';\r\n  static readonly NO_BETTYPE = 'No bet type is offered for the inputted matchid.';\r\n  static readonly NO_PARLAY_BETTYPE = 'No Parlay bet type is offered for the inputted matchid.';\r\n\r\n  static readonly NO_BET_TEAM = 'Please select at least one option!';\r\n\r\n  static readonly NO_PERMISSION = 'WARNING! Not allowed to mark settled ticket! You are about to back the page and try a new search.';\r\n\r\n  static readonly INVALID_HDP = 'Invalid HDP!';\r\n  static readonly INVALID_VALUE = 'Invalid Value!';\r\n\r\n  static readonly EXPORT_EXCEL_LIMITED = `We regret to inform you that data collected for this report exceeded the web site ' +\r\n    'rendering capability (> ${CONFIG.EXPORT_EXCEL_LIMITED} tickets). Please contact IT for help. Thank you!`;\r\n  static readonly TICKET_LISTING_LIMITED = `We regret to inform you that data collected for this report exceeded the web site ' +\r\n    'rendering capability (> ${CONFIG.TICKET_LISTING_LIMITED} tickets). Please change filter condition or contact IT for help. ` +\r\n    'Thank you !';\r\n  static readonly EXPORT_FROMDATE_BEFORE_BALANCEDAY = 'We regret to inform you that data collected for this report exceeded ' +\r\n    'the web site rendering capability.  We suggest that you should export and view this report in Excel format instead. Thank you !';\r\n  static readonly SEND_FILE = 'Are you sure you want to notify affected tickets to these Licensee(s): ';\r\n\r\n  static readonly NOTIFY_RECOVER_SETTLED_MATCH = 'The selected ticket(s) will return to \"Running\" status, ' +\r\n    'please resettle the match(es) to calculate it again.';\r\n\r\n  static readonly EXPORT_LARGE_FILE = 'Not allow to export large file. Please contact IT for help. Thank you!';\r\n\r\n  static readonly NO_RESULTS = 'No Results.';\r\n  static readonly NO_PERMISSION_ON_ISSUETYPES = 'You are not authorized on this function.';\r\n  static readonly INVALID_SETTLED_TICKETS = 'Settled ticket';\r\n  static readonly INVALID_UNSUPPORTED_TICKETS = 'Unsupported ticket';\r\n  static readonly INVALID_SINGLE_TICKETS = 'Single ticket';\r\n  static readonly INVALID_MIX_PARLAY_TICKETS = 'Mix Parlay ticket';\r\n  static readonly INVALID_EXISTING_ON_OTHER_REQUEST = 'Existing on other request';\r\n  static readonly INVALID_TICKETS = 'Invalid ticket';\r\n  static readonly INVALID_NONLIVE_TICKETS = 'Non-Live ticket';\r\n  static readonly INVALID_DIFFERENT_LIVE_SCORE = 'Different live score';\r\n  static readonly INVALID_AB_WHITE_LIST_TICKETS = 'AB Exception List ticket';\r\n  static readonly INVALID_UNSUPPORTED_DATE_RANGE_TICKETS = 'Unsupported date range';\r\n\r\n  static readonly ADD_REQUEST_RESULT_TITLE = 'Add Request Result';\r\n  static readonly EDIT_REQUEST_RESULT_TITLE = 'Edit Request Result';\r\n  static readonly INVALID_TIME_FORMAT = 'Invalid Date Time format. The correct format is \"HH:mm:ss.SSS AM/PM\"';\r\n  static readonly INVALID_TO_DATE = 'Invalid To Date';\r\n  static readonly MATCH_ID_EXISTS_IN_LIST = 'MatchId already exists in the list';\r\n  static readonly FROM_BET_ID_MUST_SMALLER_THAN_TO_BET_ID = 'From BetId must be smaller than To BetId';\r\n  static readonly FROM_TIME_MUST_SMALLER_THAN_TO_TIME = 'From Time must be smaller than To Time';\r\n  static readonly FROM_TIME_MUST_GREATER_THAN_DEFAULT = 'Edited From Time must be greater than the default From Time.';\r\n  static readonly TO_TIME_MUST_SMALLER_THAN_FOLLOWING_CONSECUTIVE_FROM_TIME = 'Edited To Time must be smaller than the default From Time of the following consecutive score.';\r\n  static readonly NO_VALID_TICKETS_IN_RANGE = 'No valid tickets found in the current range';\r\n  static readonly INVALID_SETTING_TIME = 'Please fulfill AA/PA/SA values or left all fields blank.';\r\n\r\n  static readonly SEN_DATA_RESULT_TITLE = 'Send Data Result';\r\n  static readonly ALL_TICKETS_VOIDED = 'All tickets has been voided';\r\n  static readonly INVALID_TEMPLATE_MESSAGE = 'Invalid template message.';\r\n  static readonly SELECTED_VAR_OPTIONS = 'Please select NO VAR/VAR.';\r\n}\r\n","export class RegexConstant {\r\n  static readonly MULTIPLE_DECIMAL = /^-?\\d{1,5}(\\.\\d{1,3})?(&-?\\d{1,5}(\\.\\d{1,3})?)*?$/;\r\n  static readonly SINGLE_DECIMAL = /^-?\\d{1,5}(\\.\\d{1,3})?$/;\r\n  static readonly ONLY_NUMBER = /^[0-9]*$/;\r\n}","import { NgbDate } from '@ng-bootstrap/ng-bootstrap';\r\nimport * as moment from 'moment-timezone';\r\nimport { GetLogInfoModel, ValidationMessage } from 'src/add-request/app/add-request/models/get-log-info.model';\r\nimport { RequestDetailViewModel } from '../../edit-request/app/request.model';\r\nimport { DateFullTimeNewComponent } from '../components/date-time/date-full-time-new/date-full-time-new.component';\r\nimport { ModalType } from '../components/modal/modal.model';\r\nimport { ModalService } from '../components/modal/modal.service';\r\nimport { Tooltip } from '../components/tooltip/tooltip.model';\r\nimport { DateTimeFormat, FunctionConst, SubIssueTypeGroup, TVSRequestActionType } from '../constants/config';\r\nimport { IssueTypeConstant } from '../constants/issue-type.constant';\r\nimport { LABELS } from '../constants/labels';\r\nimport { RegexConstant } from '../constants/regex';\r\n\r\nexport class StaticService {\r\n  static isVoidAction(actionId: number): boolean {\r\n    return actionId === TVSRequestActionType.MANUAL_VOID_ID\r\n      || actionId === TVSRequestActionType.AUTO_VOID_WINNING_ID\r\n      || actionId === TVSRequestActionType.AUTO_VOID_INSTANT_ID\r\n      || actionId === TVSRequestActionType.AUTO_VOID_5M_BEFORE_KO_ID\r\n      || actionId === TVSRequestActionType.AUTO_VOID_10M_BEFORE_KO_ID\r\n      || actionId === TVSRequestActionType.AUTO_VOID_INSTANT_WITHOUT_POLICY;\r\n  }\r\n\r\n  static isAbnormalBet(issueTypeId: string): boolean {\r\n    return issueTypeId === IssueTypeConstant.ABNORMAL_BET;\r\n  }\r\n\r\n  static isAbnormalBetRealMember(issueTypeId: string): boolean {\r\n    return issueTypeId === IssueTypeConstant.ABNORMAL_BET_REAL_MEMBER;\r\n  }\r\n\r\n  static isDangerAccepted(issueTypeId: string): boolean {\r\n    return issueTypeId === IssueTypeConstant.DANGER_ACCEPTED;\r\n  }\r\n\r\n  static isRedCard(issueTypeId: string): boolean {\r\n    return issueTypeId === IssueTypeConstant.RED_CARD;\r\n  }\r\n\r\n  static isWrongScore(issueTypeId: string): boolean {\r\n    return issueTypeId === IssueTypeConstant.WRONG_SCORE;\r\n  }\r\n\r\n  static isAbnormalAccount(issueTypeId: string): boolean {\r\n    return issueTypeId === IssueTypeConstant.ABNORMAL_ACCOUNT;\r\n  }\r\n\r\n  static isEarlyKickOff(issueTypeId: string): boolean {\r\n    return issueTypeId === IssueTypeConstant.EARLY_KICK_OFF;\r\n  }\r\n\r\n  static isWrongKickOff(issueTypeId: string): boolean {\r\n    return issueTypeId === IssueTypeConstant.WRONG_KICK_OFF;\r\n  }\r\n\r\n  static isWrongOdds(issueTypeId: string): boolean {\r\n    return issueTypeId === IssueTypeConstant.WRONG_ODDS;\r\n  }\r\n\r\n  static isWrongHDP(issueTypeId: string): boolean {\r\n    return issueTypeId === IssueTypeConstant.WRONG_HDP;\r\n  }\r\n\r\n  static isWrong1stHDP(issueTypeId: string): boolean {\r\n    return issueTypeId === IssueTypeConstant.WRONG_1ST_HDP;\r\n  }\r\n\r\n  static isWrongQuarterHDP(issueTypeId: string): boolean {\r\n    return issueTypeId === IssueTypeConstant.WRONG_QUARTER_HDP;\r\n  }\r\n\r\n  static isWrongOU(issueTypeId: string): boolean {\r\n    return issueTypeId === IssueTypeConstant.WRONG_OU;\r\n  }\r\n\r\n  static isWrong1stOU(issueTypeId: string): boolean {\r\n    return issueTypeId === IssueTypeConstant.WRONG_1ST_OU;\r\n  }\r\n\r\n  static isArchivedTicket(issueTypeId: string): boolean {\r\n    return issueTypeId === IssueTypeConstant.ARCHIVED_TICKET;\r\n  }\r\n\r\n  static isOtherIssues(issueTypeId: string): boolean {\r\n    return issueTypeId === IssueTypeConstant.OTHER_ISSUES;\r\n  }\r\n\r\n  static isReducedOver(issueTypeId: string): boolean {\r\n    return issueTypeId === IssueTypeConstant.REDUCED_OVER;\r\n  }\r\n\r\n  static convertToFullDate(ngbDate: NgbDate): string {\r\n    const transformMonth = `0${ngbDate.month}`.slice(-2);\r\n    const transformDay = `0${ngbDate.day}`.slice(-2);\r\n\r\n    return `${ngbDate.year}/${transformMonth}/${transformDay}`;\r\n  }\r\n\r\n  static getSubIssueTypeId(requestDetail: RequestDetailViewModel): number {\r\n    if (this.isWrongScore(requestDetail.request.issueTypeId.toString())) {\r\n      return requestDetail.wrongScoreModels[0].subIssueTypeId;\r\n    } else if (this.isDangerAccepted(requestDetail.request.issueTypeId.toString())) {\r\n      return requestDetail.dangerAcceptedModels.find(x => x.isMainMatch).subIssueTypeId;\r\n    } else if (this.isRedCard(requestDetail.request.issueTypeId.toString())) {\r\n      return requestDetail.redCardModels.find(x => x.isMainMatch).subIssueTypeId;\r\n    } else if (this.isWrongHDP(requestDetail.request.issueTypeId.toString()) || this.isWrong1stHDP(requestDetail.request.issueTypeId.toString())) {\r\n      return requestDetail.wrongHdpModels.find(x => x.isMainMatch).subIssueTypeId;\r\n    } else if (this.isWrongOU(requestDetail.request.issueTypeId.toString()) || this.isWrong1stOU(requestDetail.request.issueTypeId.toString())) {\r\n      return requestDetail.wrongOuModels.find(x => x.isMainMatch).subIssueTypeId;\r\n    } else if (this.isWrongOdds(requestDetail.request.issueTypeId.toString())) {\r\n      return requestDetail.wrongOddsModels[0].subIssueTypeId;\r\n    } else if (this.isReducedOver(requestDetail.request.issueTypeId.toString())) {\r\n      return requestDetail.reducedOverModels[0].subIssueTypeId;\r\n    } else {\r\n      return requestDetail.event.subIssueTypeId;\r\n    }\r\n  }\r\n\r\n  static getEventDate(requestDetail: RequestDetailViewModel): Date {\r\n    if (this.isWrongScore(requestDetail.request.issueTypeId.toString())) {\r\n      return requestDetail.wrongScoreModels[0].eventDate;\r\n    } else if (this.isDangerAccepted(requestDetail.request.issueTypeId.toString())) {\r\n      return requestDetail.dangerAcceptedModels.find(x => x.isMainMatch).eventDate;\r\n    } else if (this.isRedCard(requestDetail.request.issueTypeId.toString())) {\r\n      return requestDetail.redCardModels.find(x => x.isMainMatch).eventDate;\r\n    } else if (this.isWrongHDP(requestDetail.request.issueTypeId.toString()) || this.isWrong1stHDP(requestDetail.request.issueTypeId.toString())) {\r\n      return requestDetail.wrongHdpModels.find(x => x.isMainMatch).eventDate;\r\n    } else if (this.isWrongOU(requestDetail.request.issueTypeId.toString()) || this.isWrong1stOU(requestDetail.request.issueTypeId.toString())) {\r\n      return requestDetail.wrongOuModels.find(x => x.isMainMatch).eventDate;\r\n    } else if (this.isWrongOdds(requestDetail.request.issueTypeId.toString())) {\r\n      return requestDetail.wrongOddsModels[0].eventDate;\r\n    }  else if (this.isReducedOver(requestDetail.request.issueTypeId.toString())) {\r\n      return requestDetail.reducedOverModels[0].eventDate;\r\n    }else {\r\n      return requestDetail.event.eventDate;\r\n    }\r\n  }\r\n\r\n  static checkHandlingCashOutAsUnSettledTicketByFunction(functionId: number): boolean {\r\n    return functionId === FunctionConst.SINGLE;\r\n  }\r\n\r\n  static checkHandlingCashOutAsUnSettledTicketByIssueTypeId(issueTypeId: string): boolean {\r\n    return issueTypeId === IssueTypeConstant.DANGER_ACCEPTED ||\r\n      issueTypeId === IssueTypeConstant.RED_CARD ||\r\n      issueTypeId === IssueTypeConstant.WRONG_SCORE ||\r\n      issueTypeId === IssueTypeConstant.EARLY_KICK_OFF ||\r\n      issueTypeId === IssueTypeConstant.WRONG_KICK_OFF;\r\n  }\r\n\r\n  static isShowCountInfo(cashOutCount: number, settleCount: number, instantlySettleCount: number) {\r\n    return this.isShowCashOutCount(cashOutCount) || this.isShowSettleCount(settleCount)\r\n      || this.isShowInstantlySettleIncluded(instantlySettleCount);\r\n  }\r\n\r\n  static isShowCashOutCount(cashOutCount: number): boolean {\r\n    return (cashOutCount > 0) ? true : false;\r\n  }\r\n\r\n  static isShowSettleCount(settleCount: number): boolean {\r\n    return (settleCount > 0) ? true : false;\r\n  }\r\n\r\n  static isShowInstantlySettleIncluded(instantlySettleCount: number): boolean {\r\n    return (instantlySettleCount > 0) ? true : false;\r\n  }\r\n\r\n  static countInfoContent(cashOutCount: number, settleCount: number, instantlySettleCount: number) {\r\n    const info: string[] = [];\r\n    if (this.isShowCashOutCount(cashOutCount)) {\r\n      info.push(`Cash Out: <strong>${cashOutCount}</strong>`);\r\n    }\r\n\r\n    if (this.isShowSettleCount(settleCount)) {\r\n      info.push(`Settled: <strong>${settleCount}</strong>`);\r\n    }\r\n\r\n    if (this.isShowInstantlySettleIncluded(instantlySettleCount)) {\r\n      info.push(`Instantly Settled: <strong>${instantlySettleCount}</strong>`);\r\n    }\r\n\r\n    return ` (${info.join(', ')})`;\r\n  }\r\n\r\n  static isFromTimeSameOrBeforeToTime(fromDateTime: string, toDateTime: string, tooltip: Tooltip, fromDateTimeClass: string): boolean {\r\n    const momentFromDateTime = moment(fromDateTime, DateTimeFormat.FULL_DATE_TIME_FORMAT);\r\n    const momentToDateTime = moment(toDateTime, DateTimeFormat.FULL_DATE_TIME_FORMAT);\r\n    if (!momentFromDateTime.isSameOrBefore(momentToDateTime)) {\r\n      tooltip.display(fromDateTimeClass, LABELS.FROM_TIME_MUST_SMALLER_THAN_TO_TIME);\r\n      return false;\r\n    }\r\n\r\n    return true;\r\n  }\r\n\r\n  static isShowVarCheck(subIssueTypeId: number) {\r\n    return subIssueTypeId && SubIssueTypeGroup.SUBTYPE_VAR.includes(subIssueTypeId);\r\n  }\r\n\r\n  static isHaveCancelCashOutTicket(issueTypeId: string): boolean {\r\n    return issueTypeId === IssueTypeConstant.DANGER_ACCEPTED ||\r\n      issueTypeId === IssueTypeConstant.RED_CARD ||\r\n      issueTypeId === IssueTypeConstant.WRONG_SCORE;\r\n  }\r\n  \r\n  static getDurationTime(fromTimeComponent: DateFullTimeNewComponent, toTimeComponent: DateFullTimeNewComponent, filterFromTransTime: string, filterToTransTime: string): string {\r\n    if (!fromTimeComponent?.isTimeValid() || !toTimeComponent?.isTimeValid()) {\r\n      return '-';\r\n    }\r\n\r\n    const fromTime = moment(filterFromTransTime, DateTimeFormat.FULL_DATE_TIME_FORMAT);\r\n    const toTime = moment(filterToTransTime, DateTimeFormat.FULL_DATE_TIME_FORMAT);\r\n    const durations = toTime.diff(fromTime);\r\n    const minutes = Math.floor(durations / 60000);\r\n    const seconds = ((durations % 60000) / 1000).toFixed(0);\r\n\r\n    return `${minutes}m${seconds}s`;\r\n  }\r\n\r\n  static isCorrectFormatMultipleDecimal(value: string, element: string, tooltip: Tooltip, errorText: string): boolean {\r\n    if (!StaticService.isCorrectRegexMultipleDecimal(value)) {\r\n      tooltip.display(element, errorText);\r\n      return false;\r\n    }\r\n    tooltip.hide();\r\n\r\n    return true;\r\n  }\r\n\r\n  static isCorrectFormatSingleDecimal(value: string, element: string, tooltip: Tooltip, errorText: string): boolean {\r\n    if (!StaticService.isCorrectRegexSingleDecimal(value)) {\r\n      tooltip.display(element, errorText);\r\n      return false;\r\n    }\r\n    tooltip.hide();\r\n\r\n    return true;\r\n  }\r\n\r\n  static isCorrectFormatOnlyNumber(value: string, element: string, tooltip: Tooltip, errorText: string): boolean {\r\n    if (!StaticService.isCorrectRegexOnlyNumber(value)) {\r\n      tooltip.display(element, errorText);\r\n      return false;\r\n    }\r\n    tooltip.hide();\r\n\r\n    return true;\r\n  }\r\n\r\n  static isCorrectRegexSingleDecimal(value: string): boolean {\r\n    return RegexConstant.SINGLE_DECIMAL.test(value);\r\n  }\r\n\r\n  static isCorrectRegexMultipleDecimal(value: string): boolean {\r\n    return RegexConstant.MULTIPLE_DECIMAL.test(value);\r\n  }\r\n\r\n  static isCorrectRegexOnlyNumber(value: string): boolean {\r\n    return RegexConstant.ONLY_NUMBER.test(value);\r\n  }\r\n\r\n  static isStringHasLength(value: string): boolean {\r\n    return value && value.length > 0;\r\n  }\r\n\r\n  static convertStringToBetId8xxx(text: string): string {\r\n    if (!this.isStringHasLength(text)) {\r\n      return null;\r\n    }\r\n\r\n    const LENGTH_OF_OVER = 3;\r\n    const PREFIX = '8';\r\n    let value = text;\r\n    if (value.length < LENGTH_OF_OVER && value.length > 0) {\r\n      value = value.padStart(LENGTH_OF_OVER, '0');\r\n    }\r\n\r\n    return `${PREFIX}${value}`;\r\n  }\r\n\r\n  static openPopupTransIds(requestId: number, transIds: string, modalService: ModalService): void {\r\n    modalService.open(\r\n      {\r\n        title: `List tickets existed in Request: ${requestId} (Click on the list to copy)`,\r\n        type: ModalType.Alert,\r\n        copyContent: true,\r\n        content: [{ title: 'Tickets:', message: transIds }]\r\n      });\r\n  }\r\n\r\n  static getValidationMessageList(logInfoModel: GetLogInfoModel): ValidationMessage[] {\r\n    const messageList: ValidationMessage[] = [];\r\n    if (logInfoModel.validation.isInvalidTotalTickets) {\r\n      messageList.push({\r\n        isError: true,\r\n        reason: LABELS.NO_VALID_TICKETS_IN_RANGE\r\n      });\r\n    }\r\n    if (logInfoModel.validation.isExistedInOtherRequest) {\r\n      logInfoModel.ticketRequest.forEach(request => {\r\n        const message: ValidationMessage = {\r\n          isError: false,\r\n          reason: `Tickets ${request.transIds} existed in Request: ${request.requestId}`\r\n        };\r\n\r\n        const transIds = request.transIds.split(\",\");\r\n        if (transIds.length > 8) {\r\n          message.isShowPopup = true;\r\n          message.reason = `Tickets ${transIds.slice(0, 8).join(\",\")},... existed in Request: ${request.requestId}`;\r\n          message.requestId = request.requestId;\r\n          message.transIds = request.transIds;\r\n        }\r\n\r\n        messageList.push(message);\r\n      });\r\n    }\r\n\r\n    return messageList;\r\n  }\r\n}","import { Injectable } from '@angular/core';\r\nimport { RequestDetailViewModel } from '../../edit-request/app/request.model';\r\nimport { VoidedReason } from '../../utility/models/reason.model';\r\nimport { Result } from '../../utility/models/result';\r\nimport { HttpService } from '../../utility/services/http.service';\r\nimport { GetTicketsQuery } from './models/get-tickets.query';\r\nimport { RequestLastModifiedDate } from './models/request-last-modified-date.model';\r\nimport { InsertQueueResult, VoidTicketsQuery } from './models/void-tickets.query';\r\nimport { TicketsModel } from './tickets-list/tickets.model';\r\n\r\n@Injectable({\r\n  providedIn: 'root'\r\n})\r\nexport class AppService {\r\n  constructor(private readonly httpService: HttpService) {}\r\n\r\n  async getRemark(): Promise<string[]> {\r\n    return this.httpService.getJson(`api/VoidRequest/GetRemark`);\r\n  }\r\n\r\n  async getRequestById(id: number): Promise<RequestDetailViewModel> {\r\n    return this.httpService.getJson(`api/ManageRequest/GetRequest/${id}`);\r\n  }\r\n\r\n  async getTickets(query: GetTicketsQuery): Promise<TicketsModel> {\r\n    return this.httpService.postJson(query, 'api/VoidRequest/GetTickets');\r\n  }\r\n\r\n  async getTicketsMini(query: GetTicketsQuery): Promise<TicketsModel> {\r\n    return this.httpService.postJson(query, 'api/VoidRequest/GetTicketsMini');\r\n  }\r\n\r\n  async getVoidedReason(subId: number, sportTypeId: number): Promise<VoidedReason> {\r\n    return this.httpService.postJson({subId: subId, sportTypeId: sportTypeId}, `api/VoidRequest/GetVoidedReason`);\r\n  }\r\n\r\n  async insertQueue(query: VoidTicketsQuery): Promise<Result<InsertQueueResult>> {\r\n    return this.httpService.postJson(query, 'api/VoidRequest/InsertQueue');\r\n  }\r\n\r\n  async exportExcel(query: GetTicketsQuery) {\r\n    const url = 'api/VoidRequest/ExportExcel';\r\n    return this.httpService.downloadFile(query, url);\r\n  }\r\n\r\n  async getLastModifiedDate(requestId: number): Promise<RequestLastModifiedDate> {\r\n    return this.httpService.postJson({requestId}, `api/VoidRequest/GetLastModifiedDate`);\r\n  }\r\n}\r\n","// Copyright (c) .NET Foundation. All rights reserved.\r\n// Licensed under the Apache License, Version 2.0. See License.txt in the project root for license information.\r\nvar __extends = (this && this.__extends) || (function () {\r\n    var extendStatics = Object.setPrototypeOf ||\r\n        ({ __proto__: [] } instanceof Array && function (d, b) { d.__proto__ = b; }) ||\r\n        function (d, b) { for (var p in b) if (b.hasOwnProperty(p)) d[p] = b[p]; };\r\n    return function (d, b) {\r\n        extendStatics(d, b);\r\n        function __() { this.constructor = d; }\r\n        d.prototype = b === null ? Object.create(b) : (__.prototype = b.prototype, new __());\r\n    };\r\n})();\r\n/** Error thrown when an HTTP request fails. */\r\nvar HttpError = /** @class */ (function (_super) {\r\n    __extends(HttpError, _super);\r\n    /** Constructs a new instance of {@link @microsoft/signalr.HttpError}.\r\n     *\r\n     * @param {string} errorMessage A descriptive error message.\r\n     * @param {number} statusCode The HTTP status code represented by this error.\r\n     */\r\n    function HttpError(errorMessage, statusCode) {\r\n        var _newTarget = this.constructor;\r\n        var _this = this;\r\n        var trueProto = _newTarget.prototype;\r\n        _this = _super.call(this, errorMessage) || this;\r\n        _this.statusCode = statusCode;\r\n        // Workaround issue in Typescript compiler\r\n        // https://github.com/Microsoft/TypeScript/issues/13965#issuecomment-278570200\r\n        _this.__proto__ = trueProto;\r\n        return _this;\r\n    }\r\n    return HttpError;\r\n}(Error));\r\nexport { HttpError };\r\n/** Error thrown when a timeout elapses. */\r\nvar TimeoutError = /** @cla