          throw new Error(\"A reconnectPolicy has already been set.\");\r\n        }\r\n        if (!retryDelaysOrReconnectPolicy) {\r\n            this.reconnectPolicy = new DefaultReconnectPolicy();\r\n        }\r\n        else if (Array.isArray(retryDelaysOrReconnectPolicy)) {\r\n            this.reconnectPolicy = new DefaultReconnectPolicy(retryDelaysOrReconnectPolicy);\r\n        }\r\n        else {\r\n            this.reconnectPolicy = retryDelaysOrReconnectPolicy;\r\n        }\r\n        return this;\r\n    };\r\n    /** Creates a {@link @microsoft/signalr.HubConnection} from the configuration options specified in this builder.\r\n     *\r\n     * @returns {HubConnection} The configured {@link @microsoft/signalr.HubConnection}.\r\n     */\r\n    HubConnectionBuilder.prototype.build = function () {\r\n        // If httpConnectionOptions has a logger, use it. Otherwise, override it with the one\r\n        // provided to configureLogger\r\n        var httpConnectionOptions = this.httpConnectionOptions || {};\r\n        // If it's 'null', the user **explicitly** asked for null, don't mess with it.\r\n        if (httpConnectionOptions.logger === undefined) {\r\n            // If our logger is undefined or null, that's OK, the HttpConnection constructor will handle it.\r\n            httpConnectionOptions.logger = this.logger;\r\n        }\r\n        // Now create the connection\r\n        if (!this.url) {\r\n            throw new Error(\"The 'HubConnectionBuilder.withUrl' method must be called before building the connection.\");\r\n        }\r\n        var connection = new HttpConnection(this.url, httpConnectionOptions);\r\n        return HubConnection.create(connection, this.logger || NullLogger.instance, this.protocol || new JsonHubProtocol(), this.reconnectPolicy);\r\n    };\r\n    return HubConnectionBuilder;\r\n}());\r\nexport { HubConnectionBuilder };\r\nfunction isLogger(logger) {\r\n    return logger.log !== undefined;\r\n}\r\n","\r\nexport class VoidBetResultCode {\r\n    static readonly VOID_REQUEST_SUCCESS = 238;\r\n    static readonly LICENSEE_SUCCESS = 236;\r\n    static readonly LICENSEE_FAIL = 136;\r\n    static readonly SEND_LETSTALK_FAIL = 137;\r\n    static readonly EXCEPTION_RUN_AFTER_VOID = 134;\r\n}","import { EventEmitter, Injectable } from '@angular/core';\r\nimport * as signalR from '@microsoft/signalr';\r\nimport { ToastrService } from 'ngx-toastr';\r\nimport { VoidBetResultCode } from '../constants/void-bet-result-code';\r\nimport { RequestStatus, Result } from '../models/signal-r.model';\r\n\r\n@Injectable({\r\n  providedIn: 'root'\r\n})\r\nexport class SignalRService {\r\n  public hubConnection: signalR.HubConnection;\r\n  public requestStatusChange = new EventEmitter<RequestStatus[]>();\r\n\r\n  constructor(private toastr: ToastrService) { }\r\n\r\n  public async initializeConnection(): Promise<void> {\r\n    this.configToastr();\r\n    this.hubConnection = new signalR.HubConnectionBuilder()\r\n      .withUrl(`${window.location.origin}${document.body.getAttribute('root-url')}SignalR/NotificationHub`)\r\n      .configureLogging(signalR.LogLevel.Trace)\r\n      .build();\r\n\r\n    this.registerShowVoidResultEvent(this.hubConnection);\r\n    this.registerShowErrorMessage(this.hubConnection);\r\n    this.registerReceiveRequestStatusModelEvent(this.hubConnection);\r\n    await this.hubConnection.start();\r\n  }\r\n\r\n  private registerShowVoidResultEvent(connection: signalR.HubConnection): void {\r\n    connection.on('showVoidResult', (results: Result[]) => {\r\n      this.showMessageForVoidResult(results);\r\n    });\r\n  }\r\n\r\n  private registerShowErrorMessage(connection: signalR.HubConnection) {\r\n    connection.on('showErrorMessage', (message: string) => {\r\n      this.toastr.error(message);\r\n    });\r\n  }\r\n\r\n  private registerReceiveRequestStatusModelEvent(connection: signalR.HubConnection): void {\r\n    connection.on('updateRequestStatus', (model: RequestStatus[]) => {\r\n      this.requestStatusChange.emit(model);\r\n    });\r\n  }\r\n\r\n  private configToastr(): void {\r\n    this.toastr.toastrConfig.enableHtml = true;\r\n    this.toastr.toastrConfig.disableTimeOut = true;\r\n    this.toastr.toastrConfig.closeButton = true;\r\n    this.toastr.toastrConfig.toastClass = 'custom-toastr ngx-toastr';\r\n    this.toastr.toastrConfig.positionClass = 'toast-bottom-right';\r\n    this.toastr.toastrConfig.easeTime = 200;\r\n  }\r\n\r\n  private showMessageForVoidResult(results: Result[]): void {\r\n    const exceptionResult = results.find(x => x.errorCode === VoidBetResultCode.EXCEPTION_RUN_AFTER_VOID);\r\n    if (exceptionResult) {\r\n      this.toastr.error(`<i class=\"fa-solid fa-triangle-exclamation icon\"></i> ${exceptionResult.errorMsg}`);\r\n      return;\r\n    }\r\n\r\n    let succeedLicenseeMsg = '';\r\n    let failedLicenseeMsg = '';\r\n    let failedSentLetsTalkMsg = '';\r\n    const voidRequestMsg = results.find(x => x.errorCode === VoidBetResultCode.VOID_REQUEST_SUCCESS)?.errorMsg;\r\n    const succeedLicenseeResult = results.find(x => x.errorCode === VoidBetResultCode.LICENSEE_SUCCESS);\r\n    const failedLicenseeResult = results.find(x => x.errorCode === VoidBetResultCode.LICENSEE_FAIL);\r\n    const failedSentLetsTalkResult = results.find(x => x.errorCode === VoidBetResultCode.SEND_LETSTALK_FAIL);\r\n\r\n    if (succeedLicenseeResult?.errorMsg) {\r\n      succeedLicenseeMsg = `<div><span>- ${succeedLicenseeResult.errorMsg}</span></div>`;\r\n    }\r\n    if (failedLicenseeResult?.errorMsg) {\r\n      failedLicenseeMsg = `<div class=\"failed-msg\"><i class=\"fa-solid fa-triangle-exclamation icon\"></i><span class=\"msg\"> ${failedLicenseeResult.errorMsg}</span></div>`;\r\n    }\r\n    if (failedSentLetsTalkResult?.errorMsg) {\r\n      failedSentLetsTalkMsg = `<div class=\"failed-msg\"><i class=\"fa-solid fa-triangle-exclamation icon\"></i><span class=\"msg\"> ${failedSentLetsTalkResult.errorMsg}</span></div>`;\r\n    }\r\n\r\n    const finalMessage = `<div class=\"void-bet-notification\"><div><span>- ${voidRequestMsg}</span></div>${succeedLicenseeMsg}${failedLicenseeMsg}${failedSentLetsTalkMsg}</div>`;\r\n    if (failedLicenseeMsg || failedSentLetsTalkMsg) {\r\n      this.toastr.warning(finalMessage);\r\n      return;\r\n    }\r\n\r\n    this.toastr.success(finalMessage);\r\n  }\r\n}\r\n","export class MenuName {\r\n  static readonly AB_EXCEPTION_LIST = 'AB Exception List';\r\n  static readonly MARK_UNMARK_TICKETS = 'Mark/Unmark Tickets';\r\n  static readonly TICKET_LISTING = 'Ticket Listing';\r\n  static readonly VOID_SINGLE_BET = 'Void Single Bet';\r\n  static readonly MANAGE_REQUEST = 'Manage Request';\r\n  static readonly ADD_REQUEST = 'Add Request';\r\n}","<div class=\"menu-bar\">\r\n  <div class=\"header-user-info user-info-background\">\r\n    <a class=\"logo\" href=\"{{rootUrl}}?ref=logo\">&nbsp;</a>\r\n    <div class=\"user-info\">\r\n      <div class=\"dropdown\">\r\n        <div class=\"dropdown-user-info\">\r\n          <i class=\"fa-solid fa-user\"></i>&nbsp; Welcome,&nbsp; <span class=\"user-name\">{{username}}</span> &nbsp;<i class=\"fa-solid fa-sort-down\"></i>\r\n        </div>\r\n        <div class=\"dropdown-content\">\r\n          <li>\r\n            <a class=\"nav-link\" href=\"{{oldSiteAbsoluteUrl}}Auth/ChangePassword\">Change Password</a>\r\n          </li>\r\n          <li>\r\n            <a class=\"nav-link\" href=\"{{oldSiteAbsoluteUrl}}Auth/LogOut\">Sign Out</a>\r\n          </li>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <nav class=\"nav-tvs-expand navbar navbar-expand bg-header-tvs\">\r\n    <div class=\"container-fluid\">\r\n      <div class=\"collapse navbar-collapse\" id=\"main_nav\">\r\n        <ul class=\"navbar-nav\">\r\n          <div *ngFor=\"let menuItem of menuItems\">\r\n            <div *ngIf=\"menuItem.items.length === 0\">\r\n              <li class=\"nav-item\">\r\n                <a class=\"nav-link\" href=\"{{menuItem.url}}\">{{menuItem.name}}</a>\r\n              </li>\r\n            </div>\r\n            <div *ngIf=\"menuItem.items.length > 0\">\r\n              <li class=\"nav-item dropdown\">\r\n                <a class=\"nav-link  dropdown-toggle\" data-bs-toggle=\"dropdown\">{{menuItem.name}}</a>\r\n                <ul class=\"dropdown-menu\">\r\n                  <li *ngFor=\"let item of menuItem.items; index as i\">\r\n                    <a class=\"dropdown-item\" href=\"{{item.url}}\">{{item.name}}</a>\r\n                  </li>\r\n                </ul>\r\n              </li>\r\n            </div>\r\n          </div>\r\n        </ul>\r\n      </div>\r\n    </div>\r\n  </nav>\r\n</div>","import { Component, OnInit } from '@angular/core';\r\nimport * as _ from 'lodash';\r\nimport { CommonService } from '../../../utility/services/common.service';\r\nimport { MenuName } from './menu-bar.constant';\r\nimport { MenuItem } from './menu-bar.model';\r\n\r\n@Component({\r\n  selector: 'menu-bar',\r\n  templateUrl: './menu-bar.component.html',\r\n  styleUrls: ['./menu-bar.component.scss']\r\n})\r\nexport class MenuBarComponent implements OnInit {\r\n  menuItems: MenuItem[] = [];\r\n  username: string;\r\n  isBlock: boolean;\r\n  rootUrl = '/';\r\n  oldSiteAbsoluteUrl = 'https://';\r\n\r\n\r\n  constructor(private readonly commonService: CommonService) { }\r\n\r\n  async ngOnInit(): Promise<void> {\r\n    this.isBlock = true;\r\n    this.rootUrl = document.body.getAttribute('root-url');\r\n    this.oldSiteAbsoluteUrl = this.getOldSiteAbsoluteUrl(document.body.getAttribute('old-site-root-url'));\r\n    const model = await this.commonService.getNapUserInfo();\r\n    this.replaceRootUrl(model.menuItem);\r\n    this.username = model.userName;\r\n    this.menuItems = _.orderBy(_.uniqBy(model.menuItem.filter(x => x.parentId <= 0), x => x.id), ['displayOrder'], ['asc']);\r\n    this.menuItems.forEach(t => {\r\n      t.items = model.menuItem.filter(z => z.parentId === t.id);\r\n      t.items = _.orderBy(_.uniqBy(t.items, x => x.id), ['displayOrder'], ['asc']);\r\n    });\r\n    this.isBlock = false;\r\n  }\r\n\r\n  private replaceRootUrl(menuItems: MenuItem[]): void {\r\n    menuItems.forEach(menu => {\r\n      if (this.isNewSite(menu.name)) {\r\n        menu.url = this.rootUrl + menu.url.substring(1);\r\n      } else {\r\n        menu.url = `${this.oldSiteAbsoluteUrl}${menu.url.substring(1)}`;\r\n      }\r\n    });\r\n  }\r\n\r\n  private getOldSiteAbsoluteUrl(oldSiteRootUrl: string): string {\r\n    if (oldSiteRootUrl.startsWith('/')) {\r\n      return `${window.location.origin}${oldSiteRootUrl}`;\r\n    }\r\n\r\n    return oldSiteRootUrl;\r\n  }\r\n\r\n  private isNewSite(menuName: string): boolean {\r\n    return menuName === MenuName.AB_EXCEPTION_LIST \r\n    || menuName === MenuName.MARK_UNMARK_TICKETS\r\n    || menuName === MenuName.TICKET_LISTING\r\n    || menuName === MenuName.VOID_SINGLE_BET\r\n    || menuName === MenuName.MANAGE_REQUEST\r\n    || menuName === MenuName.ADD_REQUEST;\r\n  }\r\n}\r\n","import { Component, OnInit } from '@angular/core';\r\n\r\n@Component({\r\n  selector: 'block-ui',\r\n  templateUrl: './block-ui.component.html',\r\n  styleUrls: ['./block-ui.component.scss']\r\n})\r\nexport class BlockUiComponent implements OnInit {\r\n\r\n  constructor() { }\r\n\r\n  ngOnInit() {\r\n  }\r\n}\r\n","<div class=\"block-ui-container\">\r\n  <div class=\"block-ui-overlay\"></div>\r\n  <div class=\"block-ui-message-container\" aria-live=\"assertive\" aria-atomic=\"true\">\r\n    <div class=\"block-ui-message\">\r\n      <div class=\"loading\"></div>\r\n    </div>\r\n  </div>\r\n</div>\r\n","import { ComponentRef, Directive, ElementRef, Input, OnChanges, SimpleChange, ViewContainerRef } from '@angular/core';\r\nimport { BlockUiComponent } from './block-ui.component';\r\n\r\n@Directive({\r\n  selector: '[blockUi]'\r\n})\r\nexport class BlockUiDirective implements OnChanges {\r\n  constructor(\r\n    private readonly viewContainerRef: ViewContainerRef,\r\n    private readonly elRef: ElementRef\r\n  ) { }\r\n\r\n  @Input('blockUi') isBlock: boolean;\r\n\r\n  private blockUiComponent: ComponentRef<BlockUiComponent>;\r\n\r\n  ngOnChanges(changes: { [propKey: string]: SimpleChange }) {\r\n    if (changes['isBlock']) {\r\n      this.openBlock();\r\n    }\r\n  }\r\n\r\n  openBlock() {\r\n    if (this.isBlock) {\r\n      this.blockUiComponent = this.viewContainerRef.createComponent(BlockUiComponent);\r\n      this.elRef.nativeElement.appendChild(this.blockUiComponent.location.nativeElement);\r\n    } else {\r\n      this.viewContainerRef.clear();\r\n    }\r\n  }\r\n}\r\n","import { ElementRef } from '@angular/core';\r\n\r\nexport class Tooltip {\r\n  className: string;\r\n  message: string;\r\n  show: boolean;\r\n  top: string;\r\n  left: string;\r\n  element: ElementRef;\r\n\r\n  display(className: string, message: string) {\r\n    this.className = className;\r\n    this.message = message;\r\n    this.show = true;\r\n    const element = this.element.nativeElement;\r\n    const targetElement = element.getElementsByClassName(this.className)[0];\r\n    if (targetElement) {\r\n      targetElement.scrollIntoView();\r\n      const box = targetElement.getBoundingClientRect();\r\n      const wrapperClass = 'wrapper-tooltip';\r\n      let wrapperTop = 0;\r\n      let wrapperLeft = 0;\r\n      const wrapperElement = element.closest('.' + wrapperClass);\r\n      if (wrapperElement !== null) {\r\n        wrapperTop = Number(wrapperElement.getBoundingClientRect().top) + window.scrollY;\r\n        wrapperLeft = Number(wrapperElement.getBoundingClientRect().left) + window.scrollX;\r\n        this.top = `${Number(box.top) - wrapperTop + Number(box.height) + window.scrollY - document.documentElement.clientTop}px`;\r\n        this.left = `${Number(box.left) - wrapperLeft + Number(box.height) + window.scrollX - document.documentElement.clientLeft}px`;\r\n      } else {\r\n        this.top = `${Number(box.top) + Number(box.height) + window.scrollY - document.documentElement.clientTop}px`;\r\n        this.left = `${Number(box.left) + window.scrollX - document.documentElement.clientLeft}px`;\r\n      }\r\n    }\r\n  }\r\n\r\n  hide() {\r\n    this.show = false;\r\n  }\r\n}","export class PrimitiveProperty {\r\n  public isBlockUI = true;\r\n  public errorMessage = '';\r\n  public userName: string;\r\n  public userPassword: string;\r\n}","import { ReducedOverGetLogInfoQuery } from '../event-reduced-over/models/get-log-info.query';\r\nimport { WrongHdpGetLogInfoQuery } from '../event-wrong-hdp/models/get-log-info.query';\r\nimport { WrongOddsGetLogInfoQuery } from '../event-wrong-odds/models/get-log-info.query';\r\nimport { WrongOuGetLogInfoQuery } from '../event-wrong-ou/models/get-log-info.query';\r\nimport { WrongScoreGetLogInfoQuery } from '../event-wrong-score/event-wrong-score.model';\r\nimport { OperatorInfo } from '../others/others.model';\r\nimport { AbnormalAccountModel } from './abnormal-account.model';\r\nimport { RedCardGetLogInfoQuery, RedCardModel } from './event-red-card.model';\r\nimport { ReducedOverModel } from './event-reduced-over.model';\r\nimport { WrongHdpModel } from './event-wrong-hdp.model';\r\nimport { WrongOddsModel } from './event-wrong-odds.model';\r\nimport { WrongOuModel } from './event-wrong-ou.model';\r\nimport { WrongScoreModel } from './event-wrong-score.model';\r\n\r\nexport class AddRequestQuery {\r\n  guid: string;\r\n  sportType: number;\r\n  subIssueTypeId: string;\r\n  actionId: string;\r\n  provider: string;\r\n  source: string;\r\n  decidedBy: string;\r\n  mistakenBy: string;\r\n  remark: string;\r\n  isTest: boolean;\r\n  issueTypeId: string;\r\n  operatorsList: OperatorInfo[];\r\n  isVoided: boolean;\r\n\r\n  requestId?: number;\r\n  matchId: number;\r\n  kickOffTime: string;\r\n  filterBy?: number;\r\n  transIds: string;\r\n  isHasUusTickets: boolean;\r\n  isConfirmCalculator: boolean;\r\n\r\n  wrongScoreInfo: WrongScoreModel[];\r\n  dangerAcceptedInfo: RedCardModel[];\r\n  redCardInfo: RedCardModel[];\r\n  wrongHdpInfo: WrongHdpModel[];\r\n  wrong1stHdpInfo: WrongHdpModel[];\r\n  wrongOuInfo: WrongOuModel[];\r\n  wrong1stOuInfo: WrongOuModel[];\r\n  wrongOddsInfo: WrongOddsModel[];\r\n  reducedOverInfo: ReducedOverModel[];\r\n  abnormalAccountInfo: AbnormalAccountModel;\r\n\r\n  transInfoJson: string;\r\n  unMarkTransIds: string;\r\n  markTransIds: string;\r\n  removeTransIds: string;\r\n\r\n  subIssueTypeName: string;\r\n  listBetteam: string;\r\n  listBettype: string;\r\n}\r\n\r\nexport interface CheckValidTransIdQuery {\r\n  matchId: number;\r\n  fromTransId: number;\r\n  toTransId: number;\r\n}\r\n\r\nexport class GetLogInfoQuery {\r\n  matchId?: number;\r\n  requestId?: number;\r\n  actionId?: number;\r\n  subIssueTypeId?: number;\r\n  issueTypeId?: number;\r\n  isShowLogOnly?: boolean;\r\n  kickOffTime?: string;\r\n  wrongScoreModels?: WrongScoreGetLogInfoQuery[];\r\n  dangerAcceptedModels?: RedCardGetLogInfoQuery[];\r\n  redCardModels?: RedCardGetLogInfoQuery[];\r\n  wrongHdpModels?: WrongHdpGetLogInfoQuery[];\r\n  wrong1stHdpModels?: WrongHdpGetLogInfoQuery[];\r\n  wrongOuModels?: WrongOuGetLogInfoQuery[];\r\n  wrong1stOuModels?: WrongOuGetLogInfoQuery[];\r\n  wrongOddsModels?: WrongOddsGetLogInfoQuery[];\r\n  reducedOverModels?: ReducedOverGetLogInfoQuery[];\r\n}\r\n","import * as _ from \"lodash\";\r\nimport { ReducedOverGetLogInfoQuery } from \"src/add-request/app/add-request/event-reduced-over/models/get-log-info.query\";\r\nimport { ReducedOverModel } from \"src/add-request/app/add-request/models/event-reduced-over.model\";\r\nimport { WrongHdpGetLogInfoQuery } from \"../../add-request/app/add-request/event-wrong-hdp/models/get-log-info.query\";\r\nimport { WrongOddsGetLogInfoQuery } from \"../../add-request/app/add-request/event-wrong-odds/models/get-log-info.query\";\r\nimport { WrongOuGetLogInfoQuery } from \"../../add-request/app/add-request/event-wrong-ou/models/get-log-info.query\";\r\nimport { WrongScoreGetLogInfoQuery } from \"../../add-request/app/add-request/event-wrong-score/event-wrong-score.model\";\r\nimport { RedCardGetLogInfoQuery, RedCardModel } from \"../../add-request/app/add-request/models/event-red-card.model\";\r\nimport { WrongHdpModel } from \"../../add-request/app/add-request/models/event-wrong-hdp.model\";\r\nimport { WrongOddsModel } from \"../../add-request/app/add-request/models/event-wrong-odds.model\";\r\nimport { WrongOuModel } from \"../../add-request/app/add-request/models/event-wrong-ou.model\";\r\nimport { WrongScoreModel } from \"../../add-request/app/add-request/models/event-wrong-score.model\";\r\nimport { StaticService } from \"./static.service\";\r\n\r\nexport class MappingModelStaticService {\r\n  static buidRedCardGetLogInfoModel(redCardModels: RedCardModel[]): RedCardGetLogInfoQuery[] {\r\n    if (_.isNull(redCardModels) || _.isUndefined(redCardModels)) {\r\n      return null;\r\n    }\r\n\r\n    return redCardModels.map(x => ({\r\n      matchId: x.matchId,\r\n      filterBy: x.filterBy,\r\n      filterFromTransTime: x.voidFromTime,\r\n      filterToTransTime: x.voidToTime,\r\n      subIssueTypeId: x.subIssueTypeId\r\n    } as RedCardGetLogInfoQuery));\r\n  }\r\n\r\n  static buidWrongScoreGetLogInfoModel(wrongScoreModels: WrongScoreModel[]): WrongScoreGetLogInfoQuery[] {\r\n    if (_.isNull(wrongScoreModels) || _.isUndefined(wrongScoreModels)) {\r\n      return null;\r\n    }\r\n\r\n    return wrongScoreModels.map(x => ({\r\n      scoreId: x.scoreId,\r\n      matchId: x.matchId,\r\n      wrongScore: x.wrongScore,\r\n      filterBy: x.filterBy,\r\n      filterFromTransTime: x.voidFromTime,\r\n      filterToTransTime: x.voidToTime,\r\n      subIssueTypeId: x.subIssueTypeId\r\n    } as WrongScoreGetLogInfoQuery));\r\n  }\r\n\r\n  static buidWrongHdpGetLogInfoModel(wrongHdpModels: WrongHdpModel[]): WrongHdpGetLogInfoQuery[] {\r\n    if (_.isNull(wrongHdpModels) || _.isUndefined(wrongHdpModels)) {\r\n      return null;\r\n    }\r\n\r\n    return wrongHdpModels.map(x => ({\r\n      matchId: x.matchId,\r\n      subIssueTypeId: x.subIssueTypeId,\r\n      filterFromTransTime: x.voidFromTime,\r\n      filterToTransTime: x.voidToTime,\r\n      homeFavorite: x.homeFavorite,\r\n      awayFavorite: x.awayFavorite,\r\n      hdpValue: x.hdpValue,\r\n      poolHouseCheckedBetTypes: x.poolHouseCheckedBetTypes,\r\n      isLinkGroup1X2: x.isLinkGroup1X2,\r\n      isLinkGroupAIO: x.isLinkGroupAIO,\r\n      isMainMatch: x.isMainMatch,\r\n      liveIndicator: x.liveIndicator\r\n    } as WrongHdpGetLogInfoQuery));\r\n  }\r\n\r\n  static buidWrongOuGetLogInfoModel(wrongOuModels: WrongOuModel[]): WrongOuGetLogInfoQuery[] {\r\n    if (_.isNull(wrongOuModels) || _.isUndefined(wrongOuModels)) {\r\n      return null;\r\n    }\r\n\r\n    return wrongOuModels.map(x => ({\r\n      matchId: x.matchId,\r\n      subIssueTypeId: x.subIssueTypeId,\r\n      filterFromTransTime: x.voidFromTime,\r\n      filterToTransTime: x.voidToTime,\r\n      wrongMarket: x.wrongMarket,\r\n      poolHouseCheckedBetTypes: x.poolHouseCheckedBetTypes,\r\n      isLinkGroup1X2: x.isLinkGroup1X2,\r\n      isLinkGroupAIO: x.isLinkGroupAIO,\r\n      isMainMatch: x.isMainMatch,\r\n      liveIndicator: x.liveIndicator\r\n    } as WrongOuGetLogInfoQuery));\r\n  }\r\n\r\n  static buidWrongOddsGetLogInfoModel(wrongOuModels: WrongOddsModel[]): WrongOddsGetLogInfoQuery[] {\r\n    if (_.isNull(wrongOuModels) || _.isUndefined(wrongOuModels)) {\r\n      return null;\r\n    }\r\n\r\n    return wrongOuModels.map(x => ({\r\n      matchId: x.matchId,\r\n      subIssueTypeId: x.subIssueTypeId,\r\n      filterFromTransTime: x.voidFromTime,\r\n      filterToTransTime: x.voidToTime,\r\n      poolHouseCheckedBetTypes: x.poolHouseCheckedBetTypes,\r\n      isLinkGroup1X2: x.isLinkGroup1X2,\r\n      isLinkGroupAIO: x.isLinkGroupAIO,\r\n      liveIndicator: x.liveIndicator,\r\n      filterOddsType: x.filterOddsType,\r\n      filterFavoriteType: x.filterFavoriteType,\r\n      filterOuType: x.filterOuType,\r\n      oddsValue: x.oddsValue,\r\n      fromOdds: x.fromOdds,\r\n      toOdds: x.toOdds,\r\n      correctOdds: x.correctOdds,\r\n      betTeam: x.betTeam,\r\n      ouValue: x.ouValue,\r\n      favoriteValue: x.favoriteValue\r\n    } as WrongOddsGetLogInfoQuery));\r\n  }\r\n\r\n  static buidReducedOverGetLogInfoModel(reducedOverModels: ReducedOverModel[]): ReducedOverGetLogInfoQuery[] {\r\n    if (_.isNull(reducedOverModels) || _.isUndefined(reducedOverModels)) {\r\n      return null;\r\n    }\r\n\r\n    return reducedOverModels.map(x => ({\r\n      matchId: x.matchId,\r\n      subIssueTypeId: x.subIssueTypeId,\r\n      betTypeIds: x.betTypeIds,\r\n      wicketOver: x.wicketOver,\r\n      filterWicketOver: StaticService.convertStringToBetId8xxx(x.wicketOver),\r\n      playerIds: x.playerIds,\r\n      runs: x.runs,\r\n      live: x.live,\r\n      nonLive: x.nonLive\r\n    } as ReducedOverGetLogInfoQuery));\r\n  }\r\n}\r\n","export class PagingConstant {\r\n  static readonly INDEX_ZERO = 0;\r\n  static readonly SIZE_DEFAULT = 3000;\r\n  static readonly SIZE_ONE = 500;\r\n  static readonly SIZE_TWO = 1000;\r\n  static readonly SIZE_THREE = 2000;\r\n  static readonly SIZE_FOUR = 3000;\r\n  static readonly SIZE_50 = 50;\r\n  static readonly GO_TO_PAGE = '...';\r\n  static readonly PREVIOUS = '<';\r\n  static readonly NEXT = '>';\r\n}\r\n\r\nexport class PagingModel {\r\n  public page = 1;\r\n  public pageSize = 3000;\r\n  public total = 0;\r\n  public selection = [PagingConstant.SIZE_ONE, PagingConstant.SIZE_TWO, PagingConstant.SIZE_THREE, PagingConstant.SIZE_FOUR];\r\n\r\n  constructor(paging = null) {\r\n    for (const key in paging) {\r\n      if (paging.hasOwnProperty(key)) {\r\n        this[key] = paging[key];\r\n      }\r\n    }\r\n  }\r\n\r\n  public get begin(): number {\r\n    return Math.min((this.page - 1) * this.pageSize + 1, this.total);\r\n  }\r\n\r\n  public get end(): number {\r\n    return Math.min(this.page * this.pageSize, this.total);\r\n  }\r\n}\r\n","export class VoidedReason {\r\n  reasonEnglish: string;\r\n  reasonChineseSimplified: string;\r\n}\r\n","import { ElementRef } from '@angular/core';\r\n\r\nimport { CommonGroupTicketsModel } from './common.group-tickets.model';\r\nimport { CommonTicketModel } from './common.ticket.model';\r\n\r\nenum IconCheckBox {\r\n    none = 0,\r\n    any = 1,\r\n    all = 2\r\n}\r\n\r\nexport class CommonTicketsModel<T extends CommonGroupTicketsModel<CommonTicketModel>> {\r\n    id: string;\r\n\r\n    groups = Array<T>();\r\n    iconCheckBox: IconCheckBox;\r\n    iconCheckBoxTop: string;\r\n\r\n    getCheckedTickets(isChecked: boolean): string[] {\r\n        const result: string[] = [];\r\n        this.groups.forEach(group => {\r\n            group.tickets.forEach(ticket => {\r\n                if (ticket.isChecked === isChecked) {\r\n                    result.push(ticket.value);\r\n                }\r\n            });\r\n        });\r\n\r\n        return result;\r\n    }\r\n\r\n    updatePositionListCheckGroup(element: ElementRef) {\r\n        const className = 'list-check-groups-input';\r\n        const targetElement = element.nativeElement.getElementsByClassName(className);\r\n        const top = Number(targetElement[0].offsetParent.offsetTop) + Number(targetElement[0].offsetHeight);\r\n        this.iconCheckBoxTop = `${top}px`;\r\n    }\r\n\r\n    updateTicketsByUncheckTransIds(uncheckTransIds: string[]): void {\r\n        this.groups.forEach(group => {\r\n            group.tickets.forEach(item => {\r\n                item.isChecked = uncheckTransIds.indexOf(item.value) > -1 ? false : item.isChecked;\r\n            });\r\n            group.setIsCheckAll();\r\n            group.checkDisableTickets();\r\n        });\r\n    }\r\n\r\n    getSingleTransIds(): string {\r\n        let result = [];\r\n        this.groups.forEach(group => {\r\n            const ticketInGroup = group.getEnableSingleTickets();\r\n            result = result.concat(ticketInGroup);\r\n        });\r\n\r\n        return result.join(',');\r\n    }\r\n\r\n    getDisableBonusTransIds(): string {\r\n        let result = [];\r\n        this.groups.forEach(group => {\r\n            const ticketInGroup = group.getDisableBonusTickets();\r\n            result = result.concat(ticketInGroup);\r\n        });\r\n\r\n        return result.join(',');\r\n    }\r\n\r\n    getParlayTransIds(): string {\r\n        let result = [];\r\n        this.groups.forEach(group => {\r\n            const ticketInGroup = group.getEnableParlayTickets();\r\n            result = result.concat(ticketInGroup);\r\n        });\r\n\r\n        return result.join(',');\r\n    }\r\n\r\n    getTicketEnable(): string {\r\n        let result = [];\r\n        this.groups.forEach(group => {\r\n            const ticketInGroup = group.getEnableTickets();\r\n            result = result.concat(ticketInGroup);\r\n        });\r\n\r\n        return result.join(',');\r\n    }\r\n\r\n    getTicketCricket(): string {\r\n        let result = [];\r\n        this.groups.forEach(group => {\r\n            const ticketInGroup = group.getTicketCricket();\r\n            result = result.concat(ticketInGroup);\r\n        });\r\n\r\n        return result.join(',');\r\n    }\r\n\r\n    getTicketSold(): string {\r\n        let result = [];\r\n        this.groups.forEach(group => {\r\n            const ticketInGroup = group.getTicketSold();\r\n            result = result.concat(ticketInGroup);\r\n        });\r\n\r\n        return result.join(',') + this.getLastedSoldId();\r\n    }\r\n\r\n    getTicketCheckBalance(): string {\r\n        let result = [];\r\n        this.groups.forEach(group => {\r\n            const ticketInGroup = group.getTicketCheckBalance();\r\n            result = result.concat(ticketInGroup);\r\n        });\r\n\r\n        return `${result}${this.getLastedSoldId()}`;\r\n    }\r\n\r\n    getLastedSoldId(): string {\r\n        const lastGroup = this.groups.length - 1;\r\n        const lastedGroup = this.groups[lastGroup];\r\n        const lastedTicket = lastedGroup.tickets[lastedGroup.tickets.length - 1];\r\n        return lastedTicket.member.toLowerCase().indexOf('bettrade') !== -1 && lastedTicket.isChecked ?\r\n            `,${lastedTicket.soldId}` : '';\r\n    }\r\n\r\n    changeIconCheckBox() {\r\n        let numberTickets = 0;\r\n        let numberTicketsChecked = 0;\r\n        this.groups.forEach(group => {\r\n            group.tickets.forEach(ticket => {\r\n                numberTickets++;\r\n                if (ticket.isChecked) {\r\n                    numberTicketsChecked++;\r\n                }\r\n            });\r\n        });\r\n        this.iconCheckBox =\r\n            numberTickets === 0 ? IconCheckBox.none :\r\n                numberTickets === numberTicketsChecked ? IconCheckBox.all :\r\n                    numberTicketsChecked > 0 ? IconCheckBox.any : IconCheckBox.none;\r\n    }\r\n\r\n    checkAllGroupsDropDown() {\r\n        if (this.iconCheckBox !== IconCheckBox.all) {\r\n            this.groups.forEach(group => {\r\n                group.isCheckAll = !group.isDisabled;\r\n                group.checkAllTickets();\r\n            });\r\n            this.iconCheckBox = IconCheckBox.all;\r\n        } else {\r\n            this.groups.forEach(group => {\r\n                group.isCheckAll = false;\r\n                group.checkAllTickets();\r\n            });\r\n            this.iconCheckBox = IconCheckBox.none;\r\n        }\r\n    }\r\n\r\n    isAllItemsChecked(): boolean {\r\n        let result = true;\r\n        for (let i = 0; i < this.groups.length && result; i++) {\r\n            for (let j = 0; j < this.groups[i].tickets.length && result; j++) {\r\n                const ticket = this.groups[i].tickets[j];\r\n                result = ticket.isChecked;\r\n            }\r\n        }\r\n\r\n        return result;\r\n    }\r\n\r\n    checkSettledTickets(): boolean {\r\n        let result = false;\r\n        this.groups.forEach(item => {\r\n            if (item.checkSettledTickets()) {\r\n                result = true;\r\n            }\r\n        });\r\n\r\n        return result;\r\n    }\r\n\r\n    getNumberOfCheckedTickets(): number {\r\n        let result = 0;\r\n        this.groups.forEach(item => result += item.getCheckedTickets().length);\r\n        return result;\r\n    }\r\n}\r\n","import { CommonTicketModel } from '../../../utility/models/common.ticket.model';\r\n\r\nexport class TicketModel extends CommonTicketModel {\r\n  secondAcceptFlag: string;\r\n  isParlay: boolean;\r\n  isBonus: boolean;\r\n  isMarked: boolean;\r\n  constructor(item = null) {\r\n    super(item);\r\n  }\r\n}\r\n","export class CommonTicketModel {\r\n    no: number;\r\n    betId: string;\r\n    value: string;\r\n    member: string;\r\n    transDate: string;\r\n    betType: string;\r\n    choice: string;\r\n    stake: string;\r\n    odds: string;\r\n    winLoss: string;\r\n    currency: string;\r\n    handicap: string;\r\n    score: string;\r\n    status: string;\r\n    isDisable: boolean;\r\n    isChecked: boolean;\r\n    isCricket: boolean;\r\n    soldId: string;\r\n    mainTransId: string;\r\n    siteDbGroupId: number;\r\n\r\n    constructor(item = null) {\r\n        for (const key in item) {\r\n            if (item.hasOwnProperty(key)) {\r\n                this[key] = item[key];\r\n            }\r\n        }\r\n\r\n        this.isChecked = !this.isDisable;\r\n    }\r\n}\r\n","import '../../../utility/extensions/string.extension';\r\nimport { CommonGroupTicketsModel } from '../../../utility/models/common.group-tickets.model';\r\nimport { TicketModel } from './ticket.model';\r\n\r\nexport class GroupModel extends CommonGroupTicketsModel<TicketModel> {\r\n\r\n  constructor(\r\n    name: string,\r\n    tickets: Array<TicketModel>,\r\n    displayTotalTickets: number) {\r\n    super();\r\n    this.mapTickets(tickets);\r\n    this.setValue(name);\r\n    this.displayTotalTickets = displayTotalTickets;\r\n  }\r\n\r\n  mapTickets(tickets: Array<TicketModel>) {\r\n    this.tickets = [];\r\n    tickets.forEach(item => {\r\n      const ticket = new TicketModel(item);\r\n      this.tickets.push(ticket);\r\n    });\r\n  }\r\n\r\n  setValue(name: string) {\r\n    this.setCommonValue(name);\r\n  }\r\n\r\n  getEnableSingleTickets(): string[] {\r\n    const result = [];\r\n    this.tickets.forEach(item => {\r\n      if (item.isChecked && !item.isDisable && !item.isParlay) {\r\n        result.push(item.value);\r\n      }\r\n    });\r\n\r\n    return result;\r\n  }\r\n\r\n  getDisableBonusTickets(): string[] {\r\n    const result = [];\r\n    this.tickets.forEach(item => {\r\n      if (item.isChecked && item.isDisable && item.isBonus) {\r\n        result.push(item.value);\r\n      }\r\n    });\r\n\r\n    return result;\r\n  }\r\n\r\n  getEnableParlayTickets(): string[] {\r\n    const result = [];\r\n    this.tickets.forEach(item => {\r\n      if (item.isChecked && !item.isDisable && item.isParlay) {\r\n        result.push(item.value);\r\n      }\r\n    });\r\n\r\n    return result;\r\n  }\r\n}\r\n","import '../extensions/string.extension';\r\nimport { CommonTicketModel } from './common.ticket.model';\r\n\r\nexport class CommonGroupTicketsModel<T extends CommonTicketModel> {\r\n    name: string;\r\n    isCheckAll: boolean;\r\n    isExpanded: boolean;\r\n    isDisabled: boolean;\r\n    tickets: Array<T>;\r\n    displayTotalTickets: number;\r\n    disabledTickets: Array<string>;\r\n\r\n    setCommonValue(name: string) {\r\n        this.name = name;\r\n        this.isExpanded = true;\r\n        this.isCheckAll = this.tickets.length !== this.numberTicketDisable();\r\n        this.isDisabled = this.tickets.length === this.numberTicketDisable();\r\n        this.setDisabledTickets();\r\n        this.checkDisableTickets();\r\n    }\r\n\r\n    setDisabledTickets() {\r\n        const list = this.tickets.map(function (item) {\r\n            return item.mainTransId;\r\n        });\r\n        this.disabledTickets = list.filter(function (item, index) {\r\n            return list.indexOf(item) === index && BigInt(item)> 0;\r\n        });\r\n    }\r\n\r\n    checkDisableTickets() {\r\n        this.tickets.forEach(ticket => {\r\n            this.checkDisabledTicket(ticket);\r\n        });\r\n    }\r\n\r\n    checkDisabledTicket(ticket: T) {\r\n        if (this.disabledTickets.indexOf(ticket.value) > -1) {\r\n            this.tickets.forEach(item => {\r\n                if (item.mainTransId === ticket.value) {\r\n                    item.isChecked = ticket.isChecked;\r\n                }\r\n            });\r\n        }\r\n    }\r\n\r\n    checkAllTickets() {\r\n        this.tickets.forEach(ticket => {\r\n            ticket.isChecked = ticket.isDisable ? ticket.isChecked : this.isCheckAll;\r\n            this.checkDisabledTicket(ticket);\r\n        });\r\n    }\r\n\r\n    changeTicketChecked(ticket: T) {\r\n        this.setIsCheckAll();\r\n        this.checkDisabledTicket(ticket);\r\n    }\r\n\r\n    setIsCheckAll() {\r\n        let temp = true;\r\n        for (let i = 0; i < this.tickets.length && temp; i++) {\r\n            if (!this.tickets[i].isChecked && !this.tickets[i].isDisable) {\r\n                temp = false;\r\n            }\r\n        }\r\n\r\n        this.isCheckAll = temp;\r\n    }\r\n\r\n    numberTicketDisable(): number {\r\n        let count = 0;\r\n        this.tickets.forEach(ticket => {\r\n            if (ticket.isDisable) {\r\n                count++;\r\n            }\r\n        });\r\n\r\n        return count;\r\n    }\r\n\r\n    getEnableTickets(): string[] {\r\n        const result = [];\r\n        this.tickets.forEach(ticket => {\r\n            if (ticket.isChecked && !ticket.isDisable) {\r\n                result.push(ticket.value);\r\n            }\r\n        });\r\n\r\n        return result;\r\n    }\r\n\r\n    getTicketCricket(): string[] {\r\n        const result = [];\r\n        this.tickets.forEach(ticket => {\r\n            if (ticket.isChecked && ticket.isCricket) {\r\n                result.push(ticket.value);\r\n            }\r\n        });\r\n\r\n        return result;\r\n    }\r\n\r\n    getTicketSold(): string[] {\r\n        const result = [];\r\n        this.tickets.forEach(ticket => {\r\n            if (ticket.isChecked && ticket.status.toLowerCase().indexOf('sold') !== -1) {\r\n                result.push(ticket.value);\r\n            }\r\n        });\r\n\r\n        return result;\r\n    }\r\n\r\n    getTicketCheckBalance(): string[] {\r\n        const soldIds = this.getTicketSold();\r\n        const enableTickets = this.getEnableTickets();\r\n        return enableTickets.concat(soldIds);\r\n    }\r\n\r\n    getCheckedTickets(): string[] {\r\n        const result: string[] = [];\r\n        this.tickets.forEach(item => {\r\n            if (item.isChecked) {\r\n                result.push(item.mainTransId);\r\n            }\r\n        });\r\n        return result;\r\n    }\r\n\r\n    checkSettledTickets(): boolean {\r\n        let result = false;\r\n        for (let i = 0; i < this.tickets.length && !result; i++) {\r\n            if (this.tickets[i].isChecked && this.tickets[i].status.isSettled()) {\r\n                result = true;\r\n            }\r\n        }\r\n\r\n        return result;\r\n    }\r\n\r\n    getEnableSingleTickets(): string[] {\r\n        const result = [];\r\n        this.tickets.forEach(item => {\r\n            if (item.isChecked && !item.isDisable) {\r\n                result.push(item.value);\r\n            }\r\n        });\r\n\r\n        return result;\r\n    }\r\n\r\n    getDisableBonusTickets(): string[] {\r\n        const result = [];\r\n        this.tickets.forEach(item => {\r\n            if (item.isChecked && item.isDisable) {\r\n                result.push(item.value);\r\n            }\r\n        });\r\n\r\n        return result;\r\n    }\r\n\r\n    getEnableParlayTickets(): string[] {\r\n        return this.getEnableSingleTickets();\r\n    }\r\n}\r\n","import * as moment from 'moment-timezone';\r\nimport { BetID } from '../../../utility/models/bet-id.model';\r\nimport { CommonTicketsModel } from '../../../utility/models/common.tickets.model';\r\nimport { GroupModel } from './group-tickets.model';\r\n\r\n\r\nenum IconCheckBox {\r\n  none = 0,\r\n  any = 1,\r\n  all = 2\r\n}\r\n\r\nexport class TicketsModel extends CommonTicketsModel<GroupModel> {\r\n  total: number;\r\n  totalSingle: number;\r\n  totalParlay: number;\r\n  totalCancelCashOut: number;\r\n  fromTime: Date;\r\n  toTime: Date;\r\n  fromDate: Date;\r\n  toDate: Date;\r\n  strFromTime: string;\r\n  strToTime: string;\r\n  singleTickets: BetID[];\r\n  parlayTickets: BetID[];\r\n  cancelCashOutTickets: BetID[];\r\n  cricketTickets: BetID[];\r\n  uncheckedTransIds: string[];\r\n  licenseesName: string;\r\n  instantLicenseesName: string;\r\n  chinaViewLicenseesName: string;\r\n  cashOutLicenseesName: string;\r\n  betTypes: string;\r\n  isHasSettledTicket: boolean;\r\n  isAllLiveTickets: boolean;\r\n  isHasAioMessage: boolean;\r\n  checkPermissionTickets: BetID[];\r\n  allCancelCashOutTickets: BetID[];\r\n\r\n  initData(data: TicketsModel) {\r\n    this.total = data.total;\r\n    this.totalSingle = data.totalSingle;\r\n    this.totalParlay = data.totalParlay;\r\n    this.totalCancelCashOut = data.totalCancelCashOut;\r\n    this.fromTime = data.fromTime;\r\n    this.toTime = data.toTime;\r\n    this.fromDate = data.fromDate;\r\n    this.toDate = data.toDate;\r\n    this.strFromTime = moment(new Date(data.fromTime)).format('hh:mm:ss A');\r\n    this.strToTime = moment(new Date(data.toTime)).format('hh:mm:ss A');\r\n    this.mapGroups(data.groups);\r\n    this.changeIconCheckBox();\r\n\r\n    this.singleTickets = data.singleTickets;\r\n    this.cancelCashOutTickets = data.cancelCashOutTickets;\r\n    this.parlayTickets = data.parlayTickets;\r\n    this.cricketTickets = data.cricketTickets;\r\n    this.uncheckedTransIds = data.uncheckedTransIds;\r\n    this.betTypes = data.betTypes;\r\n    this.checkPermissionTickets = data.checkPermissionTickets;\r\n    this.allCancelCashOutTickets = data.allCancelCashOutTickets;\r\n    this.isHasAioMessage = data.isHasAioMessage;\r\n  }\r\n\r\n  mapGroups(groups: Array<GroupModel>) {\r\n    this.groups = [];\r\n    groups.forEach(item => {\r\n      const group = new GroupModel(item.name, item.tickets, item.displayTotalTickets);\r\n      this.groups.push(group);\r\n    });\r\n  }\r\n\r\n  checkGroups() {\r\n    if (this.groups.length > 0) {\r\n      if (this.iconCheckBox !== IconCheckBox.none) {\r\n        this.groups.forEach(group => {\r\n          group.isCheckAll = false;\r\n          group.checkAllTickets();\r\n        });\r\n        this.iconCheckBox = IconCheckBox.none;\r\n      } else {\r\n        this.groups.forEach(group => {\r\n          group.isCheckAll = !group.isDisabled;\r\n          group.checkAllTickets();\r\n        });\r\n        this.iconCheckBox = IconCheckBox.all;\r\n      }\r\n    }\r\n  }\r\n}\r\n","export class AffectedLicensee {\r\n    licenseesName = '';\r\n    show: boolean;\r\n}","\r\nimport { PagingModel } from \"../../..//utility/components/paging/paging/paging.model\";\r\nimport { Message } from \"../../..//utility/components/template-message/messages/message\";\r\nimport { TemplateValue } from \"../../..//utility/components/template-message/template-message/template.model\";\r\nimport { SubIssueType } from \"../../..//utility/models/issue-type.model\";\r\nimport { LogInfoDetail } from \"../../..//utility/models/log-info-detail.model\";\r\nimport { MatchModel } from \"../../..//utility/models/match.model\";\r\nimport { VoidedReason } from \"../../..//utility/models/reason.model\";\r\nimport { TicketsModel } from \"../../..//void-request/app/tickets-list/tickets.model\";\r\nimport { AffectedLicensee } from \"../../../utility/models/affected-licensee.model\";\r\n\r\nexport class VoidMatch {\r\n  subIssueType?: SubIssueType;\r\n  displayIssueTypeName: string;\r\n  matchModel?: MatchModel;\r\n  voidTicketsMini?: TicketsModel;\r\n  voidReason?: VoidedReason;\r\n  templateValue?: TemplateValue;\r\n  logInfoDetail?: LogInfoDetail;\r\n  //filterWithHdp?: FilterWithHdpModel;\r\n  voidTicketsFull?: TicketsModel;\r\n  pagingVoidTickets: PagingModel;\r\n  isShowTicketFull: boolean;\r\n  isLoadedTicketFull: boolean;\r\n  isBlockBetList: boolean;\r\n  affectedLicensee: AffectedLicensee;\r\n  affectedInstantLicensee: AffectedLicensee;\r\n  chinaViewLicensee: AffectedLicensee;\r\n  cashOutLicensee: AffectedLicensee;\r\n  isShowTemplateMessage: boolean;\r\n  templateMessage?: Message;\r\n  isAllLiveTickets: boolean;\r\n  isCheckedEarlyEvent: boolean;\r\n  wrongMarket?: string;\r\n  actualMarket?: string;\r\n  hdpValue?: string;\r\n  isCheckedVar?: boolean;\r\n  isMainMatch: boolean;\r\n  isPoolHouseAffected: boolean;\r\n\r\n  constructor() {\r\n    this.voidTicketsFull = new TicketsModel();\r\n    this.pagingVoidTickets = new PagingModel();\r\n    this.affectedLicensee = new AffectedLicensee();\r\n    this.affectedInstantLicensee = new AffectedLicensee();\r\n    this.chinaViewLicensee = new AffectedLicensee();\r\n    this.cashOutLicensee = new AffectedLicensee();\r\n    this.voidReason = new VoidedReason();\r\n  }\r\n}","import { CheckedBetType } from '../../../utility/components/advanced-mode/advanced-mode/advanced-mode.model';\r\nimport { MatchModel } from '../../../utility/models/match.model';\r\n\r\nexport class GetTicketsQuery {\r\n  pageIndex: number;\r\n  pageSize: number;\r\n  match: MatchModel;\r\n  kickOffDate: string;\r\n  requestId?: number;\r\n  issueTypeId: number;\r\n  subIssueTypeId: number;\r\n  betTypes?: CheckedBetType[];\r\n  actionId?: number;\r\n  liveHomeScore?: number;\r\n  liveAwayScore?: number;\r\n  transInfoJson?: string; // only use for EKO search tickets\r\n}\r\n","import { Injectable } from '@angular/core';\r\nimport { RequestDetailViewModel } from '../../../../edit-request/app/request.model';\r\nimport { PagingConstant } from '../../../../utility/components/paging/paging/paging.model';\r\nimport { MatchModel } from '../../../../utility/models/match.model';\r\nimport { AppService } from '../../app.service';\r\nimport { GetTicketsQuery } from '../../models/get-tickets.query';\r\nimport { VoidMatch } from '../../models/void-match.model';\r\nimport { TicketsModel } from '../../tickets-list/tickets.model';\r\n\r\n@Injectable({\r\n  providedIn: 'root'\r\n})\r\nexport class TicketsService {\r\n\r\n  constructor(\r\n    private readonly appService: AppService\r\n  ) { }\r\n\r\n  initTicketQuery(match: MatchModel, requestDetail: RequestDetailViewModel): GetTicketsQuery {\r\n    const query = new GetTicketsQuery();\r\n    query.pageIndex = PagingConstant.INDEX_ZERO;\r\n    query.pageSize = PagingConstant.SIZE_ONE;\r\n    query.match = match;\r\n    query.kickOffDate = null;\r\n    query.requestId = requestDetail.requestId;\r\n    query.issueTypeId = requestDetail.request.issueTypeId;\r\n      \r\n    return query;\r\n  }\r\n\r\n  async getVoidTicketsMini(ticketQuery: GetTicketsQuery): Promise<TicketsModel> {\r\n    const voidTickets = await this.appService.getTicketsMini(ticketQuery);\r\n\r\n    return voidTickets;\r\n  }\r\n\r\n  async loadVoidTicketsFullOnFirstTime(voidMatch: VoidMatch, requestDetail: RequestDetailViewModel): Promise<void> {\r\n    voidMatch.pagingVoidTickets.selection = [PagingConstant.SIZE_ONE, PagingConstant.SIZE_TWO, PagingConstant.SIZE_THREE, PagingConstant.SIZE_FOUR];\r\n    voidMatch.pagingVoidTickets.pageSize = PagingConstant.SIZE_ONE;\r\n    const query = this.initTicketQuery(voidMatch.matchModel, requestDetail);\r\n    await this.getVoidTicketsFull(voidMatch, query);\r\n    voidMatch.isLoadedTicketFull = true;\r\n  }\r\n\r\n  async loadVoidTicketsFullOnPagingChange(voidMatch: VoidMatch, requestDetail: RequestDetailViewModel): Promise<void> {\r\n    const query = this.initTicketQuery(voidMatch.matchModel, requestDetail);\r\n    query.pageIndex = voidMatch.pagingVoidTickets.page - 1;\r\n    query.pageSize = voidMatch.pagingVoidTickets.pageSize;\r\n    await this.getVoidTicketsFull(voidMatch, query);\r\n  }\r\n\r\n  async exportTicketsAsExcelFile(voidMatch: VoidMatch, requestDetail: RequestDetailViewModel): Promise<void> {\r\n    voidMatch.isBlockBetList = true;\r\n    const query = this.initTicketQuery(voidMatch.matchModel, requestDetail);\r\n    query.pageIndex = voidMatch.pagingVoidTickets.page - 1;\r\n    query.pageSize = voidMatch.pagingVoidTickets.pageSize;\r\n    await this.appService.exportExcel(query);\r\n    voidMatch.isBlockBetList = false;\r\n  }\r\n\r\n  private async getVoidTicketsFull(voidMatch: VoidMatch, ticketQuery: GetTicketsQuery): Promise<void> {\r\n    voidMatch.isBlockBetList = true;\r\n    voidMatch.isShowTicketFull = true;\r\n    const data = await this.appService.getTickets(ticketQuery);\r\n    voidMatch.voidTicketsFull.initData(data);\r\n    voidMatch.pagingVoidTickets.total = data.total;\r\n    voidMatch.affectedLicensee.licenseesName = data.licenseesName;\r\n    voidMatch.affectedLicensee.show = true;\r\n    voidMatch.chinaViewLicensee.licenseesName = data.chinaViewLicenseesName;\r\n    voidMatch.chinaViewLicensee.show = true;\r\n    voidMatch.affectedInstantLicensee.licenseesName = data.instantLicenseesName;\r\n    voidMatch.affectedInstantLicensee.show = true;    \r\n    voidMatch.cashOutLicensee.licenseesName = data.cashOutLicenseesName;\r\n    voidMatch.cashOutLicensee.show = true;\r\n    voidMatch.isBlockBetList = false;\r\n  }\r\n}","import { Injectable } from '@angular/core';\r\nimport * as _ from 'lodash';\r\nimport { WrongHdpModel } from '../../../../add-request/app/add-request/models/event-wrong-hdp.model';\r\nimport { WrongOuModel } from '../../../../add-request/app/add-request/models/event-wrong-ou.model';\r\nimport { RequestDetailViewModel } from '../../../../edit-request/app/request.model';\r\nimport { TemplateValue } from '../../../../utility/components/template-message/template-message/template.model';\r\nimport { TemplateService } from '../../../../utility/components/template-message/template-message/template.service';\r\nimport { TVSRequestFilterBy } from '../../../../utility/constants/config';\r\nimport { EventType } from '../../../../utility/constants/sport.constant';\r\nimport { LogInfoDetail } from '../../../../utility/models/log-info-detail.model';\r\nimport { StaticService } from '../../../../utility/services/static.service';\r\nimport { VoidMatch } from '../../models/void-match.model';\r\n\r\n@Injectable({\r\n  providedIn: 'root'\r\n})\r\nexport class TemplateMessageService {\r\n\r\n  constructor(private readonly templateService: TemplateService) {\r\n  }\r\n\r\n  getTemplateValue(voidMatch: VoidMatch, requestDetail: RequestDetailViewModel): TemplateValue {\r\n    const templateValue = this.templateService.getTemplateValue(voidMatch.matchModel);\r\n    templateValue.kickOffTime = null;\r\n    templateValue.checkSettled = voidMatch.voidTicketsMini.isHasSettledTicket;\r\n    templateValue.fromTransTime = voidMatch.voidTicketsMini.fromTime;\r\n    templateValue.toTransTime = voidMatch.voidTicketsMini.toTime;\r\n    templateValue.totalTickets = voidMatch.voidTicketsMini.total;\r\n    templateValue.isCheckedEarlyEvent = false;\r\n\r\n    const issueTypeId = requestDetail.request.issueTypeId.toString();\r\n    if (StaticService.isDangerAccepted(issueTypeId)) {\r\n      this.initValueForDangerAccepted(templateValue, voidMatch.logInfoDetail, requestDetail.dangerAcceptedModels[0].filterBy, voidMatch.isCheckedVar);\r\n    } else if (StaticService.isWrongScore(issueTypeId)) {\r\n      this.initValueForWrongScore(templateValue, requestDetail.wrongScoreModels[0].wrongScore,\r\n        requestDetail.wrongScoreModels[0].actualScore, requestDetail.wrongScoreModels[0].isCheckedVar);\r\n    } else if (StaticService.isWrongHDP(issueTypeId) || StaticService.isWrong1stHDP(issueTypeId)) {\r\n      this.initValueForWrongHdp(templateValue, voidMatch, requestDetail.wrongHdpModels);\r\n    } else if (StaticService.isWrongOU(issueTypeId) || StaticService.isWrong1stOU(issueTypeId)) {\r\n      this.initValueForWrongOu(templateValue, voidMatch, requestDetail.wrongOuModels);\r\n    }\r\n\r\n    return templateValue;\r\n  }\r\n\r\n  private initValueForDangerAccepted(templateValue: TemplateValue, logInfoDetail: LogInfoDetail, filterBy: number, isCheckedVar = false): void {\r\n    templateValue.eventType = EventType.LIVE;\r\n    templateValue.score = this.getLiveScoreForTemplateMessage(logInfoDetail.scoreNormalTicket, logInfoDetail.scoreOfMatch);\r\n    templateValue.isCheckTime = filterBy === TVSRequestFilterBy.CHECK_TIME;\r\n    templateValue.isCheckedVar = isCheckedVar;\r\n  }\r\n\r\n  private getLiveScoreForTemplateMessage(scoreNormalTicket: string, scoreOfMatch: string): string {\r\n    return !scoreNormalTicket ? scoreOfMatch : scoreNormalTicket.split('|')[0].replace(/ /g, '');\r\n  }\r\n\r\n  private initValueForWrongHdp(templateValue: TemplateValue, voidMatch: VoidMatch, wrongHdpModels: WrongHdpModel[]): void {\r\n    const wrongHdpModel = wrongHdpModels.find(x => x.matchId === voidMatch.matchModel.matchId);\r\n\r\n    templateValue.eventType = voidMatch.isAllLiveTickets ? EventType.LIVE : null;\r\n    templateValue.score = this.getLiveScoreForTemplateMessage(voidMatch.logInfoDetail.scoreNormalTicket, voidMatch.logInfoDetail.scoreOfMatch);\r\n    templateValue.wrongMarket = wrongHdpModel.homeFavorite ?? wrongHdpModel.awayFavorite;\r\n    templateValue.actualMarket = wrongHdpModel.actualMarket;\r\n    templateValue.hdpValue = wrongHdpModel.hdpValue;\r\n    templateValue.checkAIOMessage = voidMatch.voidTicketsMini.isHasAioMessage;\r\n  }\r\n\r\n  private initValueForWrongOu(templateValue: TemplateValue, voidMatch: VoidMatch, wrongOuModels: WrongOuModel[]): void {\r\n    const wrongOuModel = wrongOuModels.find(x => x.matchId === voidMatch.matchModel.matchId);\r\n    const liveScoreList = voidMatch.logInfoDetail.liveScores.split('|');\r\n\r\n    templateValue.eventType = voidMatch.isAllLiveTickets ? EventType.LIVE : null;\r\n    templateValue.score = _.first(liveScoreList).replace(/ /g, '');\r\n    templateValue.wrongMarket = wrongOuModel.wrongMarket;\r\n    templateValue.actualMarket = wrongOuModel.actualMarket;\r\n    templateValue.checkAIOMessage = voidMatch.voidTicketsMini.isHasAioMessage;\r\n  }\r\n  private initValueForWrongScore(templateValue: TemplateValue, wrongScore: string, actualScore: string, isCheckedVar = false) {\r\n    //// TODO\r\n  }\r\n}","import { Injectable } from '@angular/core';\r\nimport { GetLogInfoQuery } from '../../../../add-request/app/add-request/models/add-request.query';\r\nimport { GetLogInfoModel } from '../../../../add-request/app/add-request/models/get-log-info.model';\r\nimport { RequestDetailViewModel } from '../../../../edit-request/app/request.model';\r\nimport { IssueTypesModel, SubIssueType } from '../../../../utility/models/issue-type.model';\r\nimport { CommonService } from '../../../../utility/services/common.service';\r\nimport { MappingModelStaticService } from '../../../../utility/services/mapping-model-static.service';\r\nimport { StaticService } from '../../../../utility/services/static.service';\r\nimport { AppService } from '../../app.service';\r\nimport { BasicRequestInfo } from '../../models/basic-request-info.model';\r\nimport { VoidMatch } from '../../models/void-match.model';\r\nimport { PrimitiveProperty } from '../void-danger-accepted.model';\r\nimport { TemplateMessageService } from './template-message.service';\r\nimport { TicketsService } from './tickets.service';\r\n\r\n@Injectable({\r\n  providedIn: 'root'\r\n})\r\nexport class VoidPageService {\r\n\r\n  constructor(\r\n    private readonly commonService: CommonService,\r\n    private readonly appService: AppService,\r\n    private readonly ticketsService: TicketsService,\r\n    private readonly templateMessageService: TemplateMessageService) {\r\n  }\r\n\r\n  async getIssueTypes(): Promise<IssueTypesModel> {\r\n    return this.commonService.getIssueTypes();\r\n  }\r\n\r\n  async getBasicVoidMatchesData(issueTypes: IssueTypesModel, requestDetail: RequestDetailViewModel, primitiveProperty: PrimitiveProperty): Promise<VoidMatch[]> {\r\n    const voidMatches: VoidMatch[] = [];\r\n    const logInfoList = await this.getAllLogInfo(requestDetail, primitiveProperty);\r\n    const issueTypeId = requestDetail.request.issueTypeId.toString();\r\n    const basicRequestInfo = this.initBasicRequestInfo(issueTypeId, requestDetail);\r\n    for (const element of basicRequestInfo) {\r\n      const voidMatchInfo = new VoidMatch();\r\n      voidMatchInfo.subIssueType = this.getSubIssueTypeModel(element.subIssueTypeId, issueTypes);\r\n      voidMatchInfo.displayIssueTypeName = this.getDisplayIssueTypeName(requestDetail.request.issueTypeId, voidMatchInfo.subIssueType,\r\n        issueTypes);\r\n      voidMatchInfo.matchModel = await this.commonService.getMatch(element.matchId);\r\n      voidMatchInfo.logInfoDetail = logInfoList.find(x => x.logInfoDetail.matchId === element.matchId).logInfoDetail;\r\n      voidMatchInfo.wrongMarket = element.wrongMarket;\r\n      voidMatchInfo.actualMarket = element.actualMarket;\r\n      voidMatchInfo.hdpValue = element.hdpValue;\r\n      voidMatchInfo.isCheckedVar = element.isCheckedVar;\r\n      voidMatchInfo.isMainMatch = element.isMainMatch;\r\n      voidMatchInfo.isPoolHouseAffected = logInfoList.find(x => x.logInfoDetail.matchId === element.matchId).validation.isPoolHouseAffected;\r\n      voidMatches.push(voidMatchInfo);\r\n    }\r\n\r\n    return voidMatches;\r\n  }\r\n\r\n  async loadUnderneathVoidMatchesData(voidMatches: VoidMatch[], requestDetail: RequestDetailViewModel): Promise<void> {\r\n    for (const element of voidMatches) {\r\n      const ticketQuery = this.ticketsService.initTicketQuery(element.matchModel, requestDetail);\r\n      element.voidTicketsMini = await this.ticketsService.getVoidTicketsMini(ticketQuery);\r\n      element.isAllLiveTickets = element.voidTicketsMini.isAllLiveTickets;\r\n      element.isCheckedEarlyEvent = false;\r\n      element.templateValue = this.templateMessageService.getTemplateValue(element, requestDetail);\r\n      element.templateValue.numberOfCorner = element.matchModel.numberOfCorner;\r\n      const sportTypeId = StaticService.isAbnormalAccount(requestDetail.request.issueTypeId.toString()) ? 0 : element.matchModel.sportType;\r\n      element.voidReason = await this.appService.getVoidedReason(element.subIssueType.subIssueTypeId, sportTypeId);\r\n    }\r\n  }\r\n\r\n  public toggleTicketsArea(currentVoidMatch: VoidMatch, allVoidMatches: VoidMatch[]): void {\r\n    const currentIsShowTicketFull = currentVoidMatch.isShowTicketFull;\r\n    const currentIsShowTemplateMessage = currentVoidMatch.isShowTemplateMessage;\r\n    allVoidMatches.forEach(item => {\r\n      item.isShowTemplateMessage = false;\r\n      item.isShowTicketFull = false;\r\n    });\r\n    currentVoidMatch.isShowTicketFull = !currentIsShowTicketFull;\r\n    currentVoidMatch.isShowTemplateMessage = currentIsShowTemplateMessage;\r\n  }\r\n\r\n  public toggleTemplateMessageArea(currentVoidMatch: VoidMatch, allVoidMatches: VoidMatch[]): void {\r\n    const currentIsShowTemplateMessage = currentVoidMatch.isShowTemplateMessage;\r\n    const currentIsShowTicketFull = currentVoidMatch.isShowTicketFull;\r\n    allVoidMatches.forEach(item => {\r\n      item.isShowTemplateMessage = false;\r\n      item.isShowTicketFull = false;\r\n    });\r\n    currentVoidMatch.isShowTicketFull = currentIsShowTicketFull;\r\n    currentVoidMatch.isShowTemplateMessage = !currentIsShowTemplateMessage;\r\n  }\r\n\r\n  private async getAllLogInfo(requestDetail: RequestDetailViewModel, primitiveProperty: PrimitiveProperty): Promise<GetLogInfoModel[]> {\r\n    primitiveProperty.isBlockUI = true;\r\n    const query = new GetLogInfoQuery();\r\n    query.requestId = requestDetail.requestId;\r\n    query.isShowLogOnly = true;\r\n    query.issueTypeId = requestDetail.request.issueTypeId;\r\n\r\n    if (StaticService.isDangerAccepted(requestDetail.request.issueTypeId.toString())) {\r\n      query.dangerAcceptedModels = MappingModelStaticService.buidRedCardGetLogInfoModel(requestDetail.dangerAcceptedModels);\r\n    }\r\n\r\n    if (StaticService.isWrongHDP(requestDetail.request.issueTypeId.toString())) {\r\n      query.wrongHdpModels = MappingModelStaticService.buidWrongHdpGetLogInfoModel(requestDetail.wrongHdpModels);\r\n    }\r\n\r\n    if (StaticService.isWrong1stHDP(requestDetail.request.issueTypeId.toString())) {\r\n      query.wrong1stHdpModels = MappingModelStaticService.buidWrongHdpGetLogInfoModel(requestDetail.wrongHdpModels);\r\n    }\r\n\r\n    if (StaticService.isWrongOU(requestDetail.request.issueTypeId.toString())) {\r\n      query.wrongOuModels = MappingModelStaticService.buidWrongOuGetLogInfoModel(requestDetail.wrongOuModels);\r\n    }\r\n\r\n    if (StaticService.isWrong1stOU(requestDetail.request.issueTypeId.toString())) {\r\n      query.wrong1stOuModels = MappingModelStaticService.buidWrongOuGetLogInfoModel(requestDetail.wrongOuModels);\r\n    }\r\n\r\n    const viewModel = await this.commonService.getLogInfo(query);\r\n    primitiveProperty.isBlockUI = false;\r\n\r\n    return viewModel.getLogInfoModels;\r\n  }\r\n\r\n  private initBasicRequestInfo(issueTypeId: string, requestDetail: RequestDetailViewModel): BasicRequestInfo[] {\r\n    if (StaticService.isDangerAccepted(issueTypeId)) {\r\n      return requestDetail.dangerAcceptedModels.map(x => {\r\n        const info: BasicRequestInfo = {\r\n          matchId: x.matchId,\r\n          subIssueTypeId: x.subIssueTypeId,\r\n          isMainMatch: x.isMainMatch,\r\n          isCheckedVar: x.isCheckedVar\r\n        };\r\n        return info;\r\n      });\r\n    }\r\n\r\n    if (StaticService.isWrongHDP(issueTypeId) || StaticService.isWrong1stHDP(issueTypeId)) {\r\n      return requestDetail.wrongHdpModels.map(x => {\r\n        const info: BasicRequestInfo = {\r\n          matchId: x.matchId,\r\n          subIssueTypeId: x.subIssueTypeId,\r\n          wrongMarket: x.homeFavorite ?? x.awayFavorite,\r\n          actualMarket: x.actualMarket,\r\n          hdpValue: x.hdpValue,\r\n          isMainMatch: x.isMainMatch\r\n        };\r\n\r\n        return info;\r\n      });\r\n    }\r\n\r\n    if (StaticService.isWrongOU(issueTypeId) || StaticService.isWrong1stOU(issueTypeId)) {\r\n      return requestDetail.wrongOuModels.map(x => {\r\n        const info: BasicRequestInfo = {\r\n          matchId: x.matchId,\r\n          subIssueTypeId: x.subIssueTypeId,\r\n          wrongMarket: x.wrongMarket,\r\n          actualMarket: x.actualMarket,\r\n          isMainMatch: x.isMainMatch,\r\n        };\r\n\r\n        return info;\r\n      });\r\n    }\r\n\r\n    return [];\r\n  }\r\n\r\n  private getSubIssueTypeModel(subIssueTypeId: number, issueTypes: IssueTypesModel): SubIssueType {\r\n    return issueTypes.subIssueTypes.find(x => x.subIssueTypeId === subIssueTypeId);\r\n  }\r\n\r\n  private getDisplayIssueTypeName(issueTypeId: number, subIssueTypeModel: SubIssueType, issueTypes: IssueTypesModel): string {\r\n    const currentIssueType = issueTypes.issueTypes.find(x => x.issueTypeId === issueTypeId);\r\n    const displayName = currentIssueType.issueTypeName === subIssueTypeModel.subIssueTypeName ? currentIssueType.issueTypeName\r\n      : `${currentIssueType.issueTypeName} - ${subIssueTypeModel.subIssueTypeName}`;\r\n\r\n    return displayName;\r\n  }\r\n}\r\n\r\n","export class CONFIG {\r\n    static readonly EXPORT_EXCEL_LIMITED = 100000;\r\n    static readonly TICKET_LISTING_LIMITED = 200000;\r\n}\r\n\r\nexport class TEXT {\r\n    static readonly INVALID_MATCHID = 'Invalid MatchId.';\r\n    static readonly INVALID_HDP = 'Invalid HDP!';\r\n    static readonly INVALID_OU = 'Invalid OU!';\r\n    static readonly INVALID_ODDS = 'Invalid Odds!';\r\n    static readonly INVALID_RUNS = 'Invalid Runs!';\r\n    static readonly INVALID_WICKET_OVER = 'Invalid Wicket/Over!';\r\n\r\n    static readonly INVALID_FROMBETID = 'Invalid From BetID.';\r\n    static readonly INVALID_TOBETID = 'Invalid To BetID.';\r\n    static readonly INVALID_BETIDS = 'Invalid BetID(s) are highlighted in RED.';\r\n    static readonly REQUIRED_MATCHID = 'MatchId is required.';\r\n    static readonly REQUIRED_BETIDS = 'Bet ID is required.';\r\n    static readonly REQUIRED_FROMBETID = 'From BetID is required.';\r\n    static readonly REQUIRED_TOBETID = 'To BetID is required.';\r\n    static readonly REQUIRED_REQUEST_ID = 'Request ID is required.';\r\n    static readonly REQUIRED_VOIDING_HISTORY_ID = 'Voiding History ID is required.';\r\n    static readonly REQUIRED_SITE = 'Site is required.';\r\n    static readonly REQUIRED_SUB_TYPE = 'Sub Type is required.';\r\n    static readonly REQUIRED_VOID_VIP = 'Void VIP is required.';\r\n    static readonly REQUIRED_FIELD = 'Required field.';\r\n\r\n    static readonly EMPTY_LICENSEE = 'At least one Licensee  must be selected.';\r\n    static readonly EMPTY_CURRENCY = 'At least one Currency  must be selected.';\r\n    static readonly EMPTY_TICKET = 'At least one ticket must be selected.';\r\n    static readonly EMPTY_BETTYPE = 'At least one bettype must be selected.';\r\n    static readonly EMPTY_SELECT = 'Please select at least one option!';\r\n    static readonly INVALID_TRANSDATE = 'Invalid Trans Date';\r\n    static readonly EVENT_HAS_NO_TICKET = 'The event has no ticket.';\r\n    static readonly AB_WHITE_LIST_ADDED_SUCCESS = 'Added User(s) successfully';\r\n\r\n    static readonly INPUT_REASON = 'Please input reason.';\r\n    static readonly INPUT_PASSWORD = 'Please input password.';\r\n\r\n    static readonly EMPTY_ENGLISH = 'You must enter English message.';\r\n    static readonly INVALID_ENGLISH = 'You must include @@ in English message for replacing ticket number.';\r\n    static readonly EMPTY_CHINESE_TRADITIONAL = 'You must enter Chinese Traditional message.';\r\n    static readonly INVALID_CHINESE_TRADITIONAL = 'You must include @@ in Chinese Traditional message for replacing ticket number.';\r\n    static readonly EMPTY_CHINESE_SIMPLIFIED = 'You must enter Chinese Simplified message.';\r\n    static readonly INVALID_CHINESE_SIMPLIFIED = 'You must include @@ in Chinese Simplified message for replacing ticket number.';\r\n    static readonly EMPTY_NEW_CHINESE_SIMPLIFIED = 'You must enter New Chinese Simplified message.';\r\n    static readonly INVALID_NEW_CHINESE_SIMPLIFIED = 'You must include @@ in New Chinese Simplified message for replacing ticket number.';\r\n    static readonly INVALID_THAI = 'You must include @@ in Thai message for replacing ticket number.';\r\n    static readonly INVALID_KOREAN = 'You must include @@ in Korean message for replacing ticket number.';\r\n    static readonly INVALID_JAPANESE = 'You must include @@ in Japanese message for replacing ticket number.';\r\n    static readonly INVALID_ITALIAN = 'You must include @@ in Italian message for replacing ticket number.';\r\n    static readonly INVALID_SPANISH = 'You must include @@ in Spanish message for replacing ticket number.';\r\n\r\n    static readonly CONFIRM_NEGATIVE_CUSTORMER = 'This action could lead to a negative amount of Bet Credit of the following customers: ';\r\n    static readonly CONFIRM_VOID_TICKET = 'Are you sure you want to void selected tickets?';\r\n    static readonly REQUEST_CONFIRMED_SUCCESSFULLY = 'Your request has been confirmed.';\r\n    static readonly CONFIRM_VOID_TICKET_IN_PAGE = 'Only selected tickets on present page will be voided. Are you sure you want to proceed?';\r\n    static readonly CONFIRM_ADD_REQUEST_HAS_WARNING = 'There are some warnings in this request. Are you sure you want to process?';\r\n    static readonly CONFIRM_YOU_WANT_TO_PROCESS = 'Are you sure you want to process?';\r\n    static readonly WARNING_MESSAGE_ADD_REQUEST = 'There are some warnings in this request.';\r\n    static readonly MESSAGE_EXCLUDE_ERROR_RELATED_MATCHES = 'Related match(es) excluded when creating new request because having no valid tickets in the current range:';\r\n\r\n\r\n\r\n    static readonly INVALID_DATA_IN_REQUEST = 'There are some invalid data in this request, please check again!';\r\n\r\n    static readonly CONFIRM_RECOVER_TICKET = 'Are you sure you want to recover selected tickets?';\r\n    static readonly CONFIRM_RECOVER_TICKET_IN_PAGE =\r\n    'Only selected tickets on present page will be recovered. Are you sure you want to proceed?';\r\n    static readonly WARNING_FILTER_OPTION_CHANGED =\r\n    'WARNING! The filter option was changed! \\nYou are about to back the page and try a new search.';\r\n\r\n    static readonly NO_CHECKED_BETTYPE = 'At least one bettype must be selected.';\r\n    static readonly NO_BETTYPE = 'No bet type is offered for the inputted matchid.';\r\n    static readonly NO_PARLAY_BETTYPE = 'No Parlay bet type is offered for the inputted matchid.';\r\n\r\n    static readonly NO_BET_TEAM = 'Please select at least one option!';\r\n\r\n    static readonly EXPORT_EXCEL_LIMITED = 'We regret to inform you that data collected for this report exceeded the web site ' +\r\n    'rendering capability (> ' + CONFIG.EXPORT_EXCEL_LIMITED.toString() + ' tickets). Please contact IT for help. Thank you!';\r\n    static readonly TICKET_LISTING_LIMITED = 'We regret to inform you that data collected for this report exceeded the web site ' +\r\n    'rendering capability (> ' + CONFIG.TICKET_LISTING_LIMITED.toString()  + ' tickets). Please change filter condition or contact IT for help. ' +\r\n    'Thank you !';\r\n    static readonly SEND_FILE = 'Are you sure you want to notify affected tickets to these Licensee(s): ';\r\n\r\n    static readonly NOTIFY_RECOVER_SETTLED_MATCH = 'The selected ticket(s) will return to \"Running\" status, ' +\r\n    'please resettle the match(es) to calculate it again.';\r\n    static readonly INVALID_SELECTION = 'Please select at least one option!';\r\n\r\n}\r\n","import { Injectable } from '@angular/core';\r\nimport { ModalType } from '../../../../utility/components/modal/modal.model';\r\nimport { ModalService } from '../../../../utility/components/modal/modal.service';\r\nimport { TemplateMessageComponent } from '../../../../utility/components/template-message/template-message/template-message.component';\r\nimport { LABELS } from '../../../../utility/constants/labels';\r\nimport { TEXT } from '../../../../utility/constants/text';\r\nimport { Result } from '../../../../utility/models/result';\r\nimport { VoidMatch } from '../../models/void-match.model';\r\n\r\n@Injectable({\r\n  providedIn: 'root'\r\n})\r\nexport class PopupService {\r\n  constructor(private readonly modalService: ModalService) { }\r\n\r\n  showVoidBetConfirm(matchHasTickets: VoidMatch[], templateMessageComponents: TemplateMessageComponent[], onYesCallback: () => void) {\r\n    this.modalService.confirm(\r\n      {\r\n        title: 'Void Bet Confirm',\r\n        message: `${this.getWarningInTemplateMessage(matchHasTickets, templateMessageComponents)}<div>${LABELS.CONFIRM_VOID_ALL_TICKETS}</div>`\r\n      }, onYesCallback,\r\n      () => { });\r\n  }\r\n\r\n  showWarningVoidBetPermission(message: string) {\r\n    this.modalService.open({\r\n      title: 'Warning!',\r\n      message: message,\r\n      type: ModalType.Warning\r\n    }, () => window.location.reload());\r\n  }\r\n\r\n  showWarningExportExcel() {\r\n    const header = 'Export Excel Result';\r\n    const body = LABELS.EXPORT_LARGE_FILE;\r\n    this.modalService.open({ title: header, message: body, type: ModalType.Warning });\r\n  }\r\n\r\n  showSubmitVoidRequestSuccess() {\r\n    this.modalService.open({\r\n      title: 'Confirmation Result ',\r\n      message: TEXT.REQUEST_CONFIRMED_SUCCESSFULLY,\r\n      type: ModalType.Alert\r\n    }, () => { window.close(); });\r\n  }\r\n\r\n  showSubmitVoidRequestError(insertQueueResult: Result<null>) {\r\n    this.modalService.open({\r\n      title: 'Error',\r\n      message: insertQueueResult.errorMsg,\r\n      type: ModalType.Error\r\n    }, () => {\r\n      const WRONG_PASSWORD_CODE = 121;\r\n      if (insertQueueResult.errorCode !== WRONG_PASSWORD_CODE) {\r\n        window.close();\r\n      }\r\n    });\r\n  }\r\n\r\n  private getWarningInTemplateMessage(matchHasTickets: VoidMatch[], templateMessageComponents: TemplateMessageComponent[]): string {\r\n    const matchesHaveWarning = this.getMatchesHaveWarning(matchHasTickets, templateMessageComponents);\r\n\r\n    if (matchesHaveWarning.length > 0) {\r\n      const matchIdList = `- Match Id: ${matchesHaveWarning.join(', ')}`;\r\n      const warningMessage = `<div><i class=\"fa fa-exclamation-triangle pt-2 text-warn\"></i>There are some message info you do not input in these matches:</div>\r\n                                  <div>${matchIdList}</div></br>`;\r\n\r\n      return warningMessage;\r\n    }\r\n\r\n    return '';\r\n  }\r\n\r\n  private getMatchesHaveWarning(matchHasTickets: VoidMatch[], templateMessageComponents: TemplateMessageComponent[]): number[] {\r\n    const matchHasWarning = matchHasTickets.filter(voidMatch =>\r\n      templateMessageComponents.find(x => x.value.matchId === voidMatch.matchModel.matchId).isHasWarningForDynamicInput());\r\n\r\n    return matchHasWarning.map(x => x.matchModel.matchId);\r\n  }\r\n}","import { Result } from '../models/result';\r\n\r\nexport class ResultModelService {\r\n  static createSuccessResult(): Result<null> {\r\n    return {\r\n      isSuccessful: true,\r\n      errorCode: 0,\r\n      errorMsg: ''\r\n    };\r\n  }\r\n\r\n  static createFailResult(errorMessage: string, errorCode: number): Result<null> {\r\n    return {\r\n      isSuccessful: false,\r\n      errorCode: errorCode,\r\n      errorMsg: errorMessage\r\n    };\r\n  }\r\n}","import { BetID } from './bet-id.model';\r\n\r\nexport class CheckingPermissionModel {\r\n    tickets: BetID[];\r\n    matchId: number;\r\n    apikey: string;\r\n    action: boolean;\r\n    isCashOutAsUnSettledTicket: boolean;\r\n    isCheckForTVS: boolean;\r\n    cancelCashOutTickets?: BetID[];\r\n\r\n    setParam(tickets: BetID[], matchId: number, apiKey: string, action: boolean, isCashOutAsUnSettledTicket: boolean, isCheckForTVS: boolean, cancelCashOutTickets?: BetID[]) {\r\n        this.tickets = tickets;\r\n        this.matchId = matchId;\r\n        this.apikey = apiKey;\r\n        this.action = action;\r\n        this.isCashOutAsUnSettledTicket = isCashOutAsUnSettledTicket;\r\n        this.isCheckForTVS = isCheckForTVS;\r\n        this.cancelCashOutTickets = cancelCashOutTickets;\r\n    }\r\n}\r\n","import { Injectable } from '@angular/core';\r\nimport { TemplateMessageComponent } from '../../../../utility/components/template-message/template-message/template-message.component';\r\nimport { IssueTypeConstant } from '../../../../utility/constants/issue-type.constant';\r\nimport { LABELS } from '../../../../utility/constants/labels';\r\nimport { CheckingPermissionModel } from '../../../../utility/models/checking-permission.model';\r\nimport { Result } from '../../../../utility/models/result';\r\nimport { CommonService } from '../../../../utility/services/common.service';\r\nimport { ResultModelService } from '../../../../utility/services/result-model.service';\r\nimport { StaticService } from '../../../../utility/services/static.service';\r\nimport { VoidMatch } from '../../models/void-match.model';\r\n\r\n@Injectable({\r\n  providedIn: 'root'\r\n})\r\nexport class ValidationService {\r\n\r\n  constructor(private readonly commonService: CommonService) { }\r\n\r\n  checkValidationBeforeVoid(matchHasTickets: VoidMatch[], templateMessageComponents: TemplateMessageComponent[]): Result<null> {\r\n    if (matchHasTickets.length === 0) {\r\n      return ResultModelService.createFailResult(LABELS.ALL_TICKETS_VOIDED, 1);\r\n    }\r\n\r\n    for (const item of matchHasTickets) {\r\n      const messageComponent = templateMessageComponents.find(x => x.value.matchId === item.matchModel.matchId);\r\n      if (!messageComponent) {\r\n        return ResultModelService.createFailResult(`${LABELS.INVALID_TEMPLATE_MESSAGE} (MatchId: ${item.matchModel.matchId})`, 1);\r\n      }\r\n\r\n      if (!messageComponent.checkValidation()) {\r\n        return ResultModelService.createFailResult(`${LABELS.INVALID_TEMPLATE_MESSAGE} (MatchId: ${item.matchModel.matchId})`, 1);\r\n      }\r\n\r\n      this.mapValidMessageToVoidMatch(item, messageComponent);\r\n\r\n      if (item.voidReason.reasonEnglish === '' || item.voidReason.reasonChineseSimplified === '') {\r\n        return ResultModelService.createFailResult(`${LABELS.INPUT_REASON} (MatchId: ${item.matchModel.matchId})`, 1);\r\n      }\r\n    }\r\n\r\n    return ResultModelService.createSuccessResult();\r\n  }\r\n\r\n  async checkVoidBetPermission(matchHasTickets: VoidMatch[], issueTypeId: number): Promise<Result<null>> {\r\n    for (const item of matchHasTickets) {\r\n      const checkingPermissionModel = new CheckingPermissionModel();\r\n      const ticketsForChecks = item.voidTicketsMini.checkPermissionTickets;\r\n\r\n      checkingPermissionModel.setParam(ticketsForChecks, item.matchModel.matchId,\r\n        'ticket-voiding-check-void-bet-permission', true, StaticService.checkHandlingCashOutAsUnSettledTicketByIssueTypeId(IssueTypeConstant.DANGER_ACCEPTED), true,\r\n        item.voidTicketsMini.allCancelCashOutTickets);\r\n      checkingPermissionModel.matchId = StaticService.isAbnormalAccount(issueTypeId.toString()) ? 0 : checkingPermissionModel.matchId;\r\n      const result = await this.commonService.checkVoidBetPermission(checkingPermissionModel);\r\n\r\n      if (result.errCode !== 0 && checkingPermissionModel.action) {\r\n        return ResultModelService.createFailResult(result.errMsg, 1);\r\n      }\r\n    }\r\n\r\n    return ResultModelService.createSuccessResult();\r\n  }\r\n\r\n  private mapValidMessageToVoidMatch(voidMatch: VoidMatch, templateMessageComponent: TemplateMessageComponent) {\r\n    voidMatch.templateMessage = templateMessageComponent.message;\r\n  }\r\n}\r\n","import { Injectable } from '@angular/core';\r\nimport { ModalType } from '../../../utility/components/modal/modal.model';\r\nimport { ModalService } from '../../../utility/components/modal/modal.service';\r\nimport { AppService } from '../app.service';\r\n\r\n@Injectable({\r\n  providedIn: 'root'\r\n})\r\nexport class CheckRequestService {\r\n\r\n  constructor(private readonly appService: AppService,\r\n    private readonly modalService: ModalService) { }\r\n\r\n  async isRequestModified(requestId: number, currentModifiedDate: Date): Promise<boolean> {\r\n    const lastModifiedDate = (await this.appService.getLastModifiedDate(requestId)).lastModifiedDate;\r\n\r\n    if (currentModifiedDate !== lastModifiedDate) {\r\n      this.showWarningPopupRequestModified();\r\n      return true;\r\n    }\r\n\r\n    return false;\r\n  }\r\n\r\n  private showWarningPopupRequestModified(): void {\r\n    this.modalService.open({\r\n      title: 'Warning',\r\n      message: 'The request was changed. You are about to back the page and check again.',\r\n      type: ModalType.Warning\r\n    }, () => { window.location.reload(); });\r\n  }\r\n}","import { Injectable } from '@angular/core';\r\n\r\n@Injectable({\r\n  providedIn: 'root'\r\n})\r\n\r\nexport class PasswordService {\r\n\r\n  private readonly SuggestedLength = 30;\r\n\r\n  public hash(password: string): string {\r\n    const standardPassword = this.fillPasswordUpTo30Chars(password);\r\n    const seed = this.toSeedNumber(standardPassword);\r\n    const hexString = this.toHexString(seed);\r\n    return this.toHashString(hexString);\r\n  }\r\n\r\n  private fillPasswordUpTo30Chars(password: string): string {\r\n    const remainLength = this.SuggestedLength - password.length;\r\n    for (let i = 1; i <= remainLength; i++) {\r\n      password += String.fromCharCode(21);\r\n    }\r\n    return password;\r\n  }\r\n\r\n  private toSeedNumber(password: string): number {\r\n    let seed = 1.0;\r\n    for (let i = 1; i <= this.SuggestedLength; i++) {\r\n      const result = password.charCodeAt(i - 1);\r\n      const temp: number = this.SuggestedLength + result * i;\r\n      seed *= temp;\r\n    }\r\n    return seed;\r\n  }\r\n\r\n  private toHexString(seed: number): string {\r\n    const seedString = Number(seed.toPrecision(15)).toString().toUpperCase();\r\n    let hexString = ``;\r\n    for (let i = 1; i <= seedString.length; i++) {\r\n      const length = (seedString.length - i < 2) ? seedString.length - i + 1 : 3;\r\n      hexString += this.getHexString(seedString.substring(i - 1, i - 1 + length));\r\n    }\r\n    return hexString;\r\n  }\r\n\r\n  private toHashString(hexString: string): string {\r\n    let hash = ``;\r\n    for (let i = 20; i <= hexString.length - 18; i += 2) {\r\n      hash += hexString.substring(i - 1, i);\r\n    }\r\n    return hash;\r\n  }\r\n\r\n  private getHexString(value: string): string {\r\n    let number = ``;\r\n    for (let i = 1; i <= value.length; i++) {\r\n      number = `${number}${value.charCodeAt(i - 1)}`;\r\n    }\r\n    return parseInt(number).toString(16).toUpperCase();\r\n  }\r\n}\r\n","import { Injectable } from '@angular/core';\r\nimport { Guid } from 'guid-typescript';\r\nimport * as moment from 'moment-timezone';\r\nimport { RequestDetailViewModel } from '../../../../edit-request/app/request.model';\r\nimport { TemplateMessageComponent } from '../../../../utility/components/template-message/template-message/template-message.component';\r\nimport { Result } from '../../../../utility/models/result';\r\nimport { PasswordService } from '../../../../utility/services/password.service';\r\nimport { ResultModelService } from '../../../../utility/services/result-model.service';\r\nimport { AppService } from '../../app.service';\r\nimport { VoidMatch } from '../../models/void-match.model';\r\nimport { VoidTicketsQuery } from '../../models/void-tickets.query';\r\nimport { CheckRequestService } from '../../services/check-request.service';\r\nimport { PrimitiveProperty } from '../void-danger-accepted.model';\r\nimport { PopupService } from './popup.service';\r\nimport { ValidationService } from './validation.service';\r\n\r\n@Injectable({\r\n  providedIn: 'root'\r\n})\r\nexport class SubmitVoidService {\r\n  constructor(\r\n    private readonly validationService: ValidationService,\r\n    private readonly popupService: PopupService,\r\n    private readonly checkRequestService: CheckRequestService,\r\n    private readonly appService: AppService,\r\n    private readonly passwordService: PasswordService) { }\r\n\r\n  public async voidAllMatches(templateMessageComponents: TemplateMessageComponent[], voidMatches: VoidMatch[],\r\n    requestDetail: RequestDetailViewModel, primitiveProperty: PrimitiveProperty): Promise<void> {\r\n    primitiveProperty.isBlockUI = true;\r\n    const matchHasTickets = voidMatches.filter(item => item.voidTicketsMini.total > 0);\r\n    const validation = this.validationService.checkValidationBeforeVoid(matchHasTickets, templateMessageComponents);\r\n    primitiveProperty.errorMessage = validation.errorMsg;\r\n    if (validation.isSuccessful) {\r\n      this.popupService.showVoidBetConfirm(matchHasTickets, templateMessageComponents,\r\n        async () => { this.checkRequestModified(matchHasTickets, requestDetail, primitiveProperty); });\r\n    }\r\n\r\n    primitiveProperty.isBlockUI = false;\r\n  }\r\n\r\n  private async checkRequestModified(matchHasTickets: VoidMatch[], requestDetail: RequestDetailViewModel, primitiveProperty: PrimitiveProperty): Promise<void> {\r\n    primitiveProperty.isBlockUI = true;\r\n    const isRequestModified = await this.checkRequestService.isRequestModified(requestDetail.requestId, requestDetail.lastModifiedDate);\r\n    if (!isRequestModified) {\r\n      await this.reCheckVoidBetPermission(matchHasTickets, requestDetail, primitiveProperty);\r\n    }\r\n    primitiveProperty.isBlockUI = false;\r\n  }\r\n\r\n  private async reCheckVoidBetPermission(matchHasTickets: VoidMatch[], requestDetail: RequestDetailViewModel, primitiveProperty: PrimitiveProperty): Promise<void> {\r\n    const validation = await this.validationService.checkVoidBetPermission(matchHasTickets, requestDetail.request.issueTypeId);\r\n    if (validation.isSuccessful) {\r\n      await this.processVoid(matchHasTickets, requestDetail, primitiveProperty);\r\n    } else {\r\n      this.popupService.showWarningVoidBetPermission(validation.errorMsg);\r\n    }\r\n  }\r\n\r\n  private async processVoid(matchHasTickets: VoidMatch[], requestDetail: RequestDetailViewModel, primitiveProperty: PrimitiveProperty): Promise<void> {\r\n    const insertQueueResult = await this.insertQueue(matchHasTickets, requestDetail, primitiveProperty.userName, primitiveProperty.userPassword);\r\n    if (insertQueueResult.isSuccessful) {\r\n      this.popupService.showSubmitVoidRequestSuccess();\r\n    } else {\r\n      this.popupService.showSubmitVoidRequestError(insertQueueResult);\r\n    }\r\n  }\r\n\r\n  private async insertQueue(matchHasTickets: VoidMatch[], requestDetail: RequestDetailViewModel, userName: string, userPassword: string): Promise<Result<null>> {\r\n    for (const item of matchHasTickets) {\r\n      const voidQuery = this.getVoidQuery(item, requestDetail, userName, userPassword);\r\n      const result = await this.appService.insertQueue(voidQuery);\r\n\r\n      if (!result.isSuccessful) {\r\n        return ResultModelService.createFailResult(result.errorMsg, result.errorCode);\r\n      }\r\n    }\r\n\r\n    return ResultModelService.createSuccessResult();\r\n  }\r\n\r\n  private getVoidQuery(voidMatch: VoidMatch, requestDetail: RequestDetailViewModel, userName: string, userPassword: string): VoidTicketsQuery {\r\n    const voidQuery: VoidTicketsQuery = {\r\n      requestId: requestDetail.requestId,\r\n      singleTickets: voidMatch.voidTicketsMini.singleTickets.filter(x => !voidMatch.voidTicketsMini.uncheckedTransIds.includes(x.transId)),\r\n      parlayTickets: voidMatch.voidTicketsMini.parlayTickets.filter(x => !voidMatch.voidTicketsMini.uncheckedTransIds.includes(x.transId)),\r\n      cancelCashOutTickets: voidMatch.voidTicketsMini.cancelCashOutTickets.filter(x => !voidMatch.voidTicketsMini.uncheckedTransIds.includes(x.transId)),\r\n\r\n      cricketTickets: voidMatch.voidTicketsMini.cricketTickets,\r\n      userName: userName,\r\n      userPassword: this.passwordService.hash(userPassword),\r\n      reason: voidMatch.voidReason.reasonEnglish,\r\n      reasonSC: voidMatch.voidReason.reasonChineseSimplified,\r\n      message: voidMatch.templateMessage,\r\n      matchId: voidMatch.matchModel.matchId,\r\n      subIssueTypeId: voidMatch.subIssueType.subIssueTypeId,\r\n      subIssueTypeName: voidMatch.subIssueType.subIssueTypeName,\r\n      subIssueTypeNameCS: voidMatch.subIssueType.subIssueTypeNameCS,\r\n      issueTypeId: requestDetail.request.issueTypeId,\r\n      voidFromTime: moment(new Date(voidMatch.voidTicketsMini.fromTime)).format('hh:mm:ss A'),\r\n      voidToTime: moment(new Date(voidMatch.voidTicketsMini.toTime)).format('hh:mm:ss A'),\r\n      voidFromDate: moment(new Date(voidMatch.voidTicketsMini.fromDate)).format('MM/DD/YYYY'),\r\n      voidToDate: moment(new Date(voidMatch.voidTicketsMini.toDate)).format('MM/DD/YYYY'),\r\n      decidedBy: requestDetail.request.decidedBy,\r\n      guid: Guid.create().toString()\r\n    };\r\n\r\n    return voidQuery;\r\n  }\r\n}\r\n","<div>\r\n    <span><strong>Log Info</strong></span><br />\r\n    <span>Live Score: </span><strong>{{logInfoDetail.liveScores}}</strong>.\r\n    Void time (GMT-4): <strong>{{displayFullDateTimeFormat(logInfoDetail.voidFromTime)}} -\r\n        {{displayFullDateTimeFormat(logInfoDetail.voidToTime)}}</strong><br />\r\n    <ng-container *ngIf=\"!isShowPoolHouseTickets()\">\r\n        Affected Single Count: <strong>{{logInfoDetail.singleCount}}</strong>\r\n        <span *ngIf=\"isShowCountInfo(logInfoDetail.cashOutCount, logInfoDetail.settleCount, logInfoDetail.instantlySettleCount)\" class=\"text-red\" \r\n        [innerHTML]=\"countInfoContent(logInfoDetail.cashOutCount, logInfoDetail.settleCount, logInfoDetail.instantlySettleCount) | sanitizeHtml\">\r\n        </span>,\r\n        Parlay Count: <strong>{{logInfoDetail.mainParlayCount}}</strong><span *ngIf=\"logInfoDetail.highlightMinTime\">, Min Time: <strong [ngClass]=\"getHighlightMinTimeClass(logInfoDetail.highlightMinTime)\">{{displayMinTime(logInfoDetail.highlightMinTime)}}</strong></span><br/>\r\n        <span *ngIf=\"isHaveCancelCashOut()\">Cancel Cash Out: <strong>{{logInfoDetail.cancelCashOutCount}}</strong></span>\r\n    </ng-container>\r\n    <ng-container *ngIf=\"isShowPoolHouseTickets()\">\r\n        LG/Early - Single Count: <strong>{{logInfoDetail.liveGameEarlySingleCount}}</strong>\r\n        <span *ngIf=\"isShowCountInfo(logInfoDetail.liveGameEarlyCashOutCount, logInfoDetail.liveGameEarlySettleCount, logInfoDetail.liveGameEarlyInstantlySettleCount)\" class=\"text-red\"\r\n        [innerHTML]=\"countInfoContent(logInfoDetail.liveGameEarlyCashOutCount, logInfoDetail.liveGameEarlySettleCount, logInfoDetail.liveGameEarlyInstantlySettleCount) | sanitizeHtml\">\r\n        </span><br />\r\n        <ng-container *ngIf=\"isMainMatch\">\r\n        <div *ngIf=\"isPoolHouseAffected\">\r\n            PH - Single Count: <strong>{{logInfoDetail.poolHouseSingleCount}}</strong>\r\n            <span *ngIf=\"isShowCountInfo(logInfoDetail.poolHouseCashOutCount, logInfoDetail.poolHouseSettleCount, logInfoDetail.poolHouseInstantlySettleCount)\" class=\"text-red\" \r\n            [innerHTML]=\"countInfoContent(logInfoDetail.poolHouseCashOutCount, logInfoDetail.poolHouseSettleCount, logInfoDetail.poolHouseInstantlySettleCount) | sanitizeHtml\">\r\n            </span>,\r\n            Parlay Count: <strong>{{logInfoDetail.poolHouseMainParlayCount}}</strong>&nbsp;\r\n        </div>\r\n        <div *ngIf=\"!isPoolHouseAffected\">PH - Not affected.</div>\r\n        </ng-container>\r\n    </ng-container>\r\n</div>","import { Component, Input } from '@angular/core';\r\nimport * as _ from 'lodash';\r\nimport * as moment from 'moment-timezone';\r\nimport { AcceptType, DateTimeFormat } from '../../../utility/constants/config';\r\nimport { IssueTypeConstant } from '../../../utility/constants/issue-type.constant';\r\nimport { LogInfoDetail } from '../../../utility/models/log-info-detail.model';\r\nimport { StaticService } from '../../../utility/services/static.service';\r\n\r\n@Component({\r\n  selector: 'log-info-new',\r\n  templateUrl: './log-info-new.component.html',\r\n  styleUrls: ['./log-info-new.component.scss']\r\n})\r\nexport class LogInfoNewComponent {\r\n  @Input() issueTypeId: number;\r\n  @Input() isMainMatch: boolean;\r\n  @Input() isPoolHouseAffected: boolean;\r\n  @Input() logInfoDetail: LogInfoDetail;\r\n  acceptTypeName = \"\";\r\n\r\n  displayFullDateTimeFormat(time: Date): string {\r\n    return moment(time).format(DateTimeFormat.FULL_DATE_TIME_FORMAT);\r\n  }\r\n\r\n  isShowPoolHouseTickets() {\r\n    const issueTypesHavePoolHouse = [\r\n      Number(IssueTypeConstant.WRONG_HDP),\r\n      Number(IssueTypeConstant.WRONG_1ST_HDP),\r\n      Number(IssueTypeConstant.WRONG_OU),\r\n      Number(IssueTypeConstant.WRONG_1ST_OU)\r\n    ];\r\n\r\n    return issueTypesHavePoolHouse.includes(this.issueTypeId);\r\n  }\r\n\r\n  isShowCountInfo(cashOutCount: number, settleCount: number, instantlySettleCount: number) {\r\n    return StaticService.isShowCountInfo(cashOutCount, settleCount, instantlySettleCount);\r\n  }\r\n\r\n  displayTransId(ticketCount: number, transId: string): string {\r\n    return ticketCount === 0 ? '-' : transId;\r\n  }\r\n\r\n  countInfoContent(cashOutCount: number, settleCount: number, instantlySettleCount: number) {\r\n    return StaticService.countInfoContent(cashOutCount, settleCount, instantlySettleCount);\r\n  }\r\n\r\n  getHighlightMinTimeClass(minTime?: Date): string {\r\n    if (minTime && this.logInfoDetail.highlightAcceptType) {\r\n      switch (this.logInfoDetail.highlightAcceptType) {\r\n        case AcceptType.AUTO_ACCEPT: {\r\n          this.acceptTypeName = \"AA\";\r\n          return 'highlight-min-aa';\r\n        }\r\n        case AcceptType.PENDING_ACCEPT: {\r\n          this.acceptTypeName = \"PA\";\r\n          return 'highlight-min-pa';\r\n        }\r\n        case AcceptType.SECOND_ACCEPT: {\r\n          this.acceptTypeName = \"SA\";\r\n          return 'highlight-min-sa';\r\n        }\r\n      }\r\n    }\r\n\r\n    return '';\r\n  }\r\n\r\n  displayMinTime(minTime?: Date): string {\r\n    if (_.isNull(minTime)) {\r\n      return '-';\r\n    }\r\n    return (this.acceptTypeName) ? `${moment(minTime).format(DateTimeFormat.TIME_FORMAT)} - ${this.acceptTypeName}` :\r\n      `${moment(minTime).format(DateTimeFormat.TIME_FORMAT)}`;\r\n  }\r\n\r\n  isHaveCancelCashOut(): boolean {\r\n    return StaticService.isHaveCancelCashOutTicket(this.issueTypeId?.toString());\r\n  }\r\n}\r\n","import { Component, ElementRef, EventEmitter, Input, OnInit, Output } from '@angular/core';\r\nimport { CommonGroupTicketsModel } from '../../../utility/models/common.group-tickets.model';\r\nimport { CommonTicketModel } from '../../../utility/models/common.ticket.model';\r\nimport { CommonTicketsModel } from '../../models/common.tickets.model';\r\nimport { PagingModel } from '../paging/paging/paging.model';\r\n\r\n@Component({\r\n  selector: 'base-tickets-list',\r\n  template: `\r\n    <p>\r\n      base-tickets-list works!\r\n    </p>\r\n  `,\r\n  styles: []\r\n})\r\nexport class BaseTicketsListComponent<T extends CommonTicketsModel<CommonGroupTicketsModel<CommonTicketModel>>>\r\n  implements OnInit {\r\n  @Input() model: T;\r\n  @Input() paging = new PagingModel();\r\n  @Input() isBlock: boolean;\r\n  @Output() pagingChange = new EventEmitter<PagingModel>();\r\n  @Output() exportExcelEvent = new EventEmitter<boolean>();\r\n  @Output() ticketsChange = new EventEmitter<number>();\r\n  isShowListCheckGroup: boolean;\r\n  showMessageBetTrade: boolean;\r\n\r\n  constructor(readonly element: ElementRef) { }\r\n\r\n  ngOnInit() {\r\n    this.clickBody();\r\n  }\r\n\r\n  showListCheckGroup() {\r\n    if (this.model.groups.length > 0) {\r\n      this.isShowListCheckGroup = true;\r\n      this.model.updatePositionListCheckGroup(this.element);\r\n    }\r\n  }\r\n\r\n  clickBody() {\r\n    const body = document.querySelector('body');\r\n    const className = 'list-check-groups-input';\r\n    const listCheckGroupsElement = this.element.nativeElement.getElementsByClassName(className);\r\n    body.addEventListener('click', e => {\r\n      if (!this.isShowListCheckGroup || !e.target) {\r\n        return;\r\n      }\r\n      if (listCheckGroupsElement[0] !== e.target && !listCheckGroupsElement[0].contains((e.target as Node))) {\r\n        this.isShowListCheckGroup = false;\r\n      }\r\n    }, false);\r\n  }\r\n\r\n  exportExcel() {\r\n    this.exportExcelEvent.emit();\r\n  }\r\n\r\n  pagingEvent() {\r\n    this.pagingChange.emit(this.paging);\r\n  }\r\n}\r\n","<div class=\"paging d-flex justify-content-between bg-light\">\r\n  <div class=\"d-flex justify-content-start\">\r\n    <label class=\"text-nowrap text-primary\"><strong>Page size</strong></label>\r\n    <select class=\"selection form-control form-control-sm\" [(ngModel)]=\"model.pageSize\" (change)=\"changePageSize()\">\r\n      <option *ngFor=\"let item of model.selection\" [attr.value]=\"item\">{{item}}</option>\r\n    </select>\r\n    <ngb-pagination [collectionSize]=\"model.total\" [(page)]=\"model.page\" [pageSize]=\"model.pageSize\" [maxSize]=\"5\"\r\n      [rotate]=\"true\" [boundaryLinks]=\"true\" (pageChange)=\"pageChange()\" size=\"sm\"></ngb-pagination>\r\n  </div>\r\n\r\n  <div>\r\n    <label>Displaying <strong>{{model.begin}}</strong> to <strong>{{model.end}}</strong> of <strong>{{model.total}}</strong> item(s)</label>\r\n  </div>\r\n</div>","import { Component, Input, Output, EventEmitter } from '@angular/core';\r\nimport { PagingModel } from './paging.model';\r\n\r\n@Component({\r\n  selector: 'paging',\r\n  templateUrl: './paging.component.html',\r\n  styleUrls: ['./paging.component.scss']\r\n})\r\nexport class PagingComponent {\r\n  @Input() model = new PagingModel();\r\n  @Output() modelChange = new EventEmitter<PagingModel>();\r\n\r\n  changePageSize() {\r\n    this.model.page = 1;\r\n    this.modelChange.emit(this.model);\r\n  }\r\n\r\n  pageChange() {\r\n    this.modelChange.emit(this.model);\r\n  }\r\n}\r\n","<div class=\"tickets-list\" [blockUi]=\"isBlock\">\r\n  <div class=\"title-tickets-list\" *ngIf=\"model.groups !== undefined && model.groups.length > 0\">\r\n    <div class=\"title-tickets-list-label\">{{title}}</div>\r\n    <div class=\"title-tickets-list-toolbox\">\r\n      <input type=\"button\" class=\"title-tickets-list-toolbox-excel\" title=\"Export to Excel\" (click)=\"exportExcel()\">\r\n    </div>\r\n  </div>\r\n  <div class=\"ticket-header\">\r\n    <table>\r\n      <thead>\r\n        <tr>\r\n          <th scope=\"col\" class=\"list-check-groups-input col-tb-1\">\r\n            <div *ngIf=\"!isDisableCheckbox\">\r\n              <div class=\"checkbox-dropdown-list\">\r\n                <span [ngClass]=\"{\r\n                                    'icon-checkbox-none':model.iconCheckBox == 0,\r\n                                    'icon-checkbox-any':model.iconCheckBox == 1,\r\n                                    'icon-checkbox-all':model.iconCheckBox == 2}\"\r\n                  (click)=\"model.checkGroups();changeTickets()\">\r\n                </span>\r\n              </div>\r\n              <span class=\"icon-arrow-white-down\" (click)=\"showListCheckGroup()\"></span>\r\n            </div>\r\n            <div *ngIf=\"isDisableCheckbox\" class=\"checkbox-dropdown-list\">\r\n              <input type=\"checkbox\" disabled [checked]=\"model.iconCheckBox == 2\">\r\n            </div>\r\n          </th>\r\n          <th scope=\"col\" class=\"col-tb-2\">\r\n            <div>No</div>\r\n          </th>\r\n          <th scope=\"col\" class=\"col-tb-3\">\r\n            <div>BetID</div>\r\n          </th>\r\n          <th scope=\"col\" class=\"col-tb-4\">\r\n            <div>Trans.Date</div>\r\n          </th>\r\n          <th scope=\"col\" class=\"col-tb-5\">\r\n            <div>Member</div>\r\n          </th>\r\n          <th scope=\"col\" class=\"col-tb-6\">\r\n            <div>Bettype</div>\r\n          </th>\r\n          <th scope=\"col\" class=\"col-tb-7\">\r\n            <div>Odds</div>\r\n          </th>\r\n          <th scope=\"col\" class=\"col-tb-8\">\r\n            <div>Stake</div>\r\n          </th>\r\n          <th scope=\"col\" class=\"col-tb-9\">\r\n            <div>Win Loss</div>\r\n          </th>\r\n          <th scope=\"col\" class=\"col-tb-10\">\r\n            <div>Currency</div>\r\n          </th>\r\n          <th scope=\"col\" class=\"col-tb-11\">\r\n            <div>Status</div>\r\n          </th>\r\n          <th scope=\"col\" class=\"col-tb-13\">\r\n            <div>Score</div>\r\n          </th>\r\n          <th scope=\"col\" class=\"col-tb-14\">\r\n            <div>HDP</div>\r\n          </th>\r\n          <th scope=\"col\" class=\"col-tb-15\">\r\n            <div>Choice</div>\r\n          </th>\r\n        </tr>\r\n      </thead>\r\n    </table>\r\n  </div>\r\n  <div class=\"ticket-content\">\r\n    <table>\r\n      <tbody *ngFor=\"let group of model.groups\">\r\n        <tr>\r\n          <td class=\"col-tb-1\">\r\n            <div>\r\n              <input type=\"checkbox\" [(ngModel)]=\"group.isCheckAll\" (ngModelChange)=\"group.checkAllTickets();\r\n                                                    model.changeIconCheckBox();\r\n                                                    changeTickets()\" [disabled]=\"group.isDisabled || isDisableCheckbox\" />\r\n            </div>\r\n          </td>\r\n          <td [attr.colspan]=\"13\" class=\"group-ticket\" (click)=\"group.isExpanded = !group.isExpanded\">\r\n            <span [ngClass]=\"{'icon-down':group.isExpanded, 'icon-right':!group.isExpanded}\"></span>\r\n            {{group.name}} ({{group.displayTotalTickets}})\r\n          </td>\r\n        </tr>\r\n        <tr *ngFor=\"let ticket of group.tickets\" [ngClass]=\"{'display-none':!group.isExpanded}\">\r\n          <td class=\"col-tb-1\">\r\n            <div>\r\n              <input type=\"checkbox\" [(ngModel)]=\"ticket.isChecked\" (change)=\"group.changeTicketChecked(ticket);\r\n                                             model.changeIconCheckBox();\r\n                                             changeTickets()\" [disabled]=\"ticket.isDisable || isDisableCheckbox\" />\r\n            </div>\r\n          </td>\r\n          <td class=\"col-tb-2\">\r\n            <div>{{ticket.no}}</div>\r\n          </td>\r\n          <td class=\"col-tb-3\">\r\n            <div [class.betIdBorder]=\"ticket.isMarked\" [innerHTML]=\"ticket.betId | sanitizeHtml\"></div>\r\n          </td>\r\n          <td class=\"col-tb-4\">\r\n            <div>{{ticket.transDate}}</div>\r\n          </td>\r\n          <td class=\"col-tb-5\">\r\n            <div [innerHTML]=\"ticket.member | sanitizeHtml\" title=\"{{ticket.member}}\"></div>\r\n          </td>\r\n          <td class=\"col-tb-6\">\r\n            <div [innerHTML]=\"ticket.betType | sanitizeHtml\"></div>\r\n          </td>\r\n          <td class=\"col-tb-7\">\r\n            <div [innerHTML]=\"ticket.odds | sanitizeHtml\"></div>\r\n          </td>\r\n          <td class=\"col-tb-8\">\r\n            <div [innerHTML]=\"ticket.stake | sanitizeHtml\"></div>\r\n          </td>\r\n          <td class=\"col-tb-9\">\r\n            <div>{{ticket.winLoss}}</div>\r\n          </td>\r\n          <td class=\"col-tb-10\">\r\n            <div>{{ticket.currency}}</div>\r\n          </td>\r\n          <td class=\"col-tb-11\">\r\n            <div [innerHTML]=\"ticket.status | sanitizeHtml\"></div>\r\n          </td>\r\n          <td class=\"col-tb-13\">\r\n            <div [innerHTML]=\"ticket.score | sanitizeHtml\"></div>\r\n          </td>\r\n          <td class=\"col-tb-14\">\r\n            <div [innerHTML]=\"ticket.handicap | sanitizeHtml\"></div>\r\n          </td>\r\n          <td class=\"col-tb-15\">\r\n            <div [innerHTML]=\"ticket.choice | sanitizeHtml\"></div>\r\n          </td>\r\n        </tr>\r\n      </tbody>\r\n    </table>\r\n    <table *ngIf=\"model.groups === undefined || model.groups.length == 0 || model.groups == null\">\r\n      <tbody>\r\n        <tr>\r\n          <td class=\"no-data\">There is no data</td>\r\n        </tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n\r\n  <paging [(model)]=\"paging\" (modelChange)=\"pagingEvent()\"></paging>\r\n  <div class=\"list-check-groups\" *ngIf=\"isShowListCheckGroup\">\r\n    <ul [style.top]=\"model.iconCheckBoxTop\">\r\n      <li [ngClass]=\"{'li-checked':model.iconCheckBox == 2}\" (click)=\"model.checkAllGroupsDropDown()\">All</li>\r\n      <li *ngFor=\"let group of model.groups\" \r\n          [ngClass]=\"{'li-checked':group.isCheckAll}\" \r\n          (click)=\"group.isCheckAll = group.isDisabled ? false : !group.isCheckAll;\r\n                group.checkAllTickets();\r\n                model.changeIconCheckBox();\r\n                changeTickets()\">\r\n        {{group.name}}\r\n      </li>\r\n    </ul>\r\n  </div>\r\n</div>\r\n<div class=\"note-lasted-bettrade\" *ngIf=\"showMessageBetTrade\">\r\n  (*) Let it be noted that selected BetTrade ticket at the last row has a \"SOLD\" ticket on the next page which will be\r\n  voided also.\r\n</div>\r\n","import { Component, ElementRef, Input, OnChanges, OnInit } from '@angular/core';\r\nimport { BaseTicketsListComponent } from '../../../utility/components/base-tickets-list/base-tickets-list.component';\r\nimport { StaticService } from '../../../utility/services/static.service';\r\nimport { TicketsModel } from './tickets.model';\r\n\r\n@Component({\r\n  selector: 'tickets-list',\r\n  templateUrl: './tickets-list.component.html',\r\n  styleUrls: ['./tickets-list.component.scss']\r\n})\r\nexport class TicketsListComponent extends BaseTicketsListComponent<TicketsModel> implements OnInit, OnChanges {\r\n  @Input() issueTypeId = 0;\r\n  @Input() isDisableCheckbox = false;\r\n\r\n  title = '';\r\n\r\n  constructor(readonly element: ElementRef) {\r\n    super(element);\r\n  }\r\n\r\n  ngOnChanges() {\r\n    this.initTitle();\r\n  }\r\n\r\n  ngOnInit() {\r\n    this.clickBody();\r\n  }\r\n\r\n  changeTickets() {\r\n    this.ticketsChange.emit(this.model.getNumberOfCheckedTickets());\r\n    this.showWarningBetTradeTicket();\r\n  }\r\n\r\n  showWarningBetTradeTicket() {\r\n    if (this.model.groups.length > 0) {\r\n      const lastGroup = this.model.groups.length - 1;\r\n      const lastedGroup = this.model.groups[lastGroup];\r\n      const lastedTicket = lastedGroup.tickets[lastedGroup.tickets.length - 1];\r\n      this.showMessageBetTrade = lastedTicket.member.toLowerCase().indexOf('bettrade') !== -1 && lastedTicket.isChecked;\r\n    }\r\n  }\r\n\r\n  initTitle() {\r\n    if (StaticService.isHaveCancelCashOutTicket(this.issueTypeId?.toString())) {\r\n      this.title = `(Single Count: ${this.model.totalSingle}, Parlay Count: ${this.model.totalParlay}, Cancel CO: ${this.model.totalCancelCashOut})`;\r\n    } else {\r\n      this.title = `(Single Count: ${this.model.totalSingle}, Parlay Count: ${this.model.totalParlay})`;\r\n    }\r\n\r\n    if (!StaticService.isAbnormalAccount(this.issueTypeId?.toString())) {\r\n      this.title = `Void Time: ${this.model.strFromTime} - ${this.model.strToTime} ${this.title}`;\r\n    }\r\n  }\r\n}\r\n","import { OrdinalNumber } from '../models/ordinal-number.model';\r\nexport class OrdinalNumberConstant {\r\n  static readonly ORDINAL_NUMBER: OrdinalNumber[] = [\r\n    { value: '1', englishValue: '1st', chineseTraditionalValue: '一', chineseSimplifiedValue: '一' },\r\n    { value: '2', englishValue: '2nd', chineseTraditionalValue: '二', chineseSimplifiedValue: '二' },\r\n    { value: '3', englishValue: '3rd', chineseTraditionalValue: '三', chineseSimplifiedValue: '三' },\r\n    { value: '4', englishValue: '4th', chineseTraditionalValue: '四', chineseSimplifiedValue: '四' },\r\n    { value: '5', englishValue: '5th', chineseTraditionalValue: '五', chineseSimplifiedValue: '五' },\r\n    { value: '6', englishValue: '6th', chineseTraditionalValue: '六', chineseSimplifiedValue: '六' },\r\n    { value: '7', englishValue: '7th', chineseTraditionalValue: '七', chineseSimplifiedValue: '七' },\r\n    { value: '8', englishValue: '8th', chineseTraditionalValue: '八', chineseSimplifiedValue: '八' },\r\n    { value: '9', englishValue: '9th', chineseTraditionalValue: '九', chineseSimplifiedValue: '九' },\r\n    { value: '10', englishValue: '10th', chineseTraditionalValue: '十', chineseSimplifiedValue: '十' },\r\n    { value: '11', englishValue: '11th', chineseTraditionalValue: '十 一', chineseSimplifiedValue: '十 一' },\r\n    { value: '12', englishValue: '12th', chineseTraditionalValue: '十 二', chineseSimplifiedValue: '十 二' },\r\n    { value: '13', englishValue: '13th', chineseTraditionalValue: '十 三', chineseSimplifiedValue: '十 三' },\r\n    { value: '14', englishValue: '14th', chineseTraditionalValue: '十 四', chineseSimplifiedValue: '十 四' },\r\n    { value: '15', englishValue: '15th', chineseTraditionalValue: '十 五', chineseSimplifiedValue: '十 五' },\r\n    { value: '16', englishValue: '16th', chineseTraditionalValue: '十 六', chineseSimplifiedValue: '十 六' },\r\n    { value: '17', englishValue: '17th', chineseTraditionalValue: '十 七', chineseSimplifiedValue: '十 七' },\r\n    { value: '18', englishValue: '18th', chineseTraditionalValue: '十 八', chineseSimplifiedValue: '十 八' },\r\n    { value: '19', englishValue: '19th', chineseTraditionalValue: '十 九', chineseSimplifiedValue: '十 九' },\r\n    { value: '20', englishValue: '20th', chineseTraditionalValue: '二 十', chineseSimplifiedValue: '二 十' },\r\n    { value: '21', englishValue: '21st', chineseTraditionalValue: '二 十 一', chineseSimplifiedValue: '二 十 一' },\r\n    { value: '22', englishValue: '22nd', chineseTraditionalValue: '二 十 二', chineseSimplifiedValue: '二 十 二' },\r\n    { value: '23', englishValue: '23rd', chineseTraditionalValue: '二 十 三', chineseSimplifiedValue: '二 十 三' },\r\n    { value: '24', englishValue: '24th', chineseTraditionalValue: '二 十 四', chineseSimplifiedValue: '二 十 四' },\r\n    { value: '25', englishValue: '25th', chineseTraditionalValue: '二 十 五', chineseSimplifiedValue: '二 十 五' }\r\n  ];\r\n}\r\n","export class Message {\r\n    creatorId: number;\r\n    creatorName: string;\r\n    contentEnglish: string;\r\n    contentChineseTraditional: string;\r\n    contentChineseSimplified: string;\r\n    contentNewChineseSimplified: string;\r\n    contentThai: string;\r\n    contentKorean: string;\r\n    contentJapanese: string;\r\n    contentItalian: string;\r\n    contentSpanish: string;\r\n}","import { MatchModel } from \"../../../models/match.model\";\r\nimport { Message } from \"../messages/message\";\r\n\r\nexport class TemplateContent {\r\n  msgEnglish: string;\r\n  msgChineseTraditional: string;\r\n  msgChineseSimplified: string;\r\n  msgChineseNewSimplified: string;\r\n}\r\n\r\nexport class TemplateModel extends TemplateContent {\r\n  templateId: number;\r\n  inputTexts: InputText[];\r\n}\r\n\r\nexport class InputText extends TemplateContent {\r\n  name: string;\r\n  msgEnglishValue: string;\r\n  msgChineseTraditionalValue: string;\r\n  msgChineseSimplifiedValue: string;\r\n  msgChineseNewSimplifiedValue: string;\r\n  hideChinese: boolean;\r\n  pattern: string;\r\n}\r\n\r\nexport class TemplateValue {\r\n  matchId: number;\r\n  sportType?: TemplateContent;\r\n  homeTeamName?: TemplateContent;\r\n  awayTeamName?: TemplateContent;\r\n  leagueName?: TemplateContent;\r\n  eventDate?: string;\r\n  eventType?: string;\r\n  kickOffTime?: string;\r\n  fromTransTime?: Date;\r\n  toTransTime?: Date;\r\n  fromCheckTime?: Date;\r\n  toCheckTime?: Date;\r\n  totalTickets?: number;\r\n  score?: string;\r\n  checkSettled?: boolean;\r\n  sportTypeId?: number;\r\n  isCheckTime?: boolean;\r\n  wrongScore?: string;\r\n  actualScore?: string;\r\n  checkAIOMessage?: boolean;\r\n  isUpdateScoreHaveText?: boolean;\r\n  filterBy?: number;\r\n  wrongMarket?: string;\r\n  actualMarket?: string;\r\n  hdpValue?: string;\r\n  isCheckedEarlyEvent?: boolean;\r\n  isCheckedSpecialBetType?: boolean;\r\n  betTypeNameReplaceMessage?: Message;\r\n  match?: MatchModel;\r\n  betTeam?: string;\r\n  correctOdds?: string;\r\n  filterOuType?: string;\r\n  ouValue?: string;\r\n\r\n  isCheckedVar?: boolean;\r\n  playerName?: TemplateContent;\r\n  numberOfCorner?: number;\r\n}\r\n","<div class=\"ng-tooltip\" [style.top]=\"tooltip.top\" [style.left]=\"tooltip.left\" *ngIf=\"tooltip.show\">\r\n  <em class=\"ng-tooltip-arrow\"></em>\r\n  <span class=\"ng-tooltip-inner\">{{tooltip.message}}</span>\r\n</div>\r\n","import { Component, HostListener, Input } from '@angular/core';\r\nimport { Tooltip } from './tooltip.model';\r\n\r\n@Component({\r\n  selector: 'tooltip',\r\n  templateUrl: './tooltip.component.html',\r\n  styleUrls: ['./tooltip.component.scss']\r\n})\r\nexport class TooltipComponent {\r\n  @Input() tooltip: Tooltip;\r\n  @HostListener('document:mousedown')\r\n  onClick() {\r\n    this.tooltip.show = false;\r\n  }\r\n}\r\n","<div class=\"messages\" *ngIf=\"isShowMessages\">\r\n  <div class=\"gray-header\">\r\n    Message\r\n  </div>\r\n  <table>\r\n    <tbody>\r\n      <tr>\r\n        <th scope=\"col\" colspan=\"4\">\r\n          <span>Please include \"@@\" in your message to replace ticket numbers.</span>\r\n        </th>\r\n      </tr>\r\n      <tr class=\"header-language\">\r\n        <td>\r\n          <span class=\"required\">*</span>English\r\n        </td>\r\n        <td>\r\n          <span class=\"required\">*</span>Chinese Traditional\r\n        </td>\r\n        <td>\r\n          <span class=\"required\">*</span>Chinese Simplified\r\n        </td>\r\n        <td>\r\n          <span class=\"required\">*</span>New Chinese Simplified\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <td>\r\n          <textarea rows=\"1\" [(ngModel)]=\"message.contentEnglish\" class=\"english\"\r\n            (change)=\"changedMessage()\"></textarea>\r\n        </td>\r\n        <td>\r\n          <textarea rows=\"1\" [(ngModel)]=\"message.contentChineseTraditional\" class=\"chinese-traditional\"\r\n            (change)=\"changedMessage()\"></textarea>\r\n        </td>\r\n        <td>\r\n          <textarea rows=\"1\" [(ngModel)]=\"message.contentChineseSimplified\" class=\"chinese-simplified\"\r\n            (change)=\"changedMessage()\"></textarea>\r\n        </td>\r\n        <td>\r\n          <textarea rows=\"1\" [(ngModel)]=\"message.contentNewChineseSimplified\" class=\"new-chinese-simplified\"\r\n            (change)=\"changedMessage()\"></textarea>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <th scope=\"col\" colspan=\"4\" class=\"header-other-language\" (click)=\"isShowOtherLanguage = !isShowOtherLanguage\">\r\n          <span>\r\n            Other languages\r\n            <span *ngIf=\"!isShowOtherLanguage\"> [+]</span>\r\n            <span *ngIf=\"isShowOtherLanguage\"> [-]</span>\r\n          </span>\r\n        </th>\r\n      </tr>\r\n      <tr class=\"header-language\" *ngIf=\"isShowOtherLanguage\">\r\n        <td>\r\n          Thai\r\n        </td>\r\n        <td>\r\n          Korean\r\n        </td>\r\n        <td>\r\n          Japanese\r\n        </td>\r\n        <td>\r\n          Italian\r\n        </td>\r\n      </tr>\r\n      <tr *ngIf=\"isShowOtherLanguage\">\r\n        <td>\r\n          <textarea rows=\"1\" [(ngModel)]=\"message.contentThai\" class=\"thai\" (change)=\"changedMessage()\"></textarea>\r\n        </td>\r\n        <td>\r\n          <textarea rows=\"1\" [(ngModel)]=\"message.contentKorean\" class=\"korean\" (change)=\"changedMessage()\"></textarea>\r\n        </td>\r\n        <td>\r\n          <textarea rows=\"1\" [(ngModel)]=\"message.contentJapanese\" class=\"japanese\"\r\n            (change)=\"changedMessage()\"></textarea>\r\n        </td>\r\n        <td>\r\n          <textarea rows=\"1\" [(ngModel)]=\"message.contentItalian\" class=\"italian\"\r\n            (change)=\"changedMessage()\"></textarea>\r\n        </td>\r\n      </tr>\r\n      <tr class=\"header-language\" *ngIf=\"isShowOtherLanguage\">\r\n        <td>\r\n          Spanish\r\n        </td>\r\n      </tr>\r\n      <tr *ngIf=\"isShowOtherLanguage\">\r\n        <td>\r\n          <textarea rows=\"1\" [(ngModel)]=\"message.contentSpanish\" class=\"spanish\"\r\n            (change)=\"changedMessage()\"></textarea>\r\n        </td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n</div>\r\n<tooltip [tooltip]=\"tooltip\"></tooltip>\r\n","import { Component, ElementRef, EventEmitter, Input, Output } from '@angular/core';\r\nimport { LABELS } from '../../../../utility/constants/labels';\r\nimport { Tooltip } from '../../tooltip/tooltip.model';\r\nimport { Message } from './message';\r\n\r\n@Component({\r\n  selector: 'messages',\r\n  templateUrl: './messages.component.html',\r\n  styleUrls: ['./messages.component.scss']\r\n})\r\n\r\nexport class MessagesComponent {\r\n  @Input() isShowMessages: boolean;\r\n  @Input() message = new Message();\r\n  @Output() messageChange = new EventEmitter<Message>();\r\n  tooltip = new Tooltip();\r\n  isShowOtherLanguage= false;\r\n  constructor(private readonly element: ElementRef) {\r\n    this.tooltip.element = this.element;\r\n\r\n  }\r\n\r\n  checkValidationForMainLanguage(): boolean {\r\n    if (!this.message.contentEnglish) {\r\n      this.tooltip.display('english', LABELS.EMPTY_ENGLISH);\r\n      return false;\r\n    }\r\n    if (this.message.contentEnglish.indexOf('@@') < 0) {\r\n      this.tooltip.display('english', LABELS.INVALID_ENGLISH);\r\n      return false;\r\n    }\r\n    if (!this.message.contentChineseTraditional) {\r\n      this.tooltip.display('chinese-traditional', LABELS.EMPTY_CHINESE_TRADITIONAL);\r\n      return false;\r\n    }\r\n    if (this.message.contentChineseTraditional.indexOf('@@') < 0) {\r\n      this.tooltip.display('chinese-traditional', LABELS.INVALID_CHINESE_TRADITIONAL);\r\n      return false;\r\n    }\r\n    if (!this.message.contentChineseSimplified) {\r\n      this.tooltip.display('chinese-simplified', LABELS.EMPTY_CHINESE_SIMPLIFIED);\r\n      return false;\r\n    }\r\n    if (this.message.contentChineseSimplified.indexOf('@@') < 0) {\r\n      this.tooltip.display('chinese-simplified', LABELS.INVALID_CHINESE_SIMPLIFIED);\r\n      return false;\r\n    }\r\n    if (!this.message.contentNewChineseSimplified) {\r\n      this.tooltip.display('new-chinese-simplified', LABELS.EMPTY_NEW_CHINESE_SIMPLIFIED);\r\n      return false;\r\n    }\r\n    if (this.message.contentNewChineseSimplified.indexOf('@@') < 0) {\r\n      this.tooltip.display('new-chinese-simplified', LABELS.INVALID_NEW_CHINESE_SIMPLIFIED);\r\n      return false;\r\n    }\r\n\r\n    return true;\r\n  }\r\n\r\n  checkContentOfOtherLanguage(content: string): boolean {\r\n    return content && content.indexOf('@@') < 0;\r\n  }\r\n\r\n  checkValidationForOtherLanguage(): boolean {\r\n\r\n    if (this.checkContentOfOtherLanguage(this.message.contentThai)) {\r\n      this.tooltip.display('thai', LABELS.INVALID_THAI);\r\n      return false;\r\n    }\r\n    if (this.checkContentOfOtherLanguage(this.message.contentKorean)) {\r\n      this.tooltip.display('korean', LABELS.INVALID_KOREAN);\r\n      return false;\r\n    }\r\n    if (this.checkContentOfOtherLanguage(this.message.contentJapanese)) {\r\n      this.tooltip.display('japanese', LABELS.INVALID_JAPANESE);\r\n      return false;\r\n    }\r\n    if (this.checkContentOfOtherLanguage(this.message.contentItalian)) {\r\n      this.tooltip.display('italian', LABELS.INVALID_ITALIAN);\r\n      return false;\r\n    }\r\n    if (this.checkContentOfOtherLanguage(this.message.contentSpanish)) {\r\n      this.tooltip.display('spanish', LABELS.INVALID_SPANISH);\r\n      return false;\r\n    }\r\n\r\n\r\n    return true;\r\n  }\r\n\r\n  checkValidation(): boolean {\r\n    let validation = true;\r\n    validation = this.checkValidationForMainLanguage();\r\n    if (!validation) {\r\n      return validation;\r\n    }\r\n    validation = this.checkValidationForOtherLanguage();\r\n    if (!validation) {\r\n      return validation;\r\n    }\r\n\r\n    return true;\r\n  }\r\n\r\n  clearData() {\r\n    this.message = new Message();\r\n  }\r\n\r\n  changedMessage() {\r\n    this.messageChange.emit(this.message);\r\n  }\r\n}\r\n","<div class=\"message-handler\" *ngIf=\"isShowMessages\">\r\n  <ng-container *ngIf=\"isShowDynamicInputs()\">\r\n    <div class=\"input-text\" *ngFor=\"let item of selectedTemplated.inputTexts\">\r\n      <div>\r\n        <label>{{item.msgEnglish}}</label>\r\n        <input type=\"text\" class=\"form-control form-control-sm\" [(ngModel)]=\"item.msgEnglishValue\" (ngModelChange)=\"setChineseInput(item);updateMessage()\">\r\n      </div>\r\n      <div [hidden]=\"item.hideChinese\">\r\n        <label>{{item.msgChineseTraditional}}</label>\r\n        <input type=\"text\" class=\"form-control form-control-sm\" [(ngModel)]=\"item.msgChineseTraditionalValue\" (ngModelChange)=\"updateMessage()\">\r\n      </div>\r\n      <div [hidden]=\"item.hideChinese\">\r\n        <label>{{item.msgChineseSimplified}}</label>\r\n        <input type=\"text\" class=\"form-control form-control-sm\" [(ngModel)]=\"item.msgChineseSimplifiedValue\" (ngModelChange)=\"updateMessage()\">\r\n      </div>\r\n      <div [hidden]=\"item.hideChinese\">\r\n        <label>{{item.msgChineseNewSimplified}}</label>\r\n        <input type=\"text\" class=\"form-control form-control-sm\" [(ngModel)]=\"item.msgChineseNewSimplifiedValue\" (ngModelChange)=\"updateMessage()\">\r\n      </div>\r\n      <div>\r\n        <label class=\"margin-top-30\">{{item.pattern}}</label>\r\n      </div>\r\n    </div>\r\n  </ng-container>\r\n</div>\r\n\r\n<div class=\"d-flex mg-left-10 mb-2\">\r\n  <div class=\"d-flex align-items-center mr-3\" *ngIf=\"isShowAioCheckBoxMessage()\">\r\n    <input [(ngModel)]=\"value.checkAIOMessage\" type=\"checkbox\" id=\"chk-aio-msg\" class=\"mr-1\" (ngModelChange)=\"updateMessage()\"/>\r\n    <label class=\"col-form-label\" for=\"chk-aio-msg\"> AIO Message</label>\r\n  </div>\r\n  <div class=\"d-flex align-items-center mr-3\" *ngIf=\"isShowEarlyEventCheckBoxMessage()\">\r\n    <input [(ngModel)]=\"value.isCheckedEarlyEvent\" [disabled]=\"isDisabledCheckBoxEarlyEvent()\" type=\"checkbox\" id=\"chk-early-event\" class=\"mr-1\" (ngModelChange)=\"updateMessage()\"/>\r\n    <label class=\"col-form-label\" for=\"chk-early-event\"> Early Event</label>\r\n  </div>\r\n  <div class=\"d-flex align-items-center\" *ngIf=\"isShowCheckBoxSpecialBetType()\">\r\n    <input [(ngModel)]=\"value.isCheckedSpecialBetType\" type=\"checkbox\" id=\"chk-special-bet-type\" class=\"mr-1\" (ngModelChange)=\"updateMessage()\"/>\r\n    <label class=\"col-form-label\" for=\"chk-special-bet-type\"> Special Bet type</label>\r\n  </div>\r\n</div>\r\n\r\n<div class=\"message\">\r\n  <messages #messages [isShowMessages]=\"isShowMessages\" [(message)]=\"message\"></messages>\r\n</div>\r\n","import { Component, Input, OnChanges, SimpleChange, ViewChild } from '@angular/core';\r\nimport * as moment from 'moment-timezone';\r\nimport { AbnormalFilterBy, FunctionConst, SubIssueTypeGroup } from '../../../../utility/constants/config';\r\nimport { OrdinalNumberConstant } from '../../../../utility/constants/ordinal-number.constant';\r\nimport { EventType } from '../../../../utility/constants/sport.constant';\r\nimport { SubIssueTypeConstant } from '../../../../utility/constants/sub-issue-type.constant';\r\nimport { HttpService } from '../../../../utility/services/http.service';\r\nimport { StaticService } from '../../../../utility/services/static.service';\r\nimport { Message } from '../messages/message';\r\nimport { MessagesComponent } from './../messages/messages.component';\r\nimport { TemplateSetting, TemplateSettings } from './template-setting.model';\r\nimport { Format, IssueTypeId, SubIssueTypeId, TemplateContentConst, TemplateReplace } from './template.const';\r\nimport { InputText, TemplateContent, TemplateModel, TemplateValue } from './template.model';\r\nimport { TemplateService } from './template.service';\r\n\r\nconst MESSAGE_TEMPLATE_ID_8 = 8;\r\nconst MESSAGE_TEMPLATE_ID_9 = 9;\r\nconst MESSAGE_TEMPLATE_ID_10 = 10;\r\nconst MESSAGE_TEMPLATE_ID_11 = 11;\r\nconst MESSAGE_TEMPLATE_ID_29 = 29;\r\nconst MESSAGE_TEMPLATE_ID_30 = 30;\r\nconst MESSAGE_TEMPLATE_ID_31 = 31;\r\nconst MESSAGE_TEMPLATE_ID_32 = 32;\r\nconst MESSAGE_TEMPLATE_ID_35 = 35;\r\nconst MESSAGE_TEMPLATE_ID_36 = 36;\r\nconst MESSAGE_TEMPLATE_ID_37 = 37;\r\nconst MESSAGE_TEMPLATE_ID_38 = 38;\r\n\r\n@Component({\r\n  selector: 'template-message',\r\n  templateUrl: './template-message.component.html',\r\n  styleUrls: ['./template-message.component.scss']\r\n})\r\nexport class TemplateMessageComponent implements OnChanges {\r\n  @Input() value = new TemplateValue();\r\n  @Input() subIssueTypeId: number;\r\n  @Input() issueTypeId: number;\r\n  @Input() isShowMessages = true;\r\n  @Input() voidFunction?: number;\r\n\r\n  @ViewChild('messages') messagesComponent: MessagesComponent;\r\n\r\n  templates: TemplateModel[] = [];\r\n  selectedTemplated = new TemplateModel();\r\n  message = new Message();\r\n  templateSettings: TemplateSetting[];\r\n\r\n  private readonly hideInputChineseForTemplateId = [\r\n    MESSAGE_TEMPLATE_ID_8,\r\n    MESSAGE_TEMPLATE_ID_9,\r\n    MESSAGE_TEMPLATE_ID_10,\r\n    MESSAGE_TEMPLATE_ID_11,\r\n    MESSAGE_TEMPLATE_ID_29,\r\n    MESSAGE_TEMPLATE_ID_30,\r\n    MESSAGE_TEMPLATE_ID_31,\r\n    MESSAGE_TEMPLATE_ID_32,\r\n    MESSAGE_TEMPLATE_ID_35,\r\n    MESSAGE_TEMPLATE_ID_36,\r\n    MESSAGE_TEMPLATE_ID_38,\r\n  ];\r\n\r\n  private readonly autoBindingChineseForIssueId = [\r\n    IssueTypeId.WRONG_HDP,\r\n    IssueTypeId.WRONG_1ST_HDP,\r\n    IssueTypeId.WRONG_OU,\r\n    IssueTypeId.WRONG_1ST_OU,\r\n    IssueTypeId.WRONG_SCORE,\r\n    IssueTypeId.WRONG_MARKET_OFFERED\r\n  ];\r\n\r\n  public initialize: boolean;\r\n\r\n  constructor(private readonly httpService: HttpService,\r\n\r\n    private readonly templateService: TemplateService,\r\n  ) { }\r\n\r\n  async ngOnChanges(changes: { [propKey: string]: SimpleChange }) {\r\n    await this.init();\r\n    if ((changes['subIssueTypeId'] || changes['value']) && this.subIssueTypeId) {\r\n      this.updateTemplate();\r\n    }\r\n  }\r\n\r\n  async init() {\r\n    if (!this.initialize) {\r\n      await this.getTemplateSetting();\r\n      this.initialize = true;\r\n    }\r\n  }\r\n\r\n  async getTemplateSetting() {\r\n    const data = await this.httpService.getJson<TemplateSettings>('api/MessageTemplate/GetTemplateSettings');\r\n    const messageTemplates = data.messageTemplates;\r\n    messageTemplates.forEach(item => {\r\n      this.setInputTextValue(item);\r\n    });\r\n\r\n    this.templateSettings = data.templateSettings;\r\n    this.templates = messageTemplates;\r\n  }\r\n\r\n  private setInputTextValue(item: TemplateModel) {\r\n    item.inputTexts.forEach(input => {\r\n      input.msgEnglishValue = '';\r\n      input.msgChineseTraditionalValue = '';\r\n      input.msgChineseSimplifiedValue = '';\r\n      input.msgChineseNewSimplifiedValue = '';\r\n      input.hideChinese = this.hideInputChineseForTemplateId.indexOf(item.templateId) > -1;\r\n    });\r\n  }\r\n\r\n  setChineseInput(item: InputText) {\r\n    if (this.autoBindingChineseForIssueId.indexOf(this.issueTypeId) > -1) {\r\n      item.msgChineseTraditionalValue = item.msgChineseSimplifiedValue = item.msgChineseNewSimplifiedValue = item.msgEnglishValue;\r\n    }\r\n  }\r\n\r\n  updateTemplate() {\r\n    let templateId = 0;\r\n    if (this.isAbnormalAccount() || this.isAbnormalBetMixParlay()) {\r\n      templateId = MESSAGE_TEMPLATE_ID_37;\r\n    } else {\r\n      templateId = this.findTemplateId(this.subIssueTypeId, this.value.sportTypeId, this.value.isCheckedVar);\r\n    }\r\n    this.selectedTemplated = this.templates.find(x => x.templateId === templateId);\r\n    this.updateInputsNextCorner();\r\n    this.updateMessage();\r\n  }\r\n\r\n  private findTemplateId(subIssueType: number, sportType?: number, isCheckedVar = false): number {\r\n    const filterSportType = sportType ? sportType : null;\r\n    const filterVar = isCheckedVar ? isCheckedVar : null;\r\n\r\n    const settingsBySubType = this.templateSettings.filter(x => x.subIssueTypeId === subIssueType);\r\n    const settingBySportType = settingsBySubType.find(x => x.sportType === filterSportType && x.isCheckedVar === filterVar);\r\n    const defaultTemplateWhenSportNull = settingsBySubType.find(x => x.sportType === null && x.isCheckedVar === filterVar);\r\n\r\n    return settingBySportType ? settingBySportType.templateId :\r\n      (defaultTemplateWhenSportNull ? defaultTemplateWhenSportNull.templateId : 9999);\r\n  }\r\n\r\n  updateMessage() {\r\n    this.resetMessage();\r\n    this.replaceEventType();\r\n    this.replaceValue();\r\n    if (this.isTVSVoidPage() && this.isWrongScore()) {\r\n      this.updateMessageForWrongScore();\r\n    } else if (this.isTVSVoidPage() && (this.isWrongHDP() || this.isWrong1stHDP())) {\r\n      this.selectedTemplated.inputTexts = [];\r\n      this.updateWrongMarketTVS();\r\n      this.updateActualMarketTVS();\r\n      this.updateHdpTVS();\r\n    } else if (this.isTVSVoidPage() && (this.isWrongOU() || this.isWrong1stOU())) {\r\n      this.selectedTemplated.inputTexts = [];\r\n      this.updateWrongMarketTVS();\r\n      this.updateActualMarketTVS();\r\n    } else if (this.isTVSVoidPage() && this.isWrongOdds()) {\r\n      this.selectedTemplated.inputTexts = [];\r\n      this.updateActualMarketTvsWrongOdds();\r\n    } else {\r\n      this.updateInputs();\r\n    }\r\n\r\n    this.value.isUpdateScoreHaveText ? this.updateScoreHaveText() : this.updateScore();\r\n    this.updateParlay();\r\n    this.updateCheckStatement();\r\n    this.updateAIOMessage();\r\n    this.updateSpecialBetType();\r\n    this.updateActualMarketTvsWrongOdds();\r\n  }\r\n\r\n  resetMessage() {\r\n    this.message.contentEnglish = this.selectedTemplated.msgEnglish;\r\n    this.message.contentChineseTraditional = this.selectedTemplated.msgChineseTraditional;\r\n    this.message.contentChineseSimplified = this.selectedTemplated.msgChineseSimplified;\r\n    this.message.contentNewChineseSimplified = this.selectedTemplated.msgChineseNewSimplified;\r\n  }\r\n\r\n  replaceValue() {\r\n    this.templateService.replaceEachLanguage(this.message, TemplateReplace.SPORT_TYPE, this.value.sportType);\r\n    this.templateService.replaceEachLanguage(this.message, TemplateReplace.HOME_TEAM_NAME, this.value.homeTeamName);\r\n    this.templateService.replaceEachLanguage(this.message, TemplateReplace.AWAY_TEAM_NAME, this.value.awayTeamName);\r\n    this.templateService.replaceEachLanguage(this.message, TemplateReplace.LEAGUE_NAME, this.value.leagueName);\r\n    this.templateService.replaceAll(this.message, TemplateReplace.EVENT_DATE, this.value.eventDate);\r\n    this.templateService.replaceTime(this.message, this.value, this.selectedTemplated.templateId);\r\n    this.templateService.replaceKickOffTime(this.message, this.value.kickOffTime);\r\n    this.templateService.replaceEachLanguage(this.message, TemplateReplace.PLAYER_NAME, this.value.playerName);\r\n  }\r\n\r\n  replaceEventType(): void {\r\n    if (this.value.eventType === EventType.LIVE) {\r\n      this.value.isCheckedEarlyEvent = false;\r\n      this.templateService.replaceEachLanguage(this.message, TemplateReplace.EVENT_TYPE, TemplateContentConst.LIVE);\r\n      return;\r\n    }\r\n\r\n    if (this.value.isCheckedEarlyEvent) {\r\n      this.templateService.replaceEachLanguage(this.message, TemplateReplace.EVENT_TYPE, TemplateContentConst.EARLY);\r\n      return;\r\n    }\r\n\r\n    if (this.checkCanUpdateEventTypeToBlank()) {\r\n      this.templateService.replaceAll(this.message, TemplateReplace.EVENT_TYPE, '');\r\n    } else {\r\n      this.templateService.replaceEachLanguage(this.message, TemplateReplace.EVENT_TYPE, TemplateContentConst.EARLY);\r\n    }\r\n  }\r\n\r\n  checkCanUpdateEventTypeToBlank(): boolean {\r\n    const issueTypes = [\r\n      IssueTypeId.REDUCED_OVER,\r\n      IssueTypeId.WRONG_ODDS,\r\n      IssueTypeId.WRONG_HDP,\r\n      IssueTypeId.WRONG_1ST_HDP,\r\n      IssueTypeId.WRONG_OU,\r\n      IssueTypeId.WRONG_1ST_OU\r\n    ];\r\n\r\n    if (issueTypes.includes(this.issueTypeId)) {\r\n      return true;\r\n    }\r\n\r\n    return issueTypes.includes(this.issueTypeId) && this.value.eventDate === moment(new Date()).format(Format.EVENT_DATE);\r\n  }\r\n\r\n  updateInputs() {\r\n    if (this.issueTypeId === IssueTypeId.WRONG_MARKET_OFFERED\r\n      && this.selectedTemplated.inputTexts[0].msgEnglishValue.length > 0) {\r\n      const isOnwardsSubtype = this.subIssueTypeId === SubIssueTypeId.ONWARDS;\r\n      this.templateService.replaceScoreOfWrongMarketOffered(this.message,\r\n        this.selectedTemplated.inputTexts[0].msgEnglishValue, isOnwardsSubtype);\r\n    } else {\r\n      if (SubIssueTypeGroup.SUBTYPE_ONWARDS.includes(this.subIssueTypeId)) {\r\n        this.templateService.replaceWrongScoreOfWrongScoreIssueType(this.message,\r\n          this.selectedTemplated.inputTexts[0].msgEnglishValue);\r\n        this.templateService.replaceActualScoreOfWrongScoreIssueType(this.message,\r\n          this.selectedTemplated.inputTexts[1].msgEnglishValue);\r\n      } else {\r\n        this.selectedTemplated.inputTexts.forEach(item => {\r\n          const text: TemplateContent = {\r\n            msgEnglish: item.msgEnglishValue,\r\n            msgChineseTraditional: item.msgChineseTraditionalValue,\r\n            msgChineseSimplified: item.msgChineseSimplifiedValue,\r\n            msgChineseNewSimplified: item.msgChineseNewSimplifiedValue\r\n          };\r\n          this.templateService.replaceEachLanguage(this.message, `{{${item.name}}}`, text);\r\n        });\r\n      }\r\n    }\r\n  }\r\n\r\n  updateInputsNextCorner() {\r\n    for(const element of this.selectedTemplated.inputTexts){\r\n      if (this.issueTypeId === IssueTypeId.DANGER_ACCEPTED && this.value.numberOfCorner && element.msgEnglish === \"Next Corner\"){\r\n        const nextCorner = OrdinalNumberConstant.ORDINAL_NUMBER.find(x => x.value === this.value.numberOfCorner.toString());\r\n        element.msgEnglishValue = nextCorner.englishValue;\r\n        element.msgChineseTraditionalValue = `第${nextCorner.chineseTraditionalValue}`;\r\n        element.msgChineseSimplifiedValue = `第${nextCorner.chineseSimplifiedValue}`;\r\n        element.msgChineseNewSimplifiedValue = `第${nextCorner.chineseSimplifiedValue}`;\r\n      }\r\n    }\r\n  }\r\n\r\n  updateMessageForWrongScore() {\r\n    if (this.issueTypeId === IssueTypeId.WRONG_SCORE) {\r\n      if (SubIssueTypeGroup.SUBTYPE_ONWARDS.includes(this.subIssueTypeId)) {\r\n        this.templateService.replaceWrongScoreOfWrongScoreIssueType(this.message,\r\n          this.value.wrongScore);\r\n        this.templateService.replaceActualScoreOfWrongScoreIssueType(this.message,\r\n          this.value.actualScore);\r\n      } else {\r\n        const replacedContent: TemplateContent = {\r\n          msgEnglish: `${this.value.actualScore}`,\r\n          msgChineseTraditional: `${this.value.actualScore}`,\r\n          msgChineseSimplified: `${this.value.actualScore}`,\r\n          msgChineseNewSimplified: `${this.value.actualScore}`\r\n        };\r\n\r\n        this.templateService.replaceEachLanguage(this.message, TemplateReplace.ACTUAL_SCORE, replacedContent);\r\n      }\r\n    }\r\n  }\r\n\r\n  updateWrongMarketTVS() {\r\n    if (this.value.wrongMarket) {\r\n      const content: TemplateContent = {\r\n        msgEnglish: `${this.value.wrongMarket}`,\r\n        msgChineseTraditional: `${this.value.wrongMarket}`,\r\n        msgChineseSimplified: `${this.value.wrongMarket}`,\r\n        msgChineseNewSimplified: `${this.value.wrongMarket}`\r\n      };\r\n      this.templateService.replaceEachLanguage(this.message, TemplateReplace.WRONG_MARKET, content);\r\n    } else {\r\n      this.templateService.replaceAll(this.message, TemplateReplace.WRONG_MARKET, '');\r\n    }\r\n  }\r\n\r\n  updateActualMarketTVS() {\r\n    if (this.value.actualMarket) {\r\n      const content: TemplateContent = {\r\n        msgEnglish: `${this.value.actualMarket}`,\r\n        msgChineseTraditional: `${this.value.actualMarket}`,\r\n        msgChineseSimplified: `${this.value.actualMarket}`,\r\n        msgChineseNewSimplified: `${this.value.actualMarket}`\r\n      };\r\n      this.templateService.replaceEachLanguage(this.message, TemplateReplace.ACTUAL_MARKET, content);\r\n    } else {\r\n      this.templateService.replaceAll(this.message, TemplateReplace.ACTUAL_MARKET, '');\r\n    }\r\n  }\r\n\r\n  updateHdpTVS() {\r\n    if (this.value.hdpValue) {\r\n      const content: TemplateContent = {\r\n        msgEnglish: `${this.value.hdpValue}`,\r\n        msgChineseTraditional: `${this.value.hdpValue}`,\r\n        msgChineseSimplified: `${this.value.hdpValue}`,\r\n        msgChineseNewSimplified: `${this.value.hdpValue}`\r\n      };\r\n      this.templateService.replaceEachLanguage(this.message, TemplateReplace.HDP_VALUE, content);\r\n    } else {\r\n      this.templateService.replaceAll(this.message, TemplateReplace.HDP_VALUE, '');\r\n    }\r\n  }\r\n\r\n  updateScore() {\r\n    if (this.value.score !== undefined && this.value.score.length > 0) {\r\n      const score: TemplateContent = {\r\n        msgEnglish: `(${TemplateContentConst.SCORE.msgEnglish} ${this.value.score}) `,\r\n        msgChineseTraditional: `(${TemplateContentConst.SCORE.msgChineseTraditional} ${this.value.score}) `,\r\n        msgChineseSimplified: `(${TemplateContentConst.SCORE.msgChineseSimplified} ${this.value.score}) `,\r\n        msgChineseNewSimplified: `(${TemplateContentConst.SCORE.msgChineseNewSimplified} ${this.value.score}) `\r\n      };\r\n      this.templateService.replaceEachLanguage(this.message, TemplateReplace.SCORE, score);\r\n    } else {\r\n      this.templateService.replaceAll(this.message, TemplateReplace.SCORE, '');\r\n    }\r\n  }\r\n\r\n  updateScoreHaveText() {\r\n    if (this.value.score !== undefined && this.value.score.length > 0) {\r\n      const score: TemplateContent = {\r\n        msgEnglish: `(${TemplateContentConst.SCORE.msgEnglish} ${this.value.score} ${TemplateContentConst.ONWARDS.msgEnglish}) `,\r\n        msgChineseTraditional:\r\n          `(${TemplateContentConst.SCORE.msgChineseTraditional} ${this.value.score} ${TemplateContentConst.ONWARDS.msgChineseTraditional}) `,\r\n        msgChineseSimplified:\r\n          `(${TemplateContentConst.SCORE.msgChineseSimplified} ${this.value.score} ${TemplateContentConst.ONWARDS.msgChineseSimplified}) `,\r\n        msgChineseNewSimplified:\r\n          `(${TemplateContentConst.SCORE.msgChineseNewSimplified} ${this.value.score} ${TemplateContentConst.ONWARDS.msgChineseNewSimplified}) `\r\n      };\r\n      this.templateService.replaceEachLanguage(this.message, TemplateReplace.SCORE, score);\r\n    } else {\r\n      this.templateService.replaceAll(this.message, TemplateReplace.SCORE, '');\r\n    }\r\n  }\r\n\r\n  updateCheckStatement() {\r\n    if (this.value.checkSettled) {\r\n      this.templateService.replaceEachLanguage(this.message, TemplateReplace.CHECK_STATEMENT, TemplateContentConst.CHECK_STATEMENT);\r\n    } else {\r\n      this.templateService.replaceAll(this.message, TemplateReplace.CHECK_STATEMENT, '');\r\n    }\r\n  }\r\n\r\n  updateAIOMessage() {\r\n    if (this.value.checkAIOMessage) {\r\n      this.templateService.replaceAOIMessage(this.message);\r\n    } else {\r\n      this.templateService.replaceAll(this.message, TemplateReplace.AOI_MESSAGE, '');\r\n    }\r\n  }\r\n\r\n  updateParlay() {\r\n    if (this.isAbnormalBetMixParlay()) {\r\n      this.templateService.replaceEachLanguage(this.message, TemplateReplace.PARLAY, TemplateContentConst.PARLAY);\r\n    } else {\r\n      this.templateService.replaceAll(this.message, TemplateReplace.PARLAY, '');\r\n    }\r\n  }\r\n\r\n  updateSpecialBetType() {\r\n    if (this.value.isCheckedSpecialBetType && this.issueTypeUpdateSpecialBetTypeVoidSingleBet()) {\r\n      this.templateService.replaceSpecialBetType(this.message, this.value.betTypeNameReplaceMessage);\r\n    } else {\r\n      this.templateService.replaceAll(this.message, TemplateReplace.SPECIAL_BET_TYPE, '');\r\n    }\r\n  }\r\n\r\n  updateActualMarketTvsWrongOdds() {\r\n    if (this.isTVSVoidPage() && this.isWrongOdds()) {\r\n      this.templateService.replaceActualMarketTvsWrongOdds(this.message, this.subIssueTypeId, this.value);\r\n    } else {\r\n      this.templateService.replaceAll(this.message, TemplateReplace.ACTUAL_MARKET, '');\r\n    }\r\n  }\r\n\r\n  issueTypeUpdateSpecialBetTypeVoidSingleBet(): boolean {\r\n    return this.isVoidSinglePage() &&\r\n      (this.isWrongHDP() || this.isWrongQuarterHDP() || this.isWrongOdds()\r\n        || (this.isWrongOU() && this.selectedTemplated.templateId !== MESSAGE_TEMPLATE_ID_38)\r\n        || (this.isOtherIssues() && this.subIssueTypeId === SubIssueTypeConstant.TECHNICAL_ERROR));\r\n  }\r\n\r\n  checkValidation(): boolean {\r\n    return this.messagesComponent.checkValidation();\r\n  }\r\n\r\n  public isHasWarningForDynamicInput(): boolean {\r\n    if (this.isShowDynamicInputs()) {\r\n      const isInputsValid = this.selectedTemplated.inputTexts.some(x => !x.msgEnglishValue || !x.msgChineseTraditionalValue\r\n        || !x.msgChineseSimplifiedValue || !x.msgChineseNewSimplifiedValue);\r\n\r\n      return isInputsValid;\r\n    }\r\n\r\n    return false;\r\n  }\r\n\r\n  isDisabledCheckBoxEarlyEvent(): boolean {\r\n    return this.value.eventType === EventType.LIVE;\r\n  }\r\n\r\n  isShowCheckBoxSpecialBetType(): boolean {\r\n    return this.isShowMessages && this.isssueTypeShowCheckBoxSpecialBetTypeVoidSingleBet();\r\n  }\r\n\r\n  isssueTypeShowCheckBoxSpecialBetTypeVoidSingleBet(): boolean {\r\n    return this.isVoidSinglePage() &&\r\n    (this.isWrongHDP() || this.isWrongQuarterHDP() || this.isWrongOdds()\r\n      || (this.isWrongOU() && this.selectedTemplated.templateId !== MESSAGE_TEMPLATE_ID_38)\r\n      || (this.isOtherIssues && this.subIssueTypeId === SubIssueTypeConstant.TECHNICAL_ERROR));\r\n  }\r\n\r\n  isShowAioCheckBoxMessage(): boolean {\r\n    return this.isShowMessages && this.isVoidSinglePage() && (this.isWrongHDP() || this.isWrong1stHDP() || this.isWrongOU() || this.isWrong1stOU());\r\n  }\r\n\r\n  isShowEarlyEventCheckBoxMessage(): boolean {\r\n    return this.isShowMessages && (this.isssueTypeShowEarlyEventCheckBoxMessageVoidSingleBet() || this.isWrongOdds());\r\n  }\r\n\r\n  isssueTypeShowEarlyEventCheckBoxMessageVoidSingleBet(): boolean {\r\n    return this.isVoidSinglePage() && (this.isWrongHDP() || this.isWrong1stHDP() || this.isWrongOU() || this.isWrong1stOU());\r\n  }\r\n\r\n  isAbnormalBetMixParlay(): boolean {\r\n    return this.isAbnormalBet() && this.value.filterBy === AbnormalFilterBy.MIX_PARLAY;\r\n  }\r\n\r\n  isAbnormalAccount(): boolean {\r\n    return StaticService.isAbnormalAccount(this.issueTypeId?.toString());\r\n  }\r\n\r\n  isAbnormalBet(): boolean {\r\n    return StaticService.isAbnormalBet(this.issueTypeId?.toString());\r\n  }\r\n\r\n  isWrongScore(): boolean {\r\n    return StaticService.isWrongScore(this.issueTypeId?.toString());\r\n  }\r\n\r\n  isTVSVoidPage(): boolean {\r\n    return this.voidFunction === FunctionConst.TVS_VOID_PAGE;\r\n  }\r\n\r\n  isVoidSinglePage(): boolean {\r\n    return this.voidFunction === FunctionConst.SINGLE;\r\n  }\r\n\r\n  isShowDynamicInputs(): boolean {\r\n    return this.isVoidSinglePage() || (this.isTVSVoidPage() && !this.isWrongScore() && !this.isWrongOdds());\r\n  }\r\n\r\n  isWrongOdds(): boolean {\r\n    return StaticService.isWrongOdds(this.issueTypeId?.toString());\r\n  }\r\n\r\n  isWrongHDP(): boolean {\r\n    return StaticService.isWrongHDP(this.issueTypeId?.toString());\r\n  }\r\n\r\n  isWrong1stHDP(): boolean {\r\n    return StaticService.isWrong1stHDP(this.issueTypeId?.toString());\r\n  }\r\n\r\n  isWrongQuarterHDP(): boolean {\r\n    return StaticService.isWrongQuarterHDP(this.issueTypeId?.toString());\r\n  }\r\n\r\n  isWrongOU(): boolean {\r\n    return StaticService.isWrongOU(this.issueTypeId?.toString());\r\n  }\r\n\r\n  isWrong1stOU(): boolean {\r\n    return StaticService.isWrong1stOU(this.issueTypeId?.toString());\r\n  }\r\n\r\n  isOtherIssues(): boolean {\r\n    return StaticService.isOtherIssues(this.issueTypeId?.toString());\r\n  }\r\n}\r\n","<div>\r\n  <ng-container *ngIf=\"isLoadedBasicData\">\r\n    <div *ngFor=\"let item of voidMatches; let id = index\" class=\"bg-gray match-void\">\r\n      <div class=\"full-width d-flex bg-gray match-void\">\r\n        <div class=\"index-of-match d-flex align-items-center\">\r\n          <div class=\"number-circle\"><span><strong>{{id + 1}}</strong></span></div>\r\n        </div>\r\n        <div class=\"col-sm-3 d-flex flex-column pd-right-0 pd-left-10\">\r\n          <div>\r\n            <div class=\"alert alert-dark p-1 m-0 mb-1\"><span>\r\n              <span *ngIf=\"item.isCheckedVar\" class=\"alert padding-2-10 text-white bg-danger\">VAR</span>\r\n              Issue Type: <strong>{{item.displayIssueTypeName}}</strong></span>\r\n            </div>\r\n          </div>\r\n          <div class=\"alert alert-dark match-info p-1 m-0 flex-grow-1\">\r\n            <span>Match Code/ID:\r\n\r\n              <strong class=\"match-text\">{{item.matchModel.matchCode}}/{{item.matchModel.matchId}}</strong></span><br />\r\n            <span>Match Event: <strong class=\"match-text\">{{item.matchModel.matchEvent}}</strong></span><br />\r\n            <span>League: <strong class=\"match-text\">{{item.matchModel.leagueName}}</strong></span><br />\r\n            <span *ngIf=\"isWrongHdp() || isWrong1stHdp() || isWrongOu() || isWrong1stOu()\" class=\"d-flex align-items-center\">\r\n              <input type=\"checkbox\" id=\"chk-early-event-{{id}}\" class=\"mr-1\"\r\n                [disabled]=\"item.isAllLiveTickets || item.voidTicketsMini?.total === 0\"\r\n                [(ngModel)]=\"item.isCheckedEarlyEvent\"\r\n                (change)=\"changeCheckBoxEarlyEvent(item)\"/>\r\n              <label class=\"col-form-label\" for=\"chk-early-event-{{id}}\">Early Event</label>\r\n            </span>\r\n          </div>\r\n        </div>\r\n        <div class=\"col-sm-6 m-0 pd-right-0 pd-left-5\">\r\n          <div class=\"log-info-cell alert alert-dark p-1 m-0\">\r\n            <log-info-new [logInfoDetail]=\"item.logInfoDetail\" [issueTypeId]=\"requestDetail.request.issueTypeId\" [isMainMatch]=\"item.isMainMatch\" [isPoolHouseAffected]=\"item.isPoolHouseAffected\"></log-info-new>\r\n          </div>\r\n        </div>\r\n        <div class=\"ml-3\" *ngIf=\"isWrongHdp() || isWrong1stHdp() || isWrongOu() || isWrong1stOu()\">\r\n          <div class=\"wrong-market d-flex mb-3\" *ngIf=\"item.wrongMarket\">\r\n            <div><label class=\"col-form-label mr-2\">Wrong Market</label></div>\r\n            <input\r\n              [ngModel]=\"item.wrongMarket\"\r\n              disabled\r\n              type=\"text\" class=\"wrong-market-input form-control form-control-sm\"/>\r\n          </div>\r\n          <div class=\"actual-market d-flex\" *ngIf=\"item.actualMarket\">\r\n            <div><label class=\"col-form-label mr-2\">Actual Market</label></div>\r\n            <input [ngModel]=\"item.actualMarket\"\r\n              disabled\r\n              type=\"text\" class=\"actual-market-input form-control form-control-sm\"/>\r\n          </div>\r\n          <div class=\"hdp-value d-flex\" *ngIf=\"item.hdpValue\">\r\n            <div><label class=\"col-form-label mr-2\">HDP Value</label></div>\r\n            <input [ngModel]=\"item.hdpValue\"\r\n              disabled\r\n              type=\"text\" class=\"hdp-value-input form-control form-control-sm\"/>\r\n          </div>\r\n        </div>\r\n        <div class=\"flex-grow-1\">\r\n          <div class=\"area-icon\">\r\n            <em [ngClass]=\"item.isShowTicketFull ? 'icon-show-tickets-expanded': 'icon-show-tickets'\"\r\n              (click)=\"onClickShowVoidTickets(item)\"></em>\r\n            <em\r\n              [ngClass]=\"item.isShowTemplateMessage ? 'icon-show-template-message-expanded' : 'icon-show-template-message'\"\r\n              (click)=\"onClickShowTemplateMessage(item)\"></em>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div>\r\n        <div class=\"affected-licensees\" *ngIf=\"item.isShowTicketFull && isShowAffectedLicenseeArea(item)\">\r\n          <span class=\"note\">Attn: system will notify affected tickets to these Licensee(s): </span><br />\r\n          <div *ngIf=\"item.affectedLicensee.show && item.affectedLicensee.licenseesName.length > 0\">\r\n            <span class=\"affected-licensees-highlight\"\r\n              (click)=\"onClickCopyLicenseesToClipboard(item.affectedLicensee.licenseesName)\">{{item.affectedLicensee.licenseesName}}</span>\r\n          </div>\r\n          <div class=\"china-view-licensee\"\r\n            *ngIf=\"item.chinaViewLicensee.show && item.chinaViewLicensee.licenseesName.length > 0\">\r\n            <span class=\"note\">China View Licensee Affected List:</span><br />\r\n            <span class=\"affected-licensees-highlight\"\r\n              (click)=\"onClickCopyLicenseesToClipboard(item.chinaViewLicensee.licenseesName)\">{{item.chinaViewLicensee.licenseesName}}</span>\r\n          </div>\r\n          <div class=\"instant-licensee\"\r\n            *ngIf=\"item.affectedInstantLicensee.show && item.affectedInstantLicensee.licenseesName.length > 0\">\r\n            <span class=\"note\">Instant OU Licensee Affected List:</span><br />\r\n            <span class=\"affected-licensees-highlight\"\r\n              (click)=\"onClickCopyLicenseesToClipboard(item.affectedInstantLicensee.licenseesName)\">{{item.affectedInstantLicensee.licenseesName}}</span>\r\n          </div>\r\n          <div class=\"cash-out-licensee\"\r\n            *ngIf=\"item.cashOutLicensee.show && item.cashOutLicensee.licenseesName.length > 0\">\r\n            <span class=\"note\">Cash Out Licensee Affected List:</span><br />\r\n            <span class=\"affected-licensees-highlight\"\r\n                (click)=\"onClickCopyLicenseesToClipboard(item.cashOutLicensee.licenseesName)\">{{item.cashOutLicensee.licenseesName}}</span>\r\n          </div>\r\n        </div>\r\n\r\n        <tickets-list class=\"m-0\" *ngIf=\"item.isShowTicketFull\" [model]=\"item.voidTicketsFull\"\r\n          [(paging)]=\"item.pagingVoidTickets\" (pagingChange)=\"onPagingTicketsChange(item)\" (exportExcelEvent)=\"exportTickets(item)\"\r\n          [isBlock]=\"item.isBlockBetList\" (ticketsChange)=\"null\" [issueTypeId]=\"requestDetail.request.issueTypeId\"\r\n          [isDisableCheckbox]=\"true\">\r\n        </tickets-list>\r\n\r\n        <div [ngClass]=\"item.isShowTemplateMessage ? 'display-block' : 'display-none'\">\r\n          <ng-container *ngIf=\"item.voidTicketsMini?.total > 0\">\r\n            <template-message #templateMessage [value]=\"item.templateValue\"\r\n              [issueTypeId]=\"requestDetail.request.issueTypeId\" [subIssueTypeId]=\"item.subIssueType.subIssueTypeId\"\r\n              [voidFunction]=\"2\"\r\n              >\r\n            </template-message>\r\n\r\n            <div class=\"reason-area\">\r\n              <div class=\"gray-header\">\r\n                Reason\r\n              </div>\r\n              <table>\r\n                <tr class=\"header-language\">\r\n                  <td>\r\n                    <span class=\"required\">&nbsp;&nbsp;*</span> <span>English (Max {{150 -\r\n                      item.voidReason.reasonEnglish?.length}} characters)</span>\r\n                  </td>\r\n                  <td>\r\n                    <span class=\"required\">&nbsp;&nbsp;*</span> <span>Chinese Simplified (Max {{150 -\r\n                      item.voidReason.reasonChineseSimplified?.length}} characters)</span>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td>\r\n                    <textarea maxlength=\"150\" class=\"reason\" [(ngModel)]=\"item.voidReason.reasonEnglish\"></textarea>\r\n                  </td>\r\n                  <td>\r\n                    <textarea maxlength=\"150\" class=\"reasonSC\"\r\n                      [(ngModel)]=\"item.voidReason.reasonChineseSimplified\"></textarea>\r\n                  </td>\r\n                </tr>\r\n              </table>\r\n            </div>\r\n          </ng-container>\r\n\r\n          <ng-container *ngIf=\"item.voidTicketsMini?.total === 0\">\r\n            <div class=\"reason-area\">\r\n              <div class=\"gray-header\">\r\n                Message\r\n              </div>\r\n              <textarea class=\"no-data-text\" rows=\"1\" readonly>There is no data</textarea>\r\n            </div>\r\n            <div class=\"reason-area\">\r\n              <div class=\"gray-header\">\r\n                Reason\r\n              </div>\r\n              <textarea class=\"no-data-text\" rows=\"1\" readonly>There is no data</textarea>\r\n            </div>\r\n          </ng-container>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <fieldset class=\"confirm-delete\">\r\n      <legend>Confirmation</legend>\r\n      <table>\r\n        <tr>\r\n          <td>\r\n            <label>Username</label>\r\n          </td>\r\n          <td>\r\n            <input class=\"form-control form-control-sm\" type=\"text\" disabled value=\"{{primitiveProperty.userName}}\" />\r\n          </td>\r\n          <td></td>\r\n        </tr>\r\n        <tr>\r\n          <td>\r\n            <label>Password</label>\r\n          </td>\r\n          <td>\r\n            <input autocomplete=\"new-password\" type=\"password\" class=\"password form-control form-control-sm\"\r\n              [(ngModel)]=\"primitiveProperty.userPassword\" />\r\n          </td>\r\n          <td><span>&nbsp;&nbsp;(*)</span></td>\r\n        </tr>\r\n        <tr>\r\n          <td></td>\r\n          <td>\r\n            <input type=\"button\" class=\"btn btn-success btn-sm font-weight-bold btn-void-all-matches\"\r\n              value=\"Void All Matches\" [disabled]=\"primitiveProperty.isBlockUI\" (click)=\"onClickVoidAllMatches()\" />\r\n          </td>\r\n        </tr>\r\n      </table>\r\n    </fieldset>\r\n    <div *ngIf=\"primitiveProperty.errorMessage\" class=\"error-text error-color\">\r\n      <i class=\"fa fa-times-circle icon-error-message\" aria-hidden=\"true\"></i>{{primitiveProperty.errorMessage}}\r\n    </div>\r\n\r\n    <tooltip [tooltip]=\"tooltip\"></tooltip>\r\n  </ng-container>\r\n</div>\r\n<div *ngIf=\"primitiveProperty.isBlockUI\">\r\n  <div class=\"in modal-backdrop spinner-overlay\"></div>\r\n  <div class=\"spinner-message-container\" aria-live=\"assertive\" aria-atomic=\"true\">\r\n    <div class=\"loading-message\">\r\n      <div class=\"loading\"></div>\r\n    </div>\r\n  </div>\r\n</div>\r\n","import { Component, ElementRef, Input, OnInit, QueryList, ViewChildren } from '@angular/core';\r\nimport * as _ from 'lodash';\r\nimport { ClipboardService } from 'ngx-clipboard';\r\nimport { Subscription, timer } from 'rxjs';\r\nimport { RequestDetailViewModel } from '../../../edit-request/app/request.model';\r\nimport { TemplateMessageComponent } from '../../../utility/components/template-message/template-message/template-message.component';\r\nimport { Tooltip } from '../../../utility/components/tooltip/tooltip.model';\r\nimport { LABELS } from '../../../utility/constants/labels';\r\nimport { SubIssueTypeConstant } from '../../../utility/constants/sub-issue-type.constant';\r\nimport { IssueTypesModel } from '../../../utility/models/issue-type.model';\r\nimport { StaticService } from '../../../utility/services/static.service';\r\nimport { VoidMatch } from '../models/void-match.model';\r\nimport { CheckRequestService } from '../services/check-request.service';\r\nimport { PopupService } from './services/popup.service';\r\nimport { SubmitVoidService } from './services/submit-void.service';\r\nimport { TicketsService } from './services/tickets.service';\r\nimport { VoidPageService } from './services/void-page.service';\r\nimport { PrimitiveProperty } from './void-danger-accepted.model';\r\n@Component({\r\n  selector: 'void-danger-accepted',\r\n  templateUrl: './void-danger-accepted.component.html',\r\n  styleUrls: ['./void-danger-accepted.component.scss']\r\n})\r\nexport class VoidDangerAcceptedComponent implements OnInit {\r\n  @Input('requestDetail') requestDetail: RequestDetailViewModel;\r\n  @ViewChildren(\"templateMessage\") templateMessageViewChildren: QueryList<TemplateMessageComponent>;\r\n\r\n  public primitiveProperty = new PrimitiveProperty();\r\n  public voidMatches: VoidMatch[] = [];\r\n  public isLoadedBasicData = false;\r\n  public isLoadedUnderneathData = false;\r\n  public issueTypes: IssueTypesModel;\r\n  public tooltip = new Tooltip();\r\n\r\n\r\n  private afterLoadUnderneathDataSubscription: Subscription;\r\n  private readonly observableTimer = timer(0, 100);\r\n  private isRunningSubscriptionCallback = false;\r\n\r\n  constructor(\r\n    private readonly voidPageService: VoidPageService,\r\n    private readonly ticketsService: TicketsService,\r\n    private readonly popupService: PopupService,\r\n    private readonly submitVoidService: SubmitVoidService,\r\n    private readonly checkRequestService: CheckRequestService,\r\n    private readonly clipboardService: ClipboardService,\r\n    private readonly element: ElementRef) {\r\n    this.tooltip.element = this.element;\r\n  }\r\n\r\n  async ngOnInit(): Promise<void> {\r\n    this.primitiveProperty.isBlockUI = true;\r\n    this.primitiveProperty.userName = document.body.getAttribute('user-name');\r\n    this.issueTypes = await this.voidPageService.getIssueTypes();\r\n    this.voidMatches = await this.voidPageService.getBasicVoidMatchesData(this.issueTypes, this.requestDetail, this.primitiveProperty);\r\n    this.isLoadedBasicData = true;\r\n    this.primitiveProperty.isBlockUI = false;\r\n\r\n    await this.voidPageService.loadUnderneathVoidMatchesData(this.voidMatches, this.requestDetail);\r\n    this.isLoadedUnderneathData = true;\r\n  }\r\n\r\n  async onClickShowVoidTickets(voidMatch: VoidMatch): Promise<void> {\r\n    if (!voidMatch.isShowTicketFull) {\r\n      this.primitiveProperty.isBlockUI = true;\r\n      const isRequestModified = await this.checkRequestService.isRequestModified(this.requestDetail.requestId, this.requestDetail.lastModifiedDate);\r\n      this.primitiveProperty.isBlockUI = false;\r\n      if (isRequestModified) {\r\n        return;\r\n      }\r\n    }\r\n\r\n    this.voidPageService.toggleTicketsArea(voidMatch, this.voidMatches);\r\n    if (!voidMatch.isLoadedTicketFull) {\r\n      await this.ticketsService.loadVoidTicketsFullOnFirstTime(voidMatch, this.requestDetail);\r\n    }\r\n  }\r\n\r\n  async onPagingTicketsChange(voidMatch: VoidMatch): Promise<void> {\r\n    await this.ticketsService.loadVoidTicketsFullOnPagingChange(voidMatch, this.requestDetail);\r\n  }\r\n\r\n  async exportTickets(voidMatch: VoidMatch) {\r\n    const maxPagingItems = 100000;\r\n    if (voidMatch.pagingVoidTickets.total > maxPagingItems) {\r\n      this.popupService.showWarningExportExcel();\r\n    } else {\r\n      await this.ticketsService.exportTicketsAsExcelFile(voidMatch, this.requestDetail);\r\n    }\r\n  }\r\n\r\n  async onClickShowTemplateMessage(voidMatch: VoidMatch): Promise<void> {\r\n    if (!voidMatch.isShowTemplateMessage) {\r\n      this.primitiveProperty.isBlockUI = true;\r\n      const isRequestModified = await this.checkRequestService.isRequestModified(this.requestDetail.requestId, this.requestDetail.lastModifiedDate);\r\n      this.primitiveProperty.isBlockUI = false;\r\n      if (isRequestModified) {\r\n        return;\r\n      }\r\n    }\r\n\r\n    if (this.afterLoadUnderneathDataSubscription) {\r\n      this.afterLoadUnderneathDataSubscription.unsubscribe();\r\n    }\r\n\r\n    this.afterLoadUnderneathDataSubscription = this.observableTimer.subscribe(async () => {\r\n      await this.checkLoadedFullDataBeforeShowMessageTemplate(voidMatch);\r\n    });\r\n  }\r\n\r\n  isShowAffectedLicenseeArea(voidMatch: VoidMatch): boolean {\r\n    return voidMatch.affectedLicensee.show && voidMatch.affectedLicensee.licenseesName.length > 0\r\n      || voidMatch.chinaViewLicensee.show && voidMatch.chinaViewLicensee.licenseesName.length > 0\r\n      || voidMatch.affectedInstantLicensee.show && voidMatch.affectedInstantLicensee.licenseesName.length > 0\r\n      || voidMatch.cashOutLicensee.show && voidMatch.cashOutLicensee.licenseesName.length > 0;\r\n  }\r\n  \r\n  onClickCopyLicenseesToClipboard(text: string): void {\r\n    this.clipboardService.copyFromContent(text);\r\n    alert('The Licensee list has been copied to clipboard.');\r\n  }\r\n\r\n  onClickVoidAllMatches(): void {\r\n    if (!this.primitiveProperty.userPassword) {\r\n      this.tooltip.display('password', LABELS.INPUT_PASSWORD);\r\n      return;\r\n    }\r\n\r\n    if (this.afterLoadUnderneathDataSubscription) {\r\n      this.afterLoadUnderneathDataSubscription.unsubscribe();\r\n    }\r\n\r\n    this.afterLoadUnderneathDataSubscription = this.observableTimer.subscribe(async () => {\r\n      await this.checkLoadedFullDataBeforeVoid();\r\n    });\r\n  }\r\n\r\n  async checkLoadedFullDataBeforeShowMessageTemplate(voidMatch: VoidMatch): Promise<void> {\r\n    if (this.isRunningSubscriptionCallback) {\r\n      return;\r\n    }\r\n    this.isRunningSubscriptionCallback = true;\r\n    this.primitiveProperty.isBlockUI = true;\r\n\r\n    if (this.isLoadedUnderneathData) {\r\n      this.voidPageService.toggleTemplateMessageArea(voidMatch, this.voidMatches);\r\n      this.primitiveProperty.isBlockUI = false;\r\n      this.afterLoadUnderneathDataSubscription.unsubscribe();\r\n    }\r\n\r\n    this.isRunningSubscriptionCallback = false;\r\n  }\r\n\r\n  async checkLoadedFullDataBeforeVoid(): Promise<void> {\r\n    if (this.isRunningSubscriptionCallback) {\r\n      return;\r\n    }\r\n\r\n    this.isRunningSubscriptionCallback = true;\r\n    this.primitiveProperty.isBlockUI = true;\r\n    const templateMessageComponents = this.templateMessageViewChildren.toArray();\r\n    if (this.isLoadedUnderneathData && templateMessageComponents.every(x => x.initialize)) {\r\n      await this.submitVoidService.voidAllMatches(templateMessageComponents, this.voidMatches, this.requestDetail, this.primitiveProperty);\r\n      this.afterLoadUnderneathDataSubscription.unsubscribe();\r\n    }\r\n\r\n    this.isRunningSubscriptionCallback = false;\r\n  }\r\n\r\n  public changeCheckBoxEarlyEvent(voidMatch: VoidMatch): void {\r\n    voidMatch.templateValue.isCheckedEarlyEvent = voidMatch.isCheckedEarlyEvent;\r\n    voidMatch.templateValue = _.clone(voidMatch.templateValue);\r\n  }\r\n\r\n  public isWrongHdp(): boolean {\r\n    return StaticService.isWrongHDP(this.requestDetail.request?.issueTypeId.toString());\r\n  }\r\n\r\n  public isWrong1stHdp(): boolean {\r\n    return StaticService.isWrong1stHDP(this.requestDetail.request?.issueTypeId.toString());\r\n  }\r\n\r\n  public isWrongOu(): boolean {\r\n    return StaticService.isWrongOU(this.requestDetail.request?.issueTypeId.toString());\r\n  }\r\n\r\n  public isWrong1stOu(): boolean {\r\n    return StaticService.isWrong1stOU(this.requestDetail.request?.issueTypeId.toString());\r\n  }\r\n\r\n  public isSubTypeWrongHdpOrWrong1stHdp(): boolean {\r\n    return this.isSubTypeWrongHdp() || this.isSubTypeWrong1stHdp();\r\n  }\r\n\r\n  private isSubTypeWrongHdp(): boolean {\r\n    return this.voidMatches[0].subIssueType.subIssueTypeId === SubIssueTypeConstant.WRONG_HDP;\r\n  }\r\n\r\n  private isSubTypeWrong1stHdp(): boolean {\r\n    return this.voidMatches[0].subIssueType.subIssueTypeId === SubIssueTypeConstant.WRONG_1ST_HDP;\r\n  }\r\n}\r\n","export class ItemsSelect {\r\n  id: number;\r\n  value: string;\r\n  text: string;\r\n  checked: boolean;\r\n  expanded: boolean;\r\n  enable: boolean;\r\n  items: ItemsSelect[];\r\n  countChilds: number;\r\n\r\n  constructor(\r\n      id: number,\r\n      value: string,\r\n      text: string,\r\n      checked: boolean,\r\n      expanded: boolean,\r\n      enable: boolean,\r\n      items: ItemsSelect[]) {\r\n      this.id = id;\r\n      this.value = value;\r\n      this.text = text;\r\n      this.checked = checked;\r\n      this.expanded = expanded;\r\n      this.enable = enable;\r\n      this.items = items;\r\n      this.countChilds = 0;\r\n      this.countChilds = this.getCountChilds();\r\n  }\r\n\r\n  checkBySelectedItem(selectedItems: string[]): void {\r\n    this.checked = selectedItems.includes(this.value);\r\n    this.items.forEach(item => {\r\n      item.checked = selectedItems.includes(item.value);\r\n      item.checkBySelectedItem(selectedItems);\r\n    });\r\n  }\r\n\r\n  expandedAllItems() {\r\n      this.expanded = true;\r\n      this.items.forEach(item => {\r\n          item.expandedAllItems();\r\n      });\r\n  }\r\n\r\n  getCountChilds() {\r\n      if (this.items.length === 0) {\r\n          this.countChilds = 1;\r\n      }\r\n\r\n      this.items.forEach(item => {\r\n          this.countChilds += item.countChilds;\r\n      });\r\n\r\n      return this.countChilds;\r\n  }\r\n\r\n  checkChilds() {\r\n      this.items.forEach(item => {\r\n          item.checked = item.enable ? this.checked : item.checked;\r\n          item.checkChilds();\r\n      });\r\n  }\r\n\r\n  checkFromChilds() {\r\n      this.checked = this.allChildIsChecked();\r\n      this.items.forEach(item => {\r\n          item.checkFromChilds();\r\n      });\r\n  }\r\n\r\n  allChildIsChecked() {\r\n      return this.countChilds === this.countChildsChecked();\r\n  }\r\n\r\n  countChildsChecked() {\r\n      let count = 0;\r\n      if (this.items.length === 0) {\r\n          count = this.checked ? 1 : 0;\r\n      }\r\n      this.items.forEach(item => {\r\n          count += item.countChildsChecked();\r\n      });\r\n\r\n      return count;\r\n  }\r\n\r\n  getValueChildsChecked() {\r\n      let values = '';\r\n      if (this.items.length === 0) {\r\n          values = this.checked ? this.value : '';\r\n      }\r\n\r\n      this.items.forEach(item => {\r\n          const value = item.getValueChildsChecked();\r\n          if (value !== '') {\r\n              values = values === '' ? value : values + ',' + value;\r\n          }\r\n      });\r\n\r\n      return values;\r\n  }\r\n\r\n  getTextChildsChecked() {\r\n      let text = '';\r\n      if (this.items.length === 0) {\r\n          text = this.checked ? this.text : '';\r\n      }\r\n\r\n      this.items.forEach(item => {\r\n          const textItem = item.getTextChildsChecked();\r\n          if (textItem !== '') {\r\n              text = text === '' ? textItem : text + ',' + textItem;\r\n          }\r\n      });\r\n\r\n      return text;\r\n  }\r\n}\r\n","export class DefaultSetting {\r\n  public static get ALL_ITEMS_CHECKED_TEXT(): string {\r\n    return 'All';\r\n  }\r\n  public static get NONE_ITEM_CHECKED_TEXT(): string {\r\n    return 'None Selected';\r\n  }\r\n  public static get SUBFIX_NUMBER_ITEMS_CHECKED_TEXT(): string {\r\n    return ' selected';\r\n  }\r\n  public static get CHECK_ALL_CHECK_BOX_TEXT(): string {\r\n    return 'Check All Items';\r\n  }\r\n  public static get NO_ITEM_TEXT(): string {\r\n    return 'No Data';\r\n  }\r\n  public static get CHARACTER_VALUE(): string {\r\n    return ',';\r\n  }\r\n  public static get CHARACTER_TEXT(): string {\r\n    return ', ';\r\n  }\r\n  public static get NUMBER_ITEMS_DISPLAY(): number {\r\n    const numberOfItems = 3;\r\n    return numberOfItems;\r\n  }\r\n  public static get MAX_HEIGHT(): string {\r\n    return '350px';\r\n  }\r\n  public static get MAX_WIDTH(): string {\r\n    return '170px';\r\n  }\r\n  public static get SHOW_HEADER(): boolean {\r\n    return true;\r\n  }\r\n  public static get BUTTON_HEIGHT(): string {\r\n    return '36px';\r\n  }\r\n}\r\n","import { DefaultSetting } from './default-setting';\r\nimport { ItemsSelect } from './items-select';\r\n\r\nexport class MultipleSelection {\r\n    selectionTitle: string;\r\n    maxHeight: string = DefaultSetting.MAX_HEIGHT;\r\n    maxWidth: string = DefaultSetting.MAX_WIDTH;\r\n    checkAllCheckBoxText: string = DefaultSetting.CHECK_ALL_CHECK_BOX_TEXT;\r\n    allItemsCheckedText: string = DefaultSetting.ALL_ITEMS_CHECKED_TEXT;\r\n    noneItemCheckedText: string = DefaultSetting.NONE_ITEM_CHECKED_TEXT;\r\n    subfixNumberItemsCheckedText: string = DefaultSetting.SUBFIX_NUMBER_ITEMS_CHECKED_TEXT;\r\n    numberItemsDisplay: number = DefaultSetting.NUMBER_ITEMS_DISPLAY;\r\n    noData: string = DefaultSetting.NO_ITEM_TEXT;\r\n    characterValue: string = DefaultSetting.CHARACTER_VALUE;\r\n    characterText: string = DefaultSetting.CHARACTER_TEXT;\r\n    showHeader: boolean = DefaultSetting.SHOW_HEADER;\r\n    items: ItemsSelect[] = [];\r\n    isCheckAll = false;\r\n    buttonHeight: string = DefaultSetting.BUTTON_HEIGHT;\r\n    isShowPlaceHolder = false;\r\n    isDefaultSelectAll = true;\r\n\r\n    getValueItems() {\r\n        let value = '';\r\n        this.items.forEach(item => {\r\n            const valueItem = item.getValueChildsChecked();\r\n            if (valueItem !== '') {\r\n                value = value === '' ?\r\n                    valueItem : value + ',' + valueItem;\r\n            }\r\n        });\r\n\r\n        return value.toString().replace(/,/g, this.characterValue);\r\n    }\r\n\r\n    getValueCheckedItemsList() {\r\n        return this.items.filter(x => x.checked).map(y => y.value);\r\n    }\r\n\r\n    getDisplayedItems() {\r\n        const maxNumberItems = this.numberItemsDisplay;\r\n        let countChecked = 0;\r\n        let count = 0;\r\n        let text = '';\r\n\r\n        this.items.forEach(item => {\r\n            countChecked += item.countChildsChecked();\r\n            count += item.countChilds;\r\n            const textItems = item.getTextChildsChecked();\r\n\r\n            if (textItems !== '') {\r\n                text = text === '' ?\r\n                    textItems : text + ',' + textItems;\r\n            }\r\n        });\r\n\r\n        text = text.replace(/,/g, this.characterText);\r\n        let textDisplay =\r\n            count === countChecked ? this.allItemsCheckedText :\r\n                countChecked === 0 ? this.noneItemCheckedText :\r\n                    countChecked > maxNumberItems ? `${countChecked}` + this.subfixNumberItemsCheckedText :\r\n                        text;\r\n        if (count === 0 && !this.isDefaultSelectAll) {\r\n            textDisplay = this.noneItemCheckedText;\r\n        }\r\n        this.isShowPlaceHolder = textDisplay === this.noneItemCheckedText;\r\n\r\n\r\n\r\n        return textDisplay;\r\n    }\r\n\r\n    checkAllItems(isChecked: boolean) {\r\n        this.items.forEach(item => {\r\n            item.checked = isChecked;\r\n            item.checkChilds();\r\n        });\r\n        this.selectionTitle = this.getDisplayedItems();\r\n    }\r\n\r\n}\r\n","import { ItemsSelect } from '../multiple-selection/items-select';\r\nimport { CheckedBetType } from './advanced-mode/advanced-mode.model';\r\n\r\nexport class AdvancedModeConstants {\r\n    static readonly RUNS_SELECTION: CheckedBetType[] = [\r\n        { value: 'All', betTeam: 'All', valueHdp1: 'All' } as CheckedBetType,\r\n        { value: '0', betTeam: '0', valueHdp1: '0' } as CheckedBetType,\r\n        { value: '1', betTeam: '1', valueHdp1: '1' } as CheckedBetType,\r\n        { value: '2', betTeam: '2', valueHdp1: '2' } as CheckedBetType,\r\n        { value: '3', betTeam: '3', valueHdp1: '3' } as CheckedBetType,\r\n        { value: '< 4', betTeam: '0', valueHdp1: '4' } as CheckedBetType,\r\n        { value: '4', betTeam: '1,2,3,4,5,6,7', valueHdp1: '4' } as CheckedBetType,\r\n        { value: '5', betTeam: 'All', valueHdp1: '5' } as CheckedBetType,\r\n        { value: '< 6', betTeam: '0', valueHdp1: '6' } as CheckedBetType,\r\n        { value: '6', betTeam: '1,2,3,4,5,6', valueHdp1: '6' } as CheckedBetType,\r\n        { value: '> 6', betTeam: '7', valueHdp1: '6' } as CheckedBetType,\r\n        { value: '7', betTeam: 'All', valueHdp1: '7' } as CheckedBetType,\r\n        { value: '< 8', betTeam: '0', valueHdp1: '8' } as CheckedBetType,\r\n        { value: '8', betTeam: '1,2,3,4,5,6,7', valueHdp1: '8' } as CheckedBetType,\r\n        { value: '9', betTeam: '0,1,2,3,4,5,6', valueHdp1: '9' } as CheckedBetType, // NOSONAR\r\n        { value: '> 9', betTeam: '7', valueHdp1: '9' } as CheckedBetType,\r\n        { value: '10', betTeam: 'All', valueHdp1: '10' } as CheckedBetType,\r\n        { value: '11', betTeam: '0,1,2,3,4,5,6', valueHdp1: '11' } as CheckedBetType,\r\n        { value: '> 11', betTeam: '7', valueHdp1: '11' } as CheckedBetType,\r\n        { value: '12', betTeam: 'All', valueHdp1: '12' } as CheckedBetType,\r\n        { value: '13', betTeam: '0,1,2,3,4,5,6', valueHdp1: '13' } as CheckedBetType,\r\n        { value: '> 13', betTeam: '7', valueHdp1: '13' } as CheckedBetType,\r\n    ];\r\n\r\n    static readonly MAP_LIST = [\r\n        new ItemsSelect(0, '801', '1', true, true, true, []),\r\n        new ItemsSelect(0, '802', '2', true, true, true, []),\r\n        new ItemsSelect(0, '803', '3', true, true, true, []),\r\n        new ItemsSelect(0, '804', '4', true, true, true, []),\r\n        new ItemsSelect(0, '805', '5', true, true, true, []),\r\n        new ItemsSelect(0, '806', '6', true, true, true, []),\r\n        new ItemsSelect(0, '807', '7', true, true, true, []),\r\n        new ItemsSelect(0, '808', '8', true, true, true, []),\r\n        new ItemsSelect(0, '809', '9', true, true, true, [])\r\n    ];\r\n\r\n    static readonly ROUND_LIST = [\r\n        new ItemsSelect(0, '01', '1', true, true, true, []),\r\n        new ItemsSelect(0, '02', '2', true, true, true, []),\r\n        new ItemsSelect(0, '03', '3', true, true, true, []),\r\n        new ItemsSelect(0, '04', '4', true, true, true, []),\r\n        new ItemsSelect(0, '05', '5', true, true, true, []),\r\n        new ItemsSelect(0, '06', '6', true, true, true, []),\r\n        new ItemsSelect(0, '07', '7', true, true, true, []),\r\n        new ItemsSelect(0, '08', '8', true, true, true, []),\r\n        new ItemsSelect(0, '09', '9', true, true, true, []),\r\n        new ItemsSelect(0, '10', '10', true, true, true, []),\r\n        new ItemsSelect(0, '11', '11', true, true, true, []),\r\n        new ItemsSelect(0, '12', '12', true, true, true, []),\r\n        new ItemsSelect(0, '13', '13', true, true, true, []),\r\n        new ItemsSelect(0, '14', '14', true, true, true, []),\r\n        new ItemsSelect(0, '15', '15', true, true, true, []),\r\n        new ItemsSelect(0, '16', '16', true, true, true, []),\r\n        new ItemsSelect(0, '17', '17', true, true, true, []),\r\n        new ItemsSelect(0, '18', '18', true, true, true, []),\r\n        new ItemsSelect(0, '19', '19', true, true, true, []),\r\n        new ItemsSelect(0, '20', '20', true, true, true, []),\r\n        new ItemsSelect(0, '21', '21', true, true, true, []),\r\n        new ItemsSelect(0, '22', '22', true, true, true, []),\r\n        new ItemsSelect(0, '23', '23', true, true, true, []),\r\n        new ItemsSelect(0, '24', '24', true, true, true, []),\r\n        new ItemsSelect(0, '25', '25', true, true, true, []),\r\n        new ItemsSelect(0, '26', '26', true, true, true, []),\r\n        new ItemsSelect(0, '27', '27', true, true, true, []),\r\n        new ItemsSelect(0, '28', '28', true, true, true, []),\r\n        new ItemsSelect(0, '29', '29', true, true, true, []),\r\n        new ItemsSelect(0, '30', '30', true, true, true, []),\r\n        new ItemsSelect(0, '>30', 'Others', true, true, true, [])\r\n    ];\r\n    static readonly ATTRIBUTE_HDP = 'ATTRIBUTE_HDP';\r\n    static readonly ATTRIBUTE_ODDS_SPREAD = 'ATTRIBUTE_ODDS_SPREAD';\r\n\r\n    static readonly MAP = 'Map:';\r\n    static readonly ROUND = 'Round:';\r\n    static readonly BETTYPES_SABA_TIME_MACHINE = '228,229';\r\n    static readonly BETTYPES_MORE_HDP = '1,7,1303,3,8,183,153,1308,1306,17,701,704,637';\r\n    static readonly BETTYPES_UPDATE_ONLY_GAME_ATTRIBUTE = '613,712,713,3909,3912,3916';\r\n    static readonly BETTYPES_CRICKET_UPDATE_FANCY = '9541,9542,9543,9544,9545,9546,9566,9567,9569,9570,9572,9573,9574,9575,9580,9581,9606,9728,9729'\r\n        + ',9576,9577,9578,9579,9582,9583,9584,9585'\r\n        + ',9547,9548,9549,9550,9551,9552,9553,9554,9559,9560,9561,9562,9563,9564'\r\n        + ',9722,9723,9724,9725,9726,9727,9714,9715,9716,9719,9720,9721'\r\n        + ',9712,9713,9717,9718,9728,9729';\r\n    static readonly BETTYPES_CRICKET_UPDATE_BALL_DELIVERY_AND_OVER = '9422,9423,9613,9614,9616,9617';\r\n    static readonly BETTYPES_OVER_X_BALL_Y_EXACT_RUNS = '9490,9491';\r\n    static readonly BETTYPES_CRICKET_UPDATE_OVER_OR_WICKET = '9410,9411,9412,9413,9414,9415,9416,9417,9418,9419,9420,9421,9428,9429,9430,9431,9432,9433'\r\n        + ',9434,9435,9436,9437,9438,9439,9502,9503,9504,9505,9506,9507,9508,9509,9510,9511,9512,9513,9514,9515,9516,9517,9518,9519'\r\n        + ',9547,9548,9549,9550,9551,9552,9553,9554,9559,9560,9561,9562,9563,9564,9607,9608,9609,9610,9611,9612'\r\n        + ',9636,9637,9638,9639,9640,9641,9722,9723,9724,9725,9726,9727,9618,9619,9620,9621,9622,9623,9484,9485,9486,9487,9488,9489'\r\n        + ',9624,9625,9626,9627,9628,9629,9630,9631,9632,9633,9634,9635';\r\n    static readonly BETTEAM_TYPE_4 = 4;\r\n    static readonly BETTEAM_TYPE_5 = 5;\r\n    static readonly BETTYPE_PENALTY_SHOOTOUT_COMBO = '376';\r\n    static readonly BETTYPE_EXTRA_TIME_NEXT_GOAL_OWN = '396';\r\n    static readonly BETTYPE_QUARTER_X_1X2 = '630';\r\n    static readonly BETTYPE_HALF_FULL_TIME_CORRECT_SCORE = '152';\r\n    static readonly BETTYPE_HALF_FULL_TIME_CORRECT_SCORE_AOS = '416';\r\n    static readonly BETTYPE_MAP_X_FIRST_TO_Y_OVER_UNDER = '9089';\r\n    // cricket phase2\r\n    static readonly BETTYPE_OVER_X_EXACT_RUNS = '9484,9485,9486,9487,9488,9489';\r\n    static readonly BETTYPE_NEXT_MAN_OUT = '9662,9664,9666,9663,9665,9667';\r\n    static readonly BETTYPE_CRICKET_WITH_PLAYER = '9680,9682,9684,9696,9698,9702,9704,9730,9732,9734,9736,9738,9690,9692,9694,9697,9699,9703,9705,9731,9733,9735,9737,9739'\r\n    + ',9681,9683,9685,9691,9693,9695,9714,9715,9716,9719,9720,9721,9650,9652,9654,9656,9658,9660,9651,9653,9655,9657,9659,9661,9662,9664,9666,9663,9665,9667'\r\n    + ',9676,9678,9686,9688,9677,9679,9687,9689,9712,9713,9717,9718,9668,9669,9670,9671,9672,9673,9674,9675';\r\n}","import { ItemsSelect } from '../../multiple-selection/items-select';\r\nimport { MultipleSelection } from '../../multiple-selection/multiple-selection';\r\nimport { AdvancedModeConstants } from '../advanced-mode.constants';\r\n\r\nexport class Item {\r\n  name: string;\r\n  value: string;\r\n  flag: boolean;\r\n  isChecked: boolean;\r\n  xmlAttribute: string;\r\n\r\n  constructor(name: string, value: string, flag: boolean, xmlAttribute: string) {\r\n    this.name = name;\r\n    this.value = value;\r\n    this.flag = flag;\r\n    this.isChecked = false;\r\n    this.xmlAttribute = xmlAttribute;\r\n  }\r\n}\r\n\r\nexport class Selection {\r\n  name: string;\r\n  value: string;\r\n  items: Selection[];\r\n  isMultiple: boolean;\r\n  xmlAttribute: string;\r\n\r\n  constructor(name: string, value: string, items: Selection[], isMultiple: boolean, xmlAttribute: string) {\r\n    this.name = name;\r\n    this.value = value;\r\n    this.renderItems(items);\r\n    this.isMultiple = isMultiple;\r\n    this.xmlAttribute = xmlAttribute;\r\n  }\r\n\r\n  renderItems(items: Selection[]) {\r\n    this.items = [];\r\n    if (items !== null) {\r\n      items.forEach(item => {\r\n        const temp = new Selection(item.name, item.value, item.items, item.isMultiple, item.xmlAttribute);\r\n        this.items.push(temp);\r\n      });\r\n    }\r\n  }\r\n}\r\n\r\nexport class MultiSelection {\r\n  name: string;\r\n  value: string;\r\n  xmlAttribute: string;\r\n  multipleSelect: MultipleSelection;\r\n}\r\n\r\nexport class BetTeamResult {\r\n  betTeam: string;\r\n  set: string;\r\n  game: string;\r\n  betOption: string;\r\n  value: string;\r\n  valueHdp1: string;\r\n  valueHdp2: string;\r\n  goal: string;\r\n  oddsSpread: string;\r\n  oddsId: string;\r\n  transdesc: string;\r\n}\r\n\r\nexport class CheckedBetType extends BetTeamResult {\r\n  id: number;\r\n}\r\n\r\nexport class BetTeam {\r\n  name: string;\r\n  value: string;\r\n  type: number;\r\n  enableBetTypes: string;\r\n  betTypes: string;\r\n  selections: Selection[];\r\n  multiSelection: MultiSelection;\r\n  multiSelectionList: MultiSelection[];\r\n  items: Item[];\r\n  inputs: Item[];\r\n  checkedBetTypes: string[];\r\n  isChecked: boolean;\r\n  isHaveMultipleMapRound: boolean;\r\n\r\n  constructor(\r\n    commonInfo: [string, string, number, string, string],\r\n    selections: Selection[],\r\n    items: Item[],\r\n    inputs: Item[],\r\n    isHaveMultipleMapRound: boolean) {\r\n    this.name = commonInfo[0];\r\n    this.value = commonInfo[1];\r\n    this.type = commonInfo[2];\r\n    this.enableBetTypes = commonInfo[3];\r\n    this.betTypes = commonInfo[4];\r\n    this.isHaveMultipleMapRound = isHaveMultipleMapRound;\r\n    this.renderSelections(selections);\r\n    this.renderItems(items);\r\n    this.renderInputs(inputs);\r\n    this.checkedBetTypes = [];\r\n    this.isChecked = false;\r\n  }\r\n\r\n  renderSelections(selections: Selection[]) {\r\n    this.selections = [];\r\n    this.multiSelectionList = [];\r\n    if (selections !== null) {\r\n      this.renderValidSelection(selections);\r\n    }\r\n  }\r\n\r\n  renderValidSelection(selections: Selection[]) {\r\n    selections.forEach(item => {\r\n      if (item.isMultiple) {\r\n        this.renderMultipleSelect(item);\r\n      } else {\r\n        if (this.isHaveMultipleMapRound) {\r\n          if (item.name === AdvancedModeConstants.MAP || item.name === AdvancedModeConstants.ROUND) {\r\n            this.renderMultipleSelectWithMapAndRound(item);\r\n          } else {\r\n            const selection = new Selection(item.name, item.value, item.items, item.isMultiple, item.xmlAttribute);\r\n            this.selections.push(selection);\r\n          }\r\n        } else {\r\n          const selection = new Selection(item.name, item.value, item.items, item.isMultiple, item.xmlAttribute);\r\n          this.selections.push(selection);\r\n        }\r\n      }\r\n    });\r\n  }\r\n\r\n  renderItems(items: Item[]) {\r\n    this.items = [];\r\n    if (items !== null) {\r\n      items.forEach(item => {\r\n        const temp = new Item(item.name, item.value, item.flag, item.xmlAttribute);\r\n        this.items.push(temp);\r\n      });\r\n    }\r\n  }\r\n\r\n  private renderInputs(inputs: Item[]) {\r\n    this.inputs = [];\r\n    if (inputs !== null) {\r\n      inputs.forEach(input => {\r\n        const temp = new Item(input.name, input.value, input.flag, input.xmlAttribute);\r\n        this.inputs.push(temp);\r\n      });\r\n    }\r\n  }\r\n\r\n  renderMultipleSelect(item: Selection) {\r\n    this.multiSelection = new MultiSelection();\r\n    this.multiSelection.multipleSelect = new MultipleSelection();\r\n    this.multiSelection.multipleSelect.checkAllCheckBoxText = 'Check All';\r\n    this.multiSelection.multipleSelect.allItemsCheckedText = 'All';\r\n    this.multiSelection.multipleSelect.noneItemCheckedText = 'Select options';\r\n    this.multiSelection.multipleSelect.maxWidth = '170px';\r\n    this.renderItemsMultipleSelect(item);\r\n  }\r\n\r\n  renderMultipleSelectWithMapAndRound(item: Selection) {\r\n    this.multiSelection = new MultiSelection();\r\n    this.multiSelection.multipleSelect = new MultipleSelection();\r\n    this.multiSelection.multipleSelect.checkAllCheckBoxText = 'All';\r\n    this.multiSelection.multipleSelect.allItemsCheckedText = 'All';\r\n    this.multiSelection.multipleSelect.noneItemCheckedText = 'Select options';\r\n    this.multiSelection.multipleSelect.maxWidth = '92px';\r\n    this.renderItemsMultipleSelectWithMapAndRound(item);\r\n  }\r\n\r\n  renderItemsMultipleSelect(multi: Selection) {\r\n    this.multiSelection.name = multi.name;\r\n    this.multiSelection.value = multi.value;\r\n    this.multiSelection.xmlAttribute = multi.xmlAttribute;\r\n    this.multiSelection.multipleSelect.items = [];\r\n    multi.items.forEach(item => {\r\n      const temp = [];\r\n      if (item.items !== null && item.items !== undefined) {\r\n        item.items.forEach(itemSelect => {\r\n          temp.push(new ItemsSelect(0, itemSelect.value, itemSelect.name, true, true, true, []));\r\n        });\r\n      }\r\n      this.multiSelection.multipleSelect.items.push(new ItemsSelect(0, item.value, item.name, true, true, true, temp));\r\n    });\r\n    this.multiSelection.multipleSelect.isCheckAll = this.multiSelection.multipleSelect.items.every(x => x.checked);\r\n    this.multiSelection.multipleSelect.selectionTitle = this.multiSelection.multipleSelect.getDisplayedItems();\r\n  }\r\n\r\n  renderItemsMultipleSelectWithMapAndRound(multi: Selection) {\r\n    this.multiSelection.name = multi.name;\r\n    this.multiSelection.value = multi.value;\r\n    this.multiSelection.xmlAttribute = multi.xmlAttribute;\r\n    this.multiSelection.multipleSelect.items = [];\r\n    multi.items.forEach(item => {\r\n      if (item.name !== 'All' || item.value !== 'All') {\r\n        this.multiSelection.multipleSelect.items.push(new ItemsSelect(0, item.value, item.name, true, true, true, []));\r\n      }\r\n    });\r\n\r\n    this.multiSelectionList.push(this.multiSelection);\r\n  }\r\n\r\n  resetChecked() {\r\n    this.isChecked = true;\r\n    this.resetSelections();\r\n    this.checkItems();\r\n  }\r\n\r\n  resetSelections() {\r\n    this.selections.forEach(selection => {\r\n      selection.value = 'All';\r\n    });\r\n  }\r\n\r\n  private handler416WithNameIsHT(item: Selection): boolean {\r\n    const MARKED_SCORE = 3;\r\n    const SECOND_SCORE_INDEX = 2;\r\n    return this.selections[1].value === 'All' ||\r\n      item.value === 'AOS' &&\r\n      ((parseInt(this.selections[1].value.charAt(0), 10) > MARKED_SCORE) ||\r\n        (parseInt(this.selections[1].value.charAt(SECOND_SCORE_INDEX), 10) > MARKED_SCORE)) ||\r\n      item.name.charAt(0) <= this.selections[1].value.charAt(0) &&\r\n      item.name.charAt(SECOND_SCORE_INDEX) <= this.selections[1].value.charAt(SECOND_SCORE_INDEX);\r\n  }\r\n\r\n  private handler416WithNameIsNotHT(item: Selection): boolean {\r\n    const MARKED_SCORE = 3;\r\n    const SECOND_SCORE_INDEX = 2;\r\n    return this.selections[0].value === 'All' ||\r\n      this.selections[0].value === 'AOS' &&\r\n      ((parseInt(item.name.charAt(0), 10) > MARKED_SCORE) || (parseInt(item.name.charAt(SECOND_SCORE_INDEX), 10) > MARKED_SCORE)) ||\r\n      item.name.charAt(0) >= this.selections[0].value.charAt(0) &&\r\n      item.name.charAt(SECOND_SCORE_INDEX) >= this.selections[0].value.charAt(SECOND_SCORE_INDEX);\r\n  }\r\n\r\n  private handler416(item: Selection, name: string): boolean {\r\n    if (item.name === 'All') {\r\n      return true;\r\n    }\r\n    if (name === 'HT:') {\r\n      return this.handler416WithNameIsHT(item);\r\n    } else {\r\n      return this.handler416WithNameIsNotHT(item);\r\n    }\r\n  }\r\n\r\n  isValidOptionForType5(item: Selection, name: string): boolean {\r\n    if (this.checkedBetTypes.some(x => (x === AdvancedModeConstants.BETTYPE_HALF_FULL_TIME_CORRECT_SCORE\r\n      || x === AdvancedModeConstants.BETTYPE_HALF_FULL_TIME_CORRECT_SCORE_AOS))) {\r\n      return this.handler416(item, name);\r\n    }\r\n\r\n    return true;\r\n  }\r\n\r\n  checkItems() {\r\n    this.items.forEach(item => {\r\n      item.isChecked = this.isChecked;\r\n    });\r\n    if (this.type === 1 && this.enableBetTypes !== null) {\r\n      this.items[0].value = '';\r\n    }\r\n  }\r\n\r\n  controlIsChecked() {\r\n    let temp = true;\r\n    for (let i = 0; i < this.items.length && temp; i++) {\r\n      temp = this.items[i].isChecked;\r\n    }\r\n    this.isChecked = temp;\r\n  }\r\n\r\n  enableInput() {\r\n    if (this.type === 1 && this.enableBetTypes !== null && this.items[0].flag === true) {\r\n      this.items[0].value = '';\r\n    }\r\n    if (this.type === 1 && this.enableBetTypes !== null && this.checkedBetTypes.length > 0) {\r\n      this.items[0].flag = true;\r\n      const enable = this.enableBetTypes.split(',');\r\n      const checkedIds = this.checkedBetTypes.join(',').split(',');\r\n      for (let i = 0; i < checkedIds.length && this.items[0].flag; i++) {\r\n        this.items[0].flag = enable.indexOf(checkedIds[i].toString()) === -1;\r\n      }\r\n    }\r\n  }\r\n\r\n  getResult(id: string): BetTeamResult {\r\n    const result = new BetTeamResult();\r\n    this.updateBySelection(result);\r\n    this.updateByMultipleSelection(result);\r\n    this.updateByMultipleSelectionWithTicketListing(result);\r\n    this.updateByItems(result, id);\r\n    this.updateByInputs(result, id);\r\n    if (this.type === AdvancedModeConstants.BETTEAM_TYPE_5\r\n      && id === (AdvancedModeConstants.BETTYPE_HALF_FULL_TIME_CORRECT_SCORE\r\n        || AdvancedModeConstants.BETTYPE_HALF_FULL_TIME_CORRECT_SCORE_AOS)) {\r\n      result.betTeam = this.betTeamTypeFive();\r\n    }\r\n    this.updateForPenaltyShootoutCombo376(result, id);\r\n    this.updateForBetTypesCricketWithFancy(result, id);\r\n    this.updateForBetTypesCricketWithBallDelivery(result, id);\r\n    this.updateBetTypesCricketOverXBallYExactRuns(result, id);\r\n    this.updateForBetType9089(result, id);\r\n    this.updateForBetTypesCricketWithOverWicket(result, id);\r\n    this.updateForBetTypesWithRuns(result, id);\r\n    this.updateForBetTypesCricketNextManOut(result, id);\r\n\r\n    return result;\r\n  }\r\n\r\n  isTicketListingAndBettypeMapOrRound(name: string): boolean {\r\n    if (this.isHaveMultipleMapRound) {\r\n      if (name === AdvancedModeConstants.MAP || name === AdvancedModeConstants.ROUND) {\r\n        return true;\r\n      } else {\r\n        return false;\r\n      }\r\n    }\r\n    return false;\r\n  }\r\n\r\n  updateBySelection(result: BetTeamResult) {\r\n    this.selections.forEach(select => {\r\n      this.updateResult(result, select.xmlAttribute, select.value);\r\n    });\r\n  }\r\n\r\n  updateByMultipleSelection(result: BetTeamResult) {\r\n    if (this.multiSelection !== undefined && (!this.isHaveMultipleMapRound ||\r\n      !this.isTicketListingAndBettypeMapOrRound(this.multiSelection.name))) {\r\n      const value = this.multiSelection.multipleSelect.getValueItems();\r\n      this.updateResult(result, this.multiSelection.xmlAttribute, value);\r\n    }\r\n  }\r\n\r\n  updateByMultipleSelectionWithTicketListing(result: BetTeamResult) {\r\n    if (this.multiSelectionList !== undefined && this.isHaveMultipleMapRound) {\r\n      this.multiSelectionList.forEach(item => {\r\n        let value = item.multipleSelect.getValueItems();\r\n        if (item.multipleSelect.selectionTitle === 'All' && (item.name === AdvancedModeConstants.MAP\r\n          || this.multiSelection.name === AdvancedModeConstants.ROUND)) {\r\n          value = 'All';\r\n        }\r\n        this.updateResult(result, item.xmlAttribute, value);\r\n      });\r\n    }\r\n  }\r\n\r\n  updateByItems(result: BetTeamResult, id: string) {\r\n    if (this.items.length === 1) {\r\n      if (this.type === 1 && this.enableBetTypes !== null) {\r\n        this.updateResultForItemOfEnableBetTypes(result, id);\r\n      } else {\r\n        this.updateResult(result, this.items[0].xmlAttribute, this.items[0].value);\r\n      }\r\n    } else if (this.items.length > 0) {\r\n      this.updateResult(result, this.items[0].xmlAttribute, this.getItemsValue());\r\n    }\r\n  }\r\n\r\n  private updateResultForItemOfEnableBetTypes(result: BetTeamResult, id: string) {\r\n    const LENGTH_OF_GAME_VALUE = 2;\r\n\r\n    const enable = this.enableBetTypes.split(',');\r\n    if (enable.indexOf(id) > -1) {\r\n      let value = this.mappingDbValue(id);\r\n      if (AdvancedModeConstants.BETTYPES_MORE_HDP.split(',').includes(id)) {\r\n        value = value.replace(/&/g, ',');\r\n      }\r\n      if (AdvancedModeConstants.BETTYPES_UPDATE_ONLY_GAME_ATTRIBUTE.split(',').includes(id)\r\n        && value.length < LENGTH_OF_GAME_VALUE && value.length > 0) {\r\n        value = value.padStart(LENGTH_OF_GAME_VALUE, '0');\r\n      }\r\n      this.updateResult(result, this.items[0].xmlAttribute, value);\r\n    } else {\r\n      this.updateResult(result, this.items[0].xmlAttribute, '');\r\n    }\r\n  }\r\n\r\n  updateByInputs(result: BetTeamResult, id: string) {\r\n    if (this.inputs.length > 0) {\r\n      this.inputs.forEach(input => {\r\n        let value = input.value;\r\n        if (this.type === 7 && AdvancedModeConstants.BETTYPES_SABA_TIME_MACHINE.split(',').includes(id)) {\r\n          value = value.replace(/&/g, ',');\r\n        }\r\n        this.updateResult(result, input.xmlAttribute, value);\r\n      });\r\n    }\r\n  }\r\n\r\n  updateItemListMapAndRound(itemList: string[], type: string) {\r\n    this.multiSelectionList.forEach(itemMultiSelection => {\r\n      if (itemMultiSelection.name === type) {\r\n        itemMultiSelection.multipleSelect.items.forEach(item => {\r\n          const object = itemList.find(f => f === item.value);\r\n          if (object !== undefined) {\r\n            item.checked = true;\r\n          } else {\r\n            item.checked = false;\r\n          }\r\n        });\r\n      }\r\n      this.changeItemsOfMultipleSelection(itemMultiSelection.multipleSelect);\r\n    });\r\n  }\r\n\r\n  changeItemsOfMultipleSelection(multipleSelect: MultipleSelection) {\r\n    const rootItems = multipleSelect.items;\r\n    let count = 0;\r\n    let countChecked = 0;\r\n    rootItems.forEach(item => {\r\n      item.checkFromChilds();\r\n      count += item.countChilds;\r\n      countChecked += item.countChildsChecked();\r\n    });\r\n    multipleSelect.selectionTitle = multipleSelect.getDisplayedItems();\r\n    multipleSelect.isCheckAll = count === countChecked;\r\n  }\r\n\r\n  mappingDbValue(id: string): string {\r\n    if (this.items[0].xmlAttribute !== 'Goal') {\r\n      return this.items[0].value;\r\n    } else {\r\n      const value = (id === AdvancedModeConstants.BETTYPE_EXTRA_TIME_NEXT_GOAL_OWN) ? '800' : '8' + id + '00';\r\n      return this.items[0].value === '' ?\r\n        '' : (parseInt(value, 10) + parseInt(this.items[0].value, 10)).toString();\r\n    }\r\n  }\r\n\r\n  getItemsValue(): string {\r\n    let value = '';\r\n    if (this.isChecked) {\r\n      value = 'All';\r\n    } else {\r\n      this.items.forEach(item => {\r\n        value = item.isChecked ? value === '' ? item.value : value + ',' + item.value : value;\r\n      });\r\n    }\r\n\r\n    return value;\r\n  }\r\n\r\n  updateResult(result: BetTeamResult, attribute: string, value: string) { // NOSONAR\r\n    switch (attribute) {\r\n      case 'BetTeam':\r\n        result.betTeam = value;\r\n        break;\r\n      case 'Set':\r\n        result.set = value;\r\n        break;\r\n      case 'Game':\r\n        result.game = value;\r\n        break;\r\n      case 'Value':\r\n        result.value = value;\r\n        break;\r\n      case 'Value