s.selections.find(x => x.name === 'Y value:').value;\r\n\r\n    if (mapValue === 'All' && yValue === 'All') {\r\n      result.set = 'All';\r\n    } else if (mapValue === 'All') {\r\n      result.set = `___${yValue}`;\r\n    } else if (yValue === 'All') {\r\n      result.set = `${mapValue}__`;\r\n    } else {\r\n      result.set = `${mapValue}${yValue}`;\r\n    }\r\n  }\r\n\r\n  private updateForBetTypesCricketWithOverWicket(result: BetTeamResult, betTypeId: string): void { //format \"Over: Wicket: Over/Wicket:\" value: 8XXX\r\n    if (AdvancedModeConstants.BETTYPES_CRICKET_UPDATE_OVER_OR_WICKET.split(',').includes(betTypeId)) {\r\n      const LENGTH_OF_OVER = 3;\r\n      const PREFIX = '8';\r\n      const input = this.inputs.find(x => x.xmlAttribute === 'Set');\r\n      if (input) {\r\n        let overValue = input.value;\r\n\r\n        if (overValue.length === 0) {\r\n          result.set = overValue;\r\n          return;\r\n        }\r\n\r\n        if (overValue.length < LENGTH_OF_OVER && overValue.length > 0) {\r\n          overValue = overValue.padStart(LENGTH_OF_OVER, '0');\r\n        }\r\n\r\n        result.set = `${PREFIX}${overValue}`;\r\n      }\r\n    }\r\n  }\r\n\r\n  private updateForBetTypesWithRuns(result: BetTeamResult, betTypeId: string): void {\r\n    if (AdvancedModeConstants.BETTYPE_OVER_X_EXACT_RUNS.split(',').includes(betTypeId)) {\r\n      const runesValue = this.selections.find(x => x.name === 'Runs:').value;\r\n      const runesTransform = AdvancedModeConstants.RUNS_SELECTION.find(x => x.value === runesValue);\r\n\r\n      result.betTeam = runesTransform.betTeam;\r\n      result.valueHdp1 = runesTransform.valueHdp1;\r\n      delete result.value;\r\n    }\r\n  }\r\n\r\n  private updateForBetTypesCricketNextManOut(result: BetTeamResult, betTypeId: string): void {\r\n    if (AdvancedModeConstants.BETTYPE_NEXT_MAN_OUT.split(',').includes(betTypeId)) {\r\n      const items = this.multiSelection.multipleSelect.getValueCheckedItemsList();\r\n      if (items.length > 0) {\r\n        result.betTeam = items.map(x => x.split(',')[0]).join(',');\r\n        result.oddsId = items.map(x => x.split(',')[1]).join(',');\r\n      }\r\n\r\n      delete result.value;\r\n    }\r\n  }\r\n}\r\n\r\nexport class GetPlayersQuery {\r\n  matchId: string;\r\n  betType: string;\r\n\r\n  constructor(matchId: string, betType: string) {\r\n    this.matchId = matchId;\r\n    this.betType = betType;\r\n  }\r\n}\r\n\r\nexport class GetOddsInfoQuery {\r\n  matchId: string;\r\n  betTypes: string;\r\n}\r\n\r\nexport class Player {\r\n  oddsInfo: string;\r\n  betChoice: string;\r\n}\r\n\r\nexport class OddsInfo {\r\n  betTypeId: string;\r\n  oddsId: string;\r\n  playerId: string;\r\n  playerName: string;\r\n  betChoice: string;\r\n  playNamesChineseTraditional: string;\r\n  playNamesChineseSimplified: string;\r\n}\r\n","export class PrimaryBetType {\r\n    static readonly ROOT = {\r\n        '1': '1,1303', '2': '2,1305,157', '3': '3,1306', '20': '20,1301', '153': '153,1308', '154': '154,1311', '155': '155,1316',\r\n        '156': '156,1312', '144': '144,163', '159': '159,406', '151': '151,410', '161': '161,407', '171': '171,408', '162': '162,409',\r\n        '191': '191,411', '4': '4,413', '30': '30,414', '172': '172,415', '152': '152,416', '188': '188,427', '184': '184,428',\r\n        '177': '177,430', '186': '186,431', '185': '185,432', '146': '146,433', '189': '189,434', '190': '190,435', '147': '147,436',\r\n        '148': '148,437', '133': '133,438', '134': '134,439', '149': '149,440', '150': '150,441', '140': '140,442', '141': '141,443',\r\n        '142': '142,444', '17': '17,183', '18': '18,178', '401': '401,461', '402': '402,462', '403': '403,463', '404': '404,464',\r\n        '22': '22,160', '206': '206,488', '194': '194,470', '203': '203,471', '202': '202,474', '207': '207,489', '208': '208,491',\r\n        '209': '209,492', '473': '473,11,199', '164': '396,164', '166': '399,166'\r\n    };\r\n}\r\n\r\nexport class NotSupportBetTypes {\r\n    static readonly IGNORE = 11;\r\n    static readonly ALTERNATIVE = 199;\r\n}\r\n\r\nconst ExactHomeTeamGoals = 161;\r\nconst ExactAwayTeamGoals = 162;\r\nconst HomeTeamOverUnder = 401;\r\nconst AwayTeamOverUnder = 402;\r\nconst _1HHomeTeamOverUnder = 403;\r\nconst _1HAwayTeamOverUnder = 404;\r\nconst HomeTeamOverUnderCorners = 482;\r\nconst _1HHomeTeamOverUnderCorners = 484;\r\nconst AwayTeamOverUnderCorners = 483;\r\nconst _1HAwayTeamOverUnderCorners = 485;\r\nconst Handicap = 1;\r\nconst OverUnder = 3;\r\nconst _1HHandicap = 7;\r\nconst _1HOverUnder = 8;\r\n\r\nexport class HighlightBetTypes {\r\n    static readonly RED = [ExactHomeTeamGoals, ExactAwayTeamGoals, HomeTeamOverUnder, AwayTeamOverUnder,\r\n        _1HHomeTeamOverUnder, _1HAwayTeamOverUnder, HomeTeamOverUnderCorners, _1HHomeTeamOverUnderCorners,\r\n        AwayTeamOverUnderCorners, _1HAwayTeamOverUnderCorners];\r\n    static readonly BLUE = [Handicap, OverUnder, _1HHandicap, _1HOverUnder];\r\n}\r\n\r\nexport class Result {\r\n    errorCode: number;\r\n    errorMsg: string;\r\n}\r\n\r\nexport class BetType {\r\n    id: number;\r\n    name: string;\r\n    liveIndicator: boolean;\r\n    type: number;\r\n    value: string;\r\n    isChecked: boolean;\r\n    redHighlight: boolean;\r\n    blueHighlight: boolean;\r\n\r\n    constructor(id: number, name: string, liveIndicator: boolean, type: number, isChecked: boolean) {\r\n        this.id = id === NotSupportBetTypes.IGNORE ? NotSupportBetTypes.ALTERNATIVE : id;\r\n        this.name = name;\r\n        this.liveIndicator = liveIndicator;\r\n        this.type = type;\r\n        this.isChecked = isChecked;\r\n        this.value = PrimaryBetType.ROOT[this.id] === undefined ? this.id.toString() : PrimaryBetType.ROOT[this.id];\r\n        this.redHighlight = HighlightBetTypes.RED.indexOf(id) > -1;\r\n        this.blueHighlight = HighlightBetTypes.BLUE.indexOf(id) > -1;\r\n    }\r\n}\r\n\r\nexport class GroupBetType {\r\n    groupName: string;\r\n    betTypes: BetType[];\r\n    isChecked: boolean;\r\n    isShow: boolean;\r\n\r\n    constructor(groupName: string, betTypes: BetType[], isChecked: boolean) {\r\n        this.isShow = true;\r\n        this.groupName = groupName;\r\n        this.isChecked = isChecked;\r\n        this.renderBetTypes(betTypes, isChecked);\r\n    }\r\n\r\n    renderBetTypes(betTypes: BetType[], isChecked: boolean) {\r\n        this.betTypes = [];\r\n        betTypes.forEach(item => {\r\n            const betType = new BetType(\r\n                parseInt(item.id.toString(), 10),\r\n                item.name,\r\n                item.liveIndicator,\r\n                item.type,\r\n                isChecked\r\n            );\r\n            this.betTypes.push(betType);\r\n        });\r\n    }\r\n\r\n    changeCheckedGroupToBetType() {\r\n        this.betTypes.forEach(betType => {\r\n            betType.isChecked = this.isChecked && this.isShow;\r\n        });\r\n    }\r\n\r\n    changeCheckedBetTypeToGroup() {\r\n        let temp = true;\r\n        for (let i = 0; i < this.betTypes.length && temp; i++) {\r\n            temp = this.betTypes[i].isChecked;\r\n        }\r\n        this.isChecked = temp;\r\n    }\r\n\r\n    getCheckedBetTypes(): number[] {\r\n        const value: Array<number> = [];\r\n        this.betTypes.forEach(betType => {\r\n            if (betType.isChecked) {\r\n                value.push(betType.id);\r\n            }\r\n        });\r\n\r\n        return value;\r\n    }\r\n\r\n    getValueCheckedBetTypes(): string[] {\r\n        const value: Array<string> = [];\r\n        this.betTypes.forEach(betType => {\r\n            if (betType.isChecked) {\r\n                value.push(betType.value);\r\n            }\r\n        });\r\n\r\n        return value;\r\n    }\r\n\r\n    hasBetType(id: number): boolean {\r\n        const index = this.betTypes.findIndex(x => x.id.toString() === id.toString());\r\n        return index > -1;\r\n    }\r\n}\r\n\r\nexport class GroupBetTypesModel {\r\n    groupBetTypes: GroupBetType[];\r\n    isChecked: boolean;\r\n    result: Result;\r\n\r\n    constructor(groups: Array<GroupBetType>, isChecked: boolean) {\r\n        this.isChecked = isChecked;\r\n        this.groupBetTypes = [];\r\n        groups.forEach(item => {\r\n            const group = new GroupBetType(item.groupName, item.betTypes, isChecked);\r\n            this.groupBetTypes.push(group);\r\n        });\r\n    }\r\n\r\n    changeCheckGroupByBetTypes() {\r\n        this.groupBetTypes.forEach(group => {\r\n            if (!group.betTypes.some(x => !x.isChecked)) {\r\n                group.isChecked = true;\r\n            } else {\r\n                group.isChecked = false;\r\n            }\r\n        });\r\n    }\r\n\r\n    changeCheckedModelToGroup() {\r\n        this.groupBetTypes.forEach(group => {\r\n            group.isChecked = this.isChecked && group.isShow;\r\n            group.changeCheckedGroupToBetType();\r\n        });\r\n    }\r\n\r\n    changeCheckedGroupToModel() {\r\n        let checkedAll = true;\r\n        let hideAll = true;\r\n        for (let i = 0; i < this.groupBetTypes.length && checkedAll; i++) {\r\n            if (this.groupBetTypes[i].isShow) {\r\n                checkedAll = this.groupBetTypes[i].isChecked;\r\n            }\r\n            if (hideAll) {\r\n                hideAll = !this.groupBetTypes[i].isShow;\r\n            }\r\n        }\r\n\r\n        this.isChecked = checkedAll && !hideAll;\r\n    }\r\n\r\n    getCheckedBetTypes(): number[] {\r\n        let value: Array<number> = [];\r\n        this.groupBetTypes.forEach(group => {\r\n            value = value.concat(group.getCheckedBetTypes());\r\n        });\r\n\r\n        return value;\r\n    }\r\n\r\n    getValueCheckedBetTypes(): string {\r\n        let value: Array<string> = [];\r\n        this.groupBetTypes.forEach(group => {\r\n            value = value.concat(group.getValueCheckedBetTypes());\r\n        });\r\n\r\n        return value.join(',');\r\n    }\r\n\r\n    getAllBetType(): BetType[] {\r\n        let value = [];\r\n        this.groupBetTypes.forEach(group => {\r\n            value = value.concat(group.betTypes);\r\n        });\r\n\r\n        return value;\r\n    }\r\n\r\n    hasBetType(id: number): boolean {\r\n        let result = false;\r\n        this.groupBetTypes.forEach(group => {\r\n            if (group.hasBetType(id)) {\r\n                result = true;\r\n            }\r\n        });\r\n\r\n        return result;\r\n    }\r\n}\r\n\r\nexport class GetBetTypesQuery {\r\n    mode: number;\r\n    matchId: number;\r\n    betTypes?: string;\r\n}","export class GetMatchQuery {\r\n  matchId: number;\r\n  isMatch3rd: boolean;\r\n}\r\n\r\nexport class MatchModel {\r\n  matchId: number;\r\n  homeId: number;\r\n  homeName: string;\r\n  homeNameNewSimplified: string;\r\n  homeNameSimplified: string;\r\n  homeNameTraditional: string;\r\n  awayId: number;\r\n  awayName: string;\r\n  awayNameNewSimplified: string;\r\n  awayNameSimplified: string;\r\n  awayNameTraditional: string;\r\n  matchCode: string;\r\n  eventDate: Date;\r\n  dateTime: Date;\r\n  leagueId: number;\r\n  leagueGroupId : number;\r\n  leagueName: string;\r\n  leagueNameNewSimplified: string;\r\n  leagueNameSimplified: string;\r\n  leagueNameTraditional: string;\r\n  matchEvent: string;\r\n  matchEventSimplified: string;\r\n  matchEventNewSimplified: string;\r\n  kickOffTime: string;\r\n  startTime: Date;\r\n  endTime: Date;\r\n  sportType: number;\r\n  sportTypeName: string;\r\n  sportTypeNameNewSimplified: string;\r\n  sportTypeNameSimplified: string;\r\n  sportTypeNameTraditional: string;\r\n  numberOfCorner?: number;\r\n}\r\n\r\nexport class CheckMatchWithRefNoQuery {\r\n  matchId: number;\r\n  fromRefNo: number;\r\n  toRefNo: number;\r\n  type: number;\r\n}\r\n\r\nexport class FirstTicketTime {\r\n  minTransDate: string;\r\n  kickOffTime: string;\r\n}\r\n","export class IssueType {\r\n  issueTypeId: number;\r\n  issueTypeName: string;\r\n}\r\n\r\nexport class SubIssueType {\r\n  subIssueTypeId: number;\r\n  issueTypeId: number;\r\n  subIssueTypeName: string;\r\n  subIssueTypeNameCS: string;\r\n}\r\n\r\n\r\nexport class IssueTypesModel {\r\n  issueTypes: IssueType[] = [];\r\n  subIssueTypes: SubIssueType[] = [];\r\n}\r\n\r\nexport class IssueInfo extends SubIssueType {\r\n  name: string;\r\n}\r\n","import { Message } from '../../../utility/components/template-message/messages/message';\r\nimport { BetID } from '../../../utility/models/bet-id.model';\r\nimport { Result } from '../../../utility/models/result';\r\n\r\nexport class VoidTicketsQuery {\r\n  requestId: number;\r\n  singleTickets?: BetID[];\r\n  parlayTickets?: BetID[];\r\n  cancelCashOutTickets?: BetID[];\r\n  cricketTickets?: BetID[];\r\n  userName: string;\r\n  userPassword: string;\r\n  reason: string;\r\n  reasonSC: string;\r\n  message: Message;\r\n  matchId: number;\r\n  subIssueTypeId?: number;\r\n  subIssueTypeName: string;\r\n  subIssueTypeNameCS: string;\r\n  issueTypeId?: number;\r\n  voidingHistoryId?: number;\r\n  historyStatusId?: number;\r\n  negativeBalanceUsers?: string;\r\n  voidFromTime: string;\r\n  voidToTime: string;\r\n  voidFromDate: string;\r\n  voidToDate: string;\r\n  decidedBy?: string;\r\n  guid?: string;\r\n}\r\n\r\nexport class InsertQueueResult {\r\n  historyId: number;\r\n  netposition?: Result<string>;\r\n}\r\n","import { Component, OnInit, Input } from '@angular/core';\r\nimport { MatchModel } from '../../../utility/models/match.model';\r\n\r\n@Component({\r\n  selector: 'event-info',\r\n  templateUrl: './event-info.component.html',\r\n  styleUrls: ['./event-info.component.scss']\r\n})\r\nexport class EventInfoComponent {\r\n  @Input() match = new MatchModel();\r\n}\r\n","<div class=\"event-info\">\r\n  <div class=\"league-info\">\r\n    <div class=\"padding-2-10 alert alert-primary\" role=\"alert\">\r\n      <strong>{{match.leagueName}}</strong>\r\n    </div>\r\n  </div>\r\n  <div class=\"match-info\">\r\n    <table>\r\n      <thead>\r\n        <tr>\r\n          <th scope=\"col\">Match Code/ID</th>\r\n          <th scope=\"col\">Match Event</th>\r\n        </tr>\r\n      </thead>\r\n      <tbody>\r\n        <tr>\r\n          <td>{{match.matchCode}}/{{match.matchId}}</td>\r\n          <td>{{match.matchEvent}}</td>\r\n        </tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n</div>\r\n","import { NgbDate } from '@ng-bootstrap/ng-bootstrap';\r\nimport { CommonTimeModel } from '../common.time.model';\r\n\r\nexport class TimeModel extends CommonTimeModel {\r\n  time: string;\r\n\r\n  constructor(date: Date) {\r\n    super(date);\r\n  }\r\n\r\n  getValue(): string {\r\n    return `${this.ngbDate.year}/${this.ngbDate.month}/${this.ngbDate.day} ${this.hour}:${this.minute}:${this.second}`;\r\n  }\r\n}\r\n","import { NgbDate } from '@ng-bootstrap/ng-bootstrap';\r\n\r\nexport class CommonTimeModel {\r\n    ngbDate: NgbDate;\r\n    hour: string;\r\n    minute: string;\r\n    second: string;\r\n\r\n    constructor(date: Date) {\r\n        this.hour = this.insertZeroFirst(date.getHours());\r\n        this.minute = this.insertZeroFirst(date.getMinutes());\r\n        this.second = this.insertZeroFirst(date.getSeconds());\r\n        this.ngbDate = new NgbDate(date.getFullYear(), date.getMonth() + 1, date.getDate());\r\n    }\r\n\r\n    insertZeroFirst(value: number) {\r\n        const NUMBER_TEN = 10;\r\n        return value < NUMBER_TEN ? `0${value}` : value.toString();\r\n    }\r\n\r\n    eventHour(event: KeyboardEvent) {\r\n        this.hour = this.setValue(event);\r\n    }\r\n\r\n    eventMinute(event: KeyboardEvent) {\r\n        this.minute = this.setValue(event);\r\n    }\r\n\r\n    eventSecond(event: KeyboardEvent) {\r\n        this.second = this.setValue(event);\r\n    }\r\n\r\n    setValue(event: KeyboardEvent) {\r\n        if (event.key === 'ArrowUp') {\r\n            return this.arrowUp(event);\r\n        } else if (event.key === 'ArrowDown') {\r\n            return this.arrowDown(event);\r\n        } else if ('0' <= event.key && event.key <= '9') {\r\n            return this.pressNumber(event);\r\n        } else if (event.key === 'Backspace' || event.key === 'Delete') {\r\n            event.preventDefault();\r\n            return '00';\r\n        } else {\r\n            if (event.ctrlKey !== true && event.key !== 'c') {\r\n                event.preventDefault();\r\n            }\r\n\r\n            return this.pressOthers(event);\r\n        }\r\n    }\r\n\r\n    arrowUp(event: KeyboardEvent) {\r\n        const eventTarget = event.target as HTMLInputElement;\r\n        let value = parseInt(eventTarget.value, 10) + 1;\r\n        value = value > parseInt(eventTarget.max, 10) ? parseInt(eventTarget.min, 10) : value;\r\n        return this.insertZeroFirst(value);\r\n    }\r\n\r\n    arrowDown(event: KeyboardEvent) {\r\n        const eventTarget = event.target as HTMLInputElement;\r\n        let value = parseInt(eventTarget.value, 10) - 1;\r\n        value = value < parseInt(eventTarget.min, 10) ? parseInt(eventTarget.max, 10) : value;\r\n        return this.insertZeroFirst(value);\r\n    }\r\n\r\n    pressNumber(event: KeyboardEvent) {\r\n        const eventTarget = event.target as HTMLInputElement;\r\n        const value = `${eventTarget.value.substr(1)}${event.key}`;\r\n        return value > eventTarget.max ? `0${event.key}` : value;\r\n    }\r\n\r\n    pressOthers(event: KeyboardEvent) {\r\n        const eventTarget = event.target as HTMLInputElement;\r\n        return eventTarget.value;\r\n    }\r\n}\r\n","export class GeneralInfo {\r\n    voidedTimeString: string;\r\n    kickOffTimeString?: string;\r\n    leagueName?: string;\r\n    matchEvent?: string;\r\n    totalVoidedTickets: number;\r\n    totalCancelCashOut: number;\r\n    decidedBy: string;\r\n    requestedBy: string;\r\n    negativeBalanceUsers: string;\r\n    voidingHistoryIds: string;\r\n    licenseeNames: string;\r\n    generalBetTypeCombinations: string;\r\n    scoreResult: string;\r\n    reason: string;\r\n}\r\n\r\nexport class GroupUserVoidMessage {\r\n    voidedBy: string;\r\n    messages: UserVoidMessage[];\r\n}\r\n\r\nexport class UserVoidMessage {\r\n    voidedBy: string;\r\n    contentEnglish: string;\r\n    contentChineseSimplified: string;\r\n}\r\n\r\nexport class GeneralInfoViewModel {\r\n    constructor() {\r\n        this.generalInfoModel = new GeneralInfo();\r\n        this.userVoidMessages = [];\r\n        this.succeedEmails = [];\r\n        this.failedEmails = [];\r\n    }\r\n    generalInfoModel: GeneralInfo;\r\n    userVoidMessages: GroupUserVoidMessage[];\r\n    succeedEmails: string[];\r\n    failedEmails: string[];\r\n}","import { Directive, ElementRef, HostListener } from '@angular/core';\r\n\r\nconst MINUTE_INDEX = 2;\r\nconst SECOND_INDEX = 4;\r\n@Directive({\r\n  selector: '[time-control]'\r\n})\r\nexport class TimeDirective {\r\n  constructor(private readonly element: ElementRef) {\r\n  }\r\n\r\n  @HostListener('keydown', ['$event']) onKeyDown(event: KeyboardEvent) {\r\n    switch (true) {\r\n      case event.key === 'ArrowLeft':\r\n        this.arrowLeft();\r\n        break;\r\n      case event.key === 'ArrowRight':\r\n        this.arrowRight();\r\n        break;\r\n      default:\r\n        break;\r\n    }\r\n  }\r\n\r\n  arrowRight() {\r\n    const parentNode = this.element.nativeElement.parentNode;\r\n    const hourElement = parentNode.children[0];\r\n    const minuteElement = parentNode.children[MINUTE_INDEX];\r\n    const secondElement = parentNode.children[SECOND_INDEX];\r\n    if (this.element.nativeElement.classList.contains('hour')) {\r\n      minuteElement.focus();\r\n    }\r\n    if (this.element.nativeElement.classList.contains('minute')) {\r\n      secondElement.focus();\r\n    }\r\n    if (this.element.nativeElement.classList.contains('second')) {\r\n      hourElement.focus();\r\n    }\r\n  }\r\n\r\n  arrowLeft() {\r\n    const parentNode = this.element.nativeElement.parentNode;\r\n    const hourElement = parentNode.children[0];\r\n    const minuteElement = parentNode.children[MINUTE_INDEX];\r\n    const secondElement = parentNode.children[SECOND_INDEX];\r\n    if (this.element.nativeElement.classList.contains('second')) {\r\n      minuteElement.focus();\r\n    }\r\n    if (this.element.nativeElement.classList.contains('minute')) {\r\n      hourElement.focus();\r\n    }\r\n    if (this.element.nativeElement.classList.contains('hour')) {\r\n      secondElement.focus();\r\n    }\r\n  }\r\n\r\n}\r\n","import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';\r\nimport { TimeModel } from './time.model';\r\n\r\nimport * as _ from 'lodash';\r\n\r\n@Component({\r\n  selector: 'date-time',\r\n  templateUrl: './date-time.component.html',\r\n  styleUrls: ['./date-time.component.scss']\r\n})\r\nexport class DateTimeComponent implements OnInit {\r\n  @Input() model = new TimeModel(new Date());\r\n  @Input() disabled: boolean;\r\n  @Output() modelChange = new EventEmitter<TimeModel>();\r\n\r\n  ngOnInit() {\r\n    if (_.isNaN(this.model.hour)) {\r\n      this.model = new TimeModel(new Date());\r\n    }\r\n  }\r\n\r\n  updateModel() {\r\n    this.modelChange.emit(this.model);\r\n  }\r\n}\r\n","<div class=\"date-time\">\r\n  <div class=\"input-group\">\r\n    <input class=\"form-control form-control-sm bg-white\" placeholder=\"yyyy-mm-dd\" name=\"dp\" [(ngModel)]=\"model.ngbDate\"\r\n      (ngModelChange)=\"updateModel()\" ngbDatepicker #d=\"ngbDatepicker\" (click)=\"d.toggle()\" [disabled]=\"disabled\" [readOnly]=\"true\">\r\n    <div class=\"input-group-append pointer\">\r\n      <span class=\"input-group-text\" (click)=\"d.toggle()\"><em class=\"fa fa-calendar\"></em></span>\r\n    </div>\r\n  </div>\r\n  <div class=\"time\" [ngClass]=\"{'disabled':disabled}\">\r\n    <input type=\"text\" maxlength=\"2\" min=\"0\" max=\"23\" class=\"hour\" [(ngModel)]=\"model.hour\" time-control\r\n      (keydown)=\"model.eventHour($event);updateModel()\" [disabled]=\"disabled\" />\r\n    <span>:</span>\r\n    <input type=\"text\" maxlength=\"2\" min=\"0\" max=\"59\" class=\"minute\" [(ngModel)]=\"model.minute\" time-control\r\n      (keydown)=\"model.eventMinute($event);updateModel()\" [disabled]=\"disabled\" />\r\n    <span>:</span>\r\n    <input type=\"text\" maxlength=\"2\" min=\"0\" max=\"59\" class=\"second\" [(ngModel)]=\"model.second\" time-control\r\n      (keydown)=\"model.eventSecond($event);updateModel()\" [disabled]=\"disabled\" />\r\n  </div>\r\n</div>\r\n","<div>\r\n  <div class=\"row no-gutters\">\r\n    <div class=\"mr-3\">\r\n      <label class=\"col-form-label mr-2\">Issue Type</label>\r\n      <label class=\"col-form-label\">\r\n        <strong>\r\n          <span class=\"padding-2-10 alert alert-dark\">{{issueTypeName}}</span>\r\n          <span *ngIf=\"isShowVar\" class=\"alert padding-2-10 mg-left-5 text-white bg-danger\">VAR</span>\r\n        </strong>\r\n      </label>\r\n    </div>\r\n\r\n    <div *ngIf=\"isEarlyKOIssueType\" class=\"nowrap d-flex mr-3\">\r\n      <label class=\"col-form-label text-right mg-right-10\">KO Time</label>\r\n      <div class=\"d-flex\">\r\n        <date-time [model]=\"kickOffTime\" [disabled]=\"true\" class=\"mr-1\"></date-time>\r\n        <label class=\"col-form-label\">(GMT+8)</label>\r\n      </div>\r\n    </div>\r\n\r\n    <div *ngIf=\"isShowGeneralInfo\" class=\"pt-2 fa\" style=\"cursor: pointer;\" (click)=\"isExpandGeneralInfo = !isExpandGeneralInfo\">\r\n      <span [ngClass]=\"{'fa-chevron-up':isExpandGeneralInfo, 'fa-chevron-down':!isExpandGeneralInfo}\" aria-hidden=\"true\"></span>\r\n    </div>\r\n  </div>\r\n\r\n  <div *ngIf=\"isAbnormalAccount && isShowAbnormalAccountInfo\">\r\n    <div class=\"row no-gutters\">Product:&nbsp;<strong>{{product}}</strong></div>\r\n    <div class=\"row no-gutters\">Ticket Status:&nbsp;<strong>{{status}}</strong></div>\r\n    <div class=\"row no-gutters\">From/To Event Date:&nbsp;<strong>{{model.event.fromDate | date: 'yyyy/MM/dd'}} - \r\n      {{model.event.toDate | date: 'yyyy/MM/dd'}}\r\n    </strong></div>\r\n  </div>\r\n  <div *ngIf=\"isShowGeneralInfo\">\r\n    <div [hidden]=\"!isExpandGeneralInfo\">\r\n      <div class=\"row no-gutters general-info-tab\">\r\n        <div class=\"inner-border\">\r\n          <span><strong>General Info</strong></span>\r\n        </div>\r\n      </div>\r\n      <div class=\"mb-3 mt-3\">\r\n        <div class=\"mb-2\" *ngIf=\"isShowMatchInfo()\">\r\n          <span class=\"row no-gutters\">Kick Off: {{generalInfoViewModel.generalInfoModel.kickOffTimeString}}<br/></span>\r\n          <span class=\"row no-gutters\">League: {{generalInfoViewModel.generalInfoModel.leagueName}}<br/></span>\r\n          <span class=\"row no-gutters\">Match: {{generalInfoViewModel.generalInfoModel.matchEvent}}<br/></span>\r\n        </div>\r\n        <span class=\"row no-gutters\">Affected: {{generalInfoViewModel.generalInfoModel.licenseeNames}}<br/></span>\r\n        <div *ngIf=\"isLikelyAbnormalBetIssueType()\">\r\n          <span *ngIf=\"!isAbnormalBetMixParlay()\" class=\"row no-gutters\">Bettype: {{generalInfoViewModel.generalInfoModel.generalBetTypeCombinations}}<br/></span>\r\n          <span class=\"row no-gutters\">Reason: {{generalInfoViewModel.generalInfoModel.reason}}<br/></span>\r\n          <span *ngIf=\"!isAbnormalBetMixParlay()\" class=\"row no-gutters\">Results: {{generalInfoViewModel.generalInfoModel.scoreResult}}<br/></span>\r\n        </div>\r\n        <span class=\"row no-gutters\">Total voided tickets: {{generalInfoViewModel.generalInfoModel.totalVoidedTickets}}<br/></span>\r\n        <span class=\"row no-gutters\">Cancel cash out: {{generalInfoViewModel.generalInfoModel.totalCancelCashOut}}<br/></span>\r\n        <span class=\"row no-gutters\">Decided by: {{generalInfoViewModel.generalInfoModel.decidedBy}}<br/></span>\r\n        <span class=\"row no-gutters\">Requested by: {{generalInfoViewModel.generalInfoModel.requestedBy}}<br/></span>\r\n         \r\n        <div class=\"mt-2\" *ngIf=\"generalInfoViewModel.userVoidMessages?.length > 0\">\r\n          <div class=\"mb-2 no-gutters\" *ngFor=\"let userVoidMessage of generalInfoViewModel.userVoidMessages\">\r\n            <span class=\"row no-gutters\">Voided by: {{userVoidMessage.voidedBy}}<br/></span>\r\n            <div *ngFor=\"let message of userVoidMessage.messages\"> \r\n              <span class=\"row no-gutters\">{{message.contentEnglish}}<br/></span>\r\n              <span class=\"row no-gutters\">{{message.contentChineseSimplified}}<br/></span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <div class=\"mb-2\" *ngIf=\"generalInfoViewModel.succeedEmails?.length > 0\">\r\n          <span class=\"row no-gutters\" *ngFor=\"let succeedEmail of generalInfoViewModel.succeedEmails\">{{succeedEmail}}</span>\r\n        </div>\r\n        <div class=\"mb-2\" *ngIf=\"generalInfoViewModel.failedEmails?.length > 0\">\r\n          <span class=\"row no-gutters\" *ngFor=\"let failedEmail of generalInfoViewModel.failedEmails\">{{failedEmail}}</span>\r\n        </div>\r\n        <div class=\"mt-2\" *ngIf=\"generalInfoViewModel.generalInfoModel.negativeBalanceUsers\" >\r\n          <span class=\"row no-gutters\">Negative Balance Customers: <strong>{{generalInfoViewModel.generalInfoModel.negativeBalanceUsers}}</strong><br/></span>\r\n        </div>\r\n      </div>\r\n  </div>\r\n</div>\r\n","import { Component, Input, OnChanges, OnInit, SimpleChange } from '@angular/core';\r\nimport { NgbAccordionConfig } from '@ng-bootstrap/ng-bootstrap';\r\nimport * as _ from 'lodash';\r\nimport { RequestDetailViewModel } from '../../../edit-request/app/request.model';\r\nimport { TimeModel } from '../../../utility/components/date-time/date-time/time.model';\r\nimport { AbnormalFilterBy } from '../../../utility/constants/config';\r\nimport { IssueInfo } from '../../../utility/models/issue-type.model';\r\nimport { StaticService } from '../../../utility/services/static.service';\r\nimport { GeneralInfoViewModel } from './request-info.model';\r\n\r\n\r\n@Component({\r\n  selector: 'request-info',\r\n  templateUrl: './request-info.component.html',\r\n  styleUrls: ['./request-info.component.scss']\r\n})\r\nexport class RequestInfoComponent implements OnInit, OnChanges {\r\n  @Input() model = new RequestDetailViewModel();\r\n  @Input() issue = new IssueInfo();\r\n  @Input() generalInfoViewModel = new GeneralInfoViewModel();\r\n  @Input() isShowGeneralInfo = false;\r\n  @Input() isShowAbnormalAccountInfo = false;\r\n  @Input() isShowVar = false;\r\n\r\n  kickOffTime = new TimeModel(new Date());\r\n  issueTypeName: string;\r\n  isExpandGeneralInfo = false;\r\n  isEarlyKOIssueType = false;\r\n  isAbnormalAccount = false;\r\n  isAbnormalBet = false;\r\n  product = '';\r\n  status = '';\r\n\r\n  constructor(config: NgbAccordionConfig) {\r\n    config.closeOthers = true;\r\n  }\r\n\r\n  ngOnInit() {\r\n  }\r\n\r\n  ngOnChanges(changes: { [propKey: string]: SimpleChange }) {\r\n    if (changes['issue']) {\r\n      this.updateIssue();\r\n    }\r\n    if (this.isShowAbnormalAccountInfo && changes['model']) {\r\n      this.getProducts();\r\n      this.getStatus();\r\n    }\r\n  }\r\n\r\n  private updateIssue() {\r\n    if (!_.isUndefined(this.issue.issueTypeId)) {\r\n      this.issueTypeName = this.issue.name === this.issue.subIssueTypeName ? this.issue.name : `${this.issue.name} - ${this.issue.subIssueTypeName}`;\r\n\r\n      this.updateDefaultIssueType(false, false);\r\n      if (this.isEarlyKickOffIssueType()) {\r\n        this.isEarlyKOIssueType = true;\r\n        if (!_.isUndefined(this.model.event)) {\r\n          this.kickOffTime = new TimeModel(new Date(this.model.event.kickOffTime));\r\n        }\r\n      }\r\n\r\n      if (this.isAbnormalAccountIssueType()) {\r\n        this.isAbnormalAccount = true;\r\n      }\r\n\r\n      if (this.isLikelyAbnormalBetIssueType()) {\r\n        this.isAbnormalBet = true;\r\n      }\r\n    }\r\n  }\r\n\r\n  private updateDefaultIssueType(eko: boolean, abnormalAccount: boolean): void {\r\n    this.isEarlyKOIssueType = eko;\r\n    this.isAbnormalAccount = abnormalAccount;\r\n  }\r\n\r\n  getProducts(): void {\r\n    this.product = this.model.event.productIds\r\n      .replace('1', 'Sportsbook')\r\n      .replace('2', 'Parlay')\r\n      .replace('3', 'Bet Builder')\r\n      .replace('4', 'Outright')\r\n      .replace('5', 'Saba')\r\n      .replace('6', 'Non-Sports');\r\n  }\r\n\r\n  getStatus(): void {\r\n    this.status = this.model.event.statusIds\r\n      .replace('0,1', 'Running')\r\n      .replace('112', 'Won')\r\n      .replace('113', 'Lose')\r\n      .replace('111', 'Draw');\r\n  }\r\n\r\n  public isShowMatchInfo(): boolean {\r\n    return !this.isAbnormalAccountIssueType() && !this.isAbnormalBetMixParlay() && !this.isArchivedTicket();\r\n  }\r\n\r\n  public isAbnormalBetMixParlay(): boolean {\r\n    return this.isAbnormalBetIssueType() && this.model.event?.filterBy === AbnormalFilterBy.MIX_PARLAY;\r\n  }\r\n\r\n  public isArchivedTicket(): boolean {\r\n    return StaticService.isArchivedTicket(this.issue.issueTypeId?.toString());\r\n  }\r\n\r\n  isEarlyKickOffIssueType(): boolean {\r\n    return StaticService.isEarlyKickOff(this.issue.issueTypeId?.toString());\r\n  }\r\n\r\n  isAbnormalAccountIssueType(): boolean {\r\n    return StaticService.isAbnormalAccount(this.issue.issueTypeId?.toString());\r\n  }\r\n\r\n  isLikelyAbnormalBetIssueType(): boolean {\r\n    return this.isAbnormalBetIssueType() || this.isAbnormalBetRealMemberIssueType();\r\n  }\r\n\r\n  private isAbnormalBetIssueType(): boolean {\r\n    return StaticService.isAbnormalBet(this.issue.issueTypeId?.toString());\r\n  }\r\n\r\n  private isAbnormalBetRealMemberIssueType(): boolean {\r\n    return StaticService.isAbnormalBetRealMember(this.issue.issueTypeId?.toString());\r\n  }\r\n}\r\n","  <div class=\"row no-gutters mt-2\">\r\n    <label class=\"col-form-label log-info-label\">Log Info </label>\r\n    <div class=\"col-sm-6 pd-top-8 remark-content\">\r\n      <div *ngFor=\"let item of logInfoDetails\" class=\"log-info p-2 mb-3\">\r\n        <span *ngIf=\"!isReducedOver()\">{{displayScoreLabel(filterBy)}}<strong>{{item.liveScores}}</strong>.</span>\r\n        {{displayVoidTimeLabel(filterBy)}}<strong>{{displayFullDateTimeFormat(item.voidFromTime)}} - {{displayFullDateTimeFormat(item.voidToTime)}}</strong><br />\r\n        <ng-container *ngIf=\"!isWrongOdds()\">\r\n          Affected Single Count: <strong>{{item.singleCount}}</strong>\r\n          <span *ngIf=\"isShowCountInfo(item.cashOutCount, item.settleCount, item.instantlySettleCount)\" class=\"text-red\"\r\n          [innerHTML]=\"countInfoContent(item.cashOutCount, item.settleCount, item.instantlySettleCount) | sanitizeHtml\">\r\n          </span>,\r\n          Parlay Count: <strong>{{item.mainParlayCount}}</strong><span *ngIf=\"item.highlightMinTime\">, Min Time: <strong [ngClass]=\"getHighlightMinTimeClass(item)\">{{displayMinTime(item.highlightMinTime)}}</strong></span>\r\n          <span *ngIf=\"!isReducedOver()\"><br/>Cancel Cash Out: <strong>{{item.cancelCashOutCount}}</strong></span>\r\n        </ng-container>\r\n\r\n        <ng-container *ngIf=\"isWrongOdds()\">\r\n          LG/Early - Single Count: <strong>{{item.liveGameEarlySingleCount}}</strong>\r\n          <span *ngIf=\"isShowCountInfo(item.liveGameEarlyCashOutCount, item.liveGameEarlySettleCount, item.liveGameEarlyInstantlySettleCount)\" class=\"text-red\"\r\n          [innerHTML]=\"countInfoContent(item.liveGameEarlyCashOutCount, item.liveGameEarlySettleCount, item.liveGameEarlyInstantlySettleCount) | sanitizeHtml\">\r\n          </span><br />\r\n          <div *ngIf=\"isPoolHouseAffected\">\r\n            PH - Single Count: <strong>{{item.poolHouseSingleCount}}</strong>\r\n            <span *ngIf=\"isShowCountInfo(item.poolHouseCashOutCount, item.poolHouseSettleCount, item.poolHouseInstantlySettleCount)\" class=\"text-red\"\r\n            [innerHTML]=\"countInfoContent(item.poolHouseCashOutCount, item.poolHouseSettleCount, item.poolHouseInstantlySettleCount) | sanitizeHtml\">\r\n            </span>,\r\n            Parlay Count: <strong>{{item.poolHouseMainParlayCount}}</strong>&nbsp;\r\n          </div>\r\n          <div *ngIf=\"!isPoolHouseAffected\">PH - Not affected.</div>\r\n        </ng-container>\r\n      </div>\r\n\r\n      <div *ngIf=\"isWrongScore()\" class=\"d-flex\">\r\n        <label class=\"col-form-label mr-3\">Actual Score</label>\r\n        <div><input class=\"input-actual-score form-control form-control-sm\" type=\"text\" [(ngModel)]=\"actualScore\" disabled/></div>\r\n      </div>\r\n      <div *ngIf=\"isWrongOdds()\" class=\"d-flex\">\r\n        <label class=\"col-form-label mr-3\">Correct Odds</label>\r\n        <div><input class=\"input-actual-score form-control form-control-sm\" type=\"text\" [(ngModel)]=\"correctOdds\" disabled/></div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n","import { Component, Input } from '@angular/core';\r\nimport * as _ from 'lodash';\r\nimport * as moment from 'moment-timezone';\r\nimport { AcceptType, DateTimeFormat, TVSRequestFilterBy } from '../../../utility/constants/config';\r\nimport { IssueTypeConstant } from '../../../utility/constants/issue-type.constant';\r\nimport { LogInfoDetail } from '../../../utility/models/log-info-detail.model';\r\nimport { StaticService } from '../../../utility/services/static.service';\r\n\r\n@Component({\r\n  selector: 'log-info',\r\n  templateUrl: './log-info.component.html',\r\n  styleUrls: ['./log-info.component.scss']\r\n})\r\nexport class LogInfoComponent {\r\n  @Input() logInfoDetails: LogInfoDetail[];\r\n  @Input() issueTypeId: number;\r\n  @Input() actualScore: string;\r\n  @Input() filterBy: number;\r\n  @Input() correctOdds: string;\r\n  @Input() isPoolHouseAffected: boolean;\r\n\r\n  acceptTypeName = \"\";\r\n\r\n  displayScoreLabel(filterBy: number): string {\r\n    return (this.isWrongScore() && (filterBy === TVSRequestFilterBy.TRANS_TIME || filterBy === TVSRequestFilterBy.TRANS_TIME_AND_CHECK_TIME)) ?\r\n      'Wrong Score: ' : 'Live Score: ';\r\n  }\r\n\r\n  displayVoidTimeLabel(filterBy: number): string {\r\n    if (this.isWrongScore()) {\r\n      if (filterBy === TVSRequestFilterBy.TRANS_TIME || filterBy === TVSRequestFilterBy.TRANS_TIME_AND_CHECK_TIME) {\r\n        return 'Void Trans Time (GMT-4): ';\r\n      } else if (filterBy === TVSRequestFilterBy.CHECK_TIME) {\r\n        return 'Void Accept Time (GMT-4): ';\r\n      }\r\n    }\r\n\r\n    return 'Void time (GMT-4): ';\r\n  }\r\n\r\n  displayFullDateTimeFormat(time: Date): string {\r\n    return moment(time).format(DateTimeFormat.FULL_DATE_TIME_FORMAT);\r\n  }\r\n\r\n  isShowCountInfo(cashOutCount: number, settleCount: number, instantlySettleCount: number) {\r\n    return StaticService.isShowCountInfo(cashOutCount, settleCount, instantlySettleCount);\r\n  }\r\n\r\n  countInfoContent(cashOutCount: number, settleCount: number, instantlySettleCount: number) {\r\n    return StaticService.countInfoContent(cashOutCount, settleCount, instantlySettleCount);\r\n  }\r\n\r\n  getHighlightMinTimeClass(logInfoDetail: LogInfoDetail): string {\r\n    if (logInfoDetail.highlightMinTime && logInfoDetail.highlightAcceptType) {\r\n      switch (logInfoDetail.highlightAcceptType) {\r\n        case AcceptType.AUTO_ACCEPT: {\r\n          this.acceptTypeName = \"AA\";\r\n          return 'highlight-min-aa';\r\n        }\r\n        case AcceptType.SECOND_ACCEPT: {\r\n          this.acceptTypeName = \"SA\";\r\n          return 'highlight-min-sa';\r\n        }\r\n        case AcceptType.PENDING_ACCEPT: {\r\n          this.acceptTypeName = \"PA\";\r\n          return 'highlight-min-pa';\r\n        }\r\n      }\r\n    }\r\n\r\n    return '';\r\n  }\r\n\r\n  displayMinTime(minTime?: Date): string {\r\n    if(_.isNull(minTime)){\r\n      return '-';\r\n    }\r\n    return (this.acceptTypeName) ? `${moment(minTime).format(DateTimeFormat.TIME_FORMAT)} - ${this.acceptTypeName}`:\r\n    `${moment(minTime).format(DateTimeFormat.TIME_FORMAT)}`;\r\n  }\r\n\r\n  isWrongScore(): boolean {\r\n    return this.issueTypeId === Number(IssueTypeConstant.WRONG_SCORE);\r\n  }\r\n\r\n  isWrongOdds(): boolean {\r\n    return this.issueTypeId === Number(IssueTypeConstant.WRONG_ODDS);\r\n  }\r\n\r\n  isReducedOver(): boolean {\r\n    return this.issueTypeId === Number(IssueTypeConstant.REDUCED_OVER);\r\n  }\r\n}\r\n","<div class=\"group-bettypes area-filter\" *ngIf=\"model.groupBetTypes.length > 0 && display\">\r\n  <table>\r\n    <thead>\r\n      <tr>\r\n        <th scope=\"col\" colspan=\"2\">\r\n          <div>\r\n            <label>\r\n              <input type=\"checkbox\" class=\"group-bettypes-all-checkbox\" [(ngModel)]=\"model.isChecked\" [disabled]=\"isDisabledAllBetTypes\"\r\n                (ngModelChange)=\"model.changeCheckedModelToGroup(); changedBetTypes()\" />\r\n              All Bet types\r\n            </label>\r\n            <label *ngIf=\"scroll\" (click)=\"collapse = !collapse\">\r\n              <em [ngClass]=\"{'icon-plus-bettypes': collapse, 'icon-minus-bettypes': !collapse}\"></em>\r\n              Show All Bet types\r\n            </label>\r\n          </div>\r\n        </th>\r\n      </tr>\r\n    </thead>\r\n    <tbody [ngClass]=\"{'collapse': collapse && scroll}\">\r\n      <tr *ngFor=\"let group of model.groupBetTypes\">\r\n        <td *ngIf=\"group.isShow && group.betTypes.length > 0\">\r\n          <label>\r\n            <input type=\"checkbox\" [(ngModel)]=\"group.isChecked\" (ngModelChange)=\"group.changeCheckedGroupToBetType();\r\n                                                model.changeCheckedGroupToModel();\r\n                                                changedBetTypes()\" [disabled]=\"isDisabledAllBetTypes\" />\r\n            {{group.groupName}}\r\n          </label>\r\n        </td>\r\n        <td *ngIf=\"group.isShow\">\r\n          <div class=\"display-flex\">\r\n            <div class=\"bet-type\" *ngFor=\"let betType of group.betTypes\">\r\n              <label\r\n                [ngClass]=\"{'red-highlight-bettype':betType.redHighlight,\r\n                  'blue-highlight-bettype': betType.blueHighlight}\">\r\n                <input type=\"checkbox\" [(ngModel)]=\"betType.isChecked\" [disabled]=\"isDisabledAllBetTypes\"\r\n                (ngModelChange)=\"group.changeCheckedBetTypeToGroup(); \r\n                                  model.changeCheckedGroupToModel(); changedBetTypes()\" />\r\n                {{betType.name}}\r\n              </label>\r\n            </div>\r\n          </div>\r\n        </td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n</div>\r\n<tooltip [tooltip]=\"tooltip\"></tooltip>\r\n","import { Component, ElementRef, EventEmitter, Input, OnChanges, OnInit, Output, SimpleChange } from '@angular/core';\r\nimport { Product } from '../../../../utility/constants/config';\r\nimport { LABELS } from '../../../../utility/constants/labels';\r\nimport { Tooltip } from '../../tooltip/tooltip.model';\r\nimport { BetType, GroupBetType, GroupBetTypesModel } from './group-bettypes.model';\r\n\r\n@Component({\r\n  selector: 'group-bettypes',\r\n  templateUrl: './group-bettypes.component.html',\r\n  styleUrls: ['./group-bettypes.component.scss']\r\n})\r\n\r\nexport class GroupBetTypesComponent implements OnInit, OnChanges {\r\n  @Input() model: GroupBetTypesModel;\r\n  @Input() product: number = Product.SPORTS_BOOK;\r\n  @Output() betTypesEvent = new EventEmitter<BetType[]>();\r\n  tooltip = new Tooltip();\r\n  isDisabledAllBetTypes: boolean;\r\n\r\n  @Input() scroll: boolean;\r\n  display: boolean;\r\n  collapse = true;\r\n\r\n  constructor(private readonly element: ElementRef) {\r\n    this.tooltip.element = this.element;\r\n  }\r\n\r\n  ngOnInit() {\r\n    this.model = new GroupBetTypesModel(new Array<GroupBetType>(), false);\r\n  }\r\n\r\n  ngOnChanges(changes: { [propKey: string]: SimpleChange }) {\r\n    this.display = this.product === Product.SPORTS_BOOK;\r\n  }\r\n\r\n  displayGroup(groups: string[]) {\r\n    this.model.groupBetTypes.forEach(group => {\r\n      group.isShow = groups.indexOf(group.groupName) > -1;\r\n      if (!group.isShow) {\r\n        group.isChecked = false;\r\n        group.changeCheckedGroupToBetType();\r\n      }\r\n    });\r\n    this.changedBetTypes();\r\n    this.model.changeCheckedGroupToModel();\r\n  }\r\n\r\n  changedBetTypes() {\r\n    const betTypes = this.model.getAllBetType();\r\n    this.betTypesEvent.emit(betTypes);\r\n  }\r\n\r\n  validate(): boolean {\r\n    const result = this.model.getCheckedBetTypes().length > 0;\r\n    if (!result) {\r\n      this.tooltip.display('group-bettypes-all-checkbox', LABELS.NO_CHECKED_BETTYPE);\r\n    }\r\n\r\n    return result;\r\n  }\r\n}\r\n","<ul class=\"multiple-select\">\r\n    <li *ngFor=\"let item of items\">\r\n        <div class=\"multiple-select-item\">\r\n            <em *ngIf=\"item.items.length > 0\" [ngClass]=\"{'i-expanded': item.expanded, 'i-collapsed': !item.expanded}\"\r\n               (click)=\"item.expanded = !item.expanded\"></em>\r\n            <label [ngClass]=\"{'margin-left-13': item.items.length == 0}\">\r\n                <input type=\"checkbox\" [(ngModel)]=\"item.checked\" \r\n                       (ngModelChange)=\"item.checkChilds();clickEvent(item)\" \r\n                       [disabled]=\"!item.enable\"  (keyup.shift)=\"keyUp()\" (keydown.shift)=\"keyDown()\" />\r\n                {{ item.text }}\r\n            </label>\r\n        </div>\r\n        <div *ngIf=\"item.expanded\">\r\n            <tree-view [items]=\"item.items\"></tree-view>\r\n        </div>\r\n    </li>\r\n</ul>","import { Component, Input } from '@angular/core';\r\nimport { ItemsSelect } from '../../multiple-selection/items-select';\r\n\r\n@Component({\r\n  selector: 'tree-view',\r\n  styleUrls: ['./tree-view.component.scss'],\r\n  templateUrl: './tree-view.component.html'\r\n})\r\n\r\nexport class TreeViewComponent {\r\n  @Input() items: Array<ItemsSelect>;\r\n  lastItem: ItemsSelect;\r\n  shiftKey: boolean;\r\n\r\n  keyDown() {\r\n    this.shiftKey = true;\r\n  }\r\n\r\n  keyUp() {\r\n    this.shiftKey = false;\r\n  }\r\n\r\n  clickEvent(item: ItemsSelect) {\r\n    if (this.shiftKey) {\r\n      this.handleWithShiftCheckbox(item);\r\n    }\r\n\r\n    this.lastItem = item;\r\n  }\r\n\r\n  handleWithShiftCheckbox(item: ItemsSelect) {\r\n    if (this.lastItem !== undefined) {\r\n      this.checkListItem(item);\r\n    }\r\n  }\r\n\r\n  checkListItem(item: ItemsSelect) {\r\n    const last = this.items.indexOf(this.lastItem);\r\n    const current = this.items.indexOf(item);\r\n    const start = Math.min(last, current);\r\n    const end = Math.max(last, current);\r\n    for (let i = start; i <= end; i++) {\r\n      this.items[i].checked = item.checked;\r\n    }\r\n  }\r\n}\r\n","<div class=\"multiple-selection\" [style.width]=\"multipleSelect.maxWidth\">\r\n    <button type=\"button\" readonly (click)=\"dropdownToggle = !dropdownToggle\" [disabled]=\"isDisabled\">\r\n        <span>{{multipleSelect.selectionTitle }}</span>\r\n        <span class=\"i-down\"></span>\r\n    </button>\r\n    <div class=\"show-tree-view\" *ngIf=\"multipleSelect.items != undefined && dropdownToggle\">\r\n        <div class=\"dropdown-header\" *ngIf=\"multipleSelect.showHeader\">\r\n            <label>\r\n                <input type=\"checkbox\" [(ngModel)]=\"multipleSelect.isCheckAll\"\r\n                    (ngModelChange)=\"multipleSelect.checkAllItems(multipleSelect.isCheckAll);changeItems();\" />\r\n                {{multipleSelect.checkAllCheckBoxText}}\r\n            </label>\r\n            <span [ngClass]=\"{'i-up': expanded, 'i-down': !expanded}\" (click)=\"toggle()\"></span>\r\n        </div>\r\n        <div class=\"tree-view-content\" [style.max-height]=\"multipleSelect.maxHeight\">\r\n            <tree-view [items]=\"multipleSelect.items\" (change)=\"changeItems()\"></tree-view>\r\n        </div>\r\n    </div>\r\n</div>\r\n","import { Component, EventEmitter, Input, OnChanges, OnInit, Output, SimpleChange, ViewContainerRef } from '@angular/core';\r\nimport { ItemsSelect } from '../../multiple-selection/items-select';\r\nimport { MultipleSelection } from '../../multiple-selection/multiple-selection';\r\nimport { TreeViewComponent } from './tree-view.component';\r\n\r\n@Component({\r\n  selector: 'multiple-select',\r\n  templateUrl: './multiple-select.component.html',\r\n  styleUrls: ['./multiple-select.component.scss'],\r\n  viewProviders: [TreeViewComponent]\r\n})\r\n\r\nexport class MultipleSelectComponent implements OnInit, OnChanges {\r\n  @Input() multipleSelect: MultipleSelection;\r\n  @Input() isDisabled: boolean;\r\n  @Output() loseFocus = new EventEmitter();\r\n  @Output() checkedItems = new EventEmitter<string[]>();\r\n\r\n  dropdownToggle: boolean;\r\n  expanded: boolean;\r\n  element: Element;\r\n  items: ItemsSelect[];\r\n\r\n  constructor(viewContainerRef: ViewContainerRef) {\r\n    this.element = viewContainerRef.element.nativeElement;\r\n  }\r\n\r\n  async ngOnChanges(changes: { [propKey: string]: SimpleChange }) {\r\n    if (changes['isDisabled'] && this.isDisabled) {\r\n      this.multipleSelect.items.forEach(x => x.checked = true);\r\n      this.getSelectedTitle();\r\n    }\r\n  }\r\n\r\n  ngOnInit() {\r\n    this.expanded = true;\r\n    this.getSelectedTitle();\r\n    this.clickBody();\r\n  }\r\n\r\n  getSelectedTitle() {\r\n    this.multipleSelect.selectionTitle = this.multipleSelect.getDisplayedItems();\r\n    this.multipleSelect.isCheckAll = this.multipleSelect.selectionTitle === this.multipleSelect.allItemsCheckedText;\r\n  }\r\n\r\n  clickBody() {\r\n    const body = document.querySelector('body');\r\n    body.addEventListener('click', e => {\r\n      if (!this.dropdownToggle || !e.target) {\r\n        return;\r\n      }\r\n      if (this.element !== e.target && !this.element.contains((e.target as Node))) {\r\n        this.dropdownToggle = false;\r\n        this.loseFocus.emit(this.multipleSelect.getValueItems());\r\n      }\r\n    }, false);\r\n  }\r\n\r\n  changeItems() {\r\n    const rootItems = this.multipleSelect.items;\r\n    let count = 0;\r\n    let countChecked = 0;\r\n    rootItems.forEach(item => {\r\n      item.checkFromChilds();\r\n      count += item.countChilds;\r\n      countChecked += item.countChildsChecked();\r\n    });\r\n\r\n    this.multipleSelect.isCheckAll = count === countChecked;\r\n    this.multipleSelect.selectionTitle = this.multipleSelect.getDisplayedItems();\r\n    this.checkedItems.emit(this.multipleSelect.getValueItems().split(','));\r\n  }\r\n\r\n  toggle() {\r\n    this.expanded = !this.expanded;\r\n    this.multipleSelect.items.forEach(item => {\r\n      item.expanded = this.expanded;\r\n      if (this.expanded) {\r\n        item.expandedAllItems();\r\n      }\r\n    });\r\n  }\r\n}\r\n","import { Injectable, ElementRef } from '@angular/core';\r\n\r\n@Injectable({\r\n  providedIn: 'root'\r\n})\r\nexport class NumbersOnlyService {\r\n\r\n  constructor() { }\r\n\r\n  executeDirective(element: ElementRef, event: KeyboardEvent, regex: RegExp, specialKeys: Array<string>) {\r\n    if (specialKeys.indexOf(event.key) !== -1) {\r\n      return;\r\n    }\r\n    const current: string = element.nativeElement.value;\r\n    const next: string = current.concat(event.key);\r\n    if (next && !String(next).match(regex)) {\r\n      event.preventDefault();\r\n    }\r\n  }\r\n}\r\n","import { Directive, ElementRef, HostListener } from '@angular/core';\r\nimport { NumbersOnlyService } from './numbers-only.service';\r\n\r\n@Directive({\r\n  selector: 'input[numbersOnly]'\r\n})\r\nexport class NumbersOnlyDirective {\r\n  constructor(private readonly _el: ElementRef) { }\r\n\r\n  @HostListener('input', ['$event']) onInputChange(event: KeyboardEvent) {\r\n    const initalValue = this._el.nativeElement.value;\r\n    this._el.nativeElement.value = initalValue.replace(/[^0-9]*/g, '');\r\n    if (initalValue !== this._el.nativeElement.value) {\r\n      event.stopPropagation();\r\n    }\r\n  }\r\n}\r\n\r\n@Directive({\r\n  selector: 'input[decimalOnly]'\r\n})\r\nexport class DecimalOnlyDirective {\r\n  private readonly regex: RegExp = new RegExp(/^\\d+\\.?\\d{0,2}$/g);\r\n  private readonly specialKeys: Array<string> = ['Backspace', 'End', 'Home'];\r\n\r\n  constructor(private readonly el: ElementRef, private readonly numberOnlyService: NumbersOnlyService) {\r\n  }\r\n  @HostListener('keydown', ['$event']) onKeyDown(event: KeyboardEvent) {\r\n    this.numberOnlyService.executeDirective(this.el, event, this.regex, this.specialKeys);\r\n  }\r\n}\r\n\r\n@Directive({\r\n  selector: 'input[multipleDecimal]'\r\n})\r\nexport class MultipleDecimalDirective {\r\n  private readonly regex: RegExp = new RegExp(/^['0-9&.']*$/g);\r\n  private readonly specialKeys: Array<string> = ['Backspace', 'End', 'Home', 'ArrowLeft', 'ArrowRight'];\r\n\r\n  constructor(private readonly el: ElementRef, private readonly numberOnlyService: NumbersOnlyService) {\r\n  }\r\n  @HostListener('keydown', ['$event']) onKeyDown(event: KeyboardEvent) {\r\n    this.numberOnlyService.executeDirective(this.el, event, this.regex, this.specialKeys);\r\n  }\r\n}","<div class=\"advanced-mode\" *ngIf=\"isShowAdvancedMode\">\r\n  <fieldset [ngClass]=\"{'fieldset-collapse': !isShowContent}\">\r\n    <legend title=\"Collapse advanced mode\" (click)=\"isShowContent = !isShowContent\">\r\n      <em class=\"font-small fa\"\r\n        [ngClass]=\"{'fa-minus-circle': isShowContent, 'fa-plus-circle': !isShowContent}\"></em>Advanced mode\r\n    </legend>\r\n    <div *ngIf=\"isShowAllBetType\" [hidden]=\"!isShowContent\" class=\"all-bet-types\">\r\n      <div class=\"bet-team-1\">\r\n        <div class=\"left\"><b>All bet types: </b></div>\r\n        <div class=\"right\">\r\n          <div class=\"right-selection\">\r\n            <span><b>Map:</b></span>\r\n            <multiple-select class=\"multiple-selection-map float-right\" [multipleSelect]=\"mapList\"\r\n              (checkedItems)=\"updateAllMapAndRoundItemsSelection($event, 'Map:')\">\r\n            </multiple-select>\r\n          </div>\r\n          <div class=\"right-selection\">\r\n            <span><b>Round:</b></span>\r\n            <multiple-select class=\"multiple-selection-round float-right\" [multipleSelect]=\"roundList\"\r\n              (checkedItems)=\"updateAllMapAndRoundItemsSelection($event, 'Round:')\">\r\n            </multiple-select>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div [hidden]=\"!isShowContent\" *ngFor=\"let betTeam of betTeams; let index = index\">\r\n      <div [ngSwitch]=\"betTeam.type\" *ngIf=\"betTeam.checkedBetTypes.length > 0\">\r\n        <div *ngSwitchCase=\"1\" class=\"bet-team\">\r\n          <div class=\"bet-team-1\">\r\n            <div class=\"left mg-right-10\">\r\n              {{betTeam.name}}:\r\n            </div>\r\n            <div class=\"right\">\r\n              <ng-container *ngIf=\"!isHaveMultipleMapRound\">\r\n                <div *ngFor=\"let selection of betTeam.selections\">\r\n                  <div class=\"right-selection\">\r\n                    <span *ngIf=\"selection.name !== ''\">{{selection.name}}</span>\r\n                    <select [(ngModel)]=\"selection.value\" (change)=\"handleChangeFancyBetTypeCricket(betTeam)\">\r\n                      <option *ngFor=\"let item of selection.items\" [attr.value]=\"item.value\">{{item.name}}</option>\r\n                    </select>\r\n                  </div>\r\n                </div>\r\n              </ng-container>\r\n\r\n              <ng-container *ngIf=\"isHaveMultipleMapRound\">\r\n                <div *ngFor=\"let multiSelection of betTeam.multiSelectionList\">\r\n                  <div class=\"right-selection\">\r\n                    <span>{{multiSelection.name}}</span>\r\n                    <multiple-select class=\"multiple-selection-{{index}} float-right\"\r\n                      [multipleSelect]=\"multiSelection.multipleSelect\">\r\n                    </multiple-select>\r\n                  </div>\r\n                </div>\r\n                <div *ngFor=\"let selection of betTeam.selections\">\r\n                  <div class=\"right-selection\">\r\n                    <span *ngIf=\"selection.name !== ''\">{{selection.name}}</span>\r\n                    <select [(ngModel)]=\"selection.value\" (change)=\"handleChangeFancyBetTypeCricket(betTeam)\">\r\n                      <option *ngFor=\"let item of selection.items\" [attr.value]=\"item.value\">{{item.name}}</option>\r\n                    </select>\r\n                  </div>\r\n                </div>\r\n              </ng-container>\r\n\r\n              <div *ngIf=\"checkBetTypesMoreHDP(betTeam, false)\">\r\n                <div class=\"right-input mg-right-10\" *ngFor=\"let item of betTeam.items\">\r\n                  {{item.name}}\r\n                  <input type=\"text\" [(ngModel)]=\"item.value\" [disabled]=\"item.flag\" decimalOnly />\r\n                </div>\r\n              </div>\r\n              <div *ngIf=\"checkBetTypesMoreHDP(betTeam, true)\" class=\"width-280\">\r\n                <div class=\"right-input mg-right-10 width-158\" *ngFor=\"let item of betTeam.items\">\r\n                  {{item.name}}\r\n                  <input class=\"bet-type-more-hdp\" type=\"text\" [(ngModel)]=\"item.value\" [disabled]=\"item.flag\"\r\n                    (ngModelChange)=\"onChangeInputMultipleDecimal(betTeam.checkedBetTypes[0],$event,'bet-type-more-hdp')\"\r\n                    triggers=\"manual\" multipleDecimal />\r\n                </div>\r\n                <div>\r\n                  Ex: 0.75&1&1.25\r\n                </div> \r\n              </div>\r\n              <div class=\"input-area\" *ngIf=\"isShowTextBox(betTeam)\">\r\n                <div class=\"right-input mg-right-10\" *ngFor=\"let input of betTeam.inputs\">\r\n                  {{input.name}}\r\n                  <input type=\"text\" [(ngModel)]=\"input.value\" [disabled]=\"input.flag\" decimalOnly />\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <div *ngSwitchCase=\"2\" class=\"bet-team\">\r\n          <div class=\"bet-team-2\">\r\n            <div class=\"flex-start\">\r\n              <label>\r\n                <input type=\"checkbox\" [(ngModel)]=\"betTeam.isChecked\" (ngModelChange)=\"betTeam.checkItems()\"\r\n                  class=\"bet-team-{{index}}\" />\r\n                {{betTeam.name}}\r\n              </label>\r\n              <div *ngFor=\"let selection of betTeam.selections\" class=\"flex-start\">\r\n                <div>\r\n                  <span *ngIf=\"selection.name !== ''\">{{selection.name}}</span>\r\n                  <select [(ngModel)]=\"selection.value\">\r\n                    <option *ngFor=\"let item of selection.items\" [attr.value]=\"item.value\">{{item.name}}</option>\r\n                  </select>\r\n                </div>\r\n              </div>\r\n            </div>\r\n            <table>\r\n              <tbody>\r\n                <tr>\r\n                  <ng-template ngFor let-item [ngForOf]=\"betTeam.items\" let-e=\"even\">\r\n                    <td *ngIf=\"e || item.flag\" [attr.rowspan]=\"item.flag?2:1\">\r\n                      <label>\r\n                        <input type=\"checkbox\" [(ngModel)]=\"item.isChecked\"\r\n                          (ngModelChange)=\"betTeam.controlIsChecked()\" />\r\n                        {{item.name}}\r\n                      </label>\r\n                    </td>\r\n                  </ng-template>\r\n                </tr>\r\n                <tr>\r\n                  <ng-template ngFor let-item [ngForOf]=\"betTeam.items\" let-e=\"even\">\r\n                    <td *ngIf=\"!e && !item.flag\">\r\n                      <label>\r\n                        <input type=\"checkbox\" [(ngModel)]=\"item.isChecked\"\r\n                          (ngModelChange)=\"betTeam.controlIsChecked()\" />\r\n                        {{item.name}}\r\n                      </label>\r\n                    </td>\r\n                  </ng-template>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n        </div>\r\n        <div *ngSwitchCase=\"3\" class=\"bet-team\">\r\n          <div class=\"bet-team-3\">\r\n            <div class=\"bet-team-checkbox\">\r\n              <div class=\"left\">\r\n                <label>\r\n                  <input type=\"checkbox\" [(ngModel)]=\"betTeam.isChecked\" (ngModelChange)=\"betTeam.checkItems()\"\r\n                    class=\"bet-team-{{index}}\" />\r\n                  {{betTeam.name}}\r\n                </label>\r\n              </div>\r\n              <div class=\"right\">\r\n                <div *ngFor=\"let item of betTeam.items\" class=\"bet-team-item\">\r\n                  <label>\r\n                    <input type=\"checkbox\" [(ngModel)]=\"item.isChecked\" (ngModelChange)=\"betTeam.controlIsChecked()\" />\r\n                    {{item.name}}\r\n                  </label>\r\n                </div>\r\n              </div>\r\n            </div>\r\n            <div class=\"multiple-selection-area\" *ngIf=\"betTeam.multiSelection !== undefined\">\r\n              <div class=\"float-right\">\r\n                <span>{{betTeam.multiSelection.name}}</span>\r\n                <multiple-select class=\"multiple-selection-{{index}}\" [multipleSelect]=\"betTeam.multiSelection.multipleSelect\">\r\n                </multiple-select>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <div *ngSwitchCase=\"4\" class=\"bet-team\">\r\n          <div class=\"bet-team-4\">\r\n            <div class=\"left\">\r\n              {{betTeam.name}}\r\n            </div>\r\n            <div class=\"right multiple-selection\">\r\n              <multiple-select class=\"multiple-selection-{{index}}\"\r\n                [multipleSelect]=\"betTeam.multiSelection.multipleSelect\"></multiple-select>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <div *ngSwitchCase=\"5\" class=\"bet-team\">\r\n          <div class=\"bet-team-5\">\r\n            <div class=\"left\">\r\n              {{betTeam.name}}\r\n            </div>\r\n            <div class=\"right\">\r\n              <div class=\"right-selection\">\r\n                <span>{{betTeam.selections[0].name}}</span>\r\n                <select [(ngModel)]=\"betTeam.selections[0].value\">\r\n                  <ng-container *ngFor=\"let item of betTeam.selections[0].items\">\r\n                    <option [ngValue]=\"item.value\"\r\n                      *ngIf=\"betTeam.isValidOptionForType5(item, betTeam.selections[0].name)\">\r\n                      {{item.name}}\r\n                    </option>\r\n                  </ng-container>\r\n                </select>\r\n              </div>\r\n              <div class=\"right-selection\">\r\n                <span>{{betTeam.selections[1].name}}</span>\r\n                <select [(ngModel)]=\"betTeam.selections[1].value\">\r\n                  <ng-container *ngFor=\"let item of betTeam.selections[1].items\">\r\n                    <option [ngValue]=\"item.value\"\r\n                      *ngIf=\"betTeam.isValidOptionForType5(item, betTeam.selections[1].name)\">\r\n                      {{item.name}}\r\n                    </option>\r\n                  </ng-container>\r\n                </select>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <div *ngSwitchCase=\"6\" class=\"bet-team\">\r\n          <div class=\"bet-team-6\">\r\n              <div class=\"bet-team-checkbox\">\r\n                <div class=\"left\">\r\n                  <label>\r\n                    <input type=\"checkbox\" [(ngModel)]=\"betTeam.isChecked\" (ngModelChange)=\"betTeam.checkItems()\"\r\n                      class=\"bet-team-{{index}}\" />\r\n                    {{betTeam.name}}\r\n                  </label>\r\n                </div>\r\n                <div class=\"right\">\r\n                  <div *ngFor=\"let item of betTeam.items\" class=\"bet-team-item\">\r\n                    <label>\r\n                      <input type=\"checkbox\" [(ngModel)]=\"item.isChecked\"\r\n                        (ngModelChange)=\"betTeam.controlIsChecked()\" />\r\n                      {{item.name}}\r\n                    </label>\r\n                  </div>\r\n                </div>\r\n              </div>\r\n\r\n            <div class=\"right inputs\">\r\n              <div class=\"right-input\" *ngFor=\"let input of betTeam.inputs\">\r\n                {{input.name}}\r\n                <input type=\"text\" [(ngModel)]=\"input.value\" decimalOnly />\r\n              </div>\r\n            </div>\r\n\r\n          </div>\r\n        </div>\r\n        <div *ngSwitchCase=\"7\" class=\"bet-team\">\r\n          <div class=\"bet-team-3\">\r\n            <div class=\"bet-team-checkbox\">\r\n              <div class=\"left\">\r\n                <label>\r\n                  <input type=\"checkbox\" [(ngModel)]=\"betTeam.isChecked\" (ngModelChange)=\"betTeam.checkItems()\"\r\n                    class=\"bet-team-{{index}}\" />\r\n                  {{betTeam.name}}\r\n                </label>\r\n              </div>\r\n              <div class=\"right\">\r\n                <div *ngFor=\"let item of betTeam.items\" class=\"bet-team-item\">\r\n                  <label>\r\n                    <input type=\"checkbox\" [(ngModel)]=\"item.isChecked\" (ngModelChange)=\"betTeam.controlIsChecked()\" />\r\n                    {{item.name}}\r\n                  </label>\r\n                </div>\r\n              </div>\r\n              <div class=\"right-input d-flex\" *ngFor=\"let input of betTeam.inputs\">\r\n                {{input.name}}\r\n                <input type=\"text\" class=\"mg-right-10\" [ngClass]=\"'bet-type-saba' + betTeam.checkedBetTypes[0]\" [(ngModel)]=\"input.value\" multipleDecimal\r\n                  (ngModelChange)=\"onChangeInputMultipleDecimal(betTeam.checkedBetTypes[0],$event,'bet-type-saba' + betTeam.checkedBetTypes[0])\" triggers=\"manual\" />\r\n                <div>\r\n                  Ex: 0.75&1&1.25\r\n                </div>\r\n              </div>\r\n            </div>\r\n            <div class=\"multiple-selection-area\" *ngIf=\"betTeam.multiSelection !== undefined\">\r\n              <div class=\"float-right\">\r\n                <span>{{betTeam.multiSelection.name}}</span>\r\n                <multiple-select class=\"multiple-selection-{{index}}\" [multipleSelect]=\"betTeam.multiSelection.multipleSelect\">\r\n                </multiple-select>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <div *ngSwitchCase=\"8\" class=\"bet-team\">\r\n          <div class=\"bet-team-8\">\r\n            <div class=\"left mg-right-10\">\r\n              {{betTeam.name}}:\r\n            </div>\r\n            <div class=\"right\">\r\n              <div class=\"multiple-selection-area\" *ngIf=\"betTeam.multiSelection !== undefined\">\r\n                <div>\r\n                  <span class=\"mr-2\">{{betTeam.multiSelection.name}}</span>\r\n                  <multiple-select class=\"multiple-selection-{{index}}\" [multipleSelect]=\"betTeam.multiSelection.multipleSelect\">\r\n                  </multiple-select>\r\n                </div>\r\n              </div>\r\n              <ng-container *ngFor=\"let selection of betTeam.selections\">\r\n                <div *ngIf=\"!selection.isMultiple\">\r\n                  <div class=\"right-selection\">\r\n                    <span *ngIf=\"selection.name !== ''\">{{selection.name}}</span>\r\n                    <select [(ngModel)]=\"selection.value\" (change)=\"handleChangeFancyBetTypeCricket(betTeam)\">\r\n                      <option *ngFor=\"let item of selection.items\" [attr.value]=\"item.value\">{{item.name}}</option>\r\n                    </select>\r\n                  </div>\r\n                </div>\r\n              </ng-container>\r\n              <div class=\"input-area\" *ngIf=\"isShowTextBox(betTeam)\">\r\n                <div class=\"right-input mg-right-10\" *ngFor=\"let input of betTeam.inputs\">\r\n                  {{input.name}}\r\n                  <input type=\"text\" [(ngModel)]=\"input.value\" [disabled]=\"input.flag\" decimalOnly />\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </fieldset>\r\n</div>\r\n<tooltip [tooltip]=\"tooltip\"></tooltip>","import { Component, ElementRef, Input, OnChanges, SimpleChange, ViewEncapsulation } from '@angular/core';\r\nimport * as _ from 'lodash';\r\nimport { LABELS } from '../../../../utility/constants/labels';\r\nimport { TEXT } from '../../../../utility/constants/text';\r\nimport { CommonService } from '../../../../utility/services/common.service';\r\nimport { StaticService } from '../../../../utility/services/static.service';\r\nimport { ItemsSelect } from '../../multiple-selection/items-select';\r\nimport { MultipleSelection } from '../../multiple-selection/multiple-selection';\r\nimport { Tooltip } from '../../tooltip/tooltip.model';\r\nimport { AdvancedModeConstants } from '../advanced-mode.constants';\r\nimport { BetType } from '../group-bettypes/group-bettypes.model';\r\nimport { BetTeam, CheckedBetType, GetPlayersQuery, OddsInfo, Player, Selection } from './advanced-mode.model';\r\nimport { AdvancedModeService } from './advanced-mode.service';\r\n\r\n@Component({\r\n  selector: 'advanced-mode',\r\n  templateUrl: './advanced-mode.component.html',\r\n  styleUrls: ['./advanced-mode.component.scss'],\r\n  encapsulation: ViewEncapsulation.None\r\n})\r\nexport class AdvancedModeComponent implements OnChanges {\r\n  @Input() getPlayerQuery: GetPlayersQuery;\r\n  @Input() matchId: string;\r\n  @Input() allBetTypes: BetType[];\r\n  @Input() isHaveMultipleMapRound: boolean;\r\n\r\n  baseBetTeam: BetTeam[] = [];\r\n  betTeams: BetTeam[] = [];\r\n  mapList: MultipleSelection;\r\n  roundList: MultipleSelection;\r\n  betTypesMoreHDP = AdvancedModeConstants.BETTYPES_MORE_HDP;\r\n  baseSpecialBetTypeCricket: Selection[] = [];\r\n  isShowAdvancedMode: boolean;\r\n  isShowContent: boolean;\r\n  isShowAllBetType: boolean;\r\n  tooltip = new Tooltip();\r\n  oddsInfo: OddsInfo[];\r\n\r\n  constructor(\r\n    private readonly service: AdvancedModeService,\r\n    private readonly commonService: CommonService,\r\n    private readonly element: ElementRef\r\n    ) {\r\n    this.tooltip.element = this.element;\r\n  }\r\n\r\n  renderBetTeams(data: BetTeam[]) {\r\n    this.betTeams = [];\r\n    data.forEach(item => {\r\n      const betTeam = new BetTeam([item.name, item.value, item.type, item.enableBetTypes, item.betTypes],\r\n        item.selections, item.items, item.inputs, this.isHaveMultipleMapRound);\r\n      this.betTeams.push(betTeam);\r\n    });\r\n  }\r\n\r\n  renderMapAndRound() {\r\n    this.mapList = new MultipleSelection();\r\n    this.mapList.checkAllCheckBoxText = 'All';\r\n    this.mapList.allItemsCheckedText = 'All';\r\n    this.mapList.noneItemCheckedText = 'Select options';\r\n    this.mapList.maxWidth = '100px';\r\n    this.mapList.items = AdvancedModeConstants.MAP_LIST;\r\n    this.mapList.checkAllItems(true);\r\n\r\n    this.roundList = new MultipleSelection();\r\n    this.roundList.checkAllCheckBoxText = 'All';\r\n    this.roundList.allItemsCheckedText = 'All';\r\n    this.roundList.noneItemCheckedText = 'Select options';\r\n    this.roundList.maxWidth = '90px';\r\n    this.roundList.items = AdvancedModeConstants.ROUND_LIST;\r\n    this.mapList.checkAllItems(true);\r\n  }\r\n\r\n  async ngOnChanges(changes: { [propKey: string]: SimpleChange }) {  \r\n    if (this.matchId && changes['allBetTypes']) {\r\n      if (this.baseBetTeam.length === 0) {\r\n        await this.getBetTeamAndRenderValue(this.matchId);\r\n      }\r\n      \r\n      this.changedBetTypes();\r\n    }\r\n    if (changes['getPlayerQuery']) {\r\n      await this.getPlayers();\r\n    }\r\n  }\r\n\r\n  public async getBetTeamAndRenderValue(matchId: string): Promise<void> {\r\n    this.baseBetTeam = await this.service.getBetTeams();\r\n    if (matchId) {\r\n      await this.getSpecialBetTeamCricket(matchId);\r\n    }\r\n    this.renderBetTeams(this.baseBetTeam);\r\n    this.renderMapAndRound();\r\n  }\r\n  \r\n  public async getSpecialBetTeamCricket(matchId: string): Promise<void> {\r\n    const data = await this.commonService.GetOddsInfoSpecialBetTypes({matchId: matchId, betTypes: AdvancedModeConstants.BETTYPE_CRICKET_WITH_PLAYER});\r\n    this.updatePlayerCricket(data);\r\n    this.oddsInfo = data;\r\n  }\r\n\r\n  changedBetTypes() {\r\n    this.isShowAdvancedMode = false;\r\n    this.isShowContent = false;\r\n    this.isShowAllBetType = false;\r\n    if (this.allBetTypes !== undefined) {\r\n      this.allBetTypes.forEach(betType => {\r\n        this.handleBetTeam(betType);\r\n      });\r\n    }\r\n  }\r\n\r\n  handleBetTeam(betType: BetType) {\r\n    this.betTeams.forEach(betTeam => {\r\n      this.changeBetTeam(betType, betTeam);\r\n      betTeam.enableInput();\r\n    });\r\n  }\r\n\r\n  changeBetTeam(betType: BetType, betTeam: BetTeam) {\r\n    const betTypeIdsOfBetTeam = betTeam.betTypes.split(',');\r\n    if (betTypeIdsOfBetTeam.indexOf(betType.id.toString()) > -1) {\r\n      this.changeCheckedBetTypes(betType, betTeam);\r\n    }\r\n  }\r\n\r\n  changeCheckedBetTypes(betType: BetType, betTeam: BetTeam) {\r\n    const index = betTeam.checkedBetTypes.indexOf(betType.value);\r\n    if (betType.isChecked) {\r\n      this.changeCheckedBetTeam(betTeam);\r\n      this.isShowAdvancedMode = true;\r\n      this.isShowContent = true;\r\n      if (index === -1) {\r\n        this.addBetTypeName(betType.name, betTeam);\r\n        betTeam.checkedBetTypes.push(betType.value);\r\n      }\r\n      if (betTeam.multiSelectionList.length > 0) {\r\n        this.isShowAllBetType = true;\r\n      }\r\n    } else {\r\n      if (index !== -1) {\r\n        this.removeBetTypeName(betType.name, betTeam);\r\n        betTeam.checkedBetTypes.splice(index, 1);\r\n      }\r\n    }\r\n\r\n    if (AdvancedModeConstants.BETTYPE_CRICKET_WITH_PLAYER.split(',').includes(betType.id.toString()) && betType.isChecked) {\r\n      betTeam.resetChecked();\r\n      this.renderSelectionCricketWithPlayer(betTeam, this.baseSpecialBetTypeCricket);\r\n    }\r\n  }\r\n\r\n  changeCheckedBetTeam(betTeam: BetTeam) {\r\n    if (betTeam.checkedBetTypes.length === 0) {\r\n      betTeam.resetChecked();\r\n    }\r\n  }\r\n\r\n  addBetTypeName(name: string, betTeam: BetTeam) {\r\n    if (betTeam.type === 1 || betTeam.type === 8) {\r\n      betTeam.name = betTeam.name === '' ? name : betTeam.name + ', ' + name;\r\n    }\r\n  }\r\n\r\n  removeBetTypeName(name: string, betTeam: BetTeam) {\r\n    if (betTeam.type === 1 || betTeam.type === 8) {\r\n      const names = betTeam.name.split(', ');\r\n      const index = names.indexOf(name);\r\n      names.splice(index, 1);\r\n      betTeam.name = names.join(', ');\r\n    }\r\n  }\r\n\r\n  async getPlayers() {\r\n    if (this.getPlayerQuery !== undefined && this.getPlayerQuery.matchId !== '') {\r\n      const data = await this.service.getPlayer(this.getPlayerQuery);\r\n      this.renderPlayer(data);\r\n    }\r\n  }\r\n\r\n  renderPlayer(players: Player[]) {\r\n    const itemSelects: Array<ItemsSelect> = [];\r\n    for (let i = 0; i < players.length; i++) {\r\n      const item = new ItemsSelect(i, players[i].betChoice, players[i].oddsInfo, true, true, true, []);\r\n      itemSelects.push(item);\r\n    }\r\n\r\n    const betTeam216 = this.betTeams.find(x => x.betTypes === '216');\r\n    betTeam216.multiSelection.multipleSelect.items = [];\r\n    betTeam216.multiSelection.multipleSelect.items = itemSelects;\r\n  }\r\n\r\n  resetBetTeam() {\r\n    this.isShowAdvancedMode = false;\r\n    this.isShowContent = false;\r\n    this.baseBetTeam = [];\r\n    this.betTeams = [];\r\n  }\r\n\r\n  validate(): boolean {\r\n    let result = true;\r\n    for (let i = 0; i < this.betTeams.length && result; i++) {\r\n      result = this.checkEmptyCheckbox(result, i);\r\n    }\r\n\r\n    let isValidOddsSpread = true;\r\n    let isValidHDP = true;\r\n\r\n    this.allBetTypes.filter(x => x.isChecked && (x.id === 228 || x.id === 229 || this.betTypesMoreHDP.includes(x.id.toString()))).forEach(y => {\r\n      const betTeam = this.betTeams.find(x => x.checkedBetTypes.some(t => t.split(',').includes(y.id.toString())));\r\n      if (betTeam) {\r\n        if (this.isBetTypeSabaTimeMachine(y.id) && !this.validateInputMultipleDecimal(y.id.toString(), betTeam.inputs[0].value, 'bet-type-saba' + y.id.toString())) {\r\n          isValidOddsSpread = false;\r\n        } else if (this.isBetTypeMoreHDP(y.id) && !this.validateInputMultipleDecimal(y.id.toString(), betTeam.items[0].value, 'bet-type-more-hdp')) {\r\n          isValidHDP = false;\r\n        }\r\n      }\r\n    });\r\n\r\n    return result && isValidHDP && isValidOddsSpread;\r\n  }\r\n\r\n  private isBetTypeSabaTimeMachine(id: number): boolean {\r\n    return AdvancedModeConstants.BETTYPES_SABA_TIME_MACHINE.split(',').includes(id.toString());\r\n  }\r\n\r\n  private isBetTypeMoreHDP(id: number): boolean {\r\n    return AdvancedModeConstants.BETTYPES_MORE_HDP.split(',').includes(id.toString());\r\n  }\r\n\r\n  private showToolTip(betTypeId: number, className: string) {\r\n    if (betTypeId === 228) {\r\n      this.tooltip.display(className, LABELS.INVALID_VALUE);\r\n    } else {\r\n      this.tooltip.display(className, LABELS.INVALID_HDP);\r\n    }\r\n  }\r\n\r\n  onChangeInputMultipleDecimal(betTypeId: string, value: string, className: string) {\r\n    if (!this.validateInputMultipleDecimal(betTypeId, value, className)) {\r\n      return false;\r\n    }\r\n    this.tooltip.hide();\r\n\r\n    return true;\r\n  }\r\n\r\n  validateInputMultipleDecimal(betTypeId: string, value: string, className: string): boolean {\r\n    const errorText = betTypeId === '228' ? LABELS.INVALID_VALUE : LABELS.INVALID_HDP;\r\n    if (value && !StaticService.isCorrectRegexMultipleDecimal(value)) {\r\n      this.tooltip.display(className, errorText);\r\n      return false;\r\n    }\r\n\r\n    return true;\r\n  }\r\n  checkMultiSelectionData(betTeam: BetTeam): boolean {\r\n    return (\r\n      betTeam.multiSelection !== undefined &&\r\n      betTeam.multiSelection.multipleSelect !== undefined &&\r\n      betTeam.multiSelection.multipleSelect.items.length > 0 &&\r\n      betTeam.multiSelection.multipleSelect.getValueItems() === ''\r\n    );\r\n  }\r\n\r\n  checkCheckedBetTypesWithHDPBetType(betTeam: BetTeam) {\r\n    return betTeam.checkedBetTypes.length > 0 && betTeam.type === 1;\r\n  }\r\n\r\n  checkEmptyCheckbox(result: boolean, i: number): boolean {\r\n    const betTeam = this.betTeams[i];\r\n    if (betTeam.checkedBetTypes.length > 0 && betTeam.type !== 1) {\r\n      if (betTeam.getItemsValue() === '' && betTeam.type !== AdvancedModeConstants.BETTEAM_TYPE_4) {\r\n        result = false;\r\n        this.isShowContent = true;\r\n        this.tooltip.display(`bet-team-${i}`, LABELS.NO_BET_TEAM);\r\n      } else if (this.checkMultiSelectionData(betTeam) && result) {\r\n        result = false;\r\n        this.isShowContent = true;\r\n        this.tooltip.display(`multiple-selection-${i}`, LABELS.NO_BET_TEAM);\r\n      }\r\n    }\r\n\r\n    if (this.checkCheckedBetTypesWithHDPBetType(betTeam) && this.isHaveMultipleMapRound && result) {\r\n      return this.checkEmptyCheckboxWithTicketListing(result, i);\r\n    }\r\n\r\n    return result;\r\n  }\r\n\r\n  checkEmptyCheckboxWithTicketListing(result: boolean, i: number) {\r\n    const betTeam = this.betTeams[i];\r\n    if (betTeam.multiSelectionList !== undefined &&\r\n      betTeam.multiSelectionList.length > 0) {\r\n      betTeam.multiSelectionList.forEach(item => {\r\n        if (item.multipleSelect !== undefined && item.multipleSelect.getValueItems() === '' && result) {\r\n          result = false;\r\n          this.isShowContent = true;\r\n          this.tooltip.display(`multiple-selection-${i}`, TEXT.NO_BET_TEAM);\r\n        }\r\n      });\r\n    }\r\n    return result;\r\n  }\r\n\r\n  getBetTypeModels(value: string): CheckedBetType[] {\r\n    const betTypes = [];\r\n    const betTypeIds = value.split(',');\r\n    this.betTeams.forEach(item => {\r\n      if (item.checkedBetTypes.length > 0) {\r\n        const checkedIds = item.checkedBetTypes.join(',').split(',');\r\n        checkedIds.forEach(id => {\r\n          const index = betTypeIds.indexOf(id.toString());\r\n          betTypeIds.splice(index, 1);\r\n          const betType: CheckedBetType = _.assignIn({ id: parseInt(id, 10) }, item.getResult(id));\r\n          betTypes.push(betType);\r\n        });\r\n      }\r\n    });\r\n\r\n    betTypeIds.forEach(id => {\r\n      const betType: CheckedBetType = {\r\n        id: parseInt(id, 10),\r\n        betTeam: '',\r\n        game: '',\r\n        set: '',\r\n        value: '',\r\n        valueHdp1: '',\r\n        valueHdp2: '',\r\n        betOption: '',\r\n        goal: '',\r\n        oddsSpread: '',\r\n        oddsId: '',\r\n        transdesc: ''\r\n      };\r\n      betTypes.push(betType);\r\n    });\r\n\r\n    return betTypes;\r\n  }\r\n\r\n  updateAllMapAndRoundItemsSelection(itemList: string[], type: string) {\r\n    if (this.betTeams.length > 0) {\r\n      this.betTeams.forEach(item => {\r\n        if (item.multiSelectionList.length > 0) {\r\n          item.updateItemListMapAndRound(itemList, type);\r\n        }\r\n      });\r\n    }\r\n  }\r\n\r\n  checkBetTypesMoreHDP(betTeam: BetTeam, isDivOfBetTypesMoreHDP: boolean) {\r\n    if (betTeam.items.length > 0 && ((betTeam.enableBetTypes === this.betTypesMoreHDP && isDivOfBetTypesMoreHDP)\r\n      || (betTeam.enableBetTypes !== this.betTypesMoreHDP && !isDivOfBetTypesMoreHDP))) {\r\n      return true;\r\n    }\r\n\r\n    return false;\r\n  }\r\n\r\n  isShowTextBox(betTeam: BetTeam) {\r\n    if (betTeam.inputs.length > 0) {\r\n      return true;\r\n    }\r\n\r\n    return false;\r\n  }\r\n\r\n  handleChangeFancyBetTypeCricket(betTeam: BetTeam): void {\r\n    if (betTeam.checkedBetTypes.some(x => AdvancedModeConstants.BETTYPES_CRICKET_UPDATE_FANCY.split(',').includes(x))) {\r\n      const input = betTeam.inputs.find(x => x.xmlAttribute === 'Value');\r\n      const selectionFancy = betTeam.selections.find(x => x.name === \"Fancy:\");\r\n      if (selectionFancy && selectionFancy.value === 'All') {\r\n        input.flag = true;\r\n        input.value = '';\r\n      } else {\r\n        input.flag = false;\r\n      }\r\n    }\r\n  }\r\n\r\n  isSabaHDPTimeMachine(betTeam: BetTeam): boolean {\r\n    return betTeam.name.includes('HDP');\r\n  }\r\n  \r\n  private updatePlayerCricket(oddsInfo: OddsInfo[]): void {\r\n    const groupBetTypes = _.groupBy(oddsInfo, 'betTypeId');\r\n    for (const betTypeId in groupBetTypes) {\r\n      const items = this.getItemsPlayerSelection(betTypeId, groupBetTypes[betTypeId]);\r\n      this.baseSpecialBetTypeCricket.push(new Selection('', `${betTypeId}`, items, true, null));\r\n    }\r\n  }\r\n\r\n  private getItemsPlayerSelection(betTypeId: string, odds: OddsInfo[]): Selection[] {\r\n    const items: Selection[] = [];\r\n    if (AdvancedModeConstants.BETTYPE_NEXT_MAN_OUT.split(',').includes(betTypeId)) {            \r\n      const groupsOdds = _.groupBy(odds, 'oddsId');\r\n      for (const oddsId in groupsOdds) {\r\n        const oddsName = groupsOdds[oddsId].map(y => y.playerName).join(' & ');\r\n        groupsOdds[oddsId].forEach(x => {\r\n          items.push(\r\n            new Selection(`${x.playerName} - ${oddsName}`, `${x.betChoice},${x.oddsId}`, null, true, null)\r\n          );\r\n        });\r\n      }\r\n    } else {\r\n      odds.forEach(x => {\r\n        items.push(new Selection(x.playerName, x.playerId, null, true, null));\r\n      });\r\n    }\r\n\r\n    return items;\r\n  }\r\n\r\n  private renderSelectionCricketWithPlayer(betTeam: BetTeam, baseBetType: Selection[]): void {\r\n    const items: Selection[] = [];\r\n    baseBetType.forEach(x => {\r\n      if (betTeam.checkedBetTypes.includes(x.value)) {\r\n        items.push(...x.items);\r\n      }\r\n    });\r\n    const playerSelection = betTeam.selections.find(x => x.name === 'Player:');\r\n    if (playerSelection) {\r\n      playerSelection.items = betTeam.selections.find(x => x.name === 'Player:').items.filter(x => x.name === 'All');\r\n      playerSelection.items.push(..._.uniqWith(items, _.isEqual));\r\n    }\r\n    betTeam.selections.forEach(x => {\r\n      if (x.name === 'Player:') {\r\n        x.isMultiple = true;\r\n        betTeam.renderMultipleSelect(x);\r\n      }\r\n    });\r\n  }\r\n}\r\n","<group-bettypes #groupBetTypesComponent [model]=\"groupBetTypes\" (betTypesEvent)=\"changeBetTypes($event)\">\r\n</group-bettypes>\r\n<advanced-mode #advancedMode [matchId]=\"match.matchId?.toString()\" [allBetTypes]=\"allBetTypes\" [getPlayerQuery]=\"getPlayerQuery\"></advanced-mode>\r\n<div class=\"search\">\r\n  <input *ngIf=\"isShowSearch\" type=\"submit\" class=\"btn btn-primary btn-sm\" value=\"Search\" (click)=\"getBetTypeModels()\" />\r\n</div>","import { Component, EventEmitter, Input, OnChanges, OnInit, Output, ViewChild } from '@angular/core';\r\nimport { AdvancedModeComponent } from '../../../utility/components/advanced-mode/advanced-mode/advanced-mode.component';\r\nimport { CheckedBetType, GetPlayersQuery } from '../../../utility/components/advanced-mode/advanced-mode/advanced-mode.model';\r\nimport { GroupBetTypesComponent } from '../../../utility/components/advanced-mode/group-bettypes/group-bettypes.component';\r\nimport { BetType, GroupBetTypesModel } from '../../../utility/components/advanced-mode/group-bettypes/group-bettypes.model';\r\nimport { MatchModel } from '../../../utility/models/match.model';\r\n\r\n@Component({\r\n  selector: 'filter',\r\n  templateUrl: './filter.component.html',\r\n  styleUrls: ['./filter.component.scss']\r\n})\r\nexport class FilterComponent implements OnInit, OnChanges {\r\n  @Input() groupBetTypes: GroupBetTypesModel;\r\n  @Input() allBetTypes: BetType[];\r\n  @Input() getPlayerQuery: GetPlayersQuery;\r\n  @Input() match = new MatchModel();\r\n  @Output() search = new EventEmitter<CheckedBetType[]>();\r\n\r\n  @ViewChild('groupBetTypesComponent') groupBetTypesComponent: GroupBetTypesComponent;\r\n  @ViewChild('advancedMode') advancedModelComponent: AdvancedModeComponent;\r\n\r\n  isShowScoreControl = false;\r\n  isShowSearch = true;\r\n\r\n  constructor() { }\r\n\r\n  ngOnChanges() {\r\n    this.isShowSearch = this.groupBetTypes?.getCheckedBetTypes().length > 0;\r\n  }\r\n\r\n  ngOnInit(): void {\r\n  }\r\n\r\n  changeBetTypes(betTypes: BetType[]): void {\r\n    this.allBetTypes = betTypes;\r\n  }\r\n\r\n  getBetTypeModels(): void {\r\n    if (!this.groupBetTypesComponent.validate() || !this.advancedModelComponent.validate()) {\r\n      this.search.emit(null);\r\n    } else {\r\n      const checkedBetTypes = this.groupBetTypes.getValueCheckedBetTypes();\r\n      const betTypeModels = this.advancedModelComponent.getBetTypeModels(checkedBetTypes);\r\n\r\n      this.search.emit(betTypeModels);\r\n    }\r\n  }\r\n}\r\n","import { Component, ElementRef, EventEmitter, Input, OnInit, Output } from '@angular/core';\r\n\r\nimport { LABELS } from '../../../utility/constants/labels';\r\nimport { Tooltip } from '../../components/tooltip/tooltip.model';\r\nimport { Confirmation } from './confirmation';\r\n\r\n@Component({\r\n  selector: 'confirmation',\r\n  templateUrl: './confirmation.component.html',\r\n  styleUrls: ['./confirmation.component.scss']\r\n})\r\n\r\nexport class ConfirmationComponent implements OnInit {\r\n  @Output() voidAll = new EventEmitter<boolean>();\r\n  @Input() isDisabledButton = false;\r\n  tooltip = new Tooltip();\r\n  confirmation: Confirmation = {\r\n    userName: document.body.getAttribute('user-name'),\r\n    reason: '',\r\n    reasonSC: '',\r\n    userPassword: ''\r\n  };\r\n\r\n  constructor(private readonly element: ElementRef) {\r\n    this.tooltip.element = this.element;\r\n  }\r\n\r\n  ngOnInit(): void {\r\n    (async () => {\r\n\r\n    })();\r\n  }\r\n\r\n  voidAllPage() {\r\n    this.voidAll.emit(true);\r\n  }\r\n\r\n  checkValidation(): boolean {\r\n    if (this.confirmation.reason === '') {\r\n      this.tooltip.display('reason', LABELS.INPUT_REASON);\r\n      return false;\r\n    }\r\n    if (this.confirmation.reasonSC === '') {\r\n      this.tooltip.display('reasonSC', LABELS.INPUT_REASON);\r\n      return false;\r\n    }\r\n    if (this.confirmation.userPassword === '') {\r\n      this.tooltip.display('password', LABELS.INPUT_PASSWORD);\r\n      return false;\r\n    }\r\n\r\n    return true;\r\n  }\r\n\r\n  clearData() {\r\n    this.confirmation.reason = '';\r\n    this.confirmation.reasonSC = '';\r\n    this.confirmation.userPassword = '';\r\n  }\r\n}\r\n","<fieldset class=\"confirm-delete\">\r\n  <legend>Confirmation</legend>\r\n  <table>\r\n    <tr>\r\n      <td>\r\n        <label for=\"reason\">Reason (EN)</label>\r\n      </td>\r\n      <td>\r\n        <textarea maxlength=\"150\" class=\"reason form-control form-control-sm\" [(ngModel)]=\"confirmation.reason\"\r\n          rows=\"1\"></textarea>\r\n      </td>\r\n      <td>\r\n        <span class=\"required\">&nbsp;&nbsp;(*)</span> <span>Max {{150 - confirmation.reason.length}} characters</span>\r\n      </td>\r\n    </tr>\r\n    <tr>\r\n      <td>\r\n        <label for=\"reasonSC\">Reason (SC)</label>\r\n      </td>\r\n      <td>\r\n        <textarea maxlength=\"150\" class=\"reasonSC form-control form-control-sm\" [(ngModel)]=\"confirmation.reasonSC\"\r\n          rows=\"1\"></textarea>\r\n      </td>\r\n      <td>\r\n        <span class=\"required\">&nbsp;&nbsp;(*)</span> <span>Max {{150 - confirmation.reasonSC.length}} characters</span>\r\n      </td>\r\n    </tr>\r\n    <tr>\r\n      <td>\r\n        <label>Username</label>\r\n      </td>\r\n      <td>\r\n        <input class=\"form-control form-control-sm\" type=\"text\" disabled value=\"{{confirmation.userName}}\" />\r\n      </td>\r\n      <td></td>\r\n    </tr>\r\n    <tr>\r\n      <td>\r\n        <label>Password</label>\r\n      </td>\r\n      <td>\r\n        <input autocomplete=\"new-password\" type=\"password\" class=\"password form-control form-control-sm\"\r\n          [(ngModel)]=\"confirmation.userPassword\" />\r\n      </td>\r\n      <td><span>&nbsp;&nbsp;(*)</span></td>\r\n    </tr>\r\n    <tr>\r\n      <td></td>\r\n      <td> \r\n        <input [disabled]=\"isDisabledButton\" type=\"button\" class=\"btn btn-success btn-sm font-weight-bold\"\r\n          value=\"Void All Pages\" (click)=\"voidAllPage()\" /> \r\n      </td>\r\n    </tr>\r\n  </table>\r\n</fieldset>\r\n<tooltip [tooltip]=\"tooltip\"></tooltip>\r\n","<div >\r\n    <div class=\"bg-gray mg-10 header-info wrapper-tooltip\">\r\n        <div *ngIf=\"isAbnormalAccount()\" class=\"affected-username padding-2-10 alert alert-primary\">\r\n            Username: <strong>{{usernames}}</strong>\r\n        </div>\r\n\r\n        <event-info *ngIf=\"isHasMatchInfo()\" [match]=\"match\"></event-info>\r\n        <request-info [model]=\"requestDetail\" [issue]=\"issue\" [isShowGeneralInfo]=\"false\"\r\n            [isShowAbnormalAccountInfo]=\"isAbnormalAccount()\" [isShowVar]=\"isShowVar\"></request-info>\r\n\r\n        <log-info *ngIf=\"isHasLogInfo()\" [logInfoDetails]=\"logInfoDetails\" [correctOdds]=\"correctOdds\"\r\n            [issueTypeId]=\"requestDetail.request.issueTypeId\" [filterBy]=\"filterBy\" [actualScore]=\"actualScore\" [isPoolHouseAffected]=\"isPoolHouseAffected\">\r\n        </log-info>\r\n\r\n        <filter *ngIf=\"isRedCard() || isWrongScore() || isWrongOdds()\" [groupBetTypes]=\"groupBetTypes\" [match]=\"match\"\r\n            [allBetTypes]=\"allBetTypes\" [getPlayerQuery]=\"getPlayerQuery\" (search)=\"search($event)\">\r\n        </filter>\r\n    </div>\r\n    <div class=\"d-flex\">\r\n        <tickets-list *ngIf=\"isShowTicket\" [model]=\"ticketsModel\" [(paging)]=\"paging\" (pagingChange)=\"pagingEvent()\"\r\n        (exportExcelEvent)=\"exportExcel()\" [isBlock]=\"isBlockBetList\" (ticketsChange)=\"ticketsChange()\"\r\n        [issueTypeId]=\"issue.issueTypeId\" [isDisableCheckbox]=\"isReducedOver()\">\r\n        </tickets-list>\r\n\r\n        <div class=\"affected-licensees\" *ngIf=\"isShowAffectedLicenseeArea()\">\r\n            <span class=\"note\">Attn: system will notify affected tickets to these Licensee(s): </span><br />\r\n            <div *ngIf=\"affectedLicensee.show && affectedLicensee.licenseesName.length > 0\">\r\n                <span class=\"affected-licensees-highlight\"\r\n                    (click)=\"copyClipboard(affectedLicensee.licenseesName)\">{{affectedLicensee.licenseesName}}</span>\r\n            </div>\r\n            <div class=\"china-view-licensee\"\r\n                *ngIf=\"chinaViewLicensee.show && chinaViewLicensee.licenseesName.length > 0\">\r\n                <span class=\"note\">China View Licensee Affected List:</span><br />\r\n                <span class=\"affected-licensees-highlight\"\r\n                    (click)=\"copyClipboard(chinaViewLicensee.licenseesName)\">{{chinaViewLicensee.licenseesName}}</span>\r\n            </div>\r\n            <div class=\"instant-licensee\"\r\n                *ngIf=\"affectedInstantLicensee.show && affectedInstantLicensee.licenseesName.length > 0\">\r\n                <span class=\"note\">Instant OU Licensee Affected List:</span><br />\r\n                <span class=\"affected-licensees-highlight\"\r\n                    (click)=\"copyClipboard(affectedInstantLicensee.licenseesName)\">{{affectedInstantLicensee.licenseesName}}</span>\r\n            </div>\r\n            <div class=\"cash-out-licensee\"\r\n                *ngIf=\"cashOutLicensee.show && cashOutLicensee.licenseesName.length > 0\">\r\n                <span class=\"note\">Cash Out Licensee Affected List:</span><br />\r\n                <span class=\"affected-licensees-highlight\"\r\n                    (click)=\"copyClipboard(cashOutLicensee.licenseesName)\">{{cashOutLicensee.licenseesName}}</span>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <div [ngClass]=\"{'display-block': paging.total > 0, 'display-none': paging.total <= 0}\">\r\n        <template-message *ngIf=\"!isArchivedTickets()\" #messages [value]=\"templateValue\" [issueTypeId]=\"issue.issueTypeId\"\r\n            [subIssueTypeId]=\"issue.subIssueTypeId\" [voidFunction]=\"2\">\r\n        </template-message>\r\n        <confirmation #confirmation (voidAll)=\"voidAll()\" [isDisabledButton]=\"isBlockBetList\"></confirmation>\r\n    </div>\r\n</div>\r\n\r\n\r\n<tooltip [tooltip]=\"tooltip\"></tooltip>","import { Component, ElementRef, Input, OnInit, ViewChild } from '@angular/core';\r\nimport { Guid } from 'guid-typescript';\r\nimport * as _ from 'lodash';\r\nimport * as moment from 'moment-timezone';\r\nimport { ClipboardService } from 'ngx-clipboard';\r\nimport { GetLogInfoQuery } from '../../../add-request/app/add-request/models/add-request.query';\r\nimport { RequestDetailViewModel } from '../../../edit-request/app/request.model';\r\nimport { AdvancedModeComponent } from '../../../utility/components/advanced-mode/advanced-mode/advanced-mode.component';\r\nimport { CheckedBetType, GetPlayersQuery } from '../../../utility/components/advanced-mode/advanced-mode/advanced-mode.model';\r\nimport { GroupBetTypesComponent } from '../../../utility/components/advanced-mode/group-bettypes/group-bettypes.component';\r\nimport { BetType, GetBetTypesQuery, GroupBetTypesModel } from '../../../utility/components/advanced-mode/group-bettypes/group-bettypes.model';\r\nimport { ModalType } from '../../../utility/components/modal/modal.model';\r\nimport { ModalService } from '../../../utility/components/modal/modal.service';\r\nimport { PagingConstant, PagingModel } from '../../../utility/components/paging/paging/paging.model';\r\nimport { TemplateMessageComponent } from '../../../utility/components/template-message/template-message/template-message.component';\r\nimport { TemplateValue } from '../../../utility/components/template-message/template-message/template.model';\r\nimport { TemplateService } from '../../../utility/components/template-message/template-message/template.service';\r\nimport { Tooltip } from '../../../utility/components/tooltip/tooltip.model';\r\nimport { AbnormalFilterBy, ModeType, SubIssueTypeGroup, TVSRequestFilterBy } from '../../../utility/constants/config';\r\nimport { LABELS } from '../../../utility/constants/labels';\r\nimport { EventType } from '../../../utility/constants/sport.constant';\r\nimport { TEXT } from '../../../utility/constants/text';\r\nimport { AffectedLicensee } from '../../../utility/models/affected-licensee.model';\r\nimport { CheckingPermissionModel } from '../../../utility/models/checking-permission.model';\r\nimport { LogInfoDetail } from '../../../utility/models/log-info-detail.model';\r\nimport { MatchModel } from '../../../utility/models/match.model';\r\nimport { VoidedReason } from '../../../utility/models/reason.model';\r\nimport { CommonService } from '../../../utility/services/common.service';\r\nimport { MappingModelStaticService } from '../../../utility/services/mapping-model-static.service';\r\nimport { PasswordService } from '../../../utility/services/password.service';\r\nimport { StaticService } from '../../../utility/services/static.service';\r\nimport { CheckRequestService } from '../services/check-request.service';\r\nimport { ConfirmationComponent } from './../../../utility/components/confirmation/confirmation.component';\r\nimport { IssueInfo } from './../../../utility/models/issue-type.model';\r\nimport { AppService } from './../app.service';\r\nimport { GetTicketsQuery } from './../models/get-tickets.query';\r\nimport { VoidTicketsQuery } from './../models/void-tickets.query';\r\nimport { TicketsModel } from './../tickets-list/tickets.model';\r\n@Component({\r\n  selector: 'void-other-issue',\r\n  templateUrl: './void-other-issue.component.html',\r\n  styleUrls: ['./void-other-issue.component.scss']\r\n})\r\nexport class VoidOtherIssueComponent implements OnInit {\r\n  @Input('requestId') requestId: number;\r\n  @Input('requestDetail') requestDetail: RequestDetailViewModel;\r\n  @ViewChild('messages') messagesComponent: TemplateMessageComponent;\r\n  @ViewChild('confirmation') confirmationComponent: ConfirmationComponent;\r\n  @ViewChild('groupBetTypesComponent') groupBetTypesComponent: GroupBetTypesComponent;\r\n  @ViewChild('advancedMode') advancedModelComponent: AdvancedModeComponent;\r\n\r\n  ticketsModel = new TicketsModel();\r\n  paging = new PagingModel();\r\n  query = new GetTicketsQuery();\r\n  tooltip = new Tooltip();\r\n  match = new MatchModel();\r\n  issue = new IssueInfo();\r\n  reason = new VoidedReason();\r\n  templateValue = new TemplateValue();\r\n\r\n  isBlockBetList: boolean;\r\n  logInfoDetails: LogInfoDetail[] = [];\r\n  groupBetTypes: GroupBetTypesModel;\r\n  allBetTypes: BetType[];\r\n  getPlayerQuery: GetPlayersQuery;\r\n  liveScoreSelection: string[] = [];\r\n  isShowTicket = true;\r\n  filterBy: number;\r\n  actualScore: string = null;\r\n  correctOdds: string = null;\r\n  isPoolHouseAffected: boolean;\r\n  isShowVar?: boolean;\r\n\r\n  affectedLicensee = new AffectedLicensee();\r\n  affectedInstantLicensee = new AffectedLicensee();\r\n  chinaViewLicensee = new AffectedLicensee();\r\n  cashOutLicensee = new AffectedLicensee();\r\n  voidQuery = new VoidTicketsQuery();\r\n\r\n  uncheckedTransIds: string[] = [];\r\n  singleTransIds: string[];\r\n  parlayTransIds: string[];\r\n  cricketTransIds: string[];\r\n  cancelCashOutTransIds: string[];\r\n  usernames = '';\r\n  transInfo: string;\r\n\r\n  constructor(\r\n    private readonly commonService: CommonService,\r\n    private readonly appService: AppService,\r\n    private readonly modalService: ModalService,\r\n    private readonly templateService: TemplateService,\r\n    private readonly checkRequestService: CheckRequestService,\r\n    private readonly clipboardService: ClipboardService,\r\n    private readonly element: ElementRef,\r\n    private readonly passwordService: PasswordService\r\n  ) {\r\n    this.tooltip.element = this.element;\r\n  }\r\n\r\n  async ngOnInit(): Promise<void> {\r\n    await this.initData();\r\n  }\r\n\r\n  async initData() {\r\n    this.paging.selection = [PagingConstant.SIZE_ONE, PagingConstant.SIZE_TWO, PagingConstant.SIZE_THREE, PagingConstant.SIZE_FOUR];\r\n    this.paging.pageSize = PagingConstant.SIZE_ONE;\r\n    if (this.isAbnormalAccount()) {\r\n      this.usernames = this.requestDetail.event.usernames.split(',').join(', ');\r\n    }\r\n    if (this.isHasLogInfo()) {\r\n      await this.getLogInfoModel();\r\n    }\r\n    this.initDataForDisplayLogInfo();\r\n    this.initLiveScore();\r\n    await this.getMatchInfo();\r\n    this.issue = await this.commonService.getIssueInfo(StaticService.getSubIssueTypeId(this.requestDetail));\r\n    this.reason = await this.appService.getVoidedReason(this.issue.subIssueTypeId, this.isHasMatchInfo() ? this.match.sportType : 0);\r\n    await this.initQuery();\r\n    await this.getTickets();\r\n    await this.getGroupBetTypes();\r\n    await this.updateTemplate();\r\n    this.updateUnchecked();\r\n  }\r\n\r\n  private async getMatchInfo(): Promise<void> {\r\n    if (this.isHasMatchInfo()) {\r\n      if (this.isWrongScore()) {\r\n        this.match = await this.commonService.getMatch(this.requestDetail.wrongScoreModels[0].matchId);\r\n        this.isShowVar = this.requestDetail.wrongScoreModels[0].isCheckedVar;\r\n      } else if (this.isRedCard()) {\r\n        this.match = await this.commonService.getMatch(this.requestDetail.redCardModels[0].matchId);\r\n        this.isShowVar = this.requestDetail.redCardModels[0].isCheckedVar;\r\n      } else if (this.isWrongOdds()) {\r\n        this.match = await this.commonService.getMatch(this.requestDetail.wrongOddsModels[0].matchId);\r\n      } else if (this.isReducedOver()) {\r\n        this.match = await this.commonService.getMatch(this.requestDetail.reducedOverModels[0].matchId);\r\n      } else {\r\n        this.match = await this.commonService.getMatch(this.requestDetail.event.matchId);\r\n      }\r\n    }\r\n  }\r\n\r\n  private initLiveScore(): void {\r\n    if (this.isRedCard() || this.isWrongScore() || this.isWrongOdds()) {\r\n      this.liveScoreSelection = this.logInfoDetails[0].liveScores.split('|');\r\n    }\r\n  }\r\n\r\n  private initDataForDisplayLogInfo(): void {\r\n    if (this.isWrongScore()) {\r\n      this.filterBy = this.requestDetail.wrongScoreModels[0].filterBy;\r\n      this.actualScore = this.requestDetail.wrongScoreModels[0].actualScore;\r\n    }\r\n\r\n    if (this.isWrongOdds()) {\r\n      this.correctOdds = this.requestDetail.wrongOddsModels[0].correctOdds;\r\n    }\r\n  }\r\n\r\n  async updateTemplate() {\r\n    if (this.paging.total > 0) {\r\n      this.updateTemplateValue();\r\n      this.updateVoidedReason();\r\n    }\r\n\r\n    if (this.isWrongOdds()) {\r\n      this.correctOdds = this.requestDetail.wrongOddsModels[0].correctOdds;\r\n    }\r\n  }\r\n\r\n  private async initQuery(): Promise<void> {\r\n    this.query.pageIndex = PagingConstant.INDEX_ZERO;\r\n    this.query.pageSize = PagingConstant.SIZE_ONE;\r\n    this.query.match = this.match;\r\n    this.query.kickOffDate = this.getKickOffDate();\r\n    this.query.requestId = this.requestId;\r\n    this.query.issueTypeId = this.requestDetail.request.issueTypeId;\r\n    this.query.subIssueTypeId = StaticService.getSubIssueTypeId(this.requestDetail);\r\n  }\r\n\r\n  private getKickOffDate(): string {\r\n    if (this.isWrongScore()) {\r\n      return this.requestDetail.wrongScoreModels[0].eventDate.toString();\r\n    }\r\n\r\n    if (this.isRedCard()) {\r\n      return this.requestDetail.redCardModels[0].eventDate.toString();\r\n    }\r\n\r\n    if (this.isWrongOdds()) {\r\n      return this.requestDetail.wrongOddsModels[0].eventDate.toString();\r\n    }\r\n\r\n    if (this.isReducedOver()) {\r\n      return this.requestDetail.reducedOverModels[0].eventDate.toString();\r\n    }\r\n\r\n    return this.requestDetail.event.kickOffTime?.toString();\r\n  }\r\n\r\n  async getTickets() {\r\n    try {\r\n      this.isBlockBetList = true;\r\n      this.isShowTicket = true;\r\n      const data = await this.appService.getTickets(this.query);\r\n      this.isBlockBetList = false;\r\n      this.ticketsModel.initData(data);\r\n      this.paging.total = data.total;\r\n      this.affectedLicensee.licenseesName = data.licenseesName;\r\n      this.affectedLicensee.show = true;\r\n      this.affectedInstantLicensee.licenseesName = data.instantLicenseesName;\r\n      this.affectedInstantLicensee.show = true;\r\n      this.chinaViewLicensee.licenseesName = data.chinaViewLicenseesName;\r\n      this.chinaViewLicensee.show = true;\r\n      this.cashOutLicensee.licenseesName = data.cashOutLicenseesName;\r\n      this.cashOutLicensee.show = true;\r\n    } catch {\r\n      this.isShowTicket = false;\r\n    }\r\n  }\r\n\r\n  private updateUnchecked() {\r\n    this.singleTransIds = this.ticketsModel.singleTickets.map(x => x.transId);\r\n    this.parlayTransIds = this.ticketsModel.parlayTickets.map(x => x.transId);\r\n    this.cricketTransIds = this.ticketsModel.cricketTickets.map(x => x.transId);\r\n    this.cancelCashOutTransIds = this.ticketsModel.cancelCashOutTickets.map(x => x.transId);\r\n\r\n    this.uncheckedTransIds = this.ticketsModel.uncheckedTransIds;\r\n  }\r\n\r\n  async pagingEvent() {\r\n    this.query.pageIndex = this.paging.page - 1;\r\n    this.query.pageSize = this.paging.pageSize;\r\n    await this.getTickets();\r\n    this.ticketsModel.updateTicketsByUncheckTransIds(this.uncheckedTransIds);\r\n  }\r\n\r\n  async exportExcel() {\r\n    const maxPagingItems = 100000;\r\n    if (this.paging.total > maxPagingItems) {\r\n      const header = 'Export Excel Result';\r\n      const body = LABELS.EXPORT_LARGE_FILE;\r\n      this.modalService.open({ title: header, message: body, type: ModalType.Warning });\r\n    } else {\r\n      this.isBlockBetList = true;\r\n      this.query.requestId = this.requestId;\r\n      await this.appService.exportExcel(this.query);\r\n      this.isBlockBetList = false;\r\n    }\r\n  }\r\n\r\n  updateTemplateValueForRedCard() {\r\n    if (this.isRedCard()) {\r\n      this.templateValue.eventType = EventType.LIVE;\r\n\r\n      this.templateValue.score = this.getLiveScoreForTemplateMessage(this.logInfoDetails[0].scoreNormalTicket, this.logInfoDetails[0].scoreOfMatch);\r\n      if (!this.logInfoDetails[0].scoreNormalTicket) {\r\n        this.templateValue.isUpdateScoreHaveText = false;\r\n      } else {\r\n        this.templateValue.isUpdateScoreHaveText = this.logInfoDetails[0].scoreNormalTicket.split(',').length > 1 ? true : false;\r\n      }\r\n      this.templateValue.isCheckTime = this.requestDetail.redCardModels[0].filterBy === TVSRequestFilterBy.CHECK_TIME;\r\n      this.templateValue.isCheckedVar = this.requestDetail.redCardModels[0].isCheckedVar;\r\n    }\r\n  }\r\n\r\n  updateTemplateValueForWrongScore() {\r\n    if (this.isWrongScore()) {\r\n      const score = (this.filterBy === TVSRequestFilterBy.TRANS_TIME || this.filterBy === TVSRequestFilterBy.TRANS_TIME_AND_CHECK_TIME)\r\n        ? this.requestDetail.wrongScoreModels[0].wrongScore\r\n        : this.getLiveScoreForTemplateMessage(this.logInfoDetails[0].scoreNormalTicket, this.logInfoDetails[0].scoreOfMatch);\r\n\r\n      if (SubIssueTypeGroup.SUBTYPE_NO_ONWARDS.includes(this.issue.subIssueTypeId)) {\r\n        this.templateValue.score = score;\r\n      } else {\r\n        this.templateValue.wrongScore = score;\r\n      }\r\n\r\n      this.templateValue.eventType = EventType.LIVE;\r\n      this.templateValue.actualScore = this.requestDetail.wrongScoreModels[0].actualScore;\r\n      this.templateValue.isCheckedVar = this.requestDetail.wrongScoreModels[0].isCheckedVar;\r\n    }\r\n  }\r\n\r\n  updateTemplateValueForAbnormalBet() {\r\n    if (this.isAbnormalBet()) {\r\n      this.templateValue.filterBy = this.requestDetail.event.filterBy;\r\n    }\r\n  }\r\n\r\n  updateTemplateValueForWrongOdds() {\r\n    if (this.isWrongOdds()) {\r\n      this.templateValue.checkAIOMessage = this.ticketsModel.isHasAioMessage;\r\n      this.templateValue.match = this.match;\r\n      this.templateValue.betTeam = this.requestDetail.wrongOddsModels[0].betTeam;\r\n      this.templateValue.filterOuType = this.requestDetail.wrongOddsModels[0].filterOuType;\r\n      this.templateValue.ouValue = this.requestDetail.wrongOddsModels[0].ouValue;\r\n      this.templateValue.correctOdds = this.requestDetail.wrongOddsModels[0].correctOdds;\r\n    }\r\n  }\r\n\r\n  updateTemplateValue() {\r\n    if (this.isArchivedTickets()) {\r\n      return;\r\n    }\r\n    this.templateValue = this.templateService.getTemplateValue(this.query.match);\r\n    this.templateValue.kickOffTime = this.query.kickOffDate;\r\n    this.templateValue.checkSettled = this.checkSettled();\r\n    this.templateValue.fromTransTime = this.ticketsModel.fromTime;\r\n    this.templateValue.toTransTime = this.ticketsModel.toTime;\r\n    this.updateTemplateValueForAbnormalBet();\r\n    this.updateTemplateValueForRedCard();\r\n    this.updateTemplateValueForWrongScore();\r\n    this.updateTemplateValueForWrongOdds();\r\n    this.templateValue.totalTickets = this.ticketsModel.total;\r\n  }\r\n\r\n  private getLiveScoreForTemplateMessage(scoreNormalTicket: string, scoreOfMatch: string): string {\r\n    return !scoreNormalTicket ? scoreOfMatch : scoreNormalTicket.split('|')[0].replace(/ /g, '');\r\n  }\r\n\r\n  updateVoidedReason() {\r\n    this.confirmationComponent.confirmation.reason = this.reason.reasonEnglish;\r\n    this.confirmationComponent.confirmation.reasonSC = this.reason.reasonChineseSimplified;\r\n  }\r\n\r\n  ticketsChange() {\r\n    const unCheckedCurrent = this.ticketsModel.getCheckedTickets(false);\r\n    const checkedCurrent = this.ticketsModel.getCheckedTickets(true);\r\n    this.uncheckedTransIds = this.uncheckedTransIds.concat(unCheckedCurrent);\r\n    this.uncheckedTransIds = _.uniq(this.uncheckedTransIds);\r\n    this.uncheckedTransIds = _.difference(this.uncheckedTransIds, checkedCurrent);\r\n    if (!this.isArchivedTickets()) {\r\n      this.templateValue = _.clone(this.templateValue);\r\n      this.templateValue.checkSettled = this.checkSettled();\r\n    }\r\n  }\r\n\r\n  voidAll() {\r\n    this.updateVoidQuery();\r\n    if (this.checkValidation() && this.isShowTicket) {\r\n      this.showConfirmVoid();\r\n    }\r\n  }\r\n\r\n  checkSettled(): boolean {\r\n    if (this.isAbnormalAccount()) {\r\n      const UNSETTLED_STATUS = '0,1';\r\n      if (this.requestDetail.event.statusIds === UNSETTLED_STATUS) {\r\n        return false;\r\n      }\r\n\r\n      return true;\r\n    }\r\n\r\n    return this.ticketsModel.checkSettledTickets();\r\n  }\r\n\r\n  private checkValidation(): boolean {\r\n    if (this.voidQuery.singleTickets.length === 0\r\n      && this.voidQuery.parlayTickets.length === 0\r\n      && this.voidQuery.cancelCashOutTickets.length === 0\r\n      && this.voidQuery.cricketTickets.length === 0) {\r\n      this.tooltip.display('checkbox-dropdown-list', LABELS.EMPTY_TICKET);\r\n      return false;\r\n    }\r\n    if (!this.isArchivedTickets() && !this.messagesComponent.checkValidation()) {\r\n      return false;\r\n    }\r\n    if (!this.confirmationComponent.checkValidation()) {\r\n      return false;\r\n    }\r\n\r\n    return true;\r\n  }\r\n\r\n  updateVoidQuery() {\r\n    this.voidQuery = {\r\n      requestId: this.requestId,\r\n      singleTickets: _.difference(this.singleTransIds, this.uncheckedTransIds).map(x => {\r\n        return this.ticketsModel.singleTickets.find(y => y.transId === x);\r\n      }),\r\n      parlayTickets: _.difference(this.parlayTransIds, this.uncheckedTransIds).map(x => {\r\n        return this.ticketsModel.parlayTickets.find(y => y.transId === x);\r\n      }),\r\n      cancelCashOutTickets: _.difference(this.cancelCashOutTransIds, this.uncheckedTransIds).map(x => {\r\n        return this.ticketsModel.cancelCashOutTickets.find(y => y.transId === x);\r\n      }),\r\n      cricketTickets: _.difference(this.cricketTransIds, this.uncheckedTransIds).map(x => {\r\n        return this.ticketsModel.cricketTickets.find(y => y.transId === x);\r\n      }),\r\n      userName: this.confirmationComponent.confirmation.userName,\r\n      userPassword: this.passwordService.hash(this.confirmationComponent.confirmation.userPassword),\r\n      reason: this.confirmationComponent.confirmation.reason,\r\n      reasonSC: this.confirmationComponent.confirmation.reasonSC,\r\n      message: this.messagesComponent?.message,\r\n      matchId: this.match.matchId,\r\n      subIssueTypeId: StaticService.getSubIssueTypeId(this.requestDetail),\r\n      subIssueTypeName: this.issue.subIssueTypeName,\r\n      subIssueTypeNameCS: this.issue.subIssueTypeNameCS,\r\n      issueTypeId: this.requestDetail.request.issueTypeId,\r\n      voidFromTime: moment(new Date(this.ticketsModel.fromTime)).format('hh:mm:ss A'),\r\n      voidToTime: moment(new Date(this.ticketsModel.toTime)).format('hh:mm:ss A'),\r\n      voidFromDate: moment(new Date(this.ticketsModel.fromDate)).format('MM/DD/YYYY'),\r\n      voidToDate: moment(new Date(this.ticketsModel.toDate)).format('MM/DD/YYYY'),\r\n      decidedBy: this.requestDetail.request.decidedBy,\r\n      guid: Guid.create().toString()\r\n    };\r\n  }\r\n\r\n  showConfirmVoid() {\r\n    this.modalService.confirm(\r\n      {\r\n        title: 'Void Bet Confirm',\r\n        message: LABELS.CONFIRM_VOID_ALL_TICKETS\r\n      }, async () => {\r\n        this.isBlockBetList = true;\r\n        const isRequestModified = await this.checkRequestService.isRequestModified(this.requestDetail.requestId, this.requestDetail.lastModifiedDate);\r\n        if (!isRequestModified) {\r\n          const checkingPermissionModel = new CheckingPermissionModel();\r\n          checkingPermissionModel.setParam(this.ticketsModel.checkPermissionTickets, this.voidQuery.matchId, 'ticket-voiding-check-void-bet-permission', true,\r\n            StaticService.checkHandlingCashOutAsUnSettledTicketByIssueTypeId(this.requestDetail.request.issueTypeId.toString()), true, this.ticketsModel.allCancelCashOutTickets);\r\n          if (this.isAbnormalAccount() || this.isAbnormalBetMixParlay() || this.isArchivedTickets()) {\r\n            checkingPermissionModel.matchId = 0;\r\n          }\r\n\r\n          const result = await this.commonService.checkVoidBetPermission(checkingPermissionModel);\r\n\r\n          if (result.errCode !== 0 && checkingPermissionModel.action) {\r\n            this.modalService.open({\r\n              title: 'Warning!',\r\n              message: result.errMsg,\r\n              type: ModalType.Warning\r\n            }, async () => this.executeGetTickets(true));\r\n          } else {\r\n            await this.insertQueue();\r\n          }\r\n        }\r\n\r\n        this.isBlockBetList = false;\r\n      });\r\n  }\r\n\r\n  async insertQueue() {\r\n    const WRONG_PASSWORD_CODE = 121;\r\n    this.isBlockBetList = true;\r\n    const result = await this.appService.insertQueue(this.voidQuery);\r\n    this.isBlockBetList = false;\r\n    if (!result.isSuccessful) {\r\n      this.modalService.open({\r\n        title: 'Error',\r\n        message: result.errorMsg,\r\n        type: ModalType.Error\r\n      }, () => {\r\n        if (result.errorCode !== WRONG_PASSWORD_CODE) {\r\n          this.closeCurrentPage();\r\n        }\r\n      });\r\n    } else {\r\n      this.modalService.open({\r\n        title: 'Confirmation Result ',\r\n        message: TEXT.REQUEST_CONFIRMED_SUCCESSFULLY,\r\n        type: ModalType.Alert\r\n      }, () => {\r\n        this.closeCurrentPage();\r\n      });\r\n    }\r\n  }\r\n\r\n  closeCurrentPage() {\r\n    window.close();\r\n  }\r\n\r\n  redirectToPage() {\r\n    window.location.assign('TicketVoidingSystem/ManageRequest/Index');\r\n  }\r\n\r\n  copyClipboard(text: string) {\r\n    this.clipboardService.copyFromContent(text);\r\n    alert('The Licensee list has been copied to clipboard.');\r\n  }\r\n\r\n  isHasMatchInfo() {\r\n    if (this.isAbnormalAccount()) {\r\n      return false;\r\n    }\r\n\r\n    if (this.isAbnormalBetMixParlay()) {\r\n      return false;\r\n    }\r\n\r\n    if (this.isArchivedTickets()) {\r\n      return false;\r\n    }\r\n\r\n    return true;\r\n  }\r\n\r\n  isAbnormalAccount(): boolean {\r\n    return StaticService.isAbnormalAccount(this.requestDetail.request.issueTypeId.toString());\r\n  }\r\n\r\n  isRedCard(): boolean {\r\n    return StaticService.isRedCard(this.requestDetail.request.issueTypeId.toString());\r\n  }\r\n\r\n  isWrongScore(): boolean {\r\n    return StaticService.isWrongScore(this.requestDetail.request.issueTypeId.toString());\r\n  }\r\n\r\n  isAbnormalBet(): boolean {\r\n    return StaticService.isAbnormalBet(this.requestDetail.request.issueTypeId.toString());\r\n  }\r\n\r\n  isAbnormalBetMixParlay(): boolean {\r\n    return this.isAbnormalBet() && this.requestDetail.event.filterBy === AbnormalFilterBy.MIX_PARLAY;\r\n  }\r\n\r\n  isArchivedTickets() {\r\n    return StaticService.isArchivedTicket(this.requestDetail.request.issueTypeId.toString());\r\n  }\r\n\r\n  isWrongOdds() {\r\n    return StaticService.isWrongOdds(this.requestDetail.request.issueTypeId.toString());\r\n  }\r\n\r\n  isReducedOver() {\r\n    return StaticService.isReducedOver(this.requestDetail.request.issueTypeId.toString());\r\n  }\r\n\r\n  public isShowAffectedLicenseeArea(): boolean {\r\n    return this.affectedLicensee.show && this.affectedLicensee.licenseesName.length > 0\r\n      || this.chinaViewLicensee.show && this.chinaViewLicensee.licenseesName.length > 0\r\n      || this.affectedInstantLicensee.show && this.affectedInstantLicensee.licenseesName.length > 0\r\n      || this.cashOutLicensee.show && this.cashOutLicensee.licenseesName.length > 0;\r\n  }\r\n\r\n  async getGroupBetTypes(): Promise<void> {\r\n    if (this.ticketsModel.betTypes.length > 0) {\r\n      const query: GetBetTypesQuery = {\r\n        mode: ModeType.MARK_TICKET,\r\n        matchId: this.match.matchId,\r\n        betTypes: this.ticketsModel.betTypes\r\n      };\r\n      const data = await this.commonService.getGroupBetTypes(query);\r\n      this.handleGroupBetTypes(data);\r\n    } else {\r\n      this.groupBetTypes = new GroupBetTypesModel([], true);\r\n      this.allBetTypes = [];\r\n    }\r\n  }\r\n\r\n  handleGroupBetTypes(data: GroupBetTypesModel): void {\r\n    this.groupBetTypes = new GroupBetTypesModel(data.groupBetTypes, true);\r\n    this.allBetTypes = this.groupBetTypes.getAllBetType();\r\n    this.handleBetType216();\r\n  }\r\n\r\n  handleBetType216(): void {\r\n    const betType216Id = 216;\r\n    if (this.groupBetTypes.hasBetType(betType216Id)) {\r\n      this.getPlayerQuery = new GetPlayersQuery('70200048', '216');\r\n    }\r\n  }\r\n\r\n  async executeGetTickets(isOnlySearch: boolean): Promise<void> {\r\n    await this.getTickets();\r\n    if (!isOnlySearch) {\r\n      await this.getGroupBetTypes();\r\n    }\r\n    this.updateUnchecked();\r\n    this.updateTemplateValue();\r\n  }\r\n\r\n  async search(checkedBetTypes: CheckedBetType[]): Promise<void> {\r\n    if (!_.isNull(checkedBetTypes)) {\r\n      await this.initQuery();\r\n      this.query.betTypes = checkedBetTypes;\r\n      await this.executeGetTickets(true);\r\n    }\r\n  }\r\n\r\n  async getLogInfoModel(): Promise<void> {\r\n    const logInfoList = await this.commonService.getLogInfo(this.getLogInfoQuery());\r\n    if (this.isReducedOver()) {\r\n      this.logInfoDetails.push(logInfoList.getLogInfoModels[0].logInfoDetail);\r\n    } else {\r\n      logInfoList.getLogInfoModels.forEach(logInfo => {\r\n        this.logInfoDetails.push(logInfo.logInfoDetail);\r\n      });\r\n\r\n      if (this.isWrongOdds()) {\r\n        this.isPoolHouseAffected = logInfoList.getLogInfoModels[0].validation.isPoolHouseAffected;\r\n      }\r\n    }\r\n  }\r\n\r\n  getLogInfoQuery(): GetLogInfoQuery {\r\n    const query: GetLogInfoQuery = {\r\n      requestId: this.requestId,\r\n      actionId: this.requestDetail.request.actionId,\r\n      isShowLogOnly: true,\r\n      issueTypeId: this.requestDetail.request.issueTypeId,\r\n      subIssueTypeId: StaticService.getSubIssueTypeId(this.requestDetail),\r\n    };\r\n    if (this.isRedCard()) {\r\n      query.matchId = this.requestDetail.redCardModels[0].matchId;\r\n      query.redCardModels = MappingModelStaticService.buidRedCardGetLogInfoModel(this.requestDetail.redCardModels);\r\n    } else if (this.isWrongScore()) {\r\n      query.matchId = this.requestDetail.wrongScoreModels[0].matchId;\r\n      query.wrongScoreModels = MappingModelStaticService.buidWrongScoreGetLogInfoModel(this.requestDetail.wrongScoreModels);\r\n    } else if (this.isWrongOdds()) {\r\n      query.matchId = this.requestDetail.wrongOddsModels[0].matchId;\r\n      query.wrongOddsModels = MappingModelStaticService.buidWrongOddsGetLogInfoModel(this.requestDetail.wrongOddsModels);\r\n    } else if (this.isReducedOver()) {\r\n      query.matchId = this.requestDetail.reducedOverModels[0].matchId;\r\n      query.reducedOverModels = MappingModelStaticService.buidReducedOverGetLogInfoModel(this.requestDetail.reducedOverModels);\r\n    }\r\n\r\n    return query;\r\n  }\r\n\r\n  async callApiGetLogInfo(query: GetLogInfoQuery) {\r\n    const logInfoList = await this.commonService.getLogInfo(query);\r\n    logInfoList.getLogInfoModels.forEach(logInfo => {\r\n      this.logInfoDetails.push(logInfo.logInfoDetail);\r\n    });\r\n  }\r\n\r\n  public isHasLogInfo(): boolean {\r\n    return this.isRedCard() || this.isWrongScore() || this.isWrongOdds() || this.isReducedOver();\r\n  }\r\n}\r\n","<menu-bar></menu-bar>\r\n\r\n<div class=\"title\">\r\n  Home / Manage Request / Void Request - {{requestId}}\r\n</div>\r\n<div class=\"body\" [blockUi]=\"isBlockUI\">\r\n  <ng-container *ngIf=\"isValidRequest()\">\r\n    <div class=\"remark\">\r\n      <span *ngFor=\"let item of remark\">\r\n          <em class=\"fa fa-exclamation-circle\"></em>{{item}}\r\n      </span>\r\n  </div>\r\n  \r\n    <void-danger-accepted *ngIf=\"isApplyVoidNewDesign()\" [requestDetail]=\"requestDetail\"></void-danger-accepted>\r\n    <void-other-issue *ngIf=\"!isApplyVoidNewDesign()\" [requestId]=\"requestId\" [requestDetail]=\"requestDetail\"></void-other-issue>\r\n  </ng-container>\r\n  <div *ngIf=\"!isValidRequest()\" class=\"mg-10 no-data\">\r\n    Loading...\r\n  </div>\r\n</div>","import { Component, OnInit } from '@angular/core';\r\nimport { RequestDetailViewModel } from '../../edit-request/app/request.model';\r\nimport { SignalRService } from '../../utility/services/signal-r.service.native';\r\nimport { StaticService } from '../../utility/services/static.service';\r\nimport { AppService } from './app.service';\r\n\r\n@Component({\r\n  selector: 'app-root',\r\n  templateUrl: './app.component.html',\r\n  styleUrls: ['./app.component.scss']\r\n})\r\nexport class AppComponent implements OnInit {\r\n  requestId: number;\r\n  requestDetail = new RequestDetailViewModel();\r\n  isBlockUI: boolean;\r\n  remark: string[];\r\n\r\n  private isReadyRender = false;\r\n\r\n  constructor(\r\n    private readonly appService: AppService,\r\n    private readonly signalRService: SignalRService\r\n  ) { }\r\n\r\n  async ngOnInit() {\r\n    this.isBlockUI = true;\r\n    this.signalRService.initializeConnection();\r\n    this.remark = await this.appService.getRemark();\r\n    const url = window.location.href;\r\n    const params = url.split('/');\r\n    this.requestId = parseInt(params[params.length - 1], 10);\r\n    this.requestDetail = await this.appService.getRequestById(this.requestId);\r\n    this.requestDetail.requestId = this.requestId;\r\n    this.requestDetail.lastModifiedDate = (await this.appService.getLastModifiedDate(this.requestId)).lastModifiedDate;\r\n    this.isReadyRender = true;\r\n    this.isBlockUI = false;\r\n  }\r\n\r\n  isApplyVoidNewDesign(): boolean {\r\n    return StaticService.isDangerAccepted(this.requestDetail.request?.issueTypeId.toString())\r\n    || StaticService.isWrongOU(this.requestDetail.request?.issueTypeId.toString())\r\n    || StaticService.isWrong1stOU(this.requestDetail.request?.issueTypeId.toString())\r\n    || StaticService.isWrongHDP(this.requestDetail.request?.issueTypeId.toString())\r\n    || StaticService.isWrong1stHDP(this.requestDetail.request?.issueTypeId.toString());\r\n  }\r\n\r\n  updateBlockUI(isBlock: boolean): void {\r\n    this.isBlockUI = isBlock;\r\n  }\r\n\r\n  isValidRequest(): boolean {\r\n    return this.isReadyRender && StaticService.isVoidAction(this.requestDetail.request.actionId);\r\n  }\r\n}\r\n","import { HttpClientModule } from '@angular/common/http';\r\nimport { NgModule } from '@angular/core';\r\nimport { FormsModule } from '@angular/forms';\r\nimport { BrowserModule } from '@angular/platform-browser';\r\nimport { NgbModule } from '@ng-bootstrap/ng-bootstrap';\r\nimport { NgSelectModule } from '@ng-select/ng-select';\r\nimport { ClipboardModule } from 'ngx-clipboard';\r\nimport { ToastrModule } from 'ngx-toastr';\r\nimport { AdvancedModeModule } from '../../utility/components/advanced-mode/advanced-mode.module';\r\nimport { DateTimeModule } from '../../utility/components/date-time/date-time.module';\r\nimport { PagingModule } from '../../utility/components/paging/paging.module';\r\nimport { RequestInfoMod